/**
 * Note Crypto
 *
 * Encryption and decryption for notes using KeyVault keys.
 * Uses AES-256-GCM consistent with @rootz/crypto.
 *
 * ## Key Hierarchy
 * ```
 * Master Key (32 bytes, per secret)
 * └── KV Key (32 bytes, encrypted with master key)
 *     └── Note (encrypted with KV key)
 * ```
 */

import {
  AES,
  type EncryptedData,
  bytesToHex,
  hexToBytes,
  randomBytes,
} from '@rootz/crypto';
import type {
  Note,
  NotePayload,
  EncryptedNote,
  NoteFile,
  NoteFileInput,
  DecryptedNoteFile,
  EncryptedIPFSRef,
} from './types.js';

/**
 * Note encryption utilities.
 */
export class NoteCrypto {
  /**
   * Generate a new KeyVault key.
   * @returns 32-byte random key
   */
  static generateKvKey(): Uint8Array {
    return randomBytes(32);
  }

  // ============================================================================
  // VDN File Encryption (IPFS Hash Protection)
  // ============================================================================

  /**
   * Encrypt an IPFS hash using VDN pattern.
   * Hides the real IPFS location from blockchain analysis.
   *
   * @param ipfsHash - Plaintext IPFS hash (e.g., "QmXxx...")
   * @param kvKey - KeyVault key for encryption
   * @returns VDN-encrypted IPFS reference
   */
  static async encryptIPFSHash(
    ipfsHash: string,
    kvKey: Uint8Array
  ): Promise<EncryptedIPFSRef> {
    const kvKeyHex = bytesToHex(kvKey);
    const encrypted = await AES.encrypt(ipfsHash, kvKeyHex);
    return {
      encrypted: encrypted.encrypted,
      iv: encrypted.iv,
      version: '5.0',
    };
  }

  /**
   * Decrypt a VDN-encrypted IPFS hash.
   *
   * @param ipfsRef - VDN-encrypted IPFS reference
   * @param kvKey - KeyVault key for decryption
   * @returns Plaintext IPFS hash
   */
  static async decryptIPFSHash(
    ipfsRef: EncryptedIPFSRef,
    kvKey: Uint8Array
  ): Promise<string> {
    const kvKeyHex = bytesToHex(kvKey);
    const encryptedData = {
      encrypted: ipfsRef.encrypted,
      iv: ipfsRef.iv,
      algorithm: 'AES-256-GCM' as const,
    };
    return AES.decrypt(encryptedData, kvKeyHex);
  }

  /**
   * Encrypt file input to storage format.
   * Converts plaintext IPFS hash to VDN-encrypted format.
   *
   * @param fileInput - File with plaintext IPFS hash
   * @param kvKey - KeyVault key for encryption
   * @returns Encrypted file ready for storage
   */
  static async encryptFileInput(
    fileInput: NoteFileInput,
    kvKey: Uint8Array
  ): Promise<NoteFile> {
    const ipfsRef = await this.encryptIPFSHash(fileInput.ipfsHash, kvKey);
    return {
      ipfsRef,
      filename: fileInput.filename,
      contentType: fileInput.contentType,
      size: fileInput.size,
      description: fileInput.description,
      contentHash: fileInput.contentHash,
      uploadedAt: Date.now(),
      encrypted: fileInput.encrypted,
      encryptionIv: fileInput.encryptionIv,
    };
  }

  /**
   * Decrypt stored file to display format.
   * Converts VDN-encrypted IPFS hash back to plaintext.
   *
   * @param noteFile - Encrypted file from storage
   * @param kvKey - KeyVault key for decryption
   * @returns Decrypted file for display/download
   */
  static async decryptNoteFile(
    noteFile: NoteFile,
    kvKey: Uint8Array
  ): Promise<DecryptedNoteFile> {
    const ipfsHash = await this.decryptIPFSHash(noteFile.ipfsRef, kvKey);
    return {
      ipfsHash,
      filename: noteFile.filename,
      contentType: noteFile.contentType,
      size: noteFile.size,
      description: noteFile.description,
      contentHash: noteFile.contentHash,
      uploadedAt: noteFile.uploadedAt,
      encrypted: noteFile.encrypted,
      encryptionIv: noteFile.encryptionIv,
    };
  }

  /**
   * Encrypt multiple file inputs.
   *
   * @param files - Array of file inputs
   * @param kvKey - KeyVault key
   * @returns Array of encrypted files
   */
  static async encryptFileInputs(
    files: NoteFileInput[],
    kvKey: Uint8Array
  ): Promise<NoteFile[]> {
    return Promise.all(files.map((f) => this.encryptFileInput(f, kvKey)));
  }

  /**
   * Decrypt multiple stored files.
   *
   * @param files - Array of encrypted files
   * @param kvKey - KeyVault key
   * @returns Array of decrypted files
   */
  static async decryptNoteFiles(
    files: NoteFile[],
    kvKey: Uint8Array
  ): Promise<DecryptedNoteFile[]> {
    return Promise.all(files.map((f) => this.decryptNoteFile(f, kvKey)));
  }

  // ============================================================================
  // File Content Encryption (Optional - for sensitive files)
  // ============================================================================

  /**
   * Convert Uint8Array to base64 string (handles large files).
   */
  private static uint8ArrayToBase64(bytes: Uint8Array): string {
    // Process in chunks to avoid stack overflow
    const CHUNK_SIZE = 0x8000; // 32KB chunks
    let result = '';
    for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
      const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
      result += String.fromCharCode.apply(null, chunk as unknown as number[]);
    }
    return btoa(result);
  }

  /**
   * Convert base64 string to Uint8Array.
   */
  private static base64ToUint8Array(base64: string): Uint8Array {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  /**
   * Encrypt file content before IPFS upload.
   * Use this for sensitive files that shouldn't be readable on IPFS.
   *
   * @param fileData - Raw file bytes
   * @param kvKey - KeyVault key for encryption
   * @returns Encrypted bytes and IV
   */
  static async encryptFileContent(
    fileData: Uint8Array,
    kvKey: Uint8Array
  ): Promise<{ encrypted: Uint8Array; iv: string }> {
    const kvKeyHex = bytesToHex(kvKey);
    // Convert file bytes to base64 for AES encryption (chunked for large files)
    const base64Data = this.uint8ArrayToBase64(fileData);
    const result = await AES.encrypt(base64Data, kvKeyHex);
    return {
      encrypted: hexToBytes(result.encrypted),
      iv: result.iv,
    };
  }

  /**
   * Decrypt file content after IPFS download.
   * Use this to decrypt files that were encrypted before upload.
   *
   * @param encryptedData - Encrypted file bytes from IPFS
   * @param iv - IV used during encryption (hex)
   * @param kvKey - KeyVault key for decryption
   * @returns Original file bytes
   */
  static async decryptFileContent(
    encryptedData: Uint8Array,
    iv: string,
    kvKey: Uint8Array
  ): Promise<Uint8Array> {
    const kvKeyHex = bytesToHex(kvKey);
    const encryptedHex = bytesToHex(encryptedData);
    const encryptedObj = {
      encrypted: encryptedHex,
      iv,
      algorithm: 'AES-256-GCM' as const,
    };
    const base64Data = await AES.decrypt(encryptedObj, kvKeyHex);
    // Convert base64 back to bytes
    return this.base64ToUint8Array(base64Data);
  }

  // ============================================================================
  // Content Encryption (for IPFS storage)
  // ============================================================================

  /**
   * Encrypt string content for IPFS storage.
   * Use this for large note content that needs to be stored on IPFS.
   *
   * SECURITY: Always encrypt content BEFORE uploading to IPFS to ensure
   * plaintext never leaves the client unencrypted.
   *
   * @param content - Plaintext content string
   * @param kvKey - KeyVault key for encryption
   * @returns Encrypted content object with ciphertext and IV
   */
  static async encryptContent(
    content: string,
    kvKey: Uint8Array
  ): Promise<EncryptedData> {
    const kvKeyHex = bytesToHex(kvKey);
    return AES.encrypt(content, kvKeyHex);
  }

  /**
   * Decrypt string content fetched from IPFS.
   * Use this to decrypt content that was encrypted before IPFS upload.
   *
   * @param encryptedData - Encrypted content object from IPFS
   * @param kvKey - KeyVault key for decryption
   * @returns Decrypted plaintext content
   */
  static async decryptContent(
    encryptedData: EncryptedData,
    kvKey: Uint8Array
  ): Promise<string> {
    const kvKeyHex = bytesToHex(kvKey);
    return AES.decrypt(encryptedData, kvKeyHex);
  }

  // ============================================================================
  // KV Key Encryption
  // ============================================================================

  /**
   * Encrypt KV key with master key for storage.
   *
   * @param kvKey - KeyVault key to encrypt
   * @param masterKey - Master key for encryption
   * @returns Encrypted key data
   */
  static async encryptKvKey(
    kvKey: Uint8Array,
    masterKey: Uint8Array
  ): Promise<EncryptedData> {
    // Convert keys to hex strings for AES
    const kvKeyHex = bytesToHex(kvKey);
    const masterKeyHex = bytesToHex(masterKey);
    return AES.encrypt(kvKeyHex, masterKeyHex);
  }

  /**
   * Decrypt KV key with master key.
   *
   * @param encryptedKvKey - Encrypted key data
   * @param masterKey - Master key for decryption
   * @returns Decrypted KeyVault key
   */
  static async decryptKvKey(
    encryptedKvKey: EncryptedData,
    masterKey: Uint8Array
  ): Promise<Uint8Array> {
    const masterKeyHex = bytesToHex(masterKey);
    const kvKeyHex = await AES.decrypt(encryptedKvKey, masterKeyHex);
    return hexToBytes(kvKeyHex);
  }

  /**
   * Encrypt note content with KV key.
   * Handles both text content and file attachments.
   * File IPFS hashes are VDN-encrypted before storage.
   *
   * @param content - Note content (can be empty for file-only notes)
   * @param kvKey - KeyVault key
   * @param author - Author wallet address
   * @param options - Optional note properties
   * @returns Encrypted note data
   */
  static async encryptNote(
    content: string,
    kvKey: Uint8Array,
    author: string,
    options: {
      files?: NoteFileInput[];
      version?: string;
      previousNote?: number;
      metadata?: Record<string, unknown>;
    } = {}
  ): Promise<EncryptedNote> {
    // Encrypt file inputs if provided (VDN pattern)
    let encryptedFiles: NoteFile[] | undefined;
    if (options.files && options.files.length > 0) {
      encryptedFiles = await this.encryptFileInputs(options.files, kvKey);
    }

    // Build payload
    const payload: NotePayload = {
      version: '1.0.0',
      content,
      author: author.toLowerCase(),
      timestamp: Date.now(),
      files: encryptedFiles,
      noteVersion: options.version,
      previousNote: options.previousNote,
      metadata: options.metadata,
    };

    // Serialize to JSON
    const payloadJson = JSON.stringify(payload);

    // Encrypt with KV key (convert to hex string)
    const kvKeyHex = bytesToHex(kvKey);
    const encrypted = await AES.encrypt(payloadJson, kvKeyHex);

    return {
      encrypted: encrypted.encrypted,
      iv: encrypted.iv,
    };
  }

  /**
   * Decrypt note from blockchain.
   * Handles both text content and file attachments.
   * File IPFS hashes are VDN-decrypted for display.
   *
   * @param encrypted - Encrypted content (hex)
   * @param iv - Initialization vector (hex)
   * @param kvKey - KeyVault key
   * @param noteIndex - Note index in KeyVault
   * @param blockNumber - Block number when written
   * @returns Decrypted note with plaintext file IPFS hashes
   */
  static async decryptNote(
    encrypted: string,
    iv: string,
    kvKey: Uint8Array,
    noteIndex: number,
    blockNumber: number
  ): Promise<Note> {
    // Reconstruct encrypted data format
    const encryptedData: EncryptedData = {
      encrypted: encrypted,
      iv: iv,
      algorithm: 'AES-256-GCM',
    };

    // Decrypt (convert key to hex string)
    const kvKeyHex = bytesToHex(kvKey);
    const payloadJson = await AES.decrypt(encryptedData, kvKeyHex);

    // Parse payload
    const payload: NotePayload = JSON.parse(payloadJson);

    // Decrypt file IPFS hashes if present
    let decryptedFiles: DecryptedNoteFile[] | undefined;
    if (payload.files && payload.files.length > 0) {
      decryptedFiles = await this.decryptNoteFiles(payload.files, kvKey);
    }

    // Build note object
    return {
      index: noteIndex,
      content: payload.content,
      author: payload.author,
      timestamp: payload.timestamp,
      blockNumber,
      files: decryptedFiles,
      version: payload.noteVersion,
      previousNote: payload.previousNote,
      metadata: payload.metadata,
    };
  }

  /**
   * Prepare encrypted note data for blockchain write.
   * Converts to bytes format expected by contract.
   *
   * @param encryptedNote - Encrypted note
   * @returns Bytes for contract writeData
   */
  static encryptedNoteToBytes(encryptedNote: EncryptedNote): Uint8Array {
    // Format: [iv (12 bytes)][ciphertext (variable)]
    const iv = hexToBytes(encryptedNote.iv);
    const ciphertext = hexToBytes(encryptedNote.encrypted);

    const combined = new Uint8Array(iv.length + ciphertext.length);
    combined.set(iv, 0);
    combined.set(ciphertext, iv.length);

    return combined;
  }

  /**
   * Parse encrypted note data from blockchain.
   *
   * @param data - Bytes from DataWritten event
   * @returns Encrypted note components
   */
  static bytesToEncryptedNote(data: Uint8Array): EncryptedNote {
    // Format: [iv (12 bytes)][ciphertext (variable)]
    const iv = data.slice(0, 12);
    const ciphertext = data.slice(12);

    return {
      iv: bytesToHex(iv),
      encrypted: bytesToHex(ciphertext),
    };
  }

  /**
   * Create schema definition bytes for KeyVault creation.
   *
   * @param schema - Schema object
   * @returns Schema as bytes
   */
  static schemaToBytes(schema: {
    type: string;
    version: string;
    fields: string[];
    description?: string;
  }): Uint8Array {
    const json = JSON.stringify(schema);
    return new TextEncoder().encode(json);
  }

  /**
   * Parse schema definition from KeyVault.
   *
   * @param data - Schema bytes
   * @returns Parsed schema
   */
  static bytesToSchema(data: Uint8Array): {
    type: string;
    version: string;
    fields: string[];
    description?: string;
  } {
    const json = new TextDecoder().decode(data);
    return JSON.parse(json);
  }
}
