/**
 * @rootz/crypto - ECDH Key Exchange
 *
 * Elliptic Curve Diffie-Hellman for team member key sharing.
 * Uses secp256k1 curve (Ethereum compatible).
 *
 * SECURITY ARCHITECTURE:
 * - Each wallet has a public/private key pair (secp256k1)
 * - Owner and member exchange PUBLIC keys via blockchain
 * - Both parties compute SHARED SECRET using ECDH
 * - Shared secret derives AES key for master key encryption
 * - NEVER transmit private keys or master keys in plaintext
 */

import { SigningKey, randomBytes as ethersRandomBytes, hexlify } from 'ethers';
import type { ECDHEncryptedPackage, KeyPair, DeviceKeyEntry, SingleDevicePackage, FatPackage } from './types.js';
import {
  hexToBytes,
  bytesToHex,
  stripHexPrefix,
  getCrypto,
} from './utils.js';

/**
 * Convert Uint8Array to ArrayBuffer for Web Crypto API compatibility.
 */
function toBuffer(arr: Uint8Array): ArrayBuffer {
  return arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength) as ArrayBuffer;
}

/**
 * ECDH key exchange for team key sharing.
 *
 * Uses secp256k1 curve (same as Ethereum) for compatibility
 * with wallet key pairs.
 */
export class ECDH {
  /**
   * Generate a new secp256k1 key pair.
   *
   * @returns Key pair with private and uncompressed public key
   *
   * @example
   * ```typescript
   * const keyPair = ECDH.generateKeyPair();
   * console.log(keyPair.privateKey); // 0x... (32 bytes)
   * console.log(keyPair.publicKey);  // 0x04... (65 bytes, uncompressed)
   * ```
   */
  static generateKeyPair(): KeyPair {
    const privateKeyBytes = ethersRandomBytes(32);
    const privateKey = hexlify(privateKeyBytes);

    const signingKey = new SigningKey(privateKey);
    const publicKey = signingKey.publicKey; // Uncompressed (0x04...)

    return {
      privateKey,
      publicKey,
    };
  }

  /**
   * Derive public key from private key.
   *
   * @param privateKey - Private key (hex with or without 0x)
   * @returns Uncompressed public key (hex with 0x, starts with 04)
   */
  static derivePublicKey(privateKey: string): string {
    const signingKey = new SigningKey(privateKey);
    return signingKey.publicKey;
  }

  /**
   * Compute ECDH shared secret.
   *
   * Mathematical property: myPrivKey * theirPubKey == theirPrivKey * myPubKey
   *
   * @param myPrivateKey - My private key (hex)
   * @param theirPublicKey - Their uncompressed public key (hex, starts with 04)
   * @returns Shared secret (32 bytes hex with 0x)
   *
   * @example
   * ```typescript
   * // Alice and Bob compute the same shared secret
   * const aliceSecret = ECDH.computeSharedSecret(alicePrivate, bobPublic);
   * const bobSecret = ECDH.computeSharedSecret(bobPrivate, alicePublic);
   * // aliceSecret === bobSecret
   * ```
   */
  static computeSharedSecret(myPrivateKey: string, theirPublicKey: string): string {
    // Validate public key format
    const pubKeyClean = stripHexPrefix(theirPublicKey);
    if (pubKeyClean.length !== 130) {
      throw new Error(
        `Invalid public key length: ${pubKeyClean.length / 2} bytes (must be 65 bytes uncompressed)`
      );
    }
    if (!pubKeyClean.startsWith('04')) {
      throw new Error('Public key must be uncompressed (start with 04)');
    }

    const signingKey = new SigningKey(myPrivateKey);
    const sharedSecret = signingKey.computeSharedSecret(theirPublicKey);

    return sharedSecret;
  }

  /**
   * Derive AES-256 key from ECDH shared secret.
   *
   * Uses SHA-256 hash of shared secret as key material.
   *
   * @param sharedSecret - ECDH shared secret (hex)
   * @returns CryptoKey for AES-256-GCM
   */
  static async deriveAESKey(sharedSecret: string): Promise<CryptoKey> {
    const crypto = getCrypto();

    const secretBytes = hexToBytes(sharedSecret);
    const keyMaterial = await crypto.subtle.digest('SHA-256', toBuffer(secretBytes));

    return crypto.subtle.importKey(
      'raw',
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  }

  /**
   * Encrypt master key for team member using ECDH.
   *
   * Steps:
   * 1. Compute shared secret using ECDH
   * 2. Derive AES-256-GCM key from shared secret
   * 3. Encrypt master key with derived key
   *
   * @param masterKey - Master key to encrypt (hex)
   * @param myPrivateKey - Owner's private key (hex)
   * @param memberPublicKey - Team member's public key (hex, uncompressed)
   * @returns Encrypted package
   *
   * @example
   * ```typescript
   * // Owner encrypts master key for team member
   * const encrypted = await ECDH.encryptMasterKeyForMember(
   *   masterKey,
   *   ownerPrivateKey,
   *   memberPublicKey
   * );
   * // Send encrypted package to member via blockchain message
   * ```
   */
  static async encryptMasterKeyForMember(
    masterKey: string,
    myPrivateKey: string,
    memberPublicKey: string
  ): Promise<ECDHEncryptedPackage> {
    const crypto = getCrypto();

    // Compute shared secret
    const sharedSecret = this.computeSharedSecret(myPrivateKey, memberPublicKey);

    // Derive AES key
    const aesKey = await this.deriveAESKey(sharedSecret);

    // Generate random IV (12 bytes for GCM)
    const iv = crypto.getRandomValues(new Uint8Array(12));

    // Encrypt master key
    const plaintext = stripHexPrefix(masterKey);
    const plaintextBytes = hexToBytes(plaintext);

    const ciphertext = await crypto.subtle.encrypt(
      {
        name: 'AES-GCM',
        iv: toBuffer(iv),
        tagLength: 128,
      },
      aesKey,
      toBuffer(plaintextBytes)
    );

    // Extract auth tag (last 16 bytes)
    const ciphertextArray = new Uint8Array(ciphertext);
    const encryptedData = ciphertextArray.slice(0, -16);
    const authTag = ciphertextArray.slice(-16);

    return {
      ciphertext: bytesToHex(encryptedData),
      iv: bytesToHex(iv),
      authTag: bytesToHex(authTag),
    };
  }

  /**
   * Decrypt master key from team owner using ECDH.
   *
   * Inverse of encryptMasterKeyForMember().
   * Uses member's private key and owner's public key to derive same shared secret.
   *
   * @param encrypted - Encrypted package from owner
   * @param myPrivateKey - Member's private key (hex)
   * @param ownerPublicKey - Owner's public key (hex, uncompressed)
   * @returns Decrypted master key (hex with 0x)
   */
  static async decryptMasterKeyFromOwner(
    encrypted: ECDHEncryptedPackage,
    myPrivateKey: string,
    ownerPublicKey: string
  ): Promise<string> {
    const crypto = getCrypto();

    // Compute shared secret (same as owner computed)
    const sharedSecret = this.computeSharedSecret(myPrivateKey, ownerPublicKey);

    // Derive AES key
    const aesKey = await this.deriveAESKey(sharedSecret);

    // Reconstruct ciphertext with auth tag
    const ciphertextBytes = hexToBytes(encrypted.ciphertext);
    const authTagBytes = hexToBytes(encrypted.authTag);
    const ivBytes = hexToBytes(encrypted.iv);

    const combined = new Uint8Array(ciphertextBytes.length + authTagBytes.length);
    combined.set(ciphertextBytes, 0);
    combined.set(authTagBytes, ciphertextBytes.length);

    // Decrypt
    const plaintext = await crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv: toBuffer(ivBytes),
        tagLength: 128,
      },
      aesKey,
      toBuffer(combined)
    );

    return bytesToHex(new Uint8Array(plaintext));
  }

  /**
   * Verify that a public key is valid uncompressed secp256k1.
   *
   * @param publicKey - Public key to verify (hex)
   * @returns true if valid
   */
  static isValidPublicKey(publicKey: string): boolean {
    try {
      const clean = stripHexPrefix(publicKey);
      if (clean.length !== 130) return false;
      if (!clean.startsWith('04')) return false;

      // Try to use it in a computation (will throw if invalid)
      const testPrivate = hexlify(ethersRandomBytes(32));
      const signingKey = new SigningKey(testPrivate);
      signingKey.computeSharedSecret('0x' + clean);

      return true;
    } catch {
      return false;
    }
  }

  // ==========================================================================
  // Ephemeral Key Encryption (Fat Package Model)
  // ==========================================================================

  /**
   * Encrypt master key for a device using ephemeral keys.
   *
   * This is the PRIMARY method for encrypting master keys.
   * Uses a one-time ephemeral key pair so:
   * - Encrypting device doesn't need to store private key
   * - Decrypting device only needs ephemeralPub + their private key
   * - Self-contained: no dependency on creator after encryption
   *
   * @param masterKey - Master key to encrypt (hex)
   * @param devicePublicKey - Device's public key (hex, uncompressed)
   * @returns Device key entry with ephemeral public key
   *
   * @example
   * ```typescript
   * // Encrypt for a device
   * const entry = await ECDH.encryptForDevice(masterKey, devicePublicKey);
   *
   * // Device decrypts later
   * const decrypted = await ECDH.decryptFromEphemeral(
   *   entry.encryptedMasterKey,
   *   entry.ephemeralPub,
   *   devicePrivateKey
   * );
   * ```
   */
  static async encryptForDevice(
    masterKey: string,
    devicePublicKey: string,
    deviceAddress?: string,
    deviceName?: string
  ): Promise<DeviceKeyEntry> {
    // Generate ephemeral key pair (one-time use)
    const ephemeral = this.generateKeyPair();

    // Encrypt using ephemeral private × device public
    const encryptedMasterKey = await this.encryptMasterKeyForMember(
      masterKey,
      ephemeral.privateKey,
      devicePublicKey
    );

    // Ephemeral private key is now discarded (garbage collected)
    // Only ephemeral public key is stored for decryption

    return {
      deviceAddress: deviceAddress ?? '',
      deviceName,
      ephemeralPub: ephemeral.publicKey,
      encryptedMasterKey,
    };
  }

  /**
   * Decrypt master key using ephemeral public key.
   *
   * @param encrypted - Encrypted package
   * @param ephemeralPub - Ephemeral public key from encryption
   * @param devicePrivateKey - Device's private key
   * @returns Decrypted master key (hex)
   */
  static async decryptFromEphemeral(
    encrypted: ECDHEncryptedPackage,
    ephemeralPub: string,
    devicePrivateKey: string
  ): Promise<string> {
    // Device computes: device_private × ephemeral_pub
    // This equals: ephemeral_private × device_pub (what was used to encrypt)
    return this.decryptMasterKeyFromOwner(encrypted, devicePrivateKey, ephemeralPub);
  }

  /**
   * Create a single device package (LOCAL mode).
   *
   * For secrets with single owner on single device.
   * On-chain recoverable using device's private key.
   *
   * @param masterKey - Master key to encrypt
   * @param devicePublicKey - Device's public key
   * @param secretContract - Secret contract address
   * @param deviceAddress - Device wallet address
   * @returns Complete single device package
   */
  static async createSingleDevicePackage(
    masterKey: string,
    devicePublicKey: string,
    secretContract: string,
    deviceAddress: string
  ): Promise<SingleDevicePackage> {
    const entry = await this.encryptForDevice(masterKey, devicePublicKey, deviceAddress);

    return {
      type: 'single-device-package',
      version: '1.0',
      secretContract,
      deviceAddress,
      ephemeralPub: entry.ephemeralPub,
      encryptedMasterKey: entry.encryptedMasterKey,
      algorithm: 'ECDH-AES-256-GCM',
      timestamp: Date.now(),
    };
  }

  /**
   * Decrypt from a single device package.
   *
   * @param package_ - Single device package
   * @param devicePrivateKey - Device's private key
   * @returns Decrypted master key
   */
  static async decryptSingleDevicePackage(
    package_: SingleDevicePackage,
    devicePrivateKey: string
  ): Promise<string> {
    return this.decryptFromEphemeral(
      package_.encryptedMasterKey,
      package_.ephemeralPub,
      devicePrivateKey
    );
  }

  /**
   * Create a fat package for multiple devices (IDENTITY mode).
   *
   * Encrypts master key separately for each device.
   * Each device can decrypt independently.
   *
   * @param masterKey - Master key to encrypt
   * @param devices - Array of devices with public keys
   * @param metadata - Package metadata
   * @returns Complete fat package
   *
   * @example
   * ```typescript
   * const devices = [
   *   { address: '0x...', publicKey: '0x04...', name: 'Phone' },
   *   { address: '0x...', publicKey: '0x04...', name: 'Laptop' },
   * ];
   *
   * const fatPackage = await ECDH.createFatPackage(masterKey, devices, {
   *   secretContract: '0x...',
   *   keyVaultBlock: 12345,
   *   secretName: 'My Secret',
   *   chainId: 80002,
   * });
   * ```
   */
  static async createFatPackage(
    masterKey: string,
    devices: Array<{ address: string; publicKey: string; name?: string }>,
    metadata: {
      secretContract: string;
      keyVaultBlock: number;
      secretName: string;
      identityContract?: string;
      chainId: number;
      chainName?: string;
    }
  ): Promise<FatPackage> {
    const deviceEntries: DeviceKeyEntry[] = [];

    for (const device of devices) {
      const entry = await this.encryptForDevice(
        masterKey,
        device.publicKey,
        device.address,
        device.name
      );
      deviceEntries.push(entry);
    }

    return {
      type: 'fat-key-package',
      version: '3.0',
      secretContract: metadata.secretContract,
      keyVaultBlock: metadata.keyVaultBlock,
      secretName: metadata.secretName,
      identityContract: metadata.identityContract,
      chainId: metadata.chainId,
      chainName: metadata.chainName,
      timestamp: Date.now(),
      devices: deviceEntries,
    };
  }

  /**
   * Decrypt master key from a fat package.
   *
   * Finds the device entry for the given address and decrypts.
   *
   * @param fatPackage - Fat package with device entries
   * @param deviceAddress - Device wallet address
   * @param devicePrivateKey - Device's private key
   * @returns Decrypted master key
   * @throws Error if device not found in package
   */
  static async decryptFromFatPackage(
    fatPackage: FatPackage,
    deviceAddress: string,
    devicePrivateKey: string
  ): Promise<string> {
    // Find device entry
    const entry = fatPackage.devices.find(
      (d) => d.deviceAddress.toLowerCase() === deviceAddress.toLowerCase()
    );

    if (!entry) {
      throw new Error(
        `Device ${deviceAddress} not found in fat package. ` +
        `Available devices: ${fatPackage.devices.map((d) => d.deviceAddress).join(', ')}`
      );
    }

    return this.decryptFromEphemeral(
      entry.encryptedMasterKey,
      entry.ephemeralPub,
      devicePrivateKey
    );
  }

  /**
   * Add a new device to an existing fat package.
   *
   * Requires the master key (which existing device can provide).
   *
   * @param fatPackage - Existing fat package
   * @param masterKey - Decrypted master key
   * @param newDevice - New device to add
   * @returns Updated fat package
   */
  static async addDeviceToFatPackage(
    fatPackage: FatPackage,
    masterKey: string,
    newDevice: { address: string; publicKey: string; name?: string }
  ): Promise<FatPackage> {
    // Check if device already exists
    const exists = fatPackage.devices.some(
      (d) => d.deviceAddress.toLowerCase() === newDevice.address.toLowerCase()
    );

    if (exists) {
      throw new Error(`Device ${newDevice.address} already in fat package`);
    }

    // Encrypt for new device
    const entry = await this.encryptForDevice(
      masterKey,
      newDevice.publicKey,
      newDevice.address,
      newDevice.name
    );

    // Return new fat package with added device
    return {
      ...fatPackage,
      devices: [...fatPackage.devices, entry],
    };
  }

  // ==========================================================================
  // V5 KeyVault Data Decryption (On-Chain Format)
  // ==========================================================================

  /**
   * Decrypt master key from V5KeyVaultData format.
   *
   * This handles the on-chain format which uses:
   * - `isMultiDevice: true` + `deviceEntries[]` for IDENTITY mode
   * - `encryptedMasterKey` + `ephemeralPub` for LOCAL mode
   *
   * @param keysData - V5KeyVaultData from chain (or parsed from rawKeysData)
   * @param deviceAddress - Current device's wallet address
   * @param devicePrivateKey - Current device's private key
   * @returns Decrypted master key (hex)
   *
   * @example
   * ```typescript
   * const keysData = JSON.parse(secret.rawKeysData);
   * const masterKey = await ECDH.decryptFromV5KeyVaultData(
   *   keysData,
   *   walletAddress,
   *   privateKey
   * );
   * ```
   */
  static async decryptFromV5KeyVaultData(
    keysData: {
      isMultiDevice?: boolean;
      encryptedMasterKey: {
        ciphertext: string;
        iv: string;
        authTag: string;
        ephemeralPub?: string;
        algorithm?: string;
      };
      deviceEntries?: Array<{
        deviceAddress: string;
        deviceName?: string;
        ephemeralPub: string;
        encryptedMasterKey: {
          ciphertext: string;
          iv: string;
          authTag: string;
        };
      }>;
    },
    deviceAddress: string,
    devicePrivateKey: string
  ): Promise<string> {
    // Multi-device (IDENTITY mode): Find device entry and decrypt
    if (keysData.isMultiDevice && keysData.deviceEntries?.length) {
      const entry = keysData.deviceEntries.find(
        (e) => e.deviceAddress.toLowerCase() === deviceAddress.toLowerCase()
      );

      if (!entry) {
        const availableDevices = keysData.deviceEntries.map((e) => e.deviceAddress).join(', ');
        throw new Error(
          `Device ${deviceAddress} not found in multi-device package. ` +
          `Available devices: ${availableDevices}`
        );
      }

      console.log(`[ECDH] Decrypting from deviceEntries[] for ${deviceAddress.slice(0, 10)}...`);
      return this.decryptFromEphemeral(
        entry.encryptedMasterKey,
        entry.ephemeralPub,
        devicePrivateKey
      );
    }

    // Single device (LOCAL mode): Use encryptedMasterKey directly
    const { encryptedMasterKey } = keysData;
    if (!encryptedMasterKey.ephemeralPub) {
      throw new Error(
        'V5KeyVaultData missing ephemeralPub in encryptedMasterKey. ' +
        'Cannot decrypt without ephemeral public key.'
      );
    }

    console.log('[ECDH] Decrypting from encryptedMasterKey (LOCAL mode)');
    return this.decryptFromEphemeral(
      {
        ciphertext: encryptedMasterKey.ciphertext,
        iv: encryptedMasterKey.iv,
        authTag: encryptedMasterKey.authTag,
      },
      encryptedMasterKey.ephemeralPub,
      devicePrivateKey
    );
  }
}
