/**
 * @rootz/crypto - Master Key Encryption
 *
 * Signature-based key derivation for master key encryption.
 * This is the Epistery pattern used throughout Rootz.
 *
 * CONTRACT (version 1.x - DO NOT CHANGE):
 * - Address must be EIP-55 checksummed
 * - Signature message format is: "Storage key for master key encryption\nOwner: {address}\nPurpose: encrypt-master-key"
 * - Key derivation: SHA-256(signature) -> AES-256-GCM key
 */

import { getAddress, type Signer } from 'ethers';
import type { MasterKeyPackage } from './types.js';
import {
  hexToBytes,
  bytesToHex,
  randomBytes,
  getCrypto,
} from './utils.js';

/**
 * Convert Uint8Array to ArrayBuffer for Web Crypto API compatibility.
 */
function toBuffer(arr: Uint8Array): ArrayBuffer {
  return arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength) as ArrayBuffer;
}

/**
 * Master key encryption using signature-based key derivation.
 *
 * This implements the Epistery pattern:
 * 1. Owner signs a deterministic message
 * 2. Signature is hashed to derive AES key
 * 3. Master key is encrypted with derived key
 *
 * Security properties:
 * - Only the owner can decrypt (signature required)
 * - Deterministic: same owner always derives same key
 * - Non-custodial: no key server needed
 */
export class MasterKey {
  /**
   * Create the standard storage key signature message.
   *
   * CONTRACT: This EXACT format must never change in version 1.x
   *
   * @param ownerAddress - EIP-55 checksummed address
   * @returns Signature message string
   */
  static createStorageKeyMessage(ownerAddress: string): string {
    return `Storage key for master key encryption\nOwner: ${ownerAddress}\nPurpose: encrypt-master-key`;
  }

  /**
   * Generate a random 32-byte master key.
   *
   * @returns Hex-encoded master key with 0x prefix
   */
  static generate(): string {
    const bytes = randomBytes(32);
    return bytesToHex(bytes);
  }

  /**
   * Encrypt master key for owner using signature-based key derivation.
   *
   * @param masterKey - Master key to encrypt (hex)
   * @param ownerAddress - Owner's Ethereum address
   * @param signer - Ethers.js Signer for signing
   * @param extensions - Additional metadata
   * @returns Encrypted master key package
   *
   * @example
   * ```typescript
   * const masterKey = MasterKey.generate();
   * const package_ = await MasterKey.encryptForOwner(
   *   masterKey,
   *   '0x1234...',
   *   signer,
   *   { secretName: 'My Secret', secretType: 'ai-context', contractAddress: '0x...' }
   * );
   * ```
   */
  static async encryptForOwner(
    masterKey: string,
    ownerAddress: string,
    signer: Signer,
    extensions: {
      secretName: string;
      secretType: string;
      contractAddress: string;
    }
  ): Promise<MasterKeyPackage> {
    const crypto = getCrypto();

    // Normalize address to EIP-55 checksum
    const checksummedAddress = getAddress(ownerAddress);

    // Create signature message
    const storageKeyMessage = this.createStorageKeyMessage(checksummedAddress);

    // Get signature from signer
    const signature = await signer.signMessage(storageKeyMessage);

    // Derive storage key from signature using SHA-256
    const encoder = new TextEncoder();
    const sigData = encoder.encode(signature);
    const keyMaterial = await crypto.subtle.digest('SHA-256', toBuffer(sigData));

    // Import as AES key
    const storageKey = await crypto.subtle.importKey(
      'raw',
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt']
    );

    // Generate random IV (12 bytes for GCM)
    const iv = randomBytes(12);

    // Encrypt the master key
    const masterKeyData = encoder.encode(masterKey);
    const encrypted = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      storageKey,
      toBuffer(masterKeyData)
    );

    // Create standard package
    return {
      version: '1.0.0',
      algorithm: 'AES-256-GCM',
      keyDerivation: 'signature-storage-key',
      encryptedKey: bytesToHex(new Uint8Array(encrypted)),
      iv: bytesToHex(iv),
      encryptedFor: checksummedAddress,
      timestamp: Date.now(),
      extensions: {
        ...extensions,
      },
    };
  }

  /**
   * Decrypt master key from encrypted package.
   *
   * @param package_ - Encrypted master key package
   * @param signer - Owner's signer (must match encryptedFor address)
   * @returns Decrypted master key (hex)
   *
   * @throws Error if signer doesn't match package owner
   *
   * @example
   * ```typescript
   * const masterKey = await MasterKey.decryptFromPackage(package_, signer);
   * // Use masterKey to decrypt content
   * ```
   */
  static async decryptFromPackage(
    package_: MasterKeyPackage,
    signer: Signer
  ): Promise<string> {
    const crypto = getCrypto();

    // Get signer's address and normalize
    const signerAddress = await signer.getAddress();
    const checksummedSignerAddress = getAddress(signerAddress);

    // Validate that signer is the intended recipient
    if (package_.encryptedFor !== checksummedSignerAddress) {
      throw new Error(
        `Package encrypted for ${package_.encryptedFor}, but signer is ${checksummedSignerAddress}`
      );
    }

    // CRITICAL: Use encryptedFor address from package for signature
    // This ensures we use the EXACT address format used during encryption
    const storageKeyMessage = this.createStorageKeyMessage(package_.encryptedFor);

    // Get signature from signer
    const signature = await signer.signMessage(storageKeyMessage);

    // Derive storage key from signature
    const encoder = new TextEncoder();
    const sigData = encoder.encode(signature);
    const keyMaterial = await crypto.subtle.digest('SHA-256', toBuffer(sigData));

    // Import as AES key
    const storageKey = await crypto.subtle.importKey(
      'raw',
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    // Decrypt
    const encryptedData = hexToBytes(package_.encryptedKey);
    const iv = hexToBytes(package_.iv);

    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: toBuffer(iv), tagLength: 128 },
      storageKey,
      toBuffer(encryptedData)
    );

    const decoder = new TextDecoder();
    return decoder.decode(decrypted);
  }

  /**
   * Verify that a package is valid.
   *
   * @param package_ - Package to verify
   * @returns true if package structure is valid
   */
  static isValidPackage(package_: unknown): package_ is MasterKeyPackage {
    if (!package_ || typeof package_ !== 'object') return false;

    const p = package_ as Record<string, unknown>;

    return (
      p.version === '1.0.0' &&
      p.algorithm === 'AES-256-GCM' &&
      p.keyDerivation === 'signature-storage-key' &&
      typeof p.encryptedKey === 'string' &&
      typeof p.iv === 'string' &&
      typeof p.encryptedFor === 'string' &&
      typeof p.timestamp === 'number' &&
      typeof p.extensions === 'object'
    );
  }
}
