/**
 * Note Manager
 *
 * Manages encrypted notes in KeyVaults on the blockchain.
 *
 * ## AI DOCUMENTATION
 *
 * ### Responsibilities
 * - Create KeyVaults for storing notes
 * - Write encrypted notes to KeyVaults
 * - Read and decrypt notes from KeyVaults
 * - Query note counts and KeyVault status
 * - Fund secret credits via Registry
 *
 * ### Contract Interactions
 * - createKeyVault(encryptedKeysData, schemaDefinition)
 * - writeData(kvBlock, data, expiresAt, v, r, s)
 * - DataWritten events for reading notes
 * - KeyVaultCreated events for KeyVault info
 *
 * ### Authorization Paths (writeData)
 * 1. Direct owner: v=0, r=0, s=0 (msg.sender == owner)
 * 2. EOA delegation: v>=27 (pre-signed ECDSA)
 * 3. Contract delegation (PATH 3): Identity/executeTransaction pattern
 *    - Device calls identityContract.executeTransaction(secretAddr, 0, writeDataCalldata)
 *    - IdentityContract (as owner) executes writeData with PATH 1 (v=0, r=0, s=0)
 *
 * ### V6 Credits Architecture
 * Credits flow through TWO contracts with distinct roles:
 *
 * ```
 * User deposits POL ──► Registry.depositCredits() ──► userCredits[user]
 *                                                           │
 *                                                           ▼
 * User funds secret ──► Registry.fundSecretCredits(secret, amount)
 *                                                           │
 *                            ┌──────────────────────────────┘
 *                            ▼
 *                  Secret.fundOperations(user, amount) ◄── Registry can call
 *                            │
 *                            ▼
 *                  ownerCredits[user] += amount
 * ```
 *
 * **CRITICAL**: Secret.fundOperations() is restricted to factory/registry only!
 * Direct calls from user wallets will fail with "Only factory/registry".
 * Always use Registry.fundSecretCredits() to fund secrets.
 *
 * ### V6.2 Credit Limits
 * - CREDIT_LIMIT_PER_OWNER = -10000 (Owner balance can go to -10000)
 * - No per-vault limit in V6.2 (vault balance is informational only)
 * - Initial credits: 1000 per owner (set at secret creation)
 * - Write cost: dataWriteBaseCost + (data.length * dataWritePerByte)
 */

import { Contract, type Signer, type Provider, ZeroHash, solidityPackedKeccak256, getBytes, hashMessage, recoverAddress, Signature } from 'ethers';
import { hexToBytes } from '@rootz/crypto';
import { NoteCrypto } from './note-crypto.js';
import { REGISTRY_V7_ABI } from './abis.js';
import {
  DEFAULT_NOTE_SCHEMA,
  CREDIT_CONSTANTS,
  type Note,
  type KeyVaultInfo,
  type KeyVaultCreatedEvent,
  type DataWrittenEvent,
  type NoteManagerConfig,
  type CreateKeyVaultOptions,
  type WriteNoteOptions,
  type WriteNoteResult,
  type ReadNotesOptions,
  type WriteCapabilityCheck,
  type CreditStatus,
} from './types.js';

/**
 * Secret contract ABI (relevant functions only).
 */
const SECRET_ABI = [
  // KeyVault creation
  'function createKeyVault(bytes encryptedKeysData, bytes schemaDefinition) external',
  'event KeyVaultCreated(uint256 indexed blockNumber, address indexed creator, bytes encryptedKeysData, bytes schemaDefinition, uint256 timestamp)',

  // Data operations
  'function writeData(uint256 keyVaultBlock, bytes data, uint256 expiresAt, uint8 v, bytes32 r, bytes32 s) external',
  'event DataWritten(address indexed secretContract, address indexed writer, uint256 indexed keyVaultBlock, bytes data, uint256 creditsCost, uint256 timestamp)',

  // Credits operations
  'function fundOperations(address owner, int256 credits) external',
  'event OperationsFunded(address indexed owner, int256 credits, uint256 timestamp)',

  // View functions
  'function getKeyVaultStatus(uint256 blockNumber) view returns (bool active, address creator, int256 creditBalance, int256 ownerTotalCredits)',
  'function originOwner() view returns (address)',
  'function newbornOwner() view returns (address)',
];

/**
 * Identity Contract ABI (for executeTransaction pattern).
 */
const IDENTITY_ABI = [
  'function executeTransaction(address target, uint256 value, bytes data) external returns (bool success, bytes returnData)',
];

// REGISTRY_V7_ABI is now imported from ./abis.js and re-exported

/**
 * Gas settings for Polygon Mainnet.
 * VERSION 6.2 pattern: explicit gas for mainnet conditions.
 * Note: Polygon can spike to 500+ gwei during congestion.
 */
const DEFAULT_GAS_SETTINGS = {
  maxFeePerGas: 750_000_000_000n,        // 750 gwei (mainnet safe)
  maxPriorityFeePerGas: 50_000_000_000n, // 50 gwei
  gasLimit: 500_000,                      // 500k for writeData
};

/**
 * IPFS Configuration defaults.
 * Content larger than threshold goes to IPFS, storing only CID on-chain.
 */
const IPFS_DEFAULTS = {
  /** Default size threshold: 100KB (safe margin below 131KB Polygon limit) */
  SIZE_THRESHOLD: 100_000,
  /** Default Pinata API endpoint */
  ENDPOINT: 'https://api.pinata.cloud',
  /** Default Pinata gateway for fetching */
  GATEWAY: 'https://gateway.pinata.cloud',
};

/**
 * IPFS reference marker stored on-chain when content is too large.
 * This JSON structure replaces the actual content in the note.
 */
interface IPFSNoteReference {
  /** Marker type for detection */
  type: 'ipfs-note-content';
  /** IPFS CID where encrypted content is stored */
  cid: string;
  /** Original content size before IPFS upload */
  originalSize: number;
  /** Version for future compatibility */
  version: '1.0';
}

/**
 * Check if content is an IPFS reference marker.
 */
function isIPFSReference(content: string): content is string {
  try {
    const parsed = JSON.parse(content);
    return parsed.type === 'ipfs-note-content' && typeof parsed.cid === 'string';
  } catch {
    return false;
  }
}

/**
 * Parse IPFS reference from content.
 */
function parseIPFSReference(content: string): IPFSNoteReference | null {
  try {
    const parsed = JSON.parse(content);
    if (parsed.type === 'ipfs-note-content') {
      return parsed as IPFSNoteReference;
    }
  } catch {
    // Not JSON or not an IPFS reference
  }
  return null;
}

/**
 * Gas tier multipliers for dynamic pricing.
 */
const GAS_TIER_MULTIPLIERS = {
  slow: 1.0,      // Base fee only - may get stuck
  standard: 1.2,  // 20% buffer - reliable
  fast: 1.5,      // 50% buffer - prioritized
};

/**
 * Priority fees per tier (Gwei).
 */
const GAS_TIER_PRIORITY = {
  slow: 30,
  standard: 35,
  fast: 50,
};

/**
 * NoteManager - Manages encrypted notes in KeyVaults.
 */
export class NoteManager {
  private config: NoteManagerConfig;
  private signer: Signer;
  private provider: Provider;
  private gasCache: { settings: typeof DEFAULT_GAS_SETTINGS; fetchedAt: number } | null = null;
  private readonly GAS_CACHE_TTL = 10_000; // 10 seconds

  constructor(signer: Signer, config: NoteManagerConfig) {
    this.signer = signer;
    this.config = {
      ...config,
      dynamicGas: config.dynamicGas ?? true, // Default to dynamic gas
      gasTier: config.gasTier ?? 'standard',
      autoFundEnabled: config.autoFundEnabled ?? true, // Default: auto-fund enabled
      autoFundAmount: config.autoFundAmount ?? 25000, // Default: 25K credits
    };
    this.provider = signer.provider!;
  }

  /**
   * Gas settings type for transactions.
   */
  private getStaticGasSettings(): { maxFeePerGas: bigint; maxPriorityFeePerGas: bigint; gasLimit: number } {
    const cfg = this.config.gasSettings;
    return {
      maxFeePerGas: cfg?.maxFeePerGas ?? DEFAULT_GAS_SETTINGS.maxFeePerGas,
      maxPriorityFeePerGas: cfg?.maxPriorityFeePerGas ?? DEFAULT_GAS_SETTINGS.maxPriorityFeePerGas,
      gasLimit: cfg?.gasLimit ?? DEFAULT_GAS_SETTINGS.gasLimit,
    };
  }

  /**
   * Get gas settings - dynamic from network or static from config.
   * Caches network results for 10 seconds to reduce RPC calls.
   */
  async getGasSettings(): Promise<{ maxFeePerGas: bigint; maxPriorityFeePerGas: bigint; gasLimit: number }> {
    // Use static settings if dynamic gas is disabled
    if (!this.config.dynamicGas) {
      return this.getStaticGasSettings();
    }

    // Check cache
    const now = Date.now();
    if (this.gasCache && (now - this.gasCache.fetchedAt) < this.GAS_CACHE_TTL) {
      return this.gasCache.settings;
    }

    // Fetch from network
    try {
      const feeData = await this.provider.getFeeData();
      const baseFee = feeData.maxFeePerGas ?? BigInt(50e9); // Fallback 50 gwei

      const tier = this.config.gasTier || 'standard';
      const multiplier = GAS_TIER_MULTIPLIERS[tier];
      const priorityFeeGwei = GAS_TIER_PRIORITY[tier];

      // Calculate max fee with tier multiplier
      const maxFeePerGas = BigInt(Math.ceil(Number(baseFee) * multiplier));
      const maxPriorityFeePerGas = BigInt(Math.ceil(priorityFeeGwei * 1e9));

      // Ensure max fee covers base + priority
      const minMaxFee = baseFee + maxPriorityFeePerGas;
      const effectiveMaxFee = maxFeePerGas > minMaxFee ? maxFeePerGas : minMaxFee;

      const settings = {
        maxFeePerGas: effectiveMaxFee,
        maxPriorityFeePerGas,
        gasLimit: this.config.gasSettings?.gasLimit ?? 500_000,
      };

      console.log(`[NoteManager] Dynamic gas: ${(Number(effectiveMaxFee) / 1e9).toFixed(2)} Gwei (${tier}), base: ${(Number(baseFee) / 1e9).toFixed(2)} Gwei`);

      // Cache the result
      this.gasCache = { settings, fetchedAt: now };
      return settings;
    } catch (error) {
      console.warn('[NoteManager] Failed to fetch dynamic gas, using fallback:', error);
      return this.getStaticGasSettings();
    }
  }

  // ============================================================================
  // KeyVault Operations
  // ============================================================================

  /**
   * Create a new KeyVault for storing notes.
   *
   * @param options - Creation options
   * @returns KeyVault info including block number
   */
  async createKeyVault(options: CreateKeyVaultOptions): Promise<KeyVaultCreatedEvent> {
    const { secretAddress, masterKey, schema = DEFAULT_NOTE_SCHEMA } = options;

    // Generate new KV key
    const kvKey = NoteCrypto.generateKvKey();

    // Encrypt KV key with master key
    const encryptedKvKey = await NoteCrypto.encryptKvKey(kvKey, masterKey);

    // Prepare encrypted keys data (JSON with encrypted KV key)
    const keysData = JSON.stringify({
      version: '1.0.0',
      kvKey: encryptedKvKey,
    });
    const encryptedKeysBytes = new TextEncoder().encode(keysData);

    // Prepare schema definition
    const schemaBytes = NoteCrypto.schemaToBytes(schema);

    // Get contract
    const contract = new Contract(secretAddress, SECRET_ABI, this.signer);

    // Get dynamic gas settings
    const gasSettings = await this.getGasSettings();
    const tx = await contract.createKeyVault(
      encryptedKeysBytes,
      schemaBytes,
      {
        maxFeePerGas: gasSettings.maxFeePerGas,
        maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
        gasLimit: gasSettings.gasLimit,
      }
    );

    // Wait for confirmation
    const receipt = await tx.wait();

    // Parse event
    const event = receipt.logs
      .map((log: { topics: string[]; data: string }) => {
        try {
          return contract.interface.parseLog(log);
        } catch {
          return null;
        }
      })
      .find((e: { name: string } | null) => e?.name === 'KeyVaultCreated');

    if (!event) {
      throw new Error('KeyVaultCreated event not found in receipt');
    }

    return {
      blockNumber: Number(event.args.blockNumber),
      creator: event.args.creator,
      encryptedKeysData: keysData,
      schemaDefinition: JSON.stringify(schema),
      timestamp: Number(event.args.timestamp) * 1000,
      txHash: receipt.hash,
    };
  }

  /**
   * Get KeyVault status from contract.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @returns KeyVault info
   */
  async getKeyVaultStatus(
    secretAddress: string,
    kvBlock: number
  ): Promise<KeyVaultInfo> {
    const contract = new Contract(secretAddress, SECRET_ABI, this.provider);

    const [active, creator, creditBalance, ownerTotalCredits] = await contract.getKeyVaultStatus(kvBlock);

    console.log('[NoteManager] getKeyVaultStatus raw values:', {
      active,
      creator,
      creditBalance: creditBalance.toString(),
      ownerTotalCredits: ownerTotalCredits.toString(),
    });

    return {
      blockNumber: kvBlock,
      creator,
      creditBalance: BigInt(creditBalance),
      ownerTotalCredits: BigInt(ownerTotalCredits),
      active,
    };
  }

  /**
   * Check if the signer is the owner of this secret.
   * Owner = originOwner OR newbornOwner (for Identity mode)
   *
   * @param secretAddress - Secret contract address
   * @returns true if signer is owner
   */
  async isOwner(secretAddress: string): Promise<boolean> {
    const contract = new Contract(secretAddress, SECRET_ABI, this.provider);
    const signerAddress = await this.signer.getAddress();

    let originOwnerAddr = '';
    let newbornOwnerAddr = '';

    // Check originOwner (main owner address)
    try {
      originOwnerAddr = await contract.originOwner();
      console.log('[NoteManager] isOwner check:', {
        secretAddress: secretAddress.slice(0, 12) + '...',
        signerAddress: signerAddress.slice(0, 12) + '...',
        originOwner: originOwnerAddr,
        signerMatchesOrigin: originOwnerAddr.toLowerCase() === signerAddress.toLowerCase(),
      });
      if (originOwnerAddr.toLowerCase() === signerAddress.toLowerCase()) {
        return true;
      }
    } catch (e) {
      console.warn('[NoteManager] Could not get originOwner:', e);
    }

    // Check newbornOwner (Identity contract mode)
    try {
      newbornOwnerAddr = await contract.newbornOwner();
      console.log('[NoteManager] newbornOwner check:', {
        newbornOwner: newbornOwnerAddr,
        signerMatchesNewborn: newbornOwnerAddr.toLowerCase() === signerAddress.toLowerCase(),
      });
      if (newbornOwnerAddr.toLowerCase() === signerAddress.toLowerCase()) {
        return true;
      }
    } catch {
      // newbornOwner may not exist on older contracts
    }

    console.log('[NoteManager] isOwner result: FALSE - signer does not match originOwner or newbornOwner');
    return false;
  }

  /**
   * Check if a write operation can proceed with current credits.
   * Auto-detects if signer is owner to apply correct limits.
   *
   * V7 Credit Model (STRICTER than V6):
   * - ALL writes require vaultBalance >= 0 (including owner writes)
   * - Owner credits limit still applies (-10000)
   * - Team members have additional vault limit check (-1000)
   *
   * V6 vs V7 Difference:
   * - V6: Owners could write with negative vault balance
   * - V7: Contract requires vaultBalance >= 0 for ALL writes
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @param estimatedBytes - Estimated size of data to write
   * @returns Write capability check result
   */
  async canWrite(
    secretAddress: string,
    kvBlock: number,
    estimatedBytes: number
  ): Promise<WriteCapabilityCheck> {
    // Auto-detect if signer is owner
    const isOwnerWrite = await this.isOwner(secretAddress);
    const kvStatus = await this.getKeyVaultStatus(secretAddress, kvBlock);

    // Calculate estimated cost
    const estimatedCost =
      CREDIT_CONSTANTS.DATA_WRITE_BASE_COST +
      BigInt(estimatedBytes) * CREDIT_CONSTANTS.DATA_WRITE_PER_BYTE;

    // V7 Credit Model: Contract requires vaultBalance >= 0 for ALL writes
    // This is stricter than V6 where owners could write with negative vault balance
    const vaultNeedsCredits = kvStatus.creditBalance < 0n;
    const vaultRemaining = kvStatus.creditBalance - CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT;

    // V7 FIX: Use actual ownerTotalCredits instead of allowing overdraft
    const ownerRemaining = kvStatus.ownerTotalCredits;

    // V7: Vault must have positive balance for ANY write
    const vaultHasPositiveBalance = kvStatus.creditBalance >= 0n;

    // Team member additional check: vault balance can't go below -1000
    const vaultOverTeamLimit = kvStatus.creditBalance < CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT;
    const vaultCanAcceptTeamWrite = !vaultOverTeamLimit && vaultRemaining >= estimatedCost;
    const ownerCanAfford = ownerRemaining >= estimatedCost;

    // V7 CHANGE: Both owner and team member writes require positive vault balance
    // Owner writes: need positive vault balance + owner credits
    // Team member writes: need positive vault balance + vault capacity + owner credits
    const canWriteResult = isOwnerWrite
      ? (vaultHasPositiveBalance && ownerCanAfford)
      : (vaultHasPositiveBalance && vaultCanAcceptTeamWrite && ownerCanAfford);

    const result: WriteCapabilityCheck = {
      canWrite: canWriteResult,
      ownerCredits: kvStatus.ownerTotalCredits,
      ownerRemaining,
      estimatedCost,
      vaultBalance: kvStatus.creditBalance,
    };

    if (!canWriteResult) {
      // V7: Check vault balance first (applies to ALL writes)
      if (!vaultHasPositiveBalance) {
        result.reason = `V7 requires positive vault balance. Current balance: ${kvStatus.creditBalance}. Auto-funding will add credits if enabled.`;
      } else if (!isOwnerWrite && vaultOverTeamLimit) {
        result.reason = `Team member vault limit exceeded: balance ${kvStatus.creditBalance} is below limit ${CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT}. Create a new KeyVault for team members.`;
      } else if (!isOwnerWrite && !vaultCanAcceptTeamWrite) {
        result.reason = `Vault would exceed team member credit limit. Need ${estimatedCost} but vault only has ${vaultRemaining} capacity remaining.`;
      } else {
        result.reason = `Insufficient owner credits. Need ${estimatedCost} but only ${ownerRemaining} capacity remaining. Fund more credits via Registry.`;
      }
    }

    console.log('[NoteManager] canWrite check (V7 model):', {
      secretAddress: secretAddress.slice(0, 10) + '...',
      kvBlock,
      estimatedBytes,
      isOwnerWrite,
      estimatedCost: estimatedCost.toString(),
      vaultBalance: kvStatus.creditBalance.toString(),
      vaultHasPositiveBalance,
      vaultNeedsCredits,
      ownerCredits: kvStatus.ownerTotalCredits.toString(),
      ownerRemaining: ownerRemaining.toString(),
      canWrite: canWriteResult,
    });

    return result;
  }

  /**
   * Get comprehensive credit status for display.
   * Returns all 3 balances + owner status + warnings.
   *
   * V7 Credit Model:
   * - Registry: User's global credits (can fund secrets/vaults via fundVaultBalance)
   * - Owner: Per-secret credits (limit -10000)
   * - Vault: Per-KeyVault balance (team members blocked at -1000, owners bypass)
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @param registryAddress - Registry contract address (for fetching user's global credits)
   * @returns Comprehensive credit status
   */
  async getCreditStatus(
    secretAddress: string,
    kvBlock: number,
    registryAddress: string
  ): Promise<CreditStatus> {
    const kvStatus = await this.getKeyVaultStatus(secretAddress, kvBlock);
    const isOwnerResult = await this.isOwner(secretAddress);
    const signerAddress = await this.signer.getAddress();

    // Fetch registry balance (user's global credits)
    const REGISTRY_ABI = [
      'function getUserCredits(address user) view returns (uint256)',
    ];
    const registry = new Contract(registryAddress, REGISTRY_ABI, this.provider);
    const registryBalance = await registry.getUserCredits(signerAddress);

    const OWNER_LIMIT = CREDIT_CONSTANTS.CREDIT_LIMIT_PER_OWNER;
    const VAULT_LIMIT = CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT;

    const ownerCapacity = kvStatus.ownerTotalCredits - OWNER_LIMIT;
    const vaultCapacity = kvStatus.creditBalance - VAULT_LIMIT;
    const vaultOverLimit = kvStatus.creditBalance < VAULT_LIMIT;

    console.log('[NoteManager] getCreditStatus:', {
      signerAddress: signerAddress.slice(0, 10) + '...',
      isOwner: isOwnerResult,
      registryBalance: registryBalance.toString(),
      ownerCredits: kvStatus.ownerTotalCredits.toString(),
      ownerCapacity: ownerCapacity.toString(),
      vaultBalance: kvStatus.creditBalance.toString(),
      vaultCapacity: vaultCapacity.toString(),
      vaultOverLimit,
    });

    return {
      registryBalance: BigInt(registryBalance),
      ownerCredits: kvStatus.ownerTotalCredits,
      ownerCapacity,
      vaultBalance: kvStatus.creditBalance,
      vaultCapacity,
      vaultOverLimit,
      isOwner: isOwnerResult,
    };
  }

  /**
   * Estimate write cost for a given data size.
   *
   * @param dataSize - Size of data in bytes
   * @returns Estimated credit cost
   */
  estimateWriteCost(dataSize: number): bigint {
    return CREDIT_CONSTANTS.DATA_WRITE_BASE_COST +
      BigInt(dataSize) * CREDIT_CONSTANTS.DATA_WRITE_PER_BYTE;
  }

  /**
   * Fund a secret's owner credits via Registry.
   *
   * This transfers credits from the caller's Registry balance to the
   * secret's owner credits, enabling more note writes and operations.
   *
   * ## V6 Architecture
   * - User first deposits POL to Registry via depositCredits()
   * - Then transfers credits to specific secrets via fundSecretCredits()
   * - Secret.fundOperations() is restricted to factory/registry callers
   * - Registry acts as the intermediary for public funding
   *
   * @param registryAddress - Registry contract address
   * @param secretAddress - Secret contract address to fund
   * @param credits - Number of credits to transfer from Registry balance
   * @returns Transaction hash and block number
   */
  async fundSecretCredits(
    registryAddress: string,
    secretAddress: string,
    credits: number
  ): Promise<{ txHash: string; blockNumber: number; creditsAdded: number }> {
    const REGISTRY_ABI = [
      'function fundSecretCredits(address secretContract, uint256 amount) external',
      'function getUserCredits(address user) view returns (uint256)',
    ];

    const registry = new Contract(registryAddress, REGISTRY_ABI, this.signer);
    const gasSettings = await this.getGasSettings();

    // Check user has enough Registry credits first
    const signerAddress = await this.signer.getAddress();
    const userCredits = await registry.getUserCredits(signerAddress);

    console.log('[NoteManager] Funding secret credits via Registry:', {
      registryAddress,
      secretAddress,
      credits,
      userRegistryCredits: userCredits.toString(),
    });

    if (BigInt(userCredits) < BigInt(credits)) {
      throw new Error(
        `Insufficient Registry credits. Have: ${userCredits.toString()}, need: ${credits}. ` +
        `Deposit POL to Registry first using the "+" button.`
      );
    }

    const tx = await registry.fundSecretCredits(secretAddress, credits, {
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
      gasLimit: 150_000,
    });

    console.log('[NoteManager] fundSecretCredits tx sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[NoteManager] fundSecretCredits confirmed at block:', receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      creditsAdded: credits,
    };
  }

  /**
   * Fund a specific vault's credit balance via V7 Registry.
   *
   * V7 introduced fundVaultBalance to allow funding specific KeyVault balances,
   * fixing the V6 bug where vault balances could only decrease.
   *
   * ## V7 Credit Flow
   * ```
   * User Registry Credits
   *     │ Registry.fundVaultBalance(secret, kvBlock, amount)
   *     ▼
   * Secret.fundVaultCredits(kvBlock, amount)
   *     │
   *     ▼
   * KeyVault.creditBalance += amount
   * ```
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number to fund
   * @param credits - Number of credits to transfer from Registry balance
   * @returns Transaction result
   */
  async fundVaultBalance(
    secretAddress: string,
    kvBlock: number,
    credits: number
  ): Promise<{ txHash: string; blockNumber: number; creditsAdded: number }> {
    if (!this.config.registryAddress) {
      throw new Error(
        'Registry address not configured. Set registryAddress in NoteManagerConfig to enable vault funding.'
      );
    }

    const registry = new Contract(this.config.registryAddress, REGISTRY_V7_ABI, this.signer);
    const gasSettings = await this.getGasSettings();

    // Check user has enough Registry credits first
    const signerAddress = await this.signer.getAddress();
    const userCredits = await registry.getUserCredits(signerAddress);

    console.log('[NoteManager] Funding vault balance via V7 Registry:', {
      registryAddress: this.config.registryAddress,
      secretAddress,
      kvBlock,
      credits,
      userRegistryCredits: userCredits.toString(),
    });

    if (BigInt(userCredits) < BigInt(credits)) {
      throw new Error(
        `Insufficient Registry credits. Have: ${userCredits.toString()}, need: ${credits}. ` +
        `Deposit POL to Registry first using the "+" button.`
      );
    }

    const tx = await registry.fundVaultBalance(secretAddress, kvBlock, credits, {
      maxFeePerGas: gasSettings.maxFeePerGas,
      maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
      gasLimit: 200_000, // Slightly higher for fundVaultBalance
    });

    console.log('[NoteManager] fundVaultBalance tx sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[NoteManager] fundVaultBalance confirmed at block:', receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      creditsAdded: credits,
    };
  }

  /**
   * Automatically fund a vault if its balance is insufficient for V7.
   *
   * V7 requires vaultBalance >= 0 for ALL writes.
   * This method checks the vault balance and funds it if needed.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @returns True if funding was performed, false if not needed
   */
  async autoFundVaultIfNeeded(
    secretAddress: string,
    kvBlock: number
  ): Promise<{ funded: boolean; amount?: number; txHash?: string }> {
    // Check if auto-funding is enabled
    if (!this.config.autoFundEnabled) {
      console.log('[NoteManager] Auto-funding disabled, skipping');
      return { funded: false };
    }

    if (!this.config.registryAddress) {
      console.log('[NoteManager] Registry address not configured, cannot auto-fund');
      return { funded: false };
    }

    // Check current vault balance
    const kvStatus = await this.getKeyVaultStatus(secretAddress, kvBlock);
    const vaultBalance = kvStatus.creditBalance;

    // V7: Vault needs funding if balance < 0
    if (vaultBalance >= 0n) {
      console.log('[NoteManager] Vault balance is positive, no funding needed:', vaultBalance.toString());
      return { funded: false };
    }

    // Calculate amount to fund: configured amount (default 25K)
    const fundAmount = this.config.autoFundAmount ?? 25000;

    console.log('[NoteManager] V7 Auto-funding vault:', {
      secretAddress: secretAddress.slice(0, 10) + '...',
      kvBlock,
      currentBalance: vaultBalance.toString(),
      fundAmount,
    });

    try {
      const result = await this.fundVaultBalance(secretAddress, kvBlock, fundAmount);
      console.log('[NoteManager] Auto-funding complete:', {
        txHash: result.txHash,
        creditsAdded: result.creditsAdded,
      });
      return {
        funded: true,
        amount: fundAmount,
        txHash: result.txHash,
      };
    } catch (error) {
      console.error('[NoteManager] Auto-funding failed:', error);
      throw new Error(
        `V7 auto-funding failed: ${error instanceof Error ? error.message : String(error)}. ` +
        `Vault balance is ${vaultBalance}, which is below the V7 minimum of 0. ` +
        `Please add credits manually via the Registry.`
      );
    }
  }

  /**
   * Ensure write capability with comprehensive auto-funding.
   *
   * This method combines canWrite() check with intelligent auto-funding:
   * 1. Checks current write capability
   * 2. If vault balance is negative (V7), auto-funds from registry
   * 3. If owner credits are low, funds from registry balance
   * 4. Re-checks write capability and returns result
   *
   * Does NOT purchase credits with POL - that should be handled at app level.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @param estimatedBytes - Estimated data size for cost calculation
   * @returns Result with canWrite status and funding details
   *
   * @example
   * ```typescript
   * const result = await noteManager.ensureCanWrite(secretAddr, kvBlock, 500);
   * if (!result.canWrite) {
   *   console.log('Cannot write:', result.reason);
   *   if (result.needsPOLPurchase) {
   *     // App can offer to buy credits with POL
   *   }
   * }
   * ```
   */
  async ensureCanWrite(
    secretAddress: string,
    kvBlock: number,
    estimatedBytes: number
  ): Promise<{
    canWrite: boolean;
    reason?: string;
    fundingPerformed: boolean;
    vaultFunded?: number;
    ownerFunded?: number;
    needsPOLPurchase?: boolean;
    creditStatus?: CreditStatus;
  }> {
    // Check if auto-funding is enabled and registry configured
    if (!this.config.autoFundEnabled) {
      const check = await this.canWrite(secretAddress, kvBlock, estimatedBytes);
      return {
        canWrite: check.canWrite,
        reason: check.reason,
        fundingPerformed: false,
      };
    }

    if (!this.config.registryAddress) {
      const check = await this.canWrite(secretAddress, kvBlock, estimatedBytes);
      return {
        canWrite: check.canWrite,
        reason: check.reason ? `${check.reason} (Registry not configured for auto-funding)` : undefined,
        fundingPerformed: false,
      };
    }

    // Initial write check
    let writeCheck = await this.canWrite(secretAddress, kvBlock, estimatedBytes);

    if (writeCheck.canWrite) {
      return { canWrite: true, fundingPerformed: false };
    }

    console.log('[NoteManager] ensureCanWrite: Cannot write, attempting auto-funding...');
    console.log('[NoteManager] Reason:', writeCheck.reason);

    // Get comprehensive credit status
    const creditStatus = await this.getCreditStatus(
      secretAddress,
      kvBlock,
      this.config.registryAddress
    );

    const fundAmount = this.config.autoFundAmount ?? 25000;
    let fundingPerformed = false;
    let vaultFunded = 0;
    let ownerFunded = 0;

    // V7: Fund vault balance FIRST if negative (required for all writes)
    const vaultNeedsCredits = creditStatus.vaultBalance < 0n;
    if (vaultNeedsCredits) {
      console.log(`[NoteManager] V7: Vault balance is ${creditStatus.vaultBalance}, auto-funding ${fundAmount} credits...`);

      if (creditStatus.registryBalance >= BigInt(fundAmount)) {
        try {
          await this.fundVaultBalance(secretAddress, kvBlock, fundAmount);
          vaultFunded = fundAmount;
          fundingPerformed = true;
          console.log('[NoteManager] V7 vault auto-funded successfully');
        } catch (vaultFundErr) {
          console.error('[NoteManager] V7 vault auto-fund failed:', vaultFundErr);
        }
      } else {
        console.log('[NoteManager] Insufficient registry credits for vault funding:', creditStatus.registryBalance.toString());
      }
    }

    // Check owner credits (V7 requires ownerCredits >= cost)
    const estimatedCost = writeCheck.estimatedCost;
    const ownerNeedsCredits = creditStatus.ownerCredits < estimatedCost;

    if (creditStatus.isOwner && ownerNeedsCredits) {
      const neededCredits = Number(estimatedCost - creditStatus.ownerCredits) + 1000; // Add buffer

      // Check remaining registry balance after vault funding
      const remainingRegistry = creditStatus.registryBalance - BigInt(vaultFunded);

      if (remainingRegistry >= BigInt(neededCredits)) {
        console.log(`[NoteManager] Auto-funding ${neededCredits} owner credits from Registry...`);
        try {
          await this.fundSecretCredits(this.config.registryAddress, secretAddress, neededCredits);
          ownerFunded = neededCredits;
          fundingPerformed = true;
          console.log('[NoteManager] Owner credits auto-funded successfully');
        } catch (fundErr) {
          console.error('[NoteManager] Owner credits auto-fund failed:', fundErr);
        }
      } else {
        console.log('[NoteManager] Insufficient registry credits for owner funding. Need POL purchase.');
      }
    }

    // Team member case: vault may need funding if over limit
    if (!creditStatus.isOwner && creditStatus.vaultOverLimit && !vaultFunded) {
      const neededVaultCredits = Number(estimatedCost) + 1500; // Buffer to get above limit

      if (creditStatus.registryBalance >= BigInt(neededVaultCredits)) {
        console.log(`[NoteManager] Auto-funding vault for team member with ${neededVaultCredits} credits...`);
        try {
          await this.fundVaultBalance(secretAddress, kvBlock, neededVaultCredits);
          vaultFunded = neededVaultCredits;
          fundingPerformed = true;
          console.log('[NoteManager] Team member vault auto-funded successfully');
        } catch (vaultFundErr) {
          console.error('[NoteManager] Team member vault auto-fund failed:', vaultFundErr);
        }
      }
    }

    // Re-check canWrite after funding attempts
    if (fundingPerformed) {
      writeCheck = await this.canWrite(secretAddress, kvBlock, estimatedBytes);
      console.log('[NoteManager] Re-checked canWrite after auto-funding:', writeCheck.canWrite);
    }

    // Determine if POL purchase is needed (registry balance depleted)
    const updatedStatus = fundingPerformed
      ? await this.getCreditStatus(secretAddress, kvBlock, this.config.registryAddress)
      : creditStatus;

    const needsPOLPurchase = !writeCheck.canWrite && updatedStatus.registryBalance < estimatedCost;

    return {
      canWrite: writeCheck.canWrite,
      reason: writeCheck.reason,
      fundingPerformed,
      vaultFunded: vaultFunded || undefined,
      ownerFunded: ownerFunded || undefined,
      needsPOLPurchase,
      creditStatus: updatedStatus,
    };
  }

  // ============================================================================
  // IPFS Operations (for large content)
  // ============================================================================

  /**
   * Upload content to IPFS via Pinata.
   *
   * Used automatically when note content exceeds ipfsSizeThreshold.
   * Returns the IPFS CID (Content Identifier).
   *
   * @param content - Content to upload (will be stored as-is)
   * @param metadata - Optional metadata for Pinata pinning
   * @returns IPFS CID string
   */
  private async uploadToIPFS(
    content: string,
    metadata?: { name?: string; keyvalues?: Record<string, string> }
  ): Promise<string> {
    if (!this.config.ipfs) {
      throw new Error(
        'IPFS not configured. Set ipfs.apiKey and ipfs.secretKey in NoteManagerConfig to enable large content support.'
      );
    }

    const endpoint = this.config.ipfs.endpoint ?? IPFS_DEFAULTS.ENDPOINT;

    console.log('[NoteManager] Uploading content to IPFS...', {
      contentSize: content.length,
      endpoint,
    });

    const pinataData = {
      pinataContent: content,
      pinataMetadata: metadata ? {
        name: metadata.name || `note-${Date.now()}`,
        keyvalues: metadata.keyvalues || {},
      } : undefined,
    };

    const response = await fetch(`${endpoint}/pinning/pinJSONToIPFS`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'pinata_api_key': this.config.ipfs.apiKey,
        'pinata_secret_api_key': this.config.ipfs.secretKey,
      },
      body: JSON.stringify(pinataData),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`IPFS upload failed: ${response.status} - ${errorText}`);
    }

    const result = await response.json();
    const cid = result.IpfsHash;

    console.log('[NoteManager] Content uploaded to IPFS:', {
      cid,
      originalSize: content.length,
    });

    return cid;
  }

  /**
   * Fetch content from IPFS via gateway.
   *
   * @param cid - IPFS CID to fetch
   * @returns Content string
   */
  async fetchFromIPFS(cid: string): Promise<string> {
    const gateway = this.config.ipfs?.gateway ?? IPFS_DEFAULTS.GATEWAY;
    const url = `${gateway}/ipfs/${cid}`;

    console.log('[NoteManager] Fetching from IPFS:', { cid, url });

    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`IPFS fetch failed: ${response.status} - ${response.statusText}`);
    }

    // The content was stored as JSON with pinataContent wrapper
    const data = await response.json();

    // Handle both raw content and Pinata-wrapped content
    const content = typeof data === 'string' ? data : data.pinataContent ?? JSON.stringify(data);

    console.log('[NoteManager] Fetched from IPFS:', { cid, contentSize: content.length });

    return content;
  }

  /**
   * Check if content should be uploaded to IPFS based on size.
   *
   * @param contentSize - Size of encrypted content in bytes
   * @returns true if content should go to IPFS
   */
  private shouldUseIPFS(contentSize: number): boolean {
    const threshold = this.config.ipfsSizeThreshold ?? IPFS_DEFAULTS.SIZE_THRESHOLD;
    const shouldUse = contentSize > threshold;

    if (shouldUse) {
      console.log(`[NoteManager] Content size ${contentSize} exceeds threshold ${threshold}, will use IPFS`);
    }

    return shouldUse;
  }

  // ============================================================================
  // Identity Mode (PATH 3 / executeTransaction)
  // ============================================================================

  /**
   * Write data via IdentityContract's executeTransaction.
   *
   * This is the correct pattern for Identity-owned secrets:
   * - The IdentityContract is the owner of the Secret
   * - Device (rivet) calls identityContract.executeTransaction(secretAddr, 0, writeDataCalldata)
   * - IdentityContract executes writeData with PATH 1 (direct owner: v=0, r=0, s=0)
   *
   * @param secretAddress - Secret contract address
   * @param identityContract - Identity contract address
   * @param writeDataCalldata - Encoded writeData call
   * @returns Transaction result
   */
  private async writeViaIdentity(
    secretAddress: string,
    identityContractAddress: string,
    writeDataCalldata: string
  ): Promise<{ txHash: string; blockNumber: number }> {
    const identityContract = new Contract(identityContractAddress, IDENTITY_ABI, this.signer);
    const gasSettings = await this.getGasSettings();

    console.log('[NoteManager] PATH 3: Executing writeData via IdentityContract...');
    console.log('[NoteManager] Identity contract:', identityContractAddress);
    console.log('[NoteManager] Target secret:', secretAddress);

    const tx = await identityContract.executeTransaction(
      secretAddress,
      0, // value
      writeDataCalldata,
      {
        maxFeePerGas: gasSettings.maxFeePerGas,
        maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
        gasLimit: gasSettings.gasLimit,
      }
    );

    const receipt = await tx.wait();
    console.log('[NoteManager] PATH 3 complete. TX:', receipt.hash);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
    };
  }

  // ============================================================================
  // Note Operations
  // ============================================================================

  /**
   * Write an encrypted note to a KeyVault.
   *
   * Authorization Paths:
   * - PATH 1 (direct owner): v=0, r=0, s=0 - when no writeAuthorization provided
   * - PATH 2 (ECDSA delegation): v>=27 - when writeAuthorization is provided
   * - PATH 3 (Identity/EIP-1271): 2-TX flow
   *   - TX1: submitRivetSignature(rawSignature) → signatureHash
   *   - TX2: writeData(v=0, r=identityContract, s=signatureHash)
   *
   * V7 Auto-Funding:
   * - Before writing, checks if vault balance is negative
   * - If autoFundEnabled (default: true), automatically funds vault with autoFundAmount (default: 25K)
   * - This prevents V7 transaction reverts due to negative vault balance
   *
   * IPFS Auto-Routing:
   * - If content exceeds ipfsSizeThreshold (default: 100KB), uploads to IPFS first
   * - Only the IPFS CID reference is stored on-chain
   * - Prevents "oversized data" errors on Polygon (131KB limit)
   * - Requires ipfs config (apiKey, secretKey) to be set
   *
   * @param options - Write options
   * @returns Write result
   */
  async writeNote(options: WriteNoteOptions): Promise<WriteNoteResult> {
    const {
      secretAddress,
      kvBlock,
      content,
      kvKey,
      files,
      version,
      previousNote,
      metadata,
      writeAuthorization,
    } = options;

    // V7 Auto-Funding: Check and fund vault if balance is negative
    // This must happen BEFORE the write to prevent V7 revert
    try {
      const fundResult = await this.autoFundVaultIfNeeded(secretAddress, kvBlock);
      if (fundResult.funded) {
        console.log(`[NoteManager] V7 Auto-funded vault with ${fundResult.amount} credits (TX: ${fundResult.txHash})`);
      }
    } catch (autoFundError) {
      // Log but continue - the write will fail if vault balance is still negative
      console.warn('[NoteManager] V7 auto-funding failed:', autoFundError);
      // Don't throw here - let the write attempt proceed and give a clearer error
    }

    // Get author address
    const author = await this.signer.getAddress();

    // IPFS Auto-Routing: Check if content is too large for on-chain storage
    // If so, encrypt content first, upload encrypted to IPFS, store reference on-chain
    let effectiveContent = content;
    let ipfsCid: string | undefined;

    if (this.shouldUseIPFS(content.length)) {
      if (!this.config.ipfs) {
        throw new Error(
          `Content size (${content.length} bytes) exceeds on-chain limit. ` +
          `Configure ipfs.apiKey and ipfs.secretKey in NoteManagerConfig to enable IPFS storage for large content.`
        );
      }

      console.log('[NoteManager] Content too large for on-chain, encrypting and uploading to IPFS...');

      // SECURITY: Encrypt content BEFORE uploading to IPFS
      // This ensures the plaintext never leaves the client unencrypted
      const encryptedForIPFS = await NoteCrypto.encryptContent(content, kvKey);

      // Upload encrypted content to IPFS (content is now encrypted!)
      ipfsCid = await this.uploadToIPFS(JSON.stringify(encryptedForIPFS), {
        name: `note-${secretAddress.slice(0, 10)}-${Date.now()}`,
        keyvalues: {
          secretAddress,
          kvBlock: kvBlock.toString(),
          type: 'encrypted-note-content',
        },
      });

      // Replace content with IPFS reference marker (CID will be encrypted in the note payload)
      const ipfsRef: IPFSNoteReference = {
        type: 'ipfs-note-content',
        cid: ipfsCid,
        originalSize: content.length,
        version: '1.0',
      };
      effectiveContent = JSON.stringify(ipfsRef);

      console.log('[NoteManager] Encrypted content uploaded to IPFS, storing reference on-chain:', {
        cid: ipfsCid,
        originalSize: content.length,
        encryptedSize: JSON.stringify(encryptedForIPFS).length,
        referenceSize: effectiveContent.length,
      });
    }

    // Encrypt note (the IPFS reference itself is also encrypted on-chain)
    const encryptedNote = await NoteCrypto.encryptNote(
      effectiveContent,
      kvKey,
      author,
      { files, version, previousNote, metadata }
    );

    // Convert to bytes for contract
    const noteBytes = NoteCrypto.encryptedNoteToBytes(encryptedNote);

    // Get contract
    const contract = new Contract(secretAddress, SECRET_ABI, this.signer);

    // Determine authorization path
    // PATH 1 (direct owner): v=0, r=0, s=0, expiresAt=0
    // PATH 2 (ECDSA delegation): v>=27, r=sig.r, s=sig.s, expiresAt=auth.expiresAt
    // PATH 3 (Identity/EIP-1271): v=0, r=identityContract, s=signatureHash
    const gasSettings = await this.getGasSettings();

    let authV: number;
    let authR: string;
    let authS: string;
    let expiresAt: number;

    if (writeAuthorization?.isIdentityMode) {
      // PATH 3: Identity mode - use executeTransaction via IdentityContract
      // The IdentityContract is the owner, so it can call writeData with PATH 1 (direct owner)
      console.log('[NoteManager] Using PATH 3 (Identity/executeTransaction) for rivet write');

      if (!writeAuthorization.identityContract) {
        throw new Error('Identity mode requires identityContract in WriteAuthorization');
      }

      // Build writeData calldata with PATH 1 (direct owner: v=0, r=0, s=0)
      // The IdentityContract IS the owner, so it doesn't need delegation
      const writeDataCalldata = contract.interface.encodeFunctionData('writeData', [
        kvBlock,
        noteBytes,
        0, // expiresAt (not needed for direct owner)
        0, // v = 0 (direct owner)
        ZeroHash, // r = 0
        ZeroHash, // s = 0
      ]);

      // Execute via IdentityContract
      const result = await this.writeViaIdentity(
        secretAddress,
        writeAuthorization.identityContract,
        writeDataCalldata
      );

      // Estimate note index
      const noteIndex = await this.estimateNoteIndex(secretAddress, kvBlock, result.blockNumber);

      return {
        txHash: result.txHash,
        blockNumber: result.blockNumber,
        noteIndex,
        creditsCharged: 0, // Not available from executeTransaction result
      };
    } else if (writeAuthorization) {
      // PATH 2: Use pre-signed authorization from owner (ECDSA)
      console.log('[NoteManager] Using PATH 2 (ECDSA delegation) for team member write');
      console.log('[NoteManager] WriteAuth details:', {
        v: writeAuthorization.v,
        r: writeAuthorization.r?.slice(0, 20) + '...',
        s: writeAuthorization.s?.slice(0, 20) + '...',
        expiresAt: writeAuthorization.expiresAt,
        hasR: !!writeAuthorization.r,
        hasS: !!writeAuthorization.s,
        rLength: writeAuthorization.r?.length,
        sLength: writeAuthorization.s?.length,
      });
      authV = writeAuthorization.v;
      authR = writeAuthorization.r;
      authS = writeAuthorization.s;
      expiresAt = writeAuthorization.expiresAt;
    } else {
      // PATH 1: Direct owner - use zeros
      console.log('[NoteManager] Using PATH 1 (direct owner) for write');
      authV = 0;
      authR = ZeroHash;
      authS = ZeroHash;
      expiresAt = 0;
    }

    // Log the exact values being sent to the contract
    console.log('[NoteManager] Calling writeData with:', {
      kvBlock,
      noteLength: noteBytes.length,
      expiresAt,
      authV,
      authR: authR?.slice(0, 20) + '...',
      authS: authS?.slice(0, 20) + '...',
      author,
      secretAddress,
    });

    // Pre-flight verification: Check if we can recover the expected signer
    if (writeAuthorization && authV >= 27) {
      try {
        // Check for kvBlock mismatch (critical for signature verification)
        const authKvBlock = (writeAuthorization as any).keyVaultBlock;
        if (authKvBlock && authKvBlock !== kvBlock) {
          console.error('[NoteManager] ⚠️ KVBLOCK MISMATCH DETECTED!');
          console.error(`[NoteManager]   Passed kvBlock: ${kvBlock}`);
          console.error(`[NoteManager]   WriteAuth keyVaultBlock: ${authKvBlock}`);
          console.error('[NoteManager]   Signature was signed for different kvBlock - WILL FAIL!');
        }

        // Recompute the hash that the contract will compute
        // IMPORTANT: Contract uses abi.encodePacked, NOT abi.encode
        // solidityPackedKeccak256 matches keccak256(abi.encodePacked(...))
        const messageHash = solidityPackedKeccak256(
          ['address', 'uint256', 'address', 'uint256'],
          [secretAddress, kvBlock, author, expiresAt]
        );

        // Apply EIP-191 prefix (same as signMessage does)
        const digest = hashMessage(getBytes(messageHash));

        // Recover signer
        const sig = Signature.from({ v: authV, r: authR, s: authS });
        const recoveredSigner = recoverAddress(digest, sig);

        // Get the KeyVault creator and newbornOwner
        const kvStatus = await this.getKeyVaultStatus(secretAddress, kvBlock);

        // Also check newbornOwner - contract might verify against this instead
        let newbornOwner = '';
        try {
          newbornOwner = await contract.newbornOwner();
        } catch (e) {
          console.warn('[NoteManager] Could not get newbornOwner:', e);
        }

        // V6 Credit Model: Vault limit (-1000) only applies to TEAM MEMBER writes
        // Owners can write without vault limit, but team members are restricted
        const vaultCreditBalance = kvStatus.creditBalance;
        const vaultOverLimit = vaultCreditBalance < CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT;

        console.log('[NoteManager] Pre-flight verification:', JSON.stringify({
          usedKvBlock: kvBlock,
          authKvBlock: authKvBlock || 'N/A',
          kvBlockMatch: authKvBlock ? kvBlock === authKvBlock : 'N/A',
          messageHash: messageHash.slice(0, 20) + '...',
          recoveredSigner,
          kvCreator: kvStatus.creator,
          newbornOwner,
          signerMatchesCreator: recoveredSigner.toLowerCase() === kvStatus.creator.toLowerCase(),
          signerMatchesNewborn: recoveredSigner.toLowerCase() === newbornOwner.toLowerCase(),
          authorMatchesWriter: author.toLowerCase() === (writeAuthorization as any).authorizedWriter?.toLowerCase(),
          vaultCreditBalance: vaultCreditBalance.toString(),
          vaultCreditLimit: CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT.toString(),
          vaultOverLimit,
        }, null, 2));

        // CRITICAL: Check vault credit limit for TEAM MEMBER writes only
        // V6 Contract: Owners can write without vault limit, but team members have -1000 limit
        // If writeAuthorization is provided, this is a team member write (PATH 2/3)
        if (writeAuthorization && vaultOverLimit) {
          console.error('[NoteManager] ⚠️ TEAM MEMBER VAULT LIMIT EXCEEDED!');
          console.error(`[NoteManager]   Vault balance: ${vaultCreditBalance}`);
          console.error(`[NoteManager]   Team member limit: ${CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT}`);
          console.error('[NoteManager]   V6 Contract: Owners have no vault limit, but team members are limited to -1000 per vault.');
          console.error('[NoteManager]   This vault has too much accumulated usage for team member writes.');
          console.error('[NoteManager]   Solution: Create a new KeyVault for bidirectional communication.');
          throw new Error(`Team member vault limit exceeded: vault balance ${vaultCreditBalance} is below the team member limit ${CREDIT_CONSTANTS.CREDIT_LIMIT_PER_VAULT}. Owner writes don't have this limit. Create a new KeyVault for team member responses.`);
        }

        if (recoveredSigner.toLowerCase() !== kvStatus.creator.toLowerCase() &&
            recoveredSigner.toLowerCase() !== newbornOwner.toLowerCase()) {
          console.warn('[NoteManager] ⚠️ SIGNATURE MISMATCH: Recovered signer does not match KeyVault creator OR newbornOwner!');
          console.warn('[NoteManager] This transaction will likely fail.');
          console.warn('[NoteManager] Recovered:', recoveredSigner);
          console.warn('[NoteManager] Expected (creator):', kvStatus.creator);
          console.warn('[NoteManager] Expected (newborn):', newbornOwner);
        }
      } catch (verifyError) {
        console.warn('[NoteManager] Pre-flight verification failed:', verifyError);
      }
    }

    // Submit transaction with detailed logging
    let tx;
    try {
      console.log('[NoteManager] Submitting writeData transaction...');
      tx = await contract.writeData(
        kvBlock,
        noteBytes,
        expiresAt,
        authV,
        authR,
        authS,
        {
          maxFeePerGas: gasSettings.maxFeePerGas,
          maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
          gasLimit: gasSettings.gasLimit,
        }
      );
      console.log('[NoteManager] Transaction submitted, hash:', tx.hash);
    } catch (submitError) {
      console.error('[NoteManager] Transaction submission FAILED:', submitError);
      throw submitError;
    }

    // Wait for confirmation
    console.log('[NoteManager] Waiting for confirmation...');
    let receipt;
    try {
      receipt = await tx.wait();
      console.log('[NoteManager] Transaction confirmed, block:', receipt.blockNumber);
    } catch (confirmError) {
      console.error('[NoteManager] Transaction confirmation FAILED:', confirmError);
      throw confirmError;
    }

    // Parse event
    const event = receipt.logs
      .map((log: { topics: string[]; data: string }) => {
        try {
          return contract.interface.parseLog(log);
        } catch {
          return null;
        }
      })
      .find((e: { name: string } | null) => e?.name === 'DataWritten');

    if (!event) {
      throw new Error('DataWritten event not found in receipt');
    }

    // Calculate note index from event data or estimate
    // Note: The contract doesn't return note index directly
    // We estimate based on timestamp ordering
    const noteIndex = await this.estimateNoteIndex(secretAddress, kvBlock, receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      noteIndex,
      creditsCharged: Number(event.args.creditsCost),
    };
  }

  /**
   * Read and decrypt notes from a KeyVault.
   *
   * First tries to read from local database if configured.
   * Falls back to chain query if database is empty or not configured.
   *
   * @param options - Read options
   * @returns Array of decrypted notes
   */
  async readNotes(options: ReadNotesOptions): Promise<Note[]> {
    // Try local database first if available
    if (this.config.database) {
      const dbNotes = await this.readNotesFromDB(options);
      if (dbNotes.length > 0) {
        console.log(`[NoteManager] Read ${dbNotes.length} notes from local database`);
        return dbNotes;
      }
      console.log(`[NoteManager] No notes in local database, querying chain`);
    }

    // Fall back to chain query
    return this.readNotesFromChain(options);
  }

  /**
   * Read notes from local database and decrypt if needed.
   *
   * @param options - Read options
   * @returns Array of decrypted notes
   */
  private async readNotesFromDB(options: ReadNotesOptions): Promise<Note[]> {
    const { secretAddress, kvBlock, kvKey, fromIndex = 0, count } = options;

    if (!this.config.database) {
      return [];
    }

    const storedNotes = await this.config.database.notes.getByKeyVault(secretAddress, kvBlock);
    if (storedNotes.length === 0) {
      return [];
    }

    // Sort by noteId (which includes index)
    storedNotes.sort((a, b) => a.noteId.localeCompare(b.noteId));

    // Apply pagination
    const startIndex = fromIndex;
    const endIndex = count !== undefined ? startIndex + count : storedNotes.length;
    const selectedNotes = storedNotes.slice(startIndex, endIndex);

    const notes: Note[] = [];

    for (let i = 0; i < selectedNotes.length; i++) {
      const stored = selectedNotes[i];
      const noteIndex = startIndex + i;

      // If already decrypted, check for IPFS reference and return the content
      if (stored.isDecrypted && stored.content) {
        let content = stored.content;
        let ipfsMetadata: Record<string, unknown> | undefined;

        // Check if content is an IPFS reference (needs to fetch and decrypt from IPFS)
        const ipfsRef = parseIPFSReference(content);
        if (ipfsRef) {
          try {
            // Fetch encrypted content from IPFS
            const encryptedJson = await this.fetchFromIPFS(ipfsRef.cid);
            const encryptedData = JSON.parse(encryptedJson);

            // Decrypt the content
            content = await NoteCrypto.decryptContent(encryptedData, kvKey);
            ipfsMetadata = { ipfsResolved: true, ipfsCid: ipfsRef.cid };
          } catch (ipfsError) {
            console.error(`[NoteManager] Failed to fetch/decrypt IPFS content for cached note ${noteIndex}:`, ipfsError);
            ipfsMetadata = { ipfsError: String(ipfsError), ipfsCid: ipfsRef.cid };
          }
        }

        notes.push({
          index: noteIndex,
          content,
          author: stored.writerAddress || '',
          timestamp: stored.timestamp || Date.now(),
          blockNumber: stored.writeBlockNumber || 0,
          metadata: ipfsMetadata,
        });
        continue;
      }

      // Need to decrypt from encryptedData
      if (!stored.encryptedData) {
        console.warn(`[NoteManager] Note ${noteIndex} has no encrypted data to decrypt`);
        notes.push({
          index: noteIndex,
          content: '',
          author: stored.writerAddress || '',
          timestamp: stored.timestamp || Date.now(),
          blockNumber: stored.writeBlockNumber || 0,
          metadata: { error: 'No encrypted data' },
        });
        continue;
      }

      try {
        // Parse encrypted data
        const hexData = stored.encryptedData.startsWith('0x')
          ? stored.encryptedData.slice(2)
          : stored.encryptedData;
        const dataBytes = hexToBytes(hexData);
        const encryptedNote = NoteCrypto.bytesToEncryptedNote(dataBytes);

        // Decrypt
        const note = await NoteCrypto.decryptNote(
          encryptedNote.encrypted,
          encryptedNote.iv,
          kvKey,
          noteIndex,
          stored.writeBlockNumber || 0
        );

        // Check if content is an IPFS reference and resolve it
        const ipfsRef = parseIPFSReference(note.content);
        if (ipfsRef) {
          try {
            // Fetch encrypted content from IPFS
            const encryptedJson = await this.fetchFromIPFS(ipfsRef.cid);
            const encryptedData = JSON.parse(encryptedJson);

            // Decrypt the content (IPFS content is encrypted before upload)
            note.content = await NoteCrypto.decryptContent(encryptedData, kvKey);
            note.metadata = { ...note.metadata, ipfsResolved: true, ipfsCid: ipfsRef.cid };
          } catch (ipfsError) {
            console.error(`[NoteManager] Failed to fetch/decrypt IPFS content for note ${noteIndex}:`, ipfsError);
            note.metadata = { ...note.metadata, ipfsError: String(ipfsError), ipfsCid: ipfsRef.cid };
          }
        }

        notes.push(note);

        // Update DB with decrypted content (stores resolved content for IPFS notes)
        await this.config.database.notes.put({
          noteId: stored.noteId,
          chainId: this.config.chainId,
          secretContract: stored.secretContract,
          keyVaultBlock: stored.keyVaultBlock,
          title: '',
          content: note.content,
          contentType: 'text',
          encryptedData: stored.encryptedData,
          encryptedIv: stored.encryptedIv,
          writeTxHash: stored.writeTxHash,
          writeBlockNumber: stored.writeBlockNumber,
          writerAddress: stored.writerAddress,
          timestamp: stored.timestamp,
          version: 1,
          createdAt: stored.timestamp || Date.now(),
          updatedAt: Date.now(),
          accessedAt: Date.now(),
          accessCount: 1,
          isDirty: false,
          isDeleted: false,
          isDecrypted: true,
        });
      } catch (error) {
        console.error(`[NoteManager] Failed to decrypt note ${noteIndex} from DB:`, error);
        notes.push({
          index: noteIndex,
          content: '',
          author: stored.writerAddress || '',
          timestamp: stored.timestamp || Date.now(),
          blockNumber: stored.writeBlockNumber || 0,
          metadata: { error: 'Decryption failed', originalError: String(error) },
        });
      }
    }

    return notes;
  }

  /**
   * Read notes directly from chain (bypasses local database).
   *
   * @param options - Read options
   * @returns Array of decrypted notes
   */
  async readNotesFromChain(options: ReadNotesOptions): Promise<Note[]> {
    const { secretAddress, kvBlock, kvKey, fromIndex = 0, count } = options;

    // Query DataWritten events for this KeyVault
    const events = await this.queryDataWrittenEvents(secretAddress, kvBlock);

    // Sort by block number (chronological)
    events.sort((a, b) => a.blockNumber - b.blockNumber);

    // Apply pagination
    const startIndex = fromIndex;
    const endIndex = count !== undefined ? startIndex + count : events.length;
    const selectedEvents = events.slice(startIndex, endIndex);

    // Decrypt each note
    const notes: Note[] = [];

    for (let i = 0; i < selectedEvents.length; i++) {
      const event = selectedEvents[i];
      const noteIndex = startIndex + i;

      try {
        // Parse encrypted data from event (remove 0x prefix and convert hex to bytes)
        const hexData = event.data.startsWith('0x') ? event.data.slice(2) : event.data;
        const dataBytes = hexToBytes(hexData);
        const encryptedNote = NoteCrypto.bytesToEncryptedNote(dataBytes);

        // Debug logging for decryption issues
        console.log(`[NoteManager] Note ${noteIndex}: dataBytes=${dataBytes.length} bytes, iv=${encryptedNote.iv.length} chars, encrypted=${encryptedNote.encrypted.length} chars, kvKey=${kvKey.length} bytes`);

        // Decrypt note
        const note = await NoteCrypto.decryptNote(
          encryptedNote.encrypted,
          encryptedNote.iv,
          kvKey,
          noteIndex,
          event.blockNumber
        );

        // Check if content is an IPFS reference and resolve it
        const ipfsRef = parseIPFSReference(note.content);
        if (ipfsRef) {
          console.log(`[NoteManager] Note ${noteIndex} contains IPFS reference, fetching and decrypting...`, {
            cid: ipfsRef.cid,
            originalSize: ipfsRef.originalSize,
          });

          try {
            // Fetch encrypted content from IPFS
            const encryptedJson = await this.fetchFromIPFS(ipfsRef.cid);
            const encryptedData = JSON.parse(encryptedJson);

            // Decrypt the content (it was encrypted before IPFS upload)
            const decryptedContent = await NoteCrypto.decryptContent(encryptedData, kvKey);
            note.content = decryptedContent;

            // Add metadata about IPFS retrieval
            note.metadata = {
              ...note.metadata,
              ipfsResolved: true,
              ipfsCid: ipfsRef.cid,
            };
            console.log(`[NoteManager] IPFS content fetched and decrypted for note ${noteIndex}`);
          } catch (ipfsError) {
            console.error(`[NoteManager] Failed to fetch/decrypt IPFS content for note ${noteIndex}:`, ipfsError);
            // Keep the IPFS reference as content so user knows there's an issue
            note.metadata = {
              ...note.metadata,
              ipfsError: String(ipfsError),
              ipfsCid: ipfsRef.cid,
            };
          }
        }

        notes.push(note);
      } catch (error) {
        // Include failed note with error indicator
        console.error(`[NoteManager] Failed to decrypt note ${noteIndex}:`, error);
        notes.push({
          index: noteIndex,
          content: '',
          author: event.writer,
          timestamp: event.timestamp,
          blockNumber: event.blockNumber,
          metadata: { error: 'Decryption failed', originalError: String(error) },
        });
      }
    }

    return notes;
  }

  /**
   * Get total note count for a KeyVault.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number
   * @returns Note count
   */
  async getNoteCount(secretAddress: string, kvBlock: number): Promise<number> {
    const events = await this.queryDataWrittenEvents(secretAddress, kvBlock);
    return events.length;
  }

  // ============================================================================
  // Event Queries
  // ============================================================================

  /**
   * Query DataWritten events for a KeyVault.
   *
   * Uses ChainReader (Etherscan API) when available - no block scanning.
   * Falls back to RPC queryFilter only if ChainReader not configured.
   */
  private async queryDataWrittenEvents(
    secretAddress: string,
    kvBlock: number
  ): Promise<DataWrittenEvent[]> {
    // Prefer ChainReader (uses Etherscan indexed API - no block scanning)
    if (this.config.chainReader && this.config.chainName) {
      console.log('[NoteManager] Using ChainReader for DataWritten query (no block scanning)');
      const events = await this.config.chainReader.getDataWrittenEvents(
        secretAddress,
        this.config.chainName,
        kvBlock
      );
      return events.map(e => ({
        secretContract: e.secretContract,
        writer: e.writer,
        keyVaultBlock: e.keyVaultBlock,
        data: e.data,
        creditsCost: e.creditsCost,
        timestamp: e.timestamp,
        txHash: e.txHash,
        blockNumber: e.blockNumber,
      }));
    }

    // Fallback: RPC query (not recommended for mainnet)
    console.warn('[NoteManager] No ChainReader configured - falling back to RPC query for DataWritten');
    const contract = new Contract(secretAddress, SECRET_ABI, this.provider);

    // Query events filtered by keyVaultBlock
    const filter = contract.filters.DataWritten(null, null, kvBlock);
    const logs = await contract.queryFilter(filter, kvBlock, 'latest');

    return logs.map((log) => {
      const parsed = contract.interface.parseLog(log);
      return {
        secretContract: parsed!.args.secretContract,
        writer: parsed!.args.writer,
        keyVaultBlock: Number(parsed!.args.keyVaultBlock),
        data: parsed!.args.data,
        creditsCost: Number(parsed!.args.creditsCost),
        timestamp: Number(parsed!.args.timestamp) * 1000,
        txHash: log.transactionHash,
        blockNumber: log.blockNumber,
      };
    });
  }

  /**
   * Query KeyVaultCreated events for a secret.
   *
   * Uses ChainReader (Etherscan API) when available - no block scanning.
   * Falls back to RPC queryFilter only if ChainReader not configured.
   *
   * @param secretAddress - Secret contract address
   * @returns Array of KeyVault created events
   */
  async queryKeyVaults(secretAddress: string): Promise<KeyVaultCreatedEvent[]> {
    // Prefer ChainReader (uses Etherscan indexed API - no block scanning)
    if (this.config.chainReader && this.config.chainName) {
      console.log('[NoteManager] Using ChainReader for KeyVault query (no block scanning)');
      const events = await this.config.chainReader.getKeyVaultCreatedEvents(
        secretAddress,
        this.config.chainName
      );
      return events.map(e => ({
        blockNumber: e.blockNumber,
        creator: e.creator,
        encryptedKeysData: e.encryptedKeysData,
        schemaDefinition: e.schemaDefinition,
        timestamp: e.timestamp,
        txHash: e.txHash,
      }));
    }

    // Fallback: RPC query (not recommended for mainnet)
    console.warn('[NoteManager] No ChainReader configured - falling back to RPC query');
    const contract = new Contract(secretAddress, SECRET_ABI, this.provider);

    // Use reasonable lookback to avoid "block range too large" errors
    const latestBlock = await this.provider.getBlockNumber();
    const startBlock = Math.max(0, latestBlock - 10_000_000);

    const filter = contract.filters.KeyVaultCreated();
    const logs = await contract.queryFilter(filter, startBlock, 'latest');

    return logs.map((log) => {
      const parsed = contract.interface.parseLog(log);
      return {
        blockNumber: Number(parsed!.args.blockNumber),
        creator: parsed!.args.creator,
        encryptedKeysData: parsed!.args.encryptedKeysData,
        schemaDefinition: parsed!.args.schemaDefinition,
        timestamp: Number(parsed!.args.timestamp) * 1000,
        txHash: log.transactionHash,
      };
    });
  }

  /**
   * Query a specific KeyVaultCreated event by block number.
   *
   * @param secretAddress - Secret contract address
   * @param kvBlock - KeyVault block number to find
   * @returns KeyVault event or null if not found
   */
  async queryKeyVaultCreatedEvent(
    secretAddress: string,
    kvBlock: number
  ): Promise<KeyVaultCreatedEvent | null> {
    const contract = new Contract(secretAddress, SECRET_ABI, this.provider);

    // Query events filtered by block number
    const filter = contract.filters.KeyVaultCreated(kvBlock);
    const logs = await contract.queryFilter(filter, kvBlock, kvBlock);

    if (logs.length === 0) {
      return null;
    }

    const log = logs[0];
    const parsed = contract.interface.parseLog(log);
    return {
      blockNumber: Number(parsed!.args.blockNumber),
      creator: parsed!.args.creator,
      encryptedKeysData: parsed!.args.encryptedKeysData,
      schemaDefinition: parsed!.args.schemaDefinition,
      timestamp: Number(parsed!.args.timestamp) * 1000,
      txHash: log.transactionHash,
    };
  }

  /**
   * Estimate note index based on block number ordering.
   */
  private async estimateNoteIndex(
    secretAddress: string,
    kvBlock: number,
    targetBlock: number
  ): Promise<number> {
    const events = await this.queryDataWrittenEvents(secretAddress, kvBlock);
    events.sort((a, b) => a.blockNumber - b.blockNumber);

    const index = events.findIndex((e) => e.blockNumber >= targetBlock);
    return index >= 0 ? index : events.length - 1;
  }
}
