/**
 * @rootz/identity-provider - Types
 *
 * CRITICAL: This is the safety mechanism for all users.
 * Multiple devices (rivets) can act for a single identity.
 * If a device is lost, another device can add a replacement.
 *
 * Core Concepts:
 * - IdentityContract: Multi-device identity (EIP-1271 compliant)
 * - Rivet: An authorized device wallet
 * - Device plurality: Any rivet can act for the identity
 * - Recovery: Add new device with any remaining device
 */

import { ethers } from 'ethers';

// ============================================================================
// EIP-1271 Constants
// ============================================================================

/**
 * EIP-1271 magic value returned when signature is valid.
 * bytes4(keccak256("isValidSignature(bytes32,bytes)"))
 */
export const EIP1271_MAGIC_VALUE = '0x1626ba7e';

/**
 * EIP-1271 value returned when signature is invalid.
 */
export const EIP1271_INVALID = '0xffffffff';

// ============================================================================
// Rivet (Device) Types
// ============================================================================

/**
 * Information about an authorized device (rivet).
 */
export interface RivetInfo {
  /** Device wallet address */
  address: string;
  /** Human-readable name (e.g., "laptop", "phone", "tablet") */
  name: string;
  /** When the device was authorized */
  addedAt: number;
  /** Which device authorized this one */
  addedBy: string;
  /** Whether device is currently active */
  active: boolean;
}

/**
 * Result of adding a new device.
 */
export interface AddRivetResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  rivetAddress: string;
  rivetName: string;
}

/**
 * Result of removing a device.
 */
export interface RemoveRivetResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  removedAddress: string;
}

// ============================================================================
// Identity Types
// ============================================================================

/**
 * Information about an IdentityContract.
 */
export interface IdentityInfo {
  /** Contract address */
  address: string;
  /** Creator address (immutable) */
  creator: string;
  /** Number of active rivets */
  rivetCount: number;
  /** Contract ETH balance (for gas) */
  balance: bigint;
  /** All rivet information */
  rivets: RivetInfo[];
}

/**
 * Result of deploying a new IdentityContract.
 */
export interface CreateIdentityResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  identityAddress: string;
  firstRivetAddress: string;
}

/**
 * Factory status and user eligibility for identity creation.
 */
export interface FactoryStatus {
  /** Factory is accepting identity creation requests */
  isActive: boolean;
  /** Credit check is enabled (testing may disable) */
  creditCheckEnabled: boolean;
  /** Cost in credits to create an identity */
  identityCost: bigint;
  /** User's current credit balance */
  userBalance: bigint;
  /** User has sufficient credits to create */
  canCreate: boolean;
}

// ============================================================================
// Transaction Execution
// ============================================================================

/**
 * Result of executing a transaction as the identity.
 */
export interface ExecuteTransactionResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  returnData: string;
}

// ============================================================================
// EIP-1271 Signature Types
// ============================================================================

/**
 * Signature validation result.
 */
export interface SignatureValidationResult {
  isValid: boolean;
  signer?: string;
  magicValue: string;
}

/**
 * Signature for EIP-1271 validation.
 * Standard ECDSA signature (65 bytes).
 */
export interface ECDSASignature {
  r: string;
  s: string;
  v: number;
}

// ============================================================================
// Contract ABIs
// ============================================================================

/**
 * IdentityContract ABI (minimal - core functions only).
 * Based on IdentityContract.sol from rootz-monorepo.
 */
export const IDENTITY_CONTRACT_ABI = [
  // Constructor creates first rivet automatically
  // No explicit constructor in ABI

  // Rivet Management
  'function addRivet(address rivet, string name) external',
  'function removeRivet(address rivet) external',

  // Transaction Execution
  'function executeTransaction(address target, uint256 value, bytes data) external payable returns (bool success, bytes returnData)',

  // EIP-1271 Signature Validation
  'function isValidSignature(bytes32 hash, bytes signature) external view returns (bytes4 magicValue)',

  // View Functions
  'function creator() external view returns (address)',
  'function authorizedRivets(address) external view returns (bool)',
  'function rivetCount() external view returns (uint256)',
  'function rivetList(uint256) external view returns (address)',
  'function getRivets() external view returns (address[])',
  'function getRivetInfo(address rivet) external view returns (string name, uint256 addedAt, address addedBy, bool active)',
  'function isRivet(address rivet) external view returns (bool)',
  'function getBalance() external view returns (uint256)',

  // Public Key Management (for ECDH key sharing between devices)
  'function setPublicKey(string publicKey) external',
  'function getPublicKey(address rivet) external view returns (string)',
  'function getRivetsWithPublicKeys() external view returns (address[] addresses, string[] names, string[] publicKeys)',

  // KeyVault (encrypted storage on identity contract)
  'function setKeyVault(string key, bytes value, bool isPublic) external',
  'function getKeyVault(string key) external view returns (bytes)',
  'function deleteKeyVault(string key) external',
  'function hasKeyVault(string key) external view returns (bool)',

  // Events
  'event RivetAdded(address indexed rivet, string name, address indexed addedBy, uint256 timestamp)',
  'event RivetRemoved(address indexed rivet, address indexed removedBy, uint256 timestamp)',
  'event TransactionExecuted(address indexed target, uint256 value, bytes data, address indexed executor, uint256 timestamp)',
  'event PublicKeyRegistered(address indexed rivet, string publicKey, uint256 timestamp)',
  'event PublicKeyUpdated(address indexed rivet, string oldKey, string newKey, uint256 timestamp)',
  'event KeyVaultSet(string indexed key, address indexed setter, bool isPublic, uint256 timestamp)',
  'event KeyVaultDeleted(string indexed key, address indexed deleter, uint256 timestamp)',
  // V3: Fallback function emits this when data is sent TO the Identity contract
  'event MessageReceived(address indexed from, bytes data, uint256 value, uint256 indexed messageIndex, uint256 timestamp)',
] as const;

/**
 * Factory ABI for creating IdentityContracts.
 * Updated for V6 with creditsCost in event signature.
 */
export const IDENTITY_FACTORY_ABI = [
  'function createIdentity() external returns (address)',
  'function createIdentityWithName(string deviceName) external returns (address)',
  'function identityTemplate() external view returns (address)',
  'function getUserIdentities(address user) external view returns (address[])',
  'function canCreateIdentity(address user) external view returns (bool hasEnough, uint256 cost, uint256 balance)',
  'function getIdentityCost() external view returns (uint256)',
  'function isActive() external view returns (bool)',
  'function creditCheckEnabled() external view returns (bool)',
  // V6 event includes creditsCost
  'event IdentityCreated(address indexed identity, address indexed creator, uint256 creditsCost, uint256 timestamp)',
] as const;

// ============================================================================
// Provider Interface
// ============================================================================

/**
 * Signer interface for identity operations.
 * Compatible with @rootz/wallet RootzSigner and ethers v6 Signer.
 *
 * NOTE: For RootzSigner compatibility, use getSignerAddress() helper method
 * in IdentityManager which handles both sync .address and async getAddress().
 */
export interface IdentitySigner {
  /** Signer's wallet address (sync for internal use) */
  address: string;

  /** Optional async getAddress for RootzSigner compatibility */
  getAddress?(): Promise<string>;

  /** Sign a message hash */
  signMessage(message: Uint8Array): Promise<string>;

  /** Send a transaction */
  sendTransaction(tx: {
    to: string;
    data: string;
    value?: bigint;
    gasLimit?: bigint;
    maxFeePerGas?: bigint;
    maxPriorityFeePerGas?: bigint;
  }): Promise<{
    hash: string;
    wait(): Promise<{
      blockNumber: number;
      logs?: Array<{ topics: readonly string[]; data: string }>;
    }>;
  }>;

  /** Get the provider */
  provider: ethers.Provider;
}

// ============================================================================
// Gas Settings (callback pattern for dynamic gas estimation)
// ============================================================================

/**
 * Gas settings returned by getGasSettings callback.
 */
export interface GasSettings {
  maxFeePerGas: bigint;
  maxPriorityFeePerGas: bigint;
}

/**
 * Callback type for dynamic gas estimation.
 * Follows the pattern used by @rootz/teams.
 */
export type GasProvider = () => Promise<GasSettings>;

// ============================================================================
// Manager Configuration
// ============================================================================

export interface IdentityManagerConfig {
  /** Signer (current device's wallet) */
  signer: IdentitySigner;

  /** Chain ID */
  chainId: number;

  /** Factory contract address (V5) */
  factoryAddress?: string;

  /** Identity template address (V5) */
  identityTemplateAddress?: string;

  /** Progress callback */
  onProgress?: (step: IdentityStep) => void;

  /**
   * Callback for dynamic gas estimation.
   * If not provided, transactions rely on ethers.js defaults.
   */
  getGasSettings?: GasProvider;
}

export interface IdentityStep {
  step:
    | 'creating-identity'
    | 'adding-rivet'
    | 'removing-rivet'
    | 'executing-transaction'
    | 'validating-signature'
    | 'complete';
  message: string;
  txHash?: string;
  blockNumber?: number;
}

// ============================================================================
// Error Types
// ============================================================================

export class IdentityError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly details?: Record<string, unknown>
  ) {
    super(message);
    this.name = 'IdentityError';
  }
}

/**
 * Error codes for identity operations.
 */
export const IdentityErrorCode = {
  NOT_A_RIVET: 'NOT_A_RIVET',
  RIVET_ALREADY_EXISTS: 'RIVET_ALREADY_EXISTS',
  CANNOT_REMOVE_LAST_RIVET: 'CANNOT_REMOVE_LAST_RIVET',
  INVALID_SIGNATURE: 'INVALID_SIGNATURE',
  TRANSACTION_FAILED: 'TRANSACTION_FAILED',
  IDENTITY_NOT_FOUND: 'IDENTITY_NOT_FOUND',
} as const;

// ============================================================================
// Recovery Types
// ============================================================================

/**
 * Device recovery scenario.
 *
 * CRITICAL SAFETY FEATURE:
 * - If you lose a device, use another device to add a replacement
 * - Then remove the lost device to prevent unauthorized access
 * - Identity is NEVER lost as long as you have ONE remaining device
 */
export interface DeviceRecoveryPlan {
  /** The identity contract address */
  identityAddress: string;

  /** Current active devices */
  activeRivets: RivetInfo[];

  /** Lost/compromised device address */
  lostRivetAddress: string;

  /** New device address to add */
  newRivetAddress: string;
  newRivetName: string;

  /** Device that will perform recovery (must be active rivet) */
  recoveringRivetAddress: string;
}

export interface DeviceRecoveryResult {
  success: boolean;

  /** Adding new device */
  addResult?: AddRivetResult;

  /** Removing lost device */
  removeResult?: RemoveRivetResult;

  /** Any errors */
  error?: string;
}

// ============================================================================
// Key Sharing Types (Multi-Device ECDH)
// ============================================================================

/**
 * Device info with public key for ECDH key sharing.
 * Used when sharing secrets across multiple devices on the same identity.
 */
export interface DeviceWithPublicKey {
  /** Device wallet address */
  address: string;
  /** Human-readable name */
  name: string;
  /** ECDH public key (uncompressed secp256k1: 0x04 + 128 hex chars) */
  publicKey: string;
  /** Whether this device has registered a public key */
  hasPublicKey: boolean;
}

/**
 * Encrypted key package for a specific device.
 * Created using ECDH: sender's private key + recipient's public key.
 */
export interface EncryptedKeyPackage {
  /** Target device address */
  recipientAddress: string;
  /** Encrypted master key (AES-256-GCM ciphertext) */
  encryptedKey: string;
  /** Initialization vector for AES-GCM */
  iv: string;
  /** Sender's public key (for recipient to compute shared secret) */
  senderPublicKey: string;
}

/**
 * Result of registering a public key on the identity contract.
 */
export interface RegisterPublicKeyResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  publicKey: string;
}

/**
 * Parameters for sharing keys with a device.
 */
export interface ShareKeysParams {
  /** Identity contract address */
  identityAddress: string;
  /** Target device to share with */
  recipientAddress: string;
  /** Master keys to share (hex strings) */
  masterKeys: Array<{
    /** Secret contract address */
    secretAddress: string;
    /** The master key (32 bytes hex) */
    masterKey: string;
  }>;
  /** Sender's private key for ECDH */
  senderPrivateKey: string;
}

/**
 * Result of sharing keys with a device.
 */
export interface ShareKeysResult {
  success: boolean;
  /** Number of keys shared */
  keyCount: number;
  /** Transaction hash (if stored on-chain) */
  txHash?: string;
  /** IPFS hash (if stored off-chain) */
  ipfsHash?: string;
}

/**
 * Package of shared keys waiting to be received.
 */
export interface PendingSharedKeys {
  /** Who sent the keys */
  senderAddress: string;
  /** Sender's public key for ECDH */
  senderPublicKey: string;
  /** When the keys were shared */
  timestamp: number;
  /** The encrypted key packages */
  encryptedPackages: EncryptedKeyPackage[];
}

/**
 * Result of receiving shared keys.
 */
export interface ReceiveKeysResult {
  success: boolean;
  /** Decrypted master keys */
  decryptedKeys: Array<{
    secretAddress: string;
    masterKey: string;
  }>;
}

// ============================================================================
// Device Invite Types (Multi-Device Onboarding)
// ============================================================================

/**
 * Device invite package sent from existing device to new device.
 * Can be transmitted via QR code, paste, or messaging.
 */
export interface DeviceInvite {
  /** Message type identifier */
  type: 'device-invite';
  /** Protocol version */
  version: '1.0.0';
  /** Unique invite ID for tracking */
  inviteId: string;
  /** Identity contract address to join */
  identityContract: string;
  /** Inviting device's address */
  inviterAddress: string;
  /** Inviting device's public key for ECDH */
  inviterPublicKey: string;
  /** Inviting device's human-readable name */
  inviterName: string;
  /** When invite was created */
  timestamp: number;
  /** When invite expires (typically 24 hours) */
  expiresAt: number;
  /** Chain ID (to prevent cross-chain confusion) */
  chainId: number;
}

/**
 * Response from new device accepting an invite.
 */
export interface DeviceInviteResponse {
  /** Message type identifier */
  type: 'device-invite-response';
  /** Protocol version */
  version: '1.0.0';
  /** Reference to original invite */
  inviteId: string;
  /** New device's address */
  deviceAddress: string;
  /** New device's public key for ECDH */
  devicePublicKey: string;
  /** Human-readable name for this device */
  deviceName: string;
  /** Whether invite was accepted */
  accepted: boolean;
  /** When response was created */
  timestamp: number;
}

/**
 * Result of generating a device invite.
 */
export interface GenerateInviteResult {
  success: boolean;
  /** The invite package */
  invite: DeviceInvite;
  /** Base64-encoded invite for easy sharing */
  inviteCode: string;
  /** URL for QR code generation (optional) */
  qrCodeUrl?: string;
}

/**
 * Result of accepting a device invite.
 */
export interface AcceptInviteResult {
  success: boolean;
  /** Transaction hash (response sent to inviter) */
  txHash: string;
  /** The response that was sent */
  response: DeviceInviteResponse;
}

/**
 * Result of completing device addition.
 */
export interface CompleteInviteResult {
  success: boolean;
  /** Transaction hash (addRivet call) */
  txHash: string;
  /** Block number of confirmation */
  blockNumber: number;
  /** New device's address */
  deviceAddress: string;
  /** New device's public key (now cached) */
  devicePublicKey: string;
}

// ============================================================================
// Fat Package Types (Multi-Device Encryption)
// ============================================================================

/**
 * Encrypted entry for a single device in a fat package.
 * Uses V3.0 ephemeral key model for forward secrecy.
 */
export interface FatPackageDeviceEntry {
  /** Target device address */
  deviceAddress: string;
  /** Human-readable device name */
  deviceName: string;
  /** Ephemeral public key (V3.0 - unique per device entry) */
  ephemeralPublicKey: string;
  /** Master key encrypted for this device */
  encryptedMasterKey: {
    ciphertext: string;
    iv: string;
    authTag: string;
  };
  /** KeyVault key encrypted for this device (optional) */
  encryptedKeyVaultKey?: {
    ciphertext: string;
    iv: string;
    authTag: string;
  };
}

/**
 * Fat package containing encrypted keys for all devices.
 * Each device has its own entry with unique ephemeral key.
 */
export interface FatPackage {
  /** Package type identifier */
  type: 'fat-key-package';
  /** Package version (3.0 = ephemeral key model) */
  version: '3.0';
  /** Secret contract this package is for */
  secretContract: string;
  /** Identity contract that owns the secret */
  identityContract: string;
  /** Human-readable secret name */
  secretName?: string;
  /** Individual device entries */
  devices: FatPackageDeviceEntry[];
  /** When package was created */
  createdAt: number;
}

/**
 * Parameters for creating a fat package.
 */
export interface CreateFatPackageParams {
  /** Secret contract address */
  secretContract: string;
  /** Secret name (for reference) */
  secretName?: string;
  /** Identity contract address */
  identityContract: string;
  /** Master key to encrypt (32 bytes hex) */
  masterKey: string;
  /** KeyVault key to encrypt (32 bytes hex, optional) */
  keyVaultKey?: string;
  /** Devices to encrypt for (with public keys) */
  devices: DeviceWithPublicKey[];
}

/**
 * Result of decrypting a fat package entry.
 */
export interface DecryptFatPackageResult {
  success: boolean;
  /** Decrypted master key */
  masterKey: string;
  /** Decrypted KeyVault key (if present) */
  keyVaultKey?: string;
  /** Which device entry was decrypted */
  deviceAddress: string;
}

// ============================================================================
// Identity Provider Types (Unified Interface)
// ============================================================================

/**
 * Operating mode for the identity provider.
 * - simple: Single device, no identity contract
 * - identity: Multi-device with identity contract
 */
export type IdentityMode = 'simple' | 'identity';

/**
 * Configuration for the unified IdentityProvider.
 */
export interface IdentityProviderConfig {
  /** Current device's signer */
  signer: IdentitySigner;
  /** Current device's private key (for ECDH) */
  privateKey: string;
  /** Chain ID */
  chainId: number;
  /** Factory address (optional - for creating new identities) */
  factoryAddress?: string;
  /** Identity contract address (if in identity mode) */
  identityAddress?: string;
  /** Progress callback */
  onProgress?: (step: IdentityStep) => void;
}

/**
 * Owner information returned by the unified interface.
 */
export interface OwnerInfo {
  /** Owner address (wallet or identity contract) */
  address: string;
  /** Operating mode */
  mode: IdentityMode;
  /** Public keys for encryption */
  publicKeys: string[];
  /** Device count (1 for simple mode) */
  deviceCount: number;
}

/**
 * Encrypted data that works in both modes.
 * Simple mode: single encryption
 * Identity mode: fat package
 */
export interface UnifiedEncryptedData {
  /** Which mode created this */
  mode: IdentityMode;
  /** For simple mode: single encrypted package */
  singlePackage?: EncryptedKeyPackage;
  /** For identity mode: fat package with all devices */
  fatPackage?: FatPackage;
}

// ============================================================================
// Device Monitor Types
// ============================================================================

/**
 * Event types emitted by the device monitor.
 */
export type DeviceMonitorEventType =
  | 'device-added'
  | 'device-removed'
  | 'device-self-removed'  // This device was removed - trigger wipe!
  | 'public-key-registered'
  | 'keys-shared';

/**
 * Event from the device monitor.
 */
export interface DeviceMonitorEvent {
  type: DeviceMonitorEventType;
  /** Transaction hash */
  txHash: string;
  /** Block number */
  blockNumber: number;
  /** Timestamp */
  timestamp: number;
  /** Event data */
  data: {
    deviceAddress?: string;
    deviceName?: string;
    publicKey?: string;
    removedBy?: string;
    addedBy?: string;
  };
}

/**
 * Callback for device monitor events.
 */
export type DeviceMonitorCallback = (event: DeviceMonitorEvent) => void;

/**
 * Device monitor configuration.
 */
export interface DeviceMonitorConfig {
  /** Identity contract to monitor */
  identityAddress: string;
  /** This device's address (to detect self-removal) */
  myAddress: string;
  /** Polling interval in milliseconds (default: 60000) */
  pollInterval?: number;
  /** Provider for blockchain queries */
  provider: ethers.Provider;
  /** Event callback */
  onEvent: DeviceMonitorCallback;
  /** Auto-wipe callback when this device is removed */
  onSelfRemoved?: () => void;
}
