/**
 * StorageGateway - Single entry point for all storage operations
 *
 * All packages read/write through this gateway. Benefits:
 * 1. Swappable backends (IndexedDB, SQLite, cloud, etc.)
 * 2. Write queuing with batching for efficiency
 * 3. Offline-first with sync when online
 * 4. Consistent access control
 * 5. Event emission for UI updates
 *
 * Architecture:
 * ```
 * ┌─────────────────────────────────────────────────────────────┐
 * │                    StorageGateway                           │
 * │  ┌─────────────┐  ┌─────────────┐  ┌─────────────────────┐ │
 * │  │ Read Cache  │  │ Write Queue │  │ Event Emitter       │ │
 * │  └──────┬──────┘  └──────┬──────┘  └─────────────────────┘ │
 * └─────────┼────────────────┼──────────────────────────────────┘
 *           │                │
 *           ▼                ▼
 * ┌─────────────────────────────────────────────────────────────┐
 * │                  StorageBackend (interface)                  │
 * │  IndexedDB │ SQLite │ Memory │ Cloud │ Custom               │
 * └─────────────────────────────────────────────────────────────┘
 * ```
 *
 * @version 1.0.0
 */

import type {
  RootzDatabase,
  KeyStorage,
  StoredInvite,
  StoredSecret,
  StoredPublicKey,
  StoredMessage,
  StoredNote,
  StoredKeyVault,
  PendingOperation,
  PendingOperationType,
  PendingOperationStatus,
  SyncState,
  WriteAuthorization,
} from './types.js';

// ============================================================================
// Types
// ============================================================================

/**
 * Storage event types for reactive updates
 */
export type StorageEventType =
  | 'invite-added'
  | 'invite-updated'
  | 'secret-added'
  | 'secret-updated'
  | 'note-added'
  | 'note-updated'
  | 'note-deleted'
  | 'message-added'
  | 'operation-added'
  | 'operation-updated'
  | 'sync-complete'
  | 'error';

/**
 * Storage event payload
 */
export interface StorageEvent {
  type: StorageEventType;
  data: unknown;
  timestamp: number;
}

/**
 * Storage event listener
 */
export type StorageEventListener = (event: StorageEvent) => void;

/**
 * Write operation for batching
 */
interface WriteOperation {
  id: string;
  store: string;
  action: 'put' | 'delete';
  key?: string;
  data?: unknown;
  timestamp: number;
}

/**
 * Gateway configuration
 */
export interface StorageGatewayConfig {
  database: RootzDatabase;
  keyStorage: KeyStorage;
  chainId: number;
  walletAddress: string;

  // Optional settings
  batchSize?: number;           // Max operations per batch (default: 10)
  batchDelayMs?: number;        // Delay before flushing batch (default: 100)
  cacheEnabled?: boolean;       // Enable read cache (default: true)
  cacheTtlMs?: number;          // Cache TTL in ms (default: 60000)
}

// ============================================================================
// StorageGateway Class
// ============================================================================

/**
 * Single entry point for all storage operations.
 * Provides caching, batching, and event emission.
 */
export class StorageGateway {
  private db: RootzDatabase;
  private keys: KeyStorage;
  private chainId: number;
  private walletAddress: string;

  // Configuration
  private batchSize: number;
  private batchDelayMs: number;
  private cacheEnabled: boolean;
  private cacheTtlMs: number;

  // Write queue
  private writeQueue: WriteOperation[] = [];
  private flushTimer: ReturnType<typeof setTimeout> | null = null;
  private isFlushing = false;

  // Read cache (simple TTL cache)
  private cache = new Map<string, { data: unknown; expires: number }>();

  // Event listeners
  private listeners = new Map<StorageEventType, Set<StorageEventListener>>();

  constructor(config: StorageGatewayConfig) {
    this.db = config.database;
    this.keys = config.keyStorage;
    this.chainId = config.chainId;
    this.walletAddress = config.walletAddress.toLowerCase();

    this.batchSize = config.batchSize ?? 10;
    this.batchDelayMs = config.batchDelayMs ?? 100;
    this.cacheEnabled = config.cacheEnabled ?? true;
    this.cacheTtlMs = config.cacheTtlMs ?? 60000;
  }

  // ==========================================================================
  // Event System
  // ==========================================================================

  /**
   * Subscribe to storage events
   */
  on(type: StorageEventType, listener: StorageEventListener): () => void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }
    this.listeners.get(type)!.add(listener);

    // Return unsubscribe function
    return () => {
      this.listeners.get(type)?.delete(listener);
    };
  }

  /**
   * Emit a storage event
   */
  private emit(type: StorageEventType, data: unknown): void {
    const event: StorageEvent = {
      type,
      data,
      timestamp: Date.now(),
    };

    this.listeners.get(type)?.forEach(listener => {
      try {
        listener(event);
      } catch (error) {
        console.error('[StorageGateway] Event listener error:', error);
      }
    });
  }

  // ==========================================================================
  // Cache Management
  // ==========================================================================

  /**
   * Get from cache if not expired
   */
  private getCached<T>(key: string): T | undefined {
    if (!this.cacheEnabled) return undefined;

    const entry = this.cache.get(key);
    if (!entry) return undefined;

    if (Date.now() > entry.expires) {
      this.cache.delete(key);
      return undefined;
    }

    return entry.data as T;
  }

  /**
   * Set cache entry
   */
  private setCache(key: string, data: unknown): void {
    if (!this.cacheEnabled) return;

    this.cache.set(key, {
      data,
      expires: Date.now() + this.cacheTtlMs,
    });
  }

  /**
   * Invalidate cache entry
   */
  private invalidateCache(key: string): void {
    this.cache.delete(key);
  }

  /**
   * Clear all cache
   */
  clearCache(): void {
    this.cache.clear();
  }

  // ==========================================================================
  // Write Queue Management
  // ==========================================================================

  /**
   * Queue a write operation
   */
  private queueWrite(
    store: string,
    action: 'put' | 'delete',
    key?: string,
    data?: unknown
  ): void {
    const op: WriteOperation = {
      id: `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      store,
      action,
      key,
      data,
      timestamp: Date.now(),
    };

    this.writeQueue.push(op);

    // Flush if batch full
    if (this.writeQueue.length >= this.batchSize) {
      this.flush();
      return;
    }

    // Schedule delayed flush
    if (!this.flushTimer) {
      this.flushTimer = setTimeout(() => {
        this.flush();
      }, this.batchDelayMs);
    }
  }

  /**
   * Flush write queue to storage
   */
  async flush(): Promise<void> {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }

    if (this.writeQueue.length === 0 || this.isFlushing) {
      return;
    }

    this.isFlushing = true;
    const operations = [...this.writeQueue];
    this.writeQueue = [];

    try {
      for (const op of operations) {
        await this.executeWrite(op);
      }
    } catch (error) {
      console.error('[StorageGateway] Flush error:', error);
      this.emit('error', { message: 'Flush failed', error });
    } finally {
      this.isFlushing = false;
    }
  }

  /**
   * Execute a single write operation
   */
  private async executeWrite(op: WriteOperation): Promise<void> {
    switch (op.store) {
      case 'invites':
        if (op.action === 'put') {
          await this.db.invites.put(op.data as StoredInvite);
        } else if (op.key) {
          await this.db.invites.delete(op.key);
        }
        break;

      case 'secrets':
        if (op.action === 'put') {
          await this.db.secrets.put(op.data as StoredSecret);
        } else if (op.key) {
          await this.db.secrets.delete(op.key);
        }
        break;

      case 'publicKeys':
        if (op.action === 'put') {
          await this.db.publicKeys.put(op.data as StoredPublicKey);
        } else if (op.key) {
          await this.db.publicKeys.delete(op.key);
        }
        break;

      case 'messages':
        if (op.action === 'put') {
          await this.db.messages.put(op.data as StoredMessage);
        } else if (op.key) {
          await this.db.messages.delete(op.key);
        }
        break;

      case 'notes':
        if (op.action === 'put') {
          await this.db.notes.put(op.data as StoredNote);
        } else if (op.key) {
          await this.db.notes.delete(op.key);
        }
        break;

      case 'pendingOperations':
        if (op.action === 'put') {
          await this.db.pendingOperations.put(op.data as PendingOperation);
        } else if (op.key) {
          await this.db.pendingOperations.delete(op.key);
        }
        break;

      case 'syncState':
        if (op.action === 'put') {
          await this.db.syncState.put(op.data as SyncState);
        }
        break;
    }
  }

  // ==========================================================================
  // Invites
  // ==========================================================================

  async getInvite(inviteId: string): Promise<StoredInvite | undefined> {
    const cacheKey = `invite:${inviteId}`;
    const cached = this.getCached<StoredInvite>(cacheKey);
    if (cached) return cached;

    const invite = await this.db.invites.get(inviteId);
    if (invite) this.setCache(cacheKey, invite);
    return invite;
  }

  async putInvite(invite: StoredInvite): Promise<void> {
    const isNew = !(await this.db.invites.get(invite.inviteId));
    this.queueWrite('invites', 'put', undefined, invite);
    this.invalidateCache(`invite:${invite.inviteId}`);
    this.emit(isNew ? 'invite-added' : 'invite-updated', invite);
  }

  async getPendingInvites(): Promise<StoredInvite[]> {
    return this.db.invites.getPending();
  }

  async getInvitesBySecret(contract: string): Promise<StoredInvite[]> {
    return this.db.invites.getBySecret(contract);
  }

  // ==========================================================================
  // Secrets
  // ==========================================================================

  async getSecret(address: string): Promise<StoredSecret | undefined> {
    const cacheKey = `secret:${address.toLowerCase()}`;
    const cached = this.getCached<StoredSecret>(cacheKey);
    if (cached) return cached;

    const secret = await this.db.secrets.get(address);
    if (secret) this.setCache(cacheKey, secret);
    return secret;
  }

  async putSecret(secret: StoredSecret): Promise<void> {
    const isNew = !(await this.db.secrets.get(secret.contractAddress));
    this.queueWrite('secrets', 'put', undefined, secret);
    this.invalidateCache(`secret:${secret.contractAddress.toLowerCase()}`);
    this.emit(isNew ? 'secret-added' : 'secret-updated', secret);
  }

  async getOwnedSecrets(): Promise<StoredSecret[]> {
    return this.db.secrets.getOwned();
  }

  async getSharedSecrets(): Promise<StoredSecret[]> {
    return this.db.secrets.getShared();
  }

  async getAllSecrets(): Promise<StoredSecret[]> {
    return this.db.secrets.getAll();
  }

  // ==========================================================================
  // Notes
  // ==========================================================================

  async getNote(noteId: string): Promise<StoredNote | undefined> {
    const cacheKey = `note:${noteId}`;
    const cached = this.getCached<StoredNote>(cacheKey);
    if (cached) return cached;

    const note = await this.db.notes.get(noteId);
    if (note) this.setCache(cacheKey, note);
    return note;
  }

  async putNote(note: StoredNote): Promise<void> {
    const isNew = !(await this.db.notes.get(note.noteId));
    this.queueWrite('notes', 'put', undefined, note);
    this.invalidateCache(`note:${note.noteId}`);
    this.emit(isNew ? 'note-added' : 'note-updated', note);
  }

  async deleteNote(noteId: string): Promise<void> {
    this.queueWrite('notes', 'delete', noteId);
    this.invalidateCache(`note:${noteId}`);
    this.emit('note-deleted', { noteId });
  }

  async getNotesBySecret(contract: string): Promise<StoredNote[]> {
    return this.db.notes.getBySecret(contract);
  }

  async getDirtyNotes(): Promise<StoredNote[]> {
    return this.db.notes.getDirty();
  }

  async getRecentNotes(limit: number = 20): Promise<StoredNote[]> {
    return this.db.notes.getRecent(limit);
  }

  // ==========================================================================
  // Messages (raw blockchain)
  // ==========================================================================

  async getMessage(txHash: string): Promise<StoredMessage | undefined> {
    const cacheKey = `msg:${txHash}`;
    const cached = this.getCached<StoredMessage>(cacheKey);
    if (cached) return cached;

    const message = await this.db.messages.get(txHash);
    if (message) this.setCache(cacheKey, message);
    return message;
  }

  async putMessage(message: StoredMessage): Promise<void> {
    this.queueWrite('messages', 'put', undefined, message);
    this.invalidateCache(`msg:${message.txHash}`);
    this.emit('message-added', message);
  }

  async getUnprocessedMessages(): Promise<StoredMessage[]> {
    return this.db.messages.getUnprocessed();
  }

  async getMessagesByType(type: string): Promise<StoredMessage[]> {
    return this.db.messages.getByType(type);
  }

  async getRecentMessages(limit: number = 50): Promise<StoredMessage[]> {
    return this.db.messages.getRecent(limit);
  }

  // ==========================================================================
  // Pending Operations (write queue)
  // ==========================================================================

  /**
   * Create a new pending operation
   */
  async createOperation(
    type: PendingOperationType,
    payload: unknown,
    refs?: {
      secretContract?: string;
      inviteId?: string;
      noteId?: string;
    }
  ): Promise<PendingOperation> {
    const op: PendingOperation = {
      operationId: `op_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      chainId: this.chainId,
      type,
      status: 'pending',
      payload,
      secretContract: refs?.secretContract,
      inviteId: refs?.inviteId,
      noteId: refs?.noteId,
      retryCount: 0,
      maxRetries: 3,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      createdBy: this.walletAddress,
    };

    this.queueWrite('pendingOperations', 'put', undefined, op);
    this.emit('operation-added', op);
    return op;
  }

  /**
   * Update operation status
   */
  async updateOperationStatus(
    operationId: string,
    status: PendingOperationStatus,
    updates?: Partial<PendingOperation>
  ): Promise<void> {
    const op = await this.db.pendingOperations.get(operationId);
    if (!op) return;

    const updated: PendingOperation = {
      ...op,
      ...updates,
      status,
      updatedAt: Date.now(),
    };

    if (status === 'complete') {
      updated.completedAt = Date.now();
    } else if (status === 'submitted') {
      updated.submittedAt = Date.now();
    }

    this.queueWrite('pendingOperations', 'put', undefined, updated);
    this.emit('operation-updated', updated);
  }

  async getPendingOperations(): Promise<PendingOperation[]> {
    return this.db.pendingOperations.getPending();
  }

  async getOperationsByStatus(status: PendingOperationStatus): Promise<PendingOperation[]> {
    return this.db.pendingOperations.getByStatus(status);
  }

  async getOperationsByType(type: PendingOperationType): Promise<PendingOperation[]> {
    return this.db.pendingOperations.getByType(type);
  }

  // ==========================================================================
  // Public Keys
  // ==========================================================================

  async getPublicKey(address: string): Promise<StoredPublicKey | undefined> {
    const cacheKey = `pubkey:${address.toLowerCase()}`;
    const cached = this.getCached<StoredPublicKey>(cacheKey);
    if (cached) return cached;

    const pubKey = await this.db.publicKeys.get(address);
    if (pubKey) this.setCache(cacheKey, pubKey);
    return pubKey;
  }

  async putPublicKey(pubKey: StoredPublicKey): Promise<void> {
    this.queueWrite('publicKeys', 'put', undefined, pubKey);
    this.invalidateCache(`pubkey:${pubKey.address.toLowerCase()}`);
  }

  // ==========================================================================
  // Key Storage (localStorage wrapper)
  // ==========================================================================

  getMasterKey(contract: string): string | null {
    return this.keys.getMasterKey(this.chainId, contract);
  }

  setMasterKey(contract: string, key: string): void {
    this.keys.setMasterKey(this.chainId, contract, key);
  }

  getKVKey(kvBlock: number): string | null {
    return this.keys.getKVKey(this.chainId, kvBlock);
  }

  setKVKey(kvBlock: number, key: string): void {
    this.keys.setKVKey(this.chainId, kvBlock, key);
  }

  getWriteAuth(contract: string, kvBlock: number): WriteAuthorization | null {
    return this.keys.getWriteAuth(this.chainId, contract, kvBlock);
  }

  setWriteAuth(contract: string, kvBlock: number, auth: WriteAuthorization): void {
    this.keys.setWriteAuth(this.chainId, contract, kvBlock, auth);
  }

  // ==========================================================================
  // Sync State
  // ==========================================================================

  async getSyncState(key: string = 'default'): Promise<SyncState | undefined> {
    return this.db.syncState.get(key);
  }

  async updateSyncState(state: SyncState): Promise<void> {
    this.queueWrite('syncState', 'put', undefined, state);
    this.emit('sync-complete', state);
  }

  // ==========================================================================
  // KeyVaults (delegate to database)
  // ==========================================================================

  /**
   * Direct access to KeyVault operations.
   * KeyVaults store encrypted KV keys for note encryption.
   */
  get keyVaults(): {
    get(keyVaultId: string): Promise<StoredKeyVault | undefined>;
    put(keyVault: StoredKeyVault): Promise<void>;
    getAll(): Promise<StoredKeyVault[]>;
    getBySecret(contract: string): Promise<StoredKeyVault[]>;
    getPrimary(contract: string): Promise<StoredKeyVault | undefined>;
    delete(keyVaultId: string): Promise<void>;
  } {
    return {
      get: (keyVaultId: string) => this.db.keyVaults.get(keyVaultId),
      put: async (keyVault: StoredKeyVault) => {
        await this.db.keyVaults.put(keyVault);
        this.invalidateCache(`keyvault:${keyVault.keyVaultId}`);
      },
      getAll: () => this.db.keyVaults.getAll(),
      getBySecret: (contract: string) => this.db.keyVaults.getBySecret(contract),
      getPrimary: (contract: string) => this.db.keyVaults.getPrimary(contract),
      delete: async (keyVaultId: string) => {
        await this.db.keyVaults.delete(keyVaultId);
        this.invalidateCache(`keyvault:${keyVaultId}`);
      },
    };
  }

  // ==========================================================================
  // Lifecycle
  // ==========================================================================

  /**
   * Ensure all pending writes are flushed
   */
  async close(): Promise<void> {
    await this.flush();
    this.cache.clear();
    this.listeners.clear();
  }

  /**
   * Clear all data (for testing or reset)
   */
  async clear(): Promise<void> {
    await this.flush();
    await this.db.clear();
    this.keys.clearChain(this.chainId);
    this.cache.clear();
  }

  /**
   * Get gateway stats for diagnostics
   */
  getStats(): {
    cacheSize: number;
    queueLength: number;
    listenerCount: number;
  } {
    let listenerCount = 0;
    this.listeners.forEach(set => {
      listenerCount += set.size;
    });

    return {
      cacheSize: this.cache.size,
      queueLength: this.writeQueue.length,
      listenerCount,
    };
  }
}

// ============================================================================
// Factory Function
// ============================================================================

/**
 * Create a StorageGateway instance
 */
export function createStorageGateway(config: StorageGatewayConfig): StorageGateway {
  return new StorageGateway(config);
}
