/**
 * Rootz V6 Dashboard - Transaction Management Tab
 *
 * Component module for managing stuck/pending transactions.
 * Uses @rootz/integration GasProvider for all gas operations.
 *
 * ## Architecture
 *
 * This module follows the component pattern:
 * - @rootz/integration GasProvider → tabs/transactions.ts
 *
 * ## Public API
 *
 * - renderTransactionsPanel(state): Returns HTML string for the panel
 * - setupTransactionsPanel(state): Sets up event handlers, returns cleanup function
 *
 * ## Capabilities
 *
 * - Check for stuck transactions
 * - Cancel single transaction
 * - Cancel all pending transactions
 * - View current network gas prices
 */

import { GasProvider } from '@rootz/integration';
import type { JsonRpcProvider, Signer } from 'ethers';

// ============================================================================
// Types
// ============================================================================

/**
 * Minimal state interface required by transactions panel.
 */
export interface TransactionsPanelState {
  wallet: {
    address: string;
    provider: JsonRpcProvider;
    signer: Signer;
  };
}

// ============================================================================
// Render Function
// ============================================================================

/**
 * Render the transactions panel HTML.
 * Pure function - no side effects.
 */
export function renderTransactionsPanel(_state: TransactionsPanelState): string {
  return `
    <div class="transactions-panel">
      <h3>⛽ Transaction Management</h3>

      <!-- Network Gas Status -->
      <section class="tx-section">
        <h4>Network Gas Prices</h4>
        <div id="gas-status">
          <p class="pending">Loading gas prices...</p>
        </div>
        <button id="refresh-gas-btn" class="secondary">🔄 Refresh</button>
      </section>

      <!-- Pending Transactions -->
      <section class="tx-section">
        <h4>Pending Transactions</h4>
        <div id="pending-tx-status">
          <p class="pending">Checking for pending transactions...</p>
        </div>
        <div id="pending-tx-actions" style="display: none; margin-top: 1rem;">
          <button id="cancel-all-btn" class="danger">🗑️ Cancel All Pending</button>
        </div>
      </section>

      <!-- Manual Cancel -->
      <section class="tx-section">
        <h4>Cancel Specific Transaction</h4>
        <div class="tx-form">
          <label for="cancel-nonce">Nonce to cancel:</label>
          <input type="number" id="cancel-nonce" placeholder="Enter nonce" min="0" />
          <button id="cancel-single-btn" class="danger">Cancel Transaction</button>
        </div>
        <div id="cancel-result"></div>
      </section>
    </div>
  `;
}

// ============================================================================
// Setup Function
// ============================================================================

/**
 * Setup event handlers for the transactions panel.
 * Returns cleanup function.
 */
export function setupTransactionsPanel(state: TransactionsPanelState): () => void {
  const gasProvider = new GasProvider(state.wallet.provider as any);
  let refreshInterval: ReturnType<typeof setInterval> | null = null;

  // Initial load
  refreshGasStatus(gasProvider);
  checkPendingTransactions(gasProvider, state.wallet.address);

  // Auto-refresh every 15 seconds
  refreshInterval = setInterval(() => {
    refreshGasStatus(gasProvider);
    checkPendingTransactions(gasProvider, state.wallet.address);
  }, 15000);

  // Refresh button
  document.getElementById('refresh-gas-btn')?.addEventListener('click', () => {
    gasProvider.clearCache();
    refreshGasStatus(gasProvider);
    checkPendingTransactions(gasProvider, state.wallet.address);
  });

  // Cancel all button
  document.getElementById('cancel-all-btn')?.addEventListener('click', async () => {
    const btn = document.getElementById('cancel-all-btn') as HTMLButtonElement;
    const statusDiv = document.getElementById('pending-tx-status');

    const confirmed = await showConfirmDialog('Cancel all pending transactions? This will send replacement transactions.');
    if (!confirmed) {
      return;
    }

    btn.disabled = true;
    btn.textContent = '⏳ Cancelling...';

    try {
      const result = await gasProvider.cancelAllPendingTransactions(state.wallet.signer);

      if (result.cancelled > 0) {
        if (statusDiv) {
          statusDiv.innerHTML = `
            <p class="success">✅ Cancelled ${result.cancelled}/${result.total} transactions</p>
            ${result.errors.length > 0 ? `<p class="warning">Errors: ${result.errors.join(', ')}</p>` : ''}
          `;
        }
      } else if (result.errors.length > 0) {
        if (statusDiv) {
          statusDiv.innerHTML = `<p class="error">❌ Failed to cancel: ${result.errors.join(', ')}</p>`;
        }
      }

      // Refresh status
      setTimeout(() => {
        checkPendingTransactions(gasProvider, state.wallet.address);
      }, 2000);
    } catch (error) {
      if (statusDiv) {
        statusDiv.innerHTML = `<p class="error">❌ Error: ${error}</p>`;
      }
    } finally {
      btn.disabled = false;
      btn.textContent = '🗑️ Cancel All Pending';
    }
  });

  // Cancel single button
  document.getElementById('cancel-single-btn')?.addEventListener('click', async () => {
    const nonceInput = document.getElementById('cancel-nonce') as HTMLInputElement;
    const resultDiv = document.getElementById('cancel-result');
    const btn = document.getElementById('cancel-single-btn') as HTMLButtonElement;

    const nonce = parseInt(nonceInput.value, 10);
    if (isNaN(nonce) || nonce < 0) {
      if (resultDiv) {
        resultDiv.innerHTML = '<p class="error">Please enter a valid nonce</p>';
      }
      return;
    }

    btn.disabled = true;
    btn.textContent = '⏳ Cancelling...';

    try {
      const result = await gasProvider.cancelTransaction(state.wallet.signer, nonce);

      if (result.success) {
        if (resultDiv) {
          resultDiv.innerHTML = `
            <p class="success">✅ Transaction cancelled!</p>
            <p>TX: <a href="https://polygonscan.com/tx/${result.txHash}" target="_blank">${result.txHash.slice(0, 20)}...</a></p>
          `;
        }
        nonceInput.value = '';
      } else {
        if (resultDiv) {
          resultDiv.innerHTML = `<p class="error">❌ Failed: ${result.error}</p>`;
        }
      }

      // Refresh status
      setTimeout(() => {
        checkPendingTransactions(gasProvider, state.wallet.address);
      }, 2000);
    } catch (error) {
      if (resultDiv) {
        resultDiv.innerHTML = `<p class="error">❌ Error: ${error}</p>`;
      }
    } finally {
      btn.disabled = false;
      btn.textContent = 'Cancel Transaction';
    }
  });

  // Cleanup function
  return () => {
    if (refreshInterval) {
      clearInterval(refreshInterval);
    }
  };
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Show a confirm dialog that works in Office Add-in environments.
 * Uses custom modal instead of native window.confirm() which is blocked.
 */
function showConfirmDialog(message: string): Promise<boolean> {
  return new Promise((resolve) => {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.display = 'flex';
    modal.innerHTML = `
      <div class="modal-backdrop"></div>
      <div class="modal-content" style="max-width: 400px;">
        <div class="modal-header">
          <h2>Confirm Action</h2>
        </div>
        <div class="modal-body">
          <p style="margin-bottom: 1.5rem;">${message}</p>
          <div style="display: flex; gap: 1rem;">
            <button id="confirm-cancel-btn" class="secondary" style="flex: 1;">Cancel</button>
            <button id="confirm-ok-btn" class="danger" style="flex: 1;">Confirm</button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const cancelBtn = modal.querySelector('#confirm-cancel-btn') as HTMLButtonElement;
    const okBtn = modal.querySelector('#confirm-ok-btn') as HTMLButtonElement;
    const backdrop = modal.querySelector('.modal-backdrop') as HTMLElement;

    const cleanup = (result: boolean) => {
      modal.remove();
      resolve(result);
    };

    cancelBtn.addEventListener('click', () => cleanup(false));
    okBtn.addEventListener('click', () => cleanup(true));
    backdrop.addEventListener('click', () => cleanup(false));
  });
}

async function refreshGasStatus(gasProvider: GasProvider): Promise<void> {
  const statusDiv = document.getElementById('gas-status');
  if (!statusDiv) return;

  try {
    const slow = await gasProvider.getGasSettings('slow');
    const standard = await gasProvider.getGasSettings('standard');
    const fast = await gasProvider.getGasSettings('fast');

    statusDiv.innerHTML = `
      <div class="gas-prices">
        <div class="gas-tier">
          <span class="tier-name">🐢 Slow</span>
          <span class="tier-price">${slow.maxFeePerGasGwei.toFixed(1)} Gwei</span>
        </div>
        <div class="gas-tier highlight">
          <span class="tier-name">⚡ Standard</span>
          <span class="tier-price">${standard.maxFeePerGasGwei.toFixed(1)} Gwei</span>
        </div>
        <div class="gas-tier">
          <span class="tier-name">🚀 Fast</span>
          <span class="tier-price">${fast.maxFeePerGasGwei.toFixed(1)} Gwei</span>
        </div>
      </div>
      <p class="hint">Base fee: ${(Number(standard.networkBaseFee) / 1e9).toFixed(1)} Gwei</p>
    `;
  } catch (error) {
    statusDiv.innerHTML = `<p class="error">Failed to fetch gas prices: ${error}</p>`;
  }
}

async function checkPendingTransactions(gasProvider: GasProvider, address: string): Promise<void> {
  const statusDiv = document.getElementById('pending-tx-status');
  const actionsDiv = document.getElementById('pending-tx-actions');
  if (!statusDiv) return;

  try {
    const pending = await gasProvider.getPendingTransactions(address);

    if (pending.hasPending) {
      statusDiv.innerHTML = `
        <p class="warning">⚠️ ${pending.stuckCount} pending transaction(s)</p>
        <p>Confirmed nonce: ${pending.confirmedNonce}</p>
        <p>Pending nonce: ${pending.pendingNonce}</p>
        <p class="hint">These transactions may be stuck due to low gas prices.</p>
      `;
      if (actionsDiv) actionsDiv.style.display = 'block';
    } else {
      statusDiv.innerHTML = '<p class="success">✅ No pending transactions</p>';
      if (actionsDiv) actionsDiv.style.display = 'none';
    }
  } catch (error) {
    statusDiv.innerHTML = `<p class="error">Failed to check pending: ${error}</p>`;
  }
}
