/**
 * Home Tab - Welcome Dashboard
 *
 * Landing page for Rootz Desktop showing wallet status,
 * archive overview, quick actions, and intelligent next-steps advisor.
 * The advisor section evolves based on what the user has already set up.
 */

import { formatAddress } from '../wallet';
import { IdentityManager } from '@rootz/identity-provider';

export interface HomeTabState {
  wallet: {
    address: string;
    balance: string;
    signer: any;  // ethers Signer for on-chain queries
  };
  operatingMode: string;
  operatingIdentity: string | null;
  availableIdentities: string[];
  config: {
    network: {
      name: string;
      chainId: number;
    };
    contracts: {
      identityFactory?: string;
    };
  };
}

// Tracked state for intelligent advisor
interface UserProgress {
  hasWallet: boolean;
  hasCredits: boolean;
  creditBalance: number;
  hasIdentity: boolean;
  identityContractCount: number;  // Number of Identity contracts
  rivetCount: number;             // Number of devices (rivets) on the active Identity contract
  hasArchives: boolean;
  localArchiveCount: number;
  chainArchiveCount: number;
  sessionCount: number;
  messageCount: number;
  hasRecoverySetup: boolean;
  hasMcpConnection: boolean;
}

/**
 * Render the Home tab HTML
 */
export function renderHomeTab(state: HomeTabState): string {
  const symbol = state.config.network.chainId === 137 ? 'POL' : 'ETH';
  const identityDisplay = state.operatingIdentity
    ? `<div class="home-info-row">
        <span class="home-label">Identity:</span>
        <span class="home-value" title="${state.operatingIdentity}">${formatAddress(state.operatingIdentity)}</span>
      </div>`
    : `<div class="home-info-row">
        <span class="home-label">Identity:</span>
        <span class="home-value dim">Not configured</span>
      </div>`;

  return `
    <div class="home-tab">
      <div class="home-hero">
        <h2>Welcome to Rootz Desktop</h2>
        <p class="home-subtitle">Your Sovereign Data Vault</p>
      </div>

      <div class="home-grid">
        <!-- Wallet Status Card -->
        <div class="home-card">
          <h3>Wallet</h3>
          <div class="home-info-row">
            <span class="home-label">Address:</span>
            <span class="home-value mono" title="${state.wallet.address}">${formatAddress(state.wallet.address)}</span>
          </div>
          <div class="home-info-row">
            <span class="home-label">Balance:</span>
            <span class="home-value" id="home-balance">${parseFloat(state.wallet.balance).toFixed(4)} ${symbol}</span>
          </div>
          ${identityDisplay}
          <div class="home-info-row">
            <span class="home-label">Credits:</span>
            <span class="home-value" id="home-credits">Loading...</span>
          </div>
          <div class="home-info-row">
            <span class="home-label">Network:</span>
            <span class="home-value">${state.config.network.name}</span>
          </div>
        </div>

        <!-- Quick Actions Card -->
        <div class="home-card">
          <h3>Quick Actions</h3>
          <div class="home-actions">
            <button class="home-action-btn" data-action="create">Create New Secret</button>
            <button class="home-action-btn" data-action="archives">Search Archives</button>
            <button class="home-action-btn" data-action="identity">Manage Identity</button>
            <button class="home-action-btn secondary" data-action="settings">Settings</button>
          </div>
        </div>

        <!-- Archive Overview Card -->
        <div class="home-card">
          <h3>Archive Overview</h3>
          <div id="home-archive-stats" class="home-stats-grid">
            <div class="home-stat">
              <span class="home-stat-value" id="home-local-count">--</span>
              <span class="home-stat-label">Local</span>
            </div>
            <div class="home-stat">
              <span class="home-stat-value" id="home-chain-count">--</span>
              <span class="home-stat-label">Blockchain</span>
            </div>
            <div class="home-stat">
              <span class="home-stat-value" id="home-session-count">--</span>
              <span class="home-stat-label">Sessions</span>
            </div>
            <div class="home-stat">
              <span class="home-stat-value" id="home-message-count">--</span>
              <span class="home-stat-label">Messages</span>
            </div>
          </div>
        </div>

        <!-- Intelligent Advisor Card -->
        <div class="home-card" id="home-advisor-card">
          <h3 id="home-advisor-title">Loading...</h3>
          <div id="home-advisor-content" class="home-advisor">
            <div class="home-advisor-loading">Checking your setup...</div>
          </div>
        </div>
      </div>

      <!-- About section (shown for new users, hidden once established) -->
      <div class="home-about" id="home-about-section">
        <h3>What is Rootz?</h3>
        <p>
          Rootz Desktop is your personal encrypted vault for AI conversations,
          documents, and digital assets. Everything is encrypted with keys only
          you control. Archives can be stored permanently on the blockchain or
          kept locally on your machine.
        </p>
        <p>
          Connect AI tools like Claude Code via MCP to automatically archive
          your conversations as searchable, immutable records.
        </p>
      </div>
    </div>
  `;
}

/**
 * Generate advisor content based on user's progress
 */
function renderAdvisor(progress: UserProgress, onNavigate: (tab: string) => void): void {
  const titleEl = document.getElementById('home-advisor-title');
  const contentEl = document.getElementById('home-advisor-content');
  const aboutEl = document.getElementById('home-about-section');
  if (!titleEl || !contentEl) return;

  // Count completed basics
  const basicsComplete = [progress.hasWallet, progress.hasCredits, progress.hasIdentity, progress.hasArchives]
    .filter(Boolean).length;

  // New user (0-1 basics done)
  if (basicsComplete <= 1) {
    titleEl.textContent = 'Getting Started';
    if (aboutEl) aboutEl.style.display = 'block';
    contentEl.innerHTML = renderNewUserChecklist(progress);
    return;
  }

  // Established user - hide basic about section
  if (aboutEl) aboutEl.style.display = 'none';

  // All basics done - show advanced recommendations
  if (basicsComplete >= 3) {
    titleEl.textContent = 'Recommendations';
    contentEl.innerHTML = renderRecommendations(progress);
  } else {
    // Partial setup - show remaining steps + tips
    titleEl.textContent = 'Next Steps';
    contentEl.innerHTML = renderNextSteps(progress);
  }

  // Attach click handlers for advisor action buttons
  contentEl.querySelectorAll('[data-nav]').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = (btn as HTMLElement).dataset.nav;
      if (target) onNavigate(target);
    });
  });
}

function renderNewUserChecklist(p: UserProgress): string {
  const check = (done: boolean) => done
    ? '<span class="check-icon done">&#10003;</span>'
    : '<span class="check-icon">&#9675;</span>';

  return `
    <div class="home-checklist">
      <div class="home-check-item ${p.hasWallet ? 'done' : ''}">
        ${check(p.hasWallet)}
        <span>Wallet created</span>
      </div>
      <div class="home-check-item ${p.hasCredits ? 'done' : ''}">
        ${check(p.hasCredits)}
        <span>Purchase credits for blockchain storage</span>
      </div>
      <div class="home-check-item ${p.hasIdentity ? 'done' : ''}">
        ${check(p.hasIdentity)}
        <span>Set up Identity for multi-device recovery</span>
      </div>
      <div class="home-check-item ${p.hasArchives ? 'done' : ''}">
        ${check(p.hasArchives)}
        <span>Create your first archive</span>
      </div>
    </div>
  `;
}

function renderNextSteps(p: UserProgress): string {
  const items: string[] = [];

  if (!p.hasCredits) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Purchase Credits</div>
        <p>Credits are needed to store data on the blockchain. Buy credits with POL to start archiving.</p>
        <button class="home-action-btn small" data-nav="settings">Buy Credits</button>
      </div>
    `);
  }

  if (!p.hasIdentity) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Create an Identity Contract</div>
        <p>An Identity contract enables multi-device access and wallet recovery.
        If you lose this device, another device linked to your Identity can recover all your secrets.</p>
        <button class="home-action-btn small" data-nav="identity">Set Up Identity</button>
      </div>
    `);
  }

  if (!p.hasArchives && p.hasCredits) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Create Your First Secret</div>
        <p>Secrets are encrypted containers for your data. Create one to start archiving conversations, documents, or keys.</p>
        <button class="home-action-btn small" data-nav="create">Create Secret</button>
      </div>
    `);
  }

  // Always show a tip
  items.push(`
    <div class="advisor-item tip">
      <div class="advisor-item-header">MCP Integration</div>
      <p>Connect Claude Code or other AI tools via MCP to automatically archive your conversations. The Desktop app serves as the MCP bridge on port 3020.</p>
    </div>
  `);

  return items.join('');
}

function renderRecommendations(p: UserProgress): string {
  const items: string[] = [];

  // Recovery advice
  if (!p.hasRecoverySetup) {
    items.push(`
      <div class="advisor-item highlight">
        <div class="advisor-item-header">Secure Your Recovery Words</div>
        <p>Your wallet recovery phrase is your master key. Password-protect it and archive it to your Identity contract for safe multi-device recovery.</p>
        <button class="home-action-btn small" data-nav="settings">Recovery Settings</button>
      </div>
    `);
  }

  // Identity device advice — check actual rivet count on the contract, not contract count
  if (p.hasIdentity && p.rivetCount > 0 && p.rivetCount <= 2) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Add ${p.rivetCount === 1 ? 'a Second' : 'Another'} Device</div>
        <p>Your Identity contract has ${p.rivetCount} device${p.rivetCount === 1 ? '' : 's'} (rivet${p.rivetCount === 1 ? '' : 's'}). Adding another device ensures you can recover if this machine is lost or damaged.</p>
        <button class="home-action-btn small" data-nav="identity">Manage Devices</button>
      </div>
    `);
  }

  // Archive growth advice
  if (p.localArchiveCount > 0 && p.chainArchiveCount === 0) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Push Archives to Blockchain</div>
        <p>You have ${p.localArchiveCount} local archives that aren't on the blockchain yet. Pushing them ensures permanent, tamper-proof storage.</p>
        <button class="home-action-btn small" data-nav="archives">View Archives</button>
      </div>
    `);
  }

  // Credit balance advice
  if (p.hasCredits && p.creditBalance < 50000) {
    items.push(`
      <div class="advisor-item">
        <div class="advisor-item-header">Low Credits</div>
        <p>Your credit balance is getting low (${p.creditBalance.toLocaleString()} remaining). Consider purchasing more to ensure uninterrupted archiving.</p>
        <button class="home-action-btn small" data-nav="settings">Buy Credits</button>
      </div>
    `);
  }

  // Sharing advice
  if (p.sessionCount > 10) {
    items.push(`
      <div class="advisor-item tip">
        <div class="advisor-item-header">Team Sharing</div>
        <p>Share encrypted secrets with team members using the Teams tab. Recipients need their own wallet to decrypt - you control who has access.</p>
        <button class="home-action-btn small secondary" data-nav="teams">Open Teams</button>
      </div>
    `);
  }

  // Stats summary
  items.push(`
    <div class="advisor-item tip">
      <div class="advisor-item-header">Your Archive Stats</div>
      <p>${p.sessionCount} sessions captured with ${p.messageCount.toLocaleString()} messages.
      ${p.chainArchiveCount} archives secured on the Polygon blockchain.</p>
    </div>
  `);

  return items.join('');
}

/**
 * Setup Home tab event handlers and load dynamic data
 */
export async function setupHomeTab(state: HomeTabState, onNavigate: (tab: string) => void): Promise<void> {
  // Quick action buttons navigate to other tabs
  document.querySelectorAll('.home-action-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const action = (btn as HTMLElement).dataset.action;
      if (action) onNavigate(action);
    });
  });

  // Build user progress by querying APIs in parallel
  const progress: UserProgress = {
    hasWallet: true,
    hasCredits: false,
    creditBalance: 0,
    hasIdentity: !!state.operatingIdentity,
    identityContractCount: state.availableIdentities?.length ?? (state.operatingIdentity ? 1 : 0),
    rivetCount: 0,
    hasArchives: false,
    localArchiveCount: 0,
    chainArchiveCount: 0,
    sessionCount: 0,
    messageCount: 0,
    hasRecoverySetup: !!localStorage.getItem('rootz_protected_mnemonic'),
    hasMcpConnection: false,
  };

  // Query Identity contract rivet count if we have an active Identity
  const identityInfoPromise = (state.operatingIdentity && state.config.contracts.identityFactory)
    ? (async () => {
        try {
          const identityManager = new IdentityManager({
            signer: state.wallet.signer,
            chainId: state.config.network.chainId,
            factoryAddress: state.config.contracts.identityFactory!,
          });
          const info = await identityManager.getIdentityInfo(state.operatingIdentity!);
          return info;
        } catch (e) {
          console.warn('[Home] Could not query Identity contract:', e);
          return null;
        }
      })()
    : Promise.resolve(null);

  // Fetch all stats in parallel (including Identity info)
  const [archiveStats, mcpStats, walletInfo, identityInfo] = await Promise.allSettled([
    fetch('http://localhost:3020/mcp/archive-stats').then(r => r.ok ? r.json() : null),
    fetch('http://localhost:3020/api/local-archives/stats').then(r => r.ok ? r.json() : null),
    fetch('http://localhost:3020/api/wallet').then(r => r.ok ? r.json() : null),
    identityInfoPromise,
  ]);

  // Process archive stats (sessions + messages + chain archives)
  if (archiveStats.status === 'fulfilled' && archiveStats.value) {
    const data = archiveStats.value;
    progress.sessionCount = data.totalSessions ?? 0;
    progress.messageCount = data.totalMessages ?? 0;
    progress.chainArchiveCount = data.chainArchives?.length ?? 0;

    const sessionEl = document.getElementById('home-session-count');
    const messageEl = document.getElementById('home-message-count');
    const chainEl = document.getElementById('home-chain-count');
    if (sessionEl) sessionEl.textContent = String(progress.sessionCount);
    if (messageEl) messageEl.textContent = progress.messageCount.toLocaleString();
    if (chainEl) chainEl.textContent = String(progress.chainArchiveCount);
  }

  // Process local archive stats
  if (mcpStats.status === 'fulfilled' && mcpStats.value) {
    const data = mcpStats.value;
    const stats = data.stats ?? data;
    progress.localArchiveCount = stats.totalArchives ?? stats.total ?? 0;

    const localEl = document.getElementById('home-local-count');
    if (localEl) localEl.textContent = String(progress.localArchiveCount);
  }

  // Any archives at all?
  progress.hasArchives = (progress.localArchiveCount + progress.chainArchiveCount + progress.sessionCount) > 0;

  // Process wallet info for credits
  if (walletInfo.status === 'fulfilled' && walletInfo.value) {
    const data = walletInfo.value;
    const creditsEl = document.getElementById('home-credits');

    // Try multiple possible response shapes
    const credits = data.credits ?? data.creditBalance ?? data.registryCredits;
    if (credits !== undefined && creditsEl) {
      progress.creditBalance = Number(credits);
      progress.hasCredits = progress.creditBalance > 0;
      creditsEl.textContent = progress.creditBalance.toLocaleString();
    } else if (creditsEl) {
      creditsEl.textContent = '--';
    }
  }

  // Process Identity contract info (rivet count)
  if (identityInfo.status === 'fulfilled' && identityInfo.value) {
    const info = identityInfo.value;
    progress.rivetCount = info.rivetCount ?? 0;
    console.log(`[Home] Identity contract has ${progress.rivetCount} rivet(s)`);
  }

  // Check MCP status
  try {
    const healthResp = await fetch('http://localhost:3020/api/health');
    progress.hasMcpConnection = healthResp.ok;
  } catch {
    // Not critical
  }

  // Render the intelligent advisor
  renderAdvisor(progress, onNavigate);
}
