/**
 * Rootz V6 Dashboard - Gas Utilities
 *
 * Dynamic gas estimation and transaction management.
 * - Queries current network gas prices
 * - Provides cost estimates before transactions
 * - Supports cancelling stuck transactions
 */

import { JsonRpcProvider, formatEther, parseEther, type Signer } from 'ethers';

/**
 * Gas price tiers for user selection
 */
export type GasTier = 'slow' | 'standard' | 'fast';

/**
 * Dynamic gas settings from network query
 */
export interface DynamicGasSettings {
  maxFeePerGas: bigint;
  maxPriorityFeePerGas: bigint;
  baseFee: bigint;
  timestamp: number;
}

/**
 * Transaction cost estimate
 */
export interface GasEstimate {
  tier: GasTier;
  maxFeePerGas: bigint;
  maxPriorityFeePerGas: bigint;
  estimatedGas: bigint;
  maxCostWei: bigint;
  maxCostPOL: string;
  networkBaseFee: bigint;
}

/**
 * Gas multipliers for different speed tiers
 */
const GAS_MULTIPLIERS: Record<GasTier, number> = {
  slow: 1.0,      // Base fee only - may take a while
  standard: 1.15, // 15% buffer - reliable
  fast: 1.3,      // 30% buffer - prioritized
};

/**
 * Priority fee per tier (in Gwei)
 */
const PRIORITY_FEES_GWEI: Record<GasTier, bigint> = {
  slow: 30n * 10n ** 9n,     // 30 Gwei
  standard: 40n * 10n ** 9n, // 40 Gwei
  fast: 60n * 10n ** 9n,     // 60 Gwei
};

/**
 * Default gas limits for different operations
 */
export const GAS_LIMITS = {
  createSecret: 1_500_000n,
  writeNote: 300_000n,
  addTeamMember: 200_000n,
  transfer: 21_000n,
  cancelTransaction: 21_000n,
};

/**
 * Get current network gas prices
 */
export async function getCurrentGasPrice(provider: JsonRpcProvider): Promise<DynamicGasSettings> {
  const feeData = await provider.getFeeData();

  if (!feeData.maxFeePerGas || !feeData.maxPriorityFeePerGas) {
    throw new Error('Network does not support EIP-1559 gas pricing');
  }

  // Get current base fee from latest block
  const block = await provider.getBlock('latest');
  const baseFee = block?.baseFeePerGas || feeData.maxFeePerGas;

  return {
    maxFeePerGas: feeData.maxFeePerGas,
    maxPriorityFeePerGas: feeData.maxPriorityFeePerGas,
    baseFee,
    timestamp: Date.now(),
  };
}

/**
 * Estimate transaction cost with dynamic gas
 */
export async function estimateTransactionCost(
  provider: JsonRpcProvider,
  gasLimit: bigint,
  tier: GasTier = 'standard'
): Promise<GasEstimate> {
  const currentGas = await getCurrentGasPrice(provider);
  const multiplier = GAS_MULTIPLIERS[tier];

  // Calculate max fee with buffer
  const maxFeePerGas = BigInt(Math.ceil(Number(currentGas.baseFee) * multiplier));
  const maxPriorityFeePerGas = PRIORITY_FEES_GWEI[tier];

  // Ensure maxFee is at least baseFee + priority
  const minMaxFee = currentGas.baseFee + maxPriorityFeePerGas;
  const effectiveMaxFee = maxFeePerGas > minMaxFee ? maxFeePerGas : minMaxFee;

  const maxCostWei = effectiveMaxFee * gasLimit;

  return {
    tier,
    maxFeePerGas: effectiveMaxFee,
    maxPriorityFeePerGas,
    estimatedGas: gasLimit,
    maxCostWei,
    maxCostPOL: formatEther(maxCostWei),
    networkBaseFee: currentGas.baseFee,
  };
}

/**
 * Get gas settings for a transaction
 */
export async function getGasSettings(
  provider: JsonRpcProvider,
  tier: GasTier = 'standard'
): Promise<{ maxFeePerGas: bigint; maxPriorityFeePerGas: bigint }> {
  const currentGas = await getCurrentGasPrice(provider);
  const multiplier = GAS_MULTIPLIERS[tier];

  const maxFeePerGas = BigInt(Math.ceil(Number(currentGas.baseFee) * multiplier));
  const maxPriorityFeePerGas = PRIORITY_FEES_GWEI[tier];

  // Ensure maxFee is at least baseFee + priority
  const minMaxFee = currentGas.baseFee + maxPriorityFeePerGas;
  const effectiveMaxFee = maxFeePerGas > minMaxFee ? maxFeePerGas : minMaxFee;

  console.log(`[Gas] Network base fee: ${formatGwei(currentGas.baseFee)} Gwei`);
  console.log(`[Gas] Using ${tier} tier: ${formatGwei(effectiveMaxFee)} Gwei max fee`);

  return {
    maxFeePerGas: effectiveMaxFee,
    maxPriorityFeePerGas,
  };
}

/**
 * Format bigint as Gwei string
 */
export function formatGwei(wei: bigint): string {
  return (Number(wei) / 1e9).toFixed(2);
}

/**
 * Get pending transaction count (nonce) for an address
 */
export async function getPendingNonce(provider: JsonRpcProvider, address: string): Promise<number> {
  // Get both confirmed and pending nonce
  const confirmedNonce = await provider.getTransactionCount(address, 'latest');
  const pendingNonce = await provider.getTransactionCount(address, 'pending');

  console.log(`[Gas] Address ${address.slice(0, 10)}...`);
  console.log(`[Gas] Confirmed nonce: ${confirmedNonce}`);
  console.log(`[Gas] Pending nonce: ${pendingNonce}`);
  console.log(`[Gas] Stuck transactions: ${pendingNonce - confirmedNonce}`);

  return confirmedNonce;
}

/**
 * Cancel a stuck transaction by sending a 0-value tx to self with same nonce
 */
export async function cancelTransaction(
  signer: Signer,
  provider: JsonRpcProvider,
  nonce: number
): Promise<{ txHash: string; success: boolean }> {
  const address = await signer.getAddress();

  console.log(`[Gas] Cancelling transaction at nonce ${nonce}...`);

  // Get current gas and add a big buffer to ensure replacement
  const gasSettings = await getGasSettings(provider, 'fast');

  // Add extra 20% to ensure replacement
  const cancelMaxFee = gasSettings.maxFeePerGas * 120n / 100n;
  const cancelPriority = gasSettings.maxPriorityFeePerGas * 120n / 100n;

  console.log(`[Gas] Cancel tx using ${formatGwei(cancelMaxFee)} Gwei max fee`);

  try {
    const tx = await signer.sendTransaction({
      to: address,  // Send to self
      value: 0n,    // Zero value
      nonce,
      maxFeePerGas: cancelMaxFee,
      maxPriorityFeePerGas: cancelPriority,
      gasLimit: GAS_LIMITS.cancelTransaction,
    });

    console.log(`[Gas] Cancel tx submitted: ${tx.hash}`);
    const receipt = await tx.wait();
    console.log(`[Gas] Cancel tx confirmed in block ${receipt?.blockNumber}`);

    return { txHash: tx.hash, success: true };
  } catch (error) {
    console.error(`[Gas] Cancel tx failed:`, error);
    return { txHash: '', success: false };
  }
}

/**
 * Cancel all pending transactions for an address
 */
export async function cancelAllPendingTransactions(
  signer: Signer,
  provider: JsonRpcProvider
): Promise<{ cancelled: number; errors: string[] }> {
  const address = await signer.getAddress();
  const confirmedNonce = await provider.getTransactionCount(address, 'latest');
  const pendingNonce = await provider.getTransactionCount(address, 'pending');

  const stuckCount = pendingNonce - confirmedNonce;

  if (stuckCount === 0) {
    console.log('[Gas] No pending transactions to cancel');
    return { cancelled: 0, errors: [] };
  }

  console.log(`[Gas] Found ${stuckCount} stuck transaction(s)`);

  const errors: string[] = [];
  let cancelled = 0;

  // Cancel each stuck transaction starting from the lowest nonce
  for (let nonce = confirmedNonce; nonce < pendingNonce; nonce++) {
    const result = await cancelTransaction(signer, provider, nonce);
    if (result.success) {
      cancelled++;
    } else {
      errors.push(`Failed to cancel nonce ${nonce}`);
    }
  }

  console.log(`[Gas] Cancelled ${cancelled}/${stuckCount} transactions`);

  return { cancelled, errors };
}

/**
 * Check if wallet has sufficient balance for a transaction
 */
export async function checkSufficientBalance(
  provider: JsonRpcProvider,
  address: string,
  requiredWei: bigint,
  includeValue: bigint = 0n
): Promise<{ sufficient: boolean; balance: bigint; required: bigint; shortfall: bigint }> {
  const balance = await provider.getBalance(address);
  const totalRequired = requiredWei + includeValue;
  const sufficient = balance >= totalRequired;
  const shortfall = sufficient ? 0n : totalRequired - balance;

  console.log(`[Gas] Balance check:`);
  console.log(`[Gas]   Balance: ${formatEther(balance)} POL`);
  console.log(`[Gas]   Required: ${formatEther(totalRequired)} POL`);
  console.log(`[Gas]   Sufficient: ${sufficient}`);

  return { sufficient, balance, required: totalRequired, shortfall };
}

/**
 * Format a cost estimate for display
 */
export function formatCostEstimate(estimate: GasEstimate): string {
  const baseFeeGwei = formatGwei(estimate.networkBaseFee);
  const maxFeeGwei = formatGwei(estimate.maxFeePerGas);

  return `Network: ${baseFeeGwei} Gwei | Max: ${maxFeeGwei} Gwei | Est. cost: ${parseFloat(estimate.maxCostPOL).toFixed(4)} POL`;
}
