/**
 * @rootz/integration - Transaction Manager
 *
 * Production-ready transaction management with:
 * - Gas estimation with graceful fallback
 * - Automatic retry with gas escalation
 * - User-friendly error classification
 * - Pre-transaction cost preview
 *
 * ## The Problem
 *
 * Blockchain transactions fail for many reasons:
 * - Gas spikes from network congestion
 * - Underestimated gas limits
 * - RPC node issues
 * - Contract reverts
 *
 * In production, we can't just throw errors and crash.
 * We need graceful handling with actionable user feedback.
 *
 * ## Usage
 *
 * ```typescript
 * const txManager = new TransactionManager(provider);
 *
 * // Get cost preview before transaction
 * const preview = await txManager.previewTransaction({
 *   operation: 'createSecret',
 *   estimator: async () => contract.createSecret.estimateGas(...args),
 * });
 *
 * if (!preview.canProceed) {
 *   showError(preview.userMessage);
 *   return;
 * }
 *
 * // Execute with automatic retry
 * const result = await txManager.executeWithRetry({
 *   operation: 'createSecret',
 *   execute: async (gasOverrides) => {
 *     return contract.createSecret(...args, gasOverrides);
 *   },
 * });
 * ```
 */

import { JsonRpcProvider, formatEther, type TransactionResponse, type TransactionReceipt } from 'ethers';
import { GasProvider, GAS_LIMITS, type GasTier, type GasSettings } from '@rootz/gas-provider';

// ============================================================================
// ERROR CLASSIFICATION
// ============================================================================

/**
 * Transaction error categories for user-friendly messaging.
 */
export type TransactionErrorCategory =
  | 'INSUFFICIENT_FUNDS'      // Not enough POL for gas + value
  | 'GAS_LIMIT_EXCEEDED'      // Estimated gas exceeds limit
  | 'GAS_PRICE_SPIKE'         // Network gas price too high
  | 'CONTRACT_REVERT'         // Smart contract rejected transaction
  | 'SIGNATURE_INVALID'       // Signature verification failed
  | 'NONCE_MISMATCH'          // Nonce doesn't match expected
  | 'CREDITS_INSUFFICIENT'    // Not enough credits in registry
  | 'FACTORY_NOT_AUTHORIZED'  // Factory not authorized in registry
  | 'NETWORK_ERROR'           // RPC or network connectivity issue
  | 'TIMEOUT'                 // Transaction took too long
  | 'USER_REJECTED'           // User cancelled in wallet
  | 'UNKNOWN';                // Uncategorized error

/**
 * Classified transaction error with user-friendly messaging.
 */
export interface ClassifiedError {
  /** Error category for programmatic handling */
  category: TransactionErrorCategory;
  /** User-friendly error message */
  userMessage: string;
  /** Technical details for debugging */
  technicalMessage: string;
  /** Suggested action for user */
  suggestedAction: string;
  /** Whether the error is recoverable (can retry) */
  recoverable: boolean;
  /** Original error */
  originalError: Error;
}

/**
 * Classify an error into a user-friendly category.
 */
export function classifyTransactionError(error: unknown): ClassifiedError {
  const err = error instanceof Error ? error : new Error(String(error));
  const message = err.message.toLowerCase();

  // Insufficient funds
  if (message.includes('insufficient funds') || message.includes('insufficient balance')) {
    return {
      category: 'INSUFFICIENT_FUNDS',
      userMessage: 'Insufficient POL balance for this transaction',
      technicalMessage: err.message,
      suggestedAction: 'Add more POL to your wallet and try again',
      recoverable: false,
      originalError: err,
    };
  }

  // Gas estimation failure (usually means contract will revert)
  if (message.includes('cannot estimate gas') || message.includes('execution reverted')) {
    // Check for specific revert reasons
    if (message.includes('invalid signature')) {
      return {
        category: 'SIGNATURE_INVALID',
        userMessage: 'Signature verification failed',
        technicalMessage: err.message,
        suggestedAction: 'Try reconnecting your wallet or refreshing the page',
        recoverable: true,
        originalError: err,
      };
    }
    if (message.includes('invalid nonce') || message.includes('nonce')) {
      return {
        category: 'NONCE_MISMATCH',
        userMessage: 'Transaction nonce mismatch',
        technicalMessage: err.message,
        suggestedAction: 'Refresh the page and try again',
        recoverable: true,
        originalError: err,
      };
    }
    if (message.includes('insufficient credits') || message.includes('credits')) {
      return {
        category: 'CREDITS_INSUFFICIENT',
        userMessage: 'Not enough credits for this operation',
        technicalMessage: err.message,
        suggestedAction: 'Purchase more credits and try again',
        recoverable: false,
        originalError: err,
      };
    }
    if (message.includes('not authorized') || message.includes('unauthorized')) {
      return {
        category: 'FACTORY_NOT_AUTHORIZED',
        userMessage: 'System configuration error - factory not authorized',
        technicalMessage: err.message,
        suggestedAction: 'Please contact support - the system needs configuration',
        recoverable: false,
        originalError: err,
      };
    }

    return {
      category: 'CONTRACT_REVERT',
      userMessage: 'Transaction would fail on the blockchain',
      technicalMessage: err.message,
      suggestedAction: 'Check your inputs and try again, or contact support if the problem persists',
      recoverable: false,
      originalError: err,
    };
  }

  // Gas limit exceeded
  if (message.includes('gas limit') || message.includes('out of gas')) {
    return {
      category: 'GAS_LIMIT_EXCEEDED',
      userMessage: 'Transaction requires more gas than allowed',
      technicalMessage: err.message,
      suggestedAction: 'Try again - the system will automatically increase the gas limit',
      recoverable: true,
      originalError: err,
    };
  }

  // User rejection
  if (message.includes('user rejected') || message.includes('user denied') || message.includes('user cancelled')) {
    return {
      category: 'USER_REJECTED',
      userMessage: 'Transaction cancelled',
      technicalMessage: err.message,
      suggestedAction: 'Click create again when you\'re ready',
      recoverable: true,
      originalError: err,
    };
  }

  // Network errors
  if (message.includes('network') || message.includes('connection') || message.includes('timeout') || message.includes('fetch')) {
    return {
      category: 'NETWORK_ERROR',
      userMessage: 'Network connection issue',
      technicalMessage: err.message,
      suggestedAction: 'Check your internet connection and try again',
      recoverable: true,
      originalError: err,
    };
  }

  // Unknown error
  return {
    category: 'UNKNOWN',
    userMessage: 'An unexpected error occurred',
    technicalMessage: err.message,
    suggestedAction: 'Please try again. If the problem persists, contact support.',
    recoverable: true,
    originalError: err,
  };
}

// ============================================================================
// TRANSACTION PREVIEW
// ============================================================================

/**
 * Pre-transaction cost preview.
 */
export interface TransactionPreview {
  /** Whether the transaction can proceed */
  canProceed: boolean;
  /** User-friendly message */
  userMessage: string;

  /** Gas estimation */
  gas: {
    /** Estimated gas units needed */
    estimatedGas: bigint;
    /** Gas limit that will be used */
    gasLimit: bigint;
    /** Max fee per gas (Gwei) */
    maxFeeGwei: number;
    /** Network base fee (Gwei) */
    baseFeeGwei: number;
    /** Buffer percentage applied */
    bufferPercent: number;
  };

  /** Cost estimate */
  cost: {
    /** Max gas cost in POL */
    maxGasCostPol: string;
    /** Transaction value in POL (if any) */
    valuePol: string;
    /** Total max cost in POL */
    totalMaxPol: string;
  };

  /** Balance check */
  balance: {
    /** Current balance in POL */
    currentPol: string;
    /** Sufficient for transaction */
    sufficient: boolean;
    /** Shortfall if insufficient (POL) */
    shortfallPol?: string;
  };

  /** Warnings (non-blocking) */
  warnings: string[];

  /** Blockers (prevent transaction) */
  blockers: string[];
}

/**
 * Options for transaction preview.
 */
export interface PreviewOptions {
  /** Operation name for gas limits */
  operation: keyof typeof GAS_LIMITS | 'custom';
  /** Custom gas limit (if operation is 'custom') */
  customGasLimit?: bigint;
  /** Gas estimator function */
  estimator?: () => Promise<bigint>;
  /** Transaction value in wei */
  value?: bigint;
  /** Wallet address for balance check */
  walletAddress: string;
  /** Gas tier to use */
  tier?: GasTier;
}

// ============================================================================
// TRANSACTION EXECUTION
// ============================================================================

/**
 * Result of a transaction execution.
 */
export interface TransactionResult<T = TransactionReceipt> {
  /** Whether the transaction succeeded */
  success: boolean;
  /** Transaction receipt (if successful) */
  receipt?: T;
  /** Transaction hash */
  txHash?: string;
  /** Block number */
  blockNumber?: number;
  /** Gas used */
  gasUsed?: bigint;
  /** Actual gas cost in POL */
  actualCostPol?: string;
  /** Error (if failed) */
  error?: ClassifiedError;
  /** Number of retry attempts made */
  retryAttempts: number;
}

/**
 * Options for transaction execution.
 */
export interface ExecuteOptions {
  /** Operation name for gas limits */
  operation: keyof typeof GAS_LIMITS | 'custom';
  /** Custom gas limit (if operation is 'custom') */
  customGasLimit?: bigint;
  /** Function to execute the transaction */
  execute: (gasOverrides: { maxFeePerGas: bigint; maxPriorityFeePerGas: bigint; gasLimit?: bigint }) => Promise<TransactionResponse>;
  /** Maximum retry attempts (default: 2) */
  maxRetries?: number;
  /** Gas tier to use (default: 'standard') */
  tier?: GasTier;
  /** Whether to escalate tier on retry (default: true) */
  escalateTierOnRetry?: boolean;
  /** Progress callback */
  onProgress?: (message: string) => void;
}

// ============================================================================
// TRANSACTION MANAGER
// ============================================================================

/**
 * Production-ready transaction manager.
 *
 * Handles gas estimation, cost preview, retry logic, and error classification
 * to provide a resilient blockchain transaction experience.
 */
export class TransactionManager {
  private gasProvider: GasProvider;
  private provider: JsonRpcProvider;

  constructor(provider: JsonRpcProvider) {
    this.provider = provider;
    this.gasProvider = new GasProvider(provider);
  }

  /**
   * Get transaction preview before execution.
   *
   * This provides:
   * - Estimated gas cost
   * - Balance check
   * - Warnings and blockers
   *
   * Call this BEFORE showing the "confirm" button to the user.
   */
  async previewTransaction(options: PreviewOptions): Promise<TransactionPreview> {
    const tier = options.tier ?? 'standard';
    const value = options.value ?? 0n;
    const warnings: string[] = [];
    const blockers: string[] = [];

    // 1. Get gas settings from network
    let gasSettings: GasSettings;
    try {
      gasSettings = await this.gasProvider.getGasSettings(tier);
    } catch (error) {
      const classified = classifyTransactionError(error);
      blockers.push(`Cannot get gas prices: ${classified.userMessage}`);
      return this.buildBlockedPreview(blockers, warnings, options.walletAddress, value);
    }

    // 2. Get base gas limit for operation
    const baseGasLimit = options.operation === 'custom'
      ? (options.customGasLimit ?? 500_000n)
      : GAS_LIMITS[options.operation];

    // 3. Try to estimate actual gas (if estimator provided)
    let estimatedGas = baseGasLimit;
    let estimationFailed = false;

    if (options.estimator) {
      try {
        estimatedGas = await options.estimator();
        console.log(`[TxManager] Gas estimation succeeded: ${estimatedGas.toLocaleString()}`);

        // Check if estimated gas is close to or exceeds limit
        if (estimatedGas > baseGasLimit) {
          const escalatedLimit = (estimatedGas * 130n) / 100n; // 30% buffer
          warnings.push(`High gas usage detected (${estimatedGas.toLocaleString()}). Using ${escalatedLimit.toLocaleString()} limit.`);
          estimatedGas = escalatedLimit;
        } else if (estimatedGas > (baseGasLimit * 90n) / 100n) {
          warnings.push(`Gas usage (${estimatedGas.toLocaleString()}) is close to limit (${baseGasLimit.toLocaleString()}). Transaction may fail if network conditions change.`);
        }
      } catch (error) {
        estimationFailed = true;
        const classified = classifyTransactionError(error);

        if (!classified.recoverable) {
          blockers.push(classified.userMessage);
          console.error(`[TxManager] Gas estimation failed (blocking): ${classified.technicalMessage}`);
        } else {
          warnings.push(`Could not estimate gas: ${classified.userMessage}. Using conservative estimate.`);
          console.warn(`[TxManager] Gas estimation failed (warning): ${classified.technicalMessage}`);
          // Use base limit with 20% buffer as fallback
          estimatedGas = (baseGasLimit * 120n) / 100n;
        }
      }
    }

    // 4. Calculate gas limit to use
    const gasLimit = estimationFailed
      ? (baseGasLimit * 130n) / 100n  // 30% buffer if estimation failed
      : (estimatedGas > baseGasLimit ? estimatedGas : baseGasLimit);

    // 5. Calculate costs
    const maxGasCostWei = gasSettings.maxFeePerGas * gasLimit;
    const totalMaxWei = maxGasCostWei + value;

    // 6. Check balance
    let balance = 0n;
    let balanceSufficient = false;
    try {
      balance = await this.provider.getBalance(options.walletAddress);
      balanceSufficient = balance >= totalMaxWei;

      if (!balanceSufficient) {
        const shortfall = totalMaxWei - balance;
        blockers.push(`Insufficient balance. Need ${formatEther(shortfall)} more POL.`);
      }
    } catch (error) {
      warnings.push('Could not check wallet balance');
    }

    // 7. Build preview
    const bufferPercent = Number(((gasLimit - estimatedGas) * 100n) / estimatedGas);

    return {
      canProceed: blockers.length === 0,
      userMessage: blockers.length > 0
        ? blockers[0]
        : warnings.length > 0
          ? `Ready with warnings: ${warnings[0]}`
          : 'Ready to proceed',

      gas: {
        estimatedGas,
        gasLimit,
        maxFeeGwei: gasSettings.maxFeePerGasGwei,
        baseFeeGwei: Number(gasSettings.networkBaseFee) / 1e9,
        bufferPercent: Math.max(0, bufferPercent),
      },

      cost: {
        maxGasCostPol: formatEther(maxGasCostWei),
        valuePol: formatEther(value),
        totalMaxPol: formatEther(totalMaxWei),
      },

      balance: {
        currentPol: formatEther(balance),
        sufficient: balanceSufficient,
        shortfallPol: !balanceSufficient ? formatEther(totalMaxWei - balance) : undefined,
      },

      warnings,
      blockers,
    };
  }

  /**
   * Build a blocked preview (when we can't complete estimation).
   */
  private async buildBlockedPreview(
    blockers: string[],
    warnings: string[],
    walletAddress: string,
    value: bigint
  ): Promise<TransactionPreview> {
    let balance = 0n;
    try {
      balance = await this.provider.getBalance(walletAddress);
    } catch {
      // Ignore balance fetch error
    }

    return {
      canProceed: false,
      userMessage: blockers[0] || 'Cannot proceed with transaction',
      gas: {
        estimatedGas: 0n,
        gasLimit: 0n,
        maxFeeGwei: 0,
        baseFeeGwei: 0,
        bufferPercent: 0,
      },
      cost: {
        maxGasCostPol: '0',
        valuePol: formatEther(value),
        totalMaxPol: formatEther(value),
      },
      balance: {
        currentPol: formatEther(balance),
        sufficient: false,
      },
      warnings,
      blockers,
    };
  }

  /**
   * Execute transaction with automatic retry on recoverable failures.
   *
   * Retry strategy:
   * 1. First attempt: Use 'standard' tier gas
   * 2. First retry: Escalate to 'fast' tier + 30% higher limit
   * 3. Second retry: Maximum gas settings
   */
  async executeWithRetry<T = TransactionReceipt>(
    options: ExecuteOptions
  ): Promise<TransactionResult<T>> {
    const maxRetries = options.maxRetries ?? 2;
    const escalate = options.escalateTierOnRetry ?? true;
    const baseGasLimit = options.operation === 'custom'
      ? (options.customGasLimit ?? 500_000n)
      : GAS_LIMITS[options.operation];

    let lastError: ClassifiedError | undefined;
    let attempts = 0;

    const tiers: GasTier[] = escalate
      ? ['standard', 'fast', 'fast']
      : [options.tier ?? 'standard', options.tier ?? 'standard', options.tier ?? 'standard'];

    const gasMultipliers = [1.0, 1.3, 1.5]; // Escalate gas limit on retries

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      attempts = attempt + 1;
      const tier = tiers[Math.min(attempt, tiers.length - 1)];
      const gasMultiplier = gasMultipliers[Math.min(attempt, gasMultipliers.length - 1)];

      try {
        options.onProgress?.(`Attempt ${attempts}: Getting gas prices...`);

        // Get gas settings
        const gasSettings = await this.gasProvider.getGasSettings(tier);
        const gasLimit = BigInt(Math.ceil(Number(baseGasLimit) * gasMultiplier));

        console.log(`[TxManager] Attempt ${attempts}: tier=${tier}, gasLimit=${gasLimit.toLocaleString()}, maxFee=${gasSettings.maxFeePerGasGwei.toFixed(2)} Gwei`);

        options.onProgress?.(`Attempt ${attempts}: Sending transaction...`);

        // Execute transaction
        const tx = await options.execute({
          maxFeePerGas: gasSettings.maxFeePerGas,
          maxPriorityFeePerGas: gasSettings.maxPriorityFeePerGas,
          gasLimit,
        });

        options.onProgress?.(`Transaction sent: ${tx.hash.slice(0, 10)}...`);

        // Wait for confirmation
        const receipt = await tx.wait();
        if (!receipt) {
          throw new Error('Transaction failed - no receipt');
        }

        const gasUsed = BigInt(receipt.gasUsed);
        const effectiveGasPrice = BigInt(receipt.gasPrice ?? gasSettings.maxFeePerGas);
        const actualCost = gasUsed * effectiveGasPrice;

        console.log(`[TxManager] Transaction confirmed: block=${receipt.blockNumber}, gasUsed=${gasUsed.toLocaleString()}, cost=${formatEther(actualCost)} POL`);

        return {
          success: true,
          receipt: receipt as unknown as T,
          txHash: receipt.hash,
          blockNumber: receipt.blockNumber,
          gasUsed,
          actualCostPol: formatEther(actualCost),
          retryAttempts: attempts - 1,
        };

      } catch (error) {
        lastError = classifyTransactionError(error);
        console.warn(`[TxManager] Attempt ${attempts} failed: ${lastError.category} - ${lastError.technicalMessage}`);

        // Don't retry non-recoverable errors
        if (!lastError.recoverable) {
          console.error(`[TxManager] Non-recoverable error, not retrying`);
          break;
        }

        // Don't retry user rejections
        if (lastError.category === 'USER_REJECTED') {
          console.log(`[TxManager] User rejected, not retrying`);
          break;
        }

        // Clear gas cache before retry
        this.gasProvider.clearCache();

        if (attempt < maxRetries) {
          options.onProgress?.(`Retrying with higher gas settings...`);
          // Small delay before retry
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }
    }

    // All attempts failed
    return {
      success: false,
      error: lastError ?? classifyTransactionError(new Error('Unknown error')),
      retryAttempts: attempts - 1,
    };
  }

  /**
   * Get current gas price summary for display.
   */
  async getGasSummary(): Promise<{
    baseFeeGwei: number;
    standardFeeGwei: number;
    fastFeeGwei: number;
    fetchedAt: Date;
  }> {
    const [standard, fast] = await Promise.all([
      this.gasProvider.getGasSettings('standard'),
      this.gasProvider.getGasSettings('fast'),
    ]);

    return {
      baseFeeGwei: Number(standard.networkBaseFee) / 1e9,
      standardFeeGwei: standard.maxFeePerGasGwei,
      fastFeeGwei: fast.maxFeePerGasGwei,
      fetchedAt: new Date(standard.fetchedAt),
    };
  }
}

/**
 * Create a transaction manager instance.
 */
export function createTransactionManager(provider: JsonRpcProvider): TransactionManager {
  return new TransactionManager(provider);
}
