/**
 * @rootz/teams - KeySharing
 *
 * ECDH key exchange for secure master key sharing between team members.
 * Uses secp256k1 curve (same as Ethereum) for compatibility.
 *
 * ## Algorithm:
 * 1. Compute ECDH shared secret: privKey_A * pubKey_B = privKey_B * pubKey_A
 * 2. Derive AES key: keccak256(sharedSecret)
 * 3. Encrypt with AES-256-GCM
 *
 * ## Package Format:
 * { encrypted: string, iv: string } - JSON string
 *
 * @see ecdh-crypto.js for browser reference implementation
 */

import { keccak256, getBytes, hexlify, SigningKey, Wallet, randomBytes } from 'ethers';
import type { ECDHCryptoProvider, ECDHEncryptedPackage } from './types.js';

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Convert hex string to Uint8Array
 */
function hexToBytes(hex: string): Uint8Array {
  const cleanHex = hex.startsWith('0x') ? hex.slice(2) : hex;
  return getBytes('0x' + cleanHex);
}

/**
 * Convert Uint8Array to hex string
 */
function bytesToHex(bytes: Uint8Array): string {
  return hexlify(bytes);
}

/**
 * Get crypto implementation (Node.js or browser)
 */
function getCrypto(): Crypto {
  if (typeof globalThis.crypto !== 'undefined') {
    return globalThis.crypto;
  }
  // Node.js
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { webcrypto } = require('crypto');
  return webcrypto as Crypto;
}

// ============================================================================
// KEY SHARING CLASS
// ============================================================================

/**
 * KeySharing - ECDH key exchange implementation
 *
 * Provides secure key sharing between team members using:
 * - secp256k1 ECDH for shared secret computation
 * - keccak256 for AES key derivation (Ethereum standard)
 * - AES-256-GCM for encryption
 *
 * @example
 * ```typescript
 * const ks = new KeySharing();
 *
 * // Owner encrypts master key for member
 * const encrypted = await ks.encryptWithEphemeralKey(
 *   masterKey,
 *   memberPublicKey,
 *   ephemeralPrivateKey
 * );
 *
 * // Member decrypts with their private key
 * const decrypted = await ks.decryptWithEphemeralKey(
 *   encrypted,
 *   ephemeralPublicKey,
 *   memberPrivateKey
 * );
 * ```
 */
export class KeySharing implements ECDHCryptoProvider {
  private crypto: Crypto;

  constructor() {
    this.crypto = getCrypto();
  }

  // ==========================================================================
  // ECDH SHARED SECRET
  // ==========================================================================

  /**
   * Compute ECDH shared secret
   *
   * Mathematical property:
   *   myPrivKey * theirPubKey == theirPrivKey * myPubKey
   *
   * @param privateKey - My private key (hex with 0x prefix)
   * @param publicKey - Their public key (uncompressed, 0x04...)
   * @returns Shared secret (hex with 0x)
   */
  async computeSharedSecret(privateKey: string, publicKey: string): Promise<string> {
    // Normalize inputs
    const privKey = privateKey.startsWith('0x') ? privateKey : '0x' + privateKey;
    const pubKey = publicKey.startsWith('0x') ? publicKey : '0x' + publicKey;

    // Validate private key (32 bytes = 64 hex chars)
    const privKeyClean = privKey.slice(2);
    if (privKeyClean.length !== 64) {
      throw new Error(`Invalid private key length: ${privKeyClean.length} (expected 64 hex chars)`);
    }

    // Validate public key (uncompressed = 65 bytes = 130 hex chars, starts with 04)
    const pubKeyClean = pubKey.slice(2);
    if (pubKeyClean.length !== 130) {
      throw new Error(`Invalid public key length: ${pubKeyClean.length} (expected 130 hex chars)`);
    }
    if (!pubKeyClean.startsWith('04')) {
      throw new Error('Public key must be uncompressed (start with 04)');
    }

    // Use ethers v6 SigningKey for ECDH
    const signingKey = new SigningKey(privKey);
    const sharedSecret = signingKey.computeSharedSecret(pubKey);

    return sharedSecret;
  }

  // ==========================================================================
  // AES KEY DERIVATION
  // ==========================================================================

  /**
   * Derive AES-256 key from ECDH shared secret
   *
   * Uses keccak256 (Ethereum standard) for key derivation.
   *
   * @param sharedSecret - ECDH shared secret (hex)
   * @returns AES-GCM CryptoKey
   */
  private async deriveAESKey(sharedSecret: string): Promise<CryptoKey> {
    // Derive key using keccak256 (Ethereum standard)
    const aesKeyHex = keccak256(sharedSecret);
    const aesKeyBytes = hexToBytes(aesKeyHex);

    // Import as AES-GCM key
    const aesKey = await this.crypto.subtle.importKey(
      'raw',
      aesKeyBytes.buffer as ArrayBuffer,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );

    return aesKey;
  }

  // ==========================================================================
  // AES ENCRYPTION
  // ==========================================================================

  /**
   * Encrypt data with AES-256-GCM
   *
   * @param data - Data to encrypt (string)
   * @param aesKey - AES key
   * @returns { encrypted, iv } - hex strings
   */
  private async encryptAES(data: string, aesKey: CryptoKey): Promise<ECDHEncryptedPackage> {
    // Generate random IV (12 bytes for GCM)
    const iv = this.crypto.getRandomValues(new Uint8Array(12));

    // Convert data to bytes (UTF-8)
    const encoder = new TextEncoder();
    const dataBytes = encoder.encode(data);

    // Encrypt with AES-GCM
    const ciphertext = await this.crypto.subtle.encrypt(
      {
        name: 'AES-GCM',
        iv: iv,
        tagLength: 128, // 16-byte auth tag
      },
      aesKey,
      dataBytes
    );

    return {
      encrypted: bytesToHex(new Uint8Array(ciphertext)),
      iv: bytesToHex(iv),
    };
  }

  /**
   * Decrypt data with AES-256-GCM
   *
   * @param encrypted - Encrypted data (hex)
   * @param iv - IV (hex)
   * @param aesKey - AES key
   * @returns Decrypted string
   */
  private async decryptAES(encrypted: string, iv: string, aesKey: CryptoKey): Promise<string> {
    const encryptedBytes = hexToBytes(encrypted);
    const ivBytes = hexToBytes(iv);

    // Decrypt with AES-GCM
    const plaintext = await this.crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv: ivBytes.buffer as ArrayBuffer,
        tagLength: 128,
      },
      aesKey,
      encryptedBytes.buffer as ArrayBuffer
    );

    // Convert bytes to string (UTF-8)
    const decoder = new TextDecoder();
    return decoder.decode(plaintext);
  }

  // ==========================================================================
  // PUBLIC API - EPHEMERAL KEY ENCRYPTION
  // ==========================================================================

  /**
   * Encrypt data using ephemeral ECDH
   *
   * This is the canonical method for encrypting data for team members.
   *
   * @param data - Data to encrypt (any string)
   * @param recipientPublicKey - Recipient's public key (0x04...)
   * @param senderPrivateKey - Sender's ephemeral private key (0x...)
   * @returns JSON string: { encrypted, iv }
   */
  async encryptWithEphemeralKey(
    data: string,
    recipientPublicKey: string,
    senderPrivateKey: string
  ): Promise<string> {
    // 1. Compute ECDH shared secret
    const sharedSecret = await this.computeSharedSecret(senderPrivateKey, recipientPublicKey);

    // 2. Derive AES key using keccak256
    const aesKey = await this.deriveAESKey(sharedSecret);

    // 3. Encrypt with AES-GCM
    const encrypted = await this.encryptAES(data, aesKey);

    // 4. Return JSON package
    return JSON.stringify(encrypted);
  }

  /**
   * Decrypt data using ephemeral ECDH
   *
   * This is the canonical method for decrypting data from team members.
   *
   * @param encryptedJson - JSON string from encryptWithEphemeralKey
   * @param senderPublicKey - Sender's ephemeral public key (0x04...)
   * @param recipientPrivateKey - Recipient's private key (0x...)
   * @returns Decrypted data string
   */
  async decryptWithEphemeralKey(
    encryptedJson: string,
    senderPublicKey: string,
    recipientPrivateKey: string
  ): Promise<string> {
    // 1. Parse JSON package
    const pkg: ECDHEncryptedPackage = JSON.parse(encryptedJson);

    // 2. Compute ECDH shared secret (same as sender computed)
    const sharedSecret = await this.computeSharedSecret(recipientPrivateKey, senderPublicKey);

    // 3. Derive AES key using keccak256 (must match encryption)
    const aesKey = await this.deriveAESKey(sharedSecret);

    // 4. Decrypt with AES-GCM
    const decrypted = await this.decryptAES(pkg.encrypted, pkg.iv, aesKey);

    return decrypted;
  }

  /**
   * Generate ephemeral key pair for forward secrecy
   *
   * @returns { privateKey, publicKey } - hex strings with 0x prefix
   */
  generateEphemeralKeyPair(): { privateKey: string; publicKey: string } {
    // Generate random 32 bytes for private key
    const privateKeyBytes = randomBytes(32);
    const privateKey = hexlify(privateKeyBytes);

    // Derive public key using ethers Wallet
    const wallet = new Wallet(privateKey);
    const publicKey = wallet.signingKey.publicKey;

    return { privateKey, publicKey };
  }

  // ==========================================================================
  // CONVENIENCE METHODS
  // ==========================================================================

  /**
   * Encrypt master key for team member
   *
   * Combines ephemeral key generation with encryption.
   * Returns encrypted package and ephemeral public key for recipient.
   *
   * @param masterKey - Master key to share (hex)
   * @param memberPublicKey - Member's public key
   * @returns { encryptedJson, ephemeralPublicKey }
   */
  async encryptMasterKeyForMember(
    masterKey: string,
    memberPublicKey: string
  ): Promise<{ encryptedJson: string; ephemeralPublicKey: string; ephemeralPrivateKey: string }> {
    // Generate ephemeral key pair
    const { privateKey: ephemeralPrivateKey, publicKey: ephemeralPublicKey } =
      this.generateEphemeralKeyPair();

    // Encrypt master key
    const encryptedJson = await this.encryptWithEphemeralKey(
      masterKey,
      memberPublicKey,
      ephemeralPrivateKey
    );

    return {
      encryptedJson,
      ephemeralPublicKey,
      ephemeralPrivateKey, // Caller should store this for the session
    };
  }

  /**
   * Decrypt master key from owner
   *
   * @param encryptedJson - Encrypted package from owner
   * @param ephemeralPublicKey - Owner's ephemeral public key
   * @param memberPrivateKey - Member's private key
   * @returns Decrypted master key
   */
  async decryptMasterKeyFromOwner(
    encryptedJson: string,
    ephemeralPublicKey: string,
    memberPrivateKey: string
  ): Promise<string> {
    return this.decryptWithEphemeralKey(encryptedJson, ephemeralPublicKey, memberPrivateKey);
  }
}
