/**
 * Document Revision - Write document updates as notes
 *
 * This module handles adding document revisions to an existing document secret.
 * Revisions are stored as encrypted notes in the secret's KeyVault, allowing
 * all versions of a document to live together under a single secret address.
 *
 * @module document-revision
 */

import { NoteManager, type WriteNoteOptions } from '@rootz/notes';
import {
  captureDocument,
  buildDocumentSecretContent,
  type DocumentCapture,
} from './office-integration';

/**
 * Configuration for creating a document revision
 */
export interface CreateRevisionConfig {
  /** Secret contract address */
  secretAddress: string;
  /** KeyVault block number */
  kvBlock: number;
  /** KV key for encryption (decrypted from KeyVault) */
  kvKey: Uint8Array;
  /** Signer for transaction */
  signer: any;
  /** Chain configuration */
  chainConfig: {
    chainId: number;
    rpcUrl: string;
    registryAddress?: string;
  };
  /** IPFS configuration for large document storage */
  ipfsConfig?: {
    apiKey: string;
    secretKey: string;
    endpoint?: string;
    gateway?: string;
  };
  /** Write authorization for Identity mode (optional for owner) */
  writeAuthorization?: WriteNoteOptions['writeAuthorization'];
  /** Current note count (for revision numbering) */
  noteCount?: number;
}

/**
 * Result of creating a revision
 */
export interface CreateRevisionResult {
  /** Transaction hash */
  txHash: string;
  /** Revision number */
  revisionNumber: number;
  /** Document hash */
  contentHash: string;
  /** Captured filename */
  filename: string;
}

/**
 * Create a document revision by capturing the current Word document
 * and writing it as a note to the secret's KeyVault.
 *
 * This uses the same content format as the original secret creation,
 * so all revisions have identical proof-of-origin metadata.
 */
export async function createDocumentRevision(
  config: CreateRevisionConfig
): Promise<CreateRevisionResult> {
  console.log('[DocumentRevision] Starting revision capture for:', config.secretAddress);

  // Step 1: Capture the current document from Word
  const capture = await captureDocument();
  console.log('[DocumentRevision] Document captured:', {
    filename: capture.metadata.filename,
    size: capture.bytes.length,
    hash: capture.hash.slice(0, 16) + '...',
  });

  // Step 2: Build the content JSON (same format as original secret)
  const content = buildDocumentSecretContent(capture);
  console.log('[DocumentRevision] Content built, size:', content.length, 'bytes');

  // Step 3: Calculate revision number
  const revisionNumber = (config.noteCount || 0) + 1;

  // Step 4: Create NoteManager with IPFS support for large documents
  const noteManager = new NoteManager(config.signer, {
    chainId: config.chainConfig.chainId,
    rpcUrl: config.chainConfig.rpcUrl,
    registryAddress: config.chainConfig.registryAddress,
    autoFundEnabled: true,
    autoFundAmount: 50000, // 50K credits for document revisions
    // IPFS config for documents larger than 100KB
    ipfs: config.ipfsConfig,
    ipfsSizeThreshold: 100000, // 100KB threshold
  });

  // Step 5: Write as note
  console.log('[DocumentRevision] Writing note to KeyVault:', config.kvBlock);

  const writeOptions: WriteNoteOptions = {
    secretAddress: config.secretAddress,
    kvBlock: config.kvBlock,
    content,
    kvKey: config.kvKey,
    metadata: {
      revisionType: 'document-revision',
      revisionNumber,
      originalFilename: capture.metadata.filename,
      capturedAt: new Date(capture.capturedAt).toISOString(),
      contentHash: capture.hash,
    },
    version: `revision-${revisionNumber}`,
    writeAuthorization: config.writeAuthorization,
  };

  // Link to previous note if this isn't the first revision
  if (config.noteCount && config.noteCount > 0) {
    writeOptions.previousNote = config.noteCount - 1;
  }

  const result = await noteManager.writeNote(writeOptions);

  console.log('[DocumentRevision] Revision written:', {
    txHash: result.txHash,
    revisionNumber,
  });

  return {
    txHash: result.txHash,
    revisionNumber,
    contentHash: `sha256:${capture.hash}`,
    filename: capture.metadata.filename,
  };
}

/**
 * Check if user can add a revision to a document secret.
 * Returns true if all requirements are met.
 */
export function canAddRevision(context: {
  isOwner: boolean;
  hasKvBlock: boolean;
  isOfficeContext: boolean;
}): boolean {
  return context.isOwner && context.hasKvBlock && context.isOfficeContext;
}

/**
 * Verify that a secret is compatible with document revisions.
 * Checks that the secret content is a word-document type.
 */
export function isDocumentSecret(content: string): boolean {
  try {
    const parsed = JSON.parse(content);
    return parsed.type === 'word-document';
  } catch {
    return false;
  }
}
