/**
 * @rootz/chain-reader - Message Types
 *
 * All message types that can appear on the Rootz blockchain.
 * Based on MESSAGE_TYPES.md specification.
 */

// ============================================================================
// Core Types
// ============================================================================

export type MessageType =
  | 'team-invite'
  | 'invite-response'
  | 'team-keys'
  | 'encrypted-keys'
  | 'direct-keys'
  | 'bootstrap-sync' // Sync keys to new device via bootstrap secret
  | 'genesis' // Epistery: self-transfer marking wallet creation
  | 'transfer' // Simple native currency transfer (POL, ETH, etc.)
  | 'secret-created'
  | 'keyvault-created'
  | 'data-written'
  | 'team-member-added'
  // File access protocol (remote file operations via blockchain)
  | 'file-request'
  | 'file-response'
  | 'unknown';

export interface ChainMessage {
  type: MessageType;
  txHash: string;
  blockNumber: number;
  from: string;
  to: string;
  timestamp: number;
  payload: unknown;
  raw: string;
}

// ============================================================================
// Transaction Message Payloads (JSON in TX input)
// ============================================================================

/**
 * Team Invite - Owner invites member to access secret
 * Direction: Owner → Member
 */
export interface TeamInvitePayload {
  type: 'team-invite';
  version: string;
  inviteId: string;

  secretContract: string;
  secretName: string;
  mintBlockNumber: number;
  keyVaultBlock: number;
  keyVaultName: string;

  proposedRole: 'MEMBER' | 'ADMIN' | 'VIEWER';

  ownerAddress: string;
  ownerPublicKey: string; // Uncompressed secp256k1

  authorization?: {
    keyVaultBlock: number;
    memberAddress: string;
    expiresAt: number;
    signature: {
      v: number;
      r: string;
      s: string;
    };
  };

  encryptedKeys: null;
  timestamp: number;
}

/**
 * Invite Response - Member accepts/declines invite
 * Direction: Member → Owner
 */
export interface InviteResponsePayload {
  type: 'invite-response';
  version: string;
  inviteId: string;
  accepted: boolean;

  inviteBlockId?: number;
  inviteBlockNumber?: number; // V4
  inviteTxHash?: string; // V4
  mintBlockNumber?: number;
  keyVaultBlock?: number;

  secretContract: string;
  secretName?: string;
  keyVaultName?: string;

  memberAddress: string;
  memberPublicKey?: string; // Only when accepted=true

  timestamp: number;
}

/**
 * Encrypted Keys - Owner sends encrypted keys to member
 * Direction: Owner → Member
 */
export interface EncryptedKeysPayload {
  type: 'encrypted-access-keys' | 'encrypted-keys' | 'team-keys';
  version: string;
  inviteId: string;

  inviteBlockId?: number;
  responseBlockNumber?: number;
  responseTxHash?: string;
  mintBlockNumber: number;
  mintTxHash?: string;
  keyVaultBlock: number;

  secretContract: string;
  secretName: string;
  keyVaultName: string;
  identityContract?: string;

  role?: string;
  proposedRole?: string;
  canWrite?: boolean;

  encryptedKVKey?: EncryptedKeyData;
  encryptedMasterKey: EncryptedKeyData;

  encryptionMethod?: string;
  ephemeralPublicKey?: string;

  writeAuthorization?: WriteAuthorization;

  recipientAddress?: string;
  timestamp: number;
}

/**
 * Direct Keys - Single-step key sharing (bypasses 3-step invite flow)
 * Direction: Owner → Member
 *
 * Used when owner already knows member's public key and wants to
 * share access in a single transaction.
 *
 * ## ECDH Key Exchange
 * - Owner generates ephemeral key pair
 * - Encrypts master key using ECDH: ephemeralPrivate + memberPublicKey
 * - Sends senderPublicKey (ephemeral) so member can decrypt
 * - Member decrypts using: memberPrivate + senderPublicKey
 *
 * ## Format Compatibility Note
 * This payload supports two encryption formats for compatibility:
 * 1. Flat format (dashboard): encryptedMasterKey as string, iv as top-level field
 * 2. Nested format (chain-reader): encryptedMasterKeyFull as EncryptedKeyData
 */
export interface DirectKeysPayload {
  type: 'direct-keys';
  version: string;

  secretContract: string;
  secretName: string;
  keyVaultBlock: number;
  mintBlockNumber?: number;

  // Recipient and sender info
  recipient: string;           // Member address receiving the keys
  sender: string;              // Owner address sending the keys
  senderIdentity?: string;     // Owner's identity contract (if using identity mode)

  // ECDH keys
  /** Ephemeral public key for ECDH decryption - use this to decrypt */
  senderPublicKey: string;     // Uncompressed secp256k1 (0x04...)
  /** Owner's permanent public key (for contact storage, not decryption) */
  ownerPublicKey?: string;     // Uncompressed secp256k1 (0x04...)

  // Flat format (dashboard compatibility)
  /** Master key ciphertext as hex string */
  encryptedMasterKey: string;
  /** IV as hex string */
  iv: string;

  // Access control
  proposedRole?: string;
  canWrite?: boolean;

  // Nested format (chain-reader compatibility)
  /** Full encrypted key data with algorithm info */
  encryptedMasterKeyFull?: EncryptedKeyData;
  /** KV key encrypted for member (optional) */
  encryptedKVKey?: EncryptedKeyData;

  writeAuthorization?: WriteAuthorization;

  timestamp: number;
}

/**
 * Bootstrap Sync - Sync all keys from sender to new device
 * Direction: Existing Rivet → New Rivet (via bootstrap secret)
 *
 * This payload is stored IN a bootstrap secret's KeyVault.
 * The bootstrap secret is created via SecretOrchestrator and costs credits.
 *
 * Flow:
 * 1. New device joins Identity as team member (establishes public key)
 * 2. Existing device creates bootstrap secret (costs credits)
 * 3. Existing device writes sync package to bootstrap secret
 * 4. New device decrypts bootstrap secret and imports keys
 * 5. New device is promoted to rivet
 */
export interface BootstrapSyncPayload {
  type: 'bootstrap-sync';
  version: '1.0';

  /** Identity contract being synced */
  identityContract: string;

  /** Source device address (sender) */
  sourceDevice: string;

  /** Target device address (recipient) */
  targetDevice: string;

  /** All owned secret keys to sync */
  ownedSecrets: Array<{
    secretContract: string;
    secretName: string;
    mintBlockNumber: number;
    keyVaultBlock?: number;
    keyVaultName?: string;
    /** Master key encrypted for target device (ECDH) */
    encryptedMasterKey: EncryptedKeyData;
    /** KV key encrypted for target device (ECDH) */
    encryptedKVKey?: EncryptedKeyData;
  }>;

  /** All team shares (from other identities) to sync */
  teamShares: Array<{
    secretContract: string;
    secretName: string;
    mintBlockNumber: number;
    keyVaultBlock?: number;
    keyVaultName?: string;
    ownerAddress: string;
    /** Master key encrypted for target device (ECDH) */
    encryptedMasterKey: EncryptedKeyData;
    /** KV key encrypted for target device (ECDH) */
    encryptedKVKey?: EncryptedKeyData;
    /** Write authorization (if granted) */
    writeAuthorization?: WriteAuthorization;
  }>;

  /** Ephemeral public key for ECDH decryption */
  ephemeralPublicKey: string;

  /** Timestamp when sync package was created */
  timestamp: number;
}

// ============================================================================
// File Access Protocol - Remote File Operations via Blockchain
// ============================================================================

/**
 * File Request - Request file operations from remote machine
 * Direction: Requester → Target Identity/Wallet
 *
 * The target's SSA watches for these messages and responds with FileResponse.
 * Authorization is checked via team membership or whitelist.
 */
export interface FileRequestPayload {
  type: 'file-request';
  version: '1.0';

  /** Unique request ID for matching responses */
  requestId: string;

  /** Command to execute */
  command: 'list' | 'get' | 'put' | 'del' | 'info' | 'search';

  /** Target path (local filesystem or cloud) */
  path: string;

  /** Source type for routing */
  source?: 'local' | 'cloud' | 'onedrive' | 'sharepoint';

  /** For 'put' command - file content (base64 for small, IPFS hash for large) */
  content?: string;
  ipfsHash?: string;
  fileName?: string;
  fileSize?: number;

  /** For 'search' command - search query */
  query?: string;

  /** Requester info */
  requesterAddress: string;
  requesterIdentity?: string;

  /** Encryption (optional - for sensitive file names/paths) */
  encrypted?: boolean;
  ephemeralPublicKey?: string;

  timestamp: number;
}

/**
 * File Response - Response to file request
 * Direction: Target → Requester
 *
 * Contains result of the file operation or error.
 */
export interface FileResponsePayload {
  type: 'file-response';
  version: '1.0';

  /** Matches the requestId from FileRequest */
  requestId: string;

  /** Whether the operation succeeded */
  success: boolean;

  /** Original command for context */
  command: 'list' | 'get' | 'put' | 'del' | 'info' | 'search';

  // === List response ===
  files?: Array<{
    name: string;
    path: string;
    size: number;
    isDirectory: boolean;
    modified: number;
    mimeType?: string;
  }>;

  // === Get response ===
  /** For small files - base64 encoded content */
  content?: string;
  /** For large files - IPFS hash to fetch */
  ipfsHash?: string;
  /** File metadata */
  fileName?: string;
  fileSize?: number;
  mimeType?: string;

  // === Info response ===
  fileInfo?: {
    path: string;
    size: number;
    isDirectory: boolean;
    created: number;
    modified: number;
    accessed: number;
    mimeType?: string;
    permissions?: string;
  };

  // === Search response ===
  searchResults?: Array<{
    path: string;
    name: string;
    matchType: 'name' | 'content';
    snippet?: string;
  }>;

  // === Mint as secret option ===
  /** If the file was minted as a secret for secure transfer */
  mintedAsSecret?: {
    secretContract: string;
    mintBlockNumber: number;
    keyVaultBlock: number;
  };

  // === Error response ===
  error?: string;
  errorCode?: 'UNAUTHORIZED' | 'NOT_FOUND' | 'ACCESS_DENIED' | 'TOO_LARGE' | 'TIMEOUT' | 'UNKNOWN';

  /** Responder info */
  responderAddress: string;
  responderIdentity?: string;

  timestamp: number;
}

/**
 * Genesis - Epistery wallet initialization marker
 * Direction: Self-transfer (from === to)
 */
export interface GenesisPayload {
  type: 'genesis';
  owner: string;
  createdAt: number;
}

// ============================================================================
// Shared Types
// ============================================================================

export interface EncryptedKeyData {
  encrypted: string;
  iv: string;
  algorithm: 'AES-256-GCM-ECDH';
}

export interface WriteAuthorization {
  secretAddress?: string;
  secretContract?: string;
  keyVaultBlock: number;
  writerAddress?: string;
  authorizedWriter?: string;
  expiresAt: number;
  v: number;
  r: string;
  s: string;
  messageHash?: string;
  rawSignature?: string;
  identityContract?: string;
  isIdentityMode?: boolean;
}

// ============================================================================
// Contract Event Payloads
// ============================================================================

export interface SecretCreatedEvent {
  type: 'secret-created';
  secretAddress: string;
  owner: string;
  timestamp: number;
  txHash: string;
  blockNumber: number;
}

export interface KeyVaultCreatedEvent {
  type: 'keyvault-created';
  blockNumber: number;
  creator: string;
  encryptedKeysData: string;
  schemaDefinition: string;
  timestamp: number;
  txHash: string;
}

export interface DataWrittenEvent {
  type: 'data-written';
  secretContract: string;
  writer: string;
  keyVaultBlock: number;
  data: string;
  creditsCost: number;
  timestamp: number;
  txHash: string;
  blockNumber: number;
}

export interface TeamMemberAddedEvent {
  type: 'team-member-added';
  member: string;
  role: number; // 0=NONE, 1=MEMBER, 2=ADMIN
  addedBy: string;
  timestamp: number;
  txHash: string;
  blockNumber: number;
  secretAddress: string;
}

// ============================================================================
// Union Types
// ============================================================================

export type TransactionPayload =
  | TeamInvitePayload
  | InviteResponsePayload
  | EncryptedKeysPayload
  | DirectKeysPayload
  | BootstrapSyncPayload
  | FileRequestPayload
  | FileResponsePayload
  | GenesisPayload;

export type ContractEvent =
  | SecretCreatedEvent
  | KeyVaultCreatedEvent
  | DataWrittenEvent
  | TeamMemberAddedEvent;

// ============================================================================
// Type Guards
// ============================================================================

export function isTeamInvite(payload: unknown): payload is TeamInvitePayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as TeamInvitePayload).type === 'team-invite'
  );
}

export function isInviteResponse(payload: unknown): payload is InviteResponsePayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as InviteResponsePayload).type === 'invite-response'
  );
}

export function isEncryptedKeys(payload: unknown): payload is EncryptedKeysPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    ((payload as EncryptedKeysPayload).type === 'encrypted-access-keys' ||
      (payload as EncryptedKeysPayload).type === 'encrypted-keys')
  );
}

export function isTeamKeys(payload: unknown): payload is EncryptedKeysPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as EncryptedKeysPayload).type === 'team-keys'
  );
}

export function isDirectKeys(payload: unknown): payload is DirectKeysPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as DirectKeysPayload).type === 'direct-keys'
  );
}

export function isGenesis(payload: unknown): payload is GenesisPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as GenesisPayload).type === 'genesis'
  );
}

export function isBootstrapSync(payload: unknown): payload is BootstrapSyncPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as BootstrapSyncPayload).type === 'bootstrap-sync'
  );
}

export function isFileRequest(payload: unknown): payload is FileRequestPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as FileRequestPayload).type === 'file-request'
  );
}

export function isFileResponse(payload: unknown): payload is FileResponsePayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    (payload as FileResponsePayload).type === 'file-response'
  );
}
