/**
 * Credit Purchaser
 *
 * Handles purchasing credits via MultiTokenCreditPurchase or Registry contracts.
 *
 * ## Usage
 * ```typescript
 * import { CreditPurchaser } from '@rootz/notes';
 *
 * const purchaser = new CreditPurchaser(signer, {
 *   multiTokenAddress: '0x...',  // Optional, preferred
 *   registryAddress: '0x...',    // Fallback
 * });
 *
 * // Purchase credits with POL
 * const result = await purchaser.purchaseWithPOL('0.1');
 *
 * // Preview purchase (MultiToken only)
 * const preview = await purchaser.previewPurchase('0.1');
 * ```
 */

import { Contract, parseEther, formatEther, getAddress, type Signer, type Provider } from 'ethers';
import { MULTI_TOKEN_PURCHASE_ABI, REGISTRY_ADMIN_ABI } from './abis.js';

/**
 * Configuration for CreditPurchaser.
 */
export interface CreditPurchaserConfig {
  /** MultiTokenCreditPurchase contract address (preferred) */
  multiTokenAddress?: string;
  /** Registry contract address (fallback) */
  registryAddress?: string;
  /** Gas limit override */
  gasLimit?: bigint;
}

/**
 * Result from a credit purchase.
 */
export interface PurchaseResult {
  success: boolean;
  txHash: string;
  blockNumber: number;
  method: 'multiToken' | 'registry';
  polSpent: string;
  preview?: PurchasePreview;
  error?: string;
}

/**
 * Preview of a credit purchase.
 */
export interface PurchasePreview {
  baseCredits: bigint;
  bonusCredits: bigint;
  totalCredits: bigint;
  bonusPercent: bigint;
}

/**
 * Gas settings for transactions.
 */
export interface GasSettings {
  maxFeePerGas: bigint;
  maxPriorityFeePerGas: bigint;
}

/**
 * CreditPurchaser - Handles credit purchases via POL.
 *
 * Supports two purchase methods:
 * 1. MultiTokenCreditPurchase (preferred) - Supports bonuses
 * 2. Registry.depositCredits (fallback) - Direct deposit
 */
export class CreditPurchaser {
  private signer: Signer;
  private provider: Provider;
  private config: CreditPurchaserConfig;

  constructor(signer: Signer, config: CreditPurchaserConfig) {
    this.signer = signer;
    this.provider = signer.provider!;
    this.config = config;

    if (!config.multiTokenAddress && !config.registryAddress) {
      throw new Error('CreditPurchaser requires either multiTokenAddress or registryAddress');
    }
  }

  /**
   * Get the purchase method that will be used.
   */
  getPurchaseMethod(): 'multiToken' | 'registry' {
    return this.config.multiTokenAddress ? 'multiToken' : 'registry';
  }

  /**
   * Preview a credit purchase (MultiToken only).
   *
   * @param polAmount - Amount of POL to spend (e.g., '0.1')
   * @returns Preview with base, bonus, and total credits
   */
  async previewPurchase(polAmount: string): Promise<PurchasePreview | null> {
    if (!this.config.multiTokenAddress) {
      console.log('[CreditPurchaser] Preview not available for Registry (only MultiToken)');
      return null;
    }

    try {
      const multiToken = new Contract(
        getAddress(this.config.multiTokenAddress),
        MULTI_TOKEN_PURCHASE_ABI,
        this.provider
      );

      const [baseCredits, bonusCredits, totalCredits, bonusPercent] =
        await multiToken.previewPurchase('POL', parseEther(polAmount));

      console.log('[CreditPurchaser] Preview:', {
        baseCredits: baseCredits.toString(),
        bonusCredits: bonusCredits.toString(),
        totalCredits: totalCredits.toString(),
        bonusPercent: bonusPercent.toString(),
      });

      return {
        baseCredits: BigInt(baseCredits),
        bonusCredits: BigInt(bonusCredits),
        totalCredits: BigInt(totalCredits),
        bonusPercent: BigInt(bonusPercent),
      };
    } catch (error) {
      console.log('[CreditPurchaser] Preview failed:', error);
      return null;
    }
  }

  /**
   * Purchase credits with POL.
   *
   * Uses MultiTokenCreditPurchase if available, otherwise falls back to Registry.
   *
   * @param polAmount - Amount of POL to spend (e.g., '0.1')
   * @param gasSettings - Optional gas settings
   * @returns Purchase result
   */
  async purchaseWithPOL(
    polAmount: string,
    gasSettings?: GasSettings
  ): Promise<PurchaseResult> {
    const walletAddress = await this.signer.getAddress();
    const valueWei = parseEther(polAmount);

    // Get gas settings from network if not provided
    const gas = gasSettings ?? await this.getDefaultGasSettings();

    const gasOptions = {
      value: valueWei,
      gasLimit: this.config.gasLimit ?? 150000n,
      maxFeePerGas: gas.maxFeePerGas,
      maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
    };

    console.log('[CreditPurchaser] Purchasing with', polAmount, 'POL');
    console.log('[CreditPurchaser] Gas:', {
      maxFeePerGas: formatEther(gas.maxFeePerGas * 1000000000n) + ' Gwei',
      gasLimit: gasOptions.gasLimit.toString(),
    });

    // Try to preview first (MultiToken only)
    let preview: PurchasePreview | null = null;
    if (this.config.multiTokenAddress) {
      preview = await this.previewPurchase(polAmount);
    }

    try {
      let tx;
      let method: 'multiToken' | 'registry';

      if (this.config.multiTokenAddress) {
        // Use MultiTokenCreditPurchase contract
        console.log('[CreditPurchaser] Using MultiToken contract:', this.config.multiTokenAddress);

        const multiToken = new Contract(
          getAddress(this.config.multiTokenAddress),
          MULTI_TOKEN_PURCHASE_ABI,
          this.signer
        );

        tx = await multiToken.purchaseCreditsWithPOL(walletAddress, gasOptions);
        method = 'multiToken';

      } else {
        // Fallback to Registry.depositCredits
        console.log('[CreditPurchaser] Using Registry fallback:', this.config.registryAddress);

        const registry = new Contract(
          getAddress(this.config.registryAddress!),
          REGISTRY_ADMIN_ABI,
          this.signer
        );

        tx = await registry.depositCredits(gasOptions);
        method = 'registry';
      }

      console.log('[CreditPurchaser] Transaction sent:', tx.hash);

      // Wait for confirmation
      const receipt = await tx.wait();
      console.log('[CreditPurchaser] Confirmed at block:', receipt.blockNumber);

      return {
        success: true,
        txHash: receipt.hash,
        blockNumber: receipt.blockNumber,
        method,
        polSpent: polAmount,
        preview: preview ?? undefined,
      };

    } catch (error) {
      console.error('[CreditPurchaser] Purchase failed:', error);
      return {
        success: false,
        txHash: '',
        blockNumber: 0,
        method: this.config.multiTokenAddress ? 'multiToken' : 'registry',
        polSpent: polAmount,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }

  /**
   * Get supported tokens (MultiToken only).
   *
   * @returns Array of supported token symbols
   */
  async getSupportedTokens(): Promise<string[]> {
    if (!this.config.multiTokenAddress) {
      return ['POL']; // Registry only supports POL
    }

    try {
      const multiToken = new Contract(
        getAddress(this.config.multiTokenAddress),
        MULTI_TOKEN_PURCHASE_ABI,
        this.provider
      );

      return await multiToken.getSupportedTokens();
    } catch (error) {
      console.error('[CreditPurchaser] Failed to get supported tokens:', error);
      return ['POL'];
    }
  }

  /**
   * Get default gas settings from the network.
   */
  private async getDefaultGasSettings(): Promise<GasSettings> {
    try {
      const feeData = await this.provider.getFeeData();
      return {
        maxFeePerGas: feeData.maxFeePerGas ?? 50_000_000_000n, // 50 Gwei fallback
        maxPriorityFeePerGas: feeData.maxPriorityFeePerGas ?? 2_000_000_000n, // 2 Gwei fallback
      };
    } catch (error) {
      console.warn('[CreditPurchaser] Failed to get fee data, using defaults');
      return {
        maxFeePerGas: 50_000_000_000n,
        maxPriorityFeePerGas: 2_000_000_000n,
      };
    }
  }
}

/**
 * Create a CreditPurchaser from app state.
 *
 * @param signer - Ethers signer
 * @param contracts - Contract addresses from config
 * @returns CreditPurchaser instance
 */
export function createCreditPurchaser(
  signer: Signer,
  contracts: { multiTokenPurchase?: string; registry?: string }
): CreditPurchaser {
  return new CreditPurchaser(signer, {
    multiTokenAddress: contracts.multiTokenPurchase,
    registryAddress: contracts.registry,
  });
}
