/**
 * @rootz/teams - WriteAuthGenerator
 *
 * Generates pre-signed write authorizations for team members.
 * Allows members to call writeData() on KeyVault without owner signing each time.
 *
 * ## Authorization Hash Format:
 * keccak256(abi.encodePacked(secretContract, kvBlock, writerAddress, expiresAt))
 *
 * IMPORTANT: Contract uses abi.encodePacked (tightly packed), NOT abi.encode (padded).
 * This is why we use solidityPackedKeccak256 instead of keccak256(abiCoder.encode(...)).
 *
 * ## Two Modes:
 * - LOCAL (PATH 2): Standard ECDSA signature, member uses v/r/s directly
 * - IDENTITY (PATH 3): EIP-1271 signature, member calls submitRivetSignature first
 *
 * @see SovereignSecretOperations_V5_COMPLETE.sol line 322-327
 * @see invite-manager-v4.js lines 486-540
 */

import {
  solidityPackedKeccak256,
  getBytes,
  Signature,
  recoverAddress,
  hashMessage,
  type Signer,
} from 'ethers';
import type { WriteAuthorization } from './types.js';

// ============================================================================
// CONSTANTS
// ============================================================================

/**
 * Default expiration: 999 years from now (effectively "never expires")
 * Contract requires expiresAt > 0 for delegation
 * @see SovereignSecretOperations_V5_COMPLETE.sol line 291
 */
const EXPIRATION_999_YEARS = 999 * 365 * 24 * 60 * 60; // seconds

// ============================================================================
// WRITE AUTH GENERATOR
// ============================================================================

/**
 * WriteAuthGenerator - Creates pre-signed write authorizations
 *
 * Generates signatures that allow team members to write to KeyVaults
 * without requiring the owner to sign each write operation.
 *
 * @example
 * ```typescript
 * const gen = new WriteAuthGenerator();
 *
 * // LOCAL mode (EOA owner)
 * const auth = await gen.createECDSAAuth({
 *   secretContract: '0x...',
 *   kvBlock: 12345,
 *   memberAddress: '0x...',
 *   signer: ownerSigner,
 * });
 *
 * // IDENTITY mode (contract owner)
 * const auth = await gen.createEIP1271Auth({
 *   secretContract: '0x...',
 *   kvBlock: 12345,
 *   memberAddress: '0x...',
 *   identityContract: '0x...',
 *   signer: rivetSigner,
 * });
 * ```
 */
export class WriteAuthGenerator {
  // ==========================================================================
  // HASH COMPUTATION
  // ==========================================================================

  /**
   * Compute authorization message hash
   *
   * Format: keccak256(abi.encodePacked(secretContract, kvBlock, writer, expiresAt))
   *
   * IMPORTANT: Contract uses abi.encodePacked (tightly packed), NOT abi.encode.
   * - abi.encode: pads all values to 32 bytes
   * - abi.encodePacked: tightly concatenates values (address=20 bytes, uint256=32 bytes)
   *
   * @see SovereignSecretOperations_V5_COMPLETE.sol line 322-327
   *
   * @param secretContract - Secret contract address
   * @param kvBlock - KeyVault block number
   * @param writerAddress - Address being authorized to write
   * @param expiresAt - Expiration timestamp
   * @returns Message hash (32 bytes hex)
   */
  computeAuthHash(
    secretContract: string,
    kvBlock: number,
    writerAddress: string,
    expiresAt: number
  ): string {
    // Match Solidity: keccak256(abi.encodePacked(address(this), keyVaultBlock, msg.sender, expiresAt))
    // solidityPackedKeccak256 matches abi.encodePacked behavior (tightly packed, no padding)
    return solidityPackedKeccak256(
      ['address', 'uint256', 'address', 'uint256'],
      [secretContract, kvBlock, writerAddress, expiresAt]
    );
  }

  // ==========================================================================
  // LOCAL MODE (PATH 2) - ECDSA
  // ==========================================================================

  /**
   * Create write authorization for LOCAL mode (EOA owner)
   *
   * The owner signs a message allowing the member to call writeData().
   * Contract verifies: ecrecover(hash, v, r, s) == vault.creator
   *
   * @param params - Authorization parameters
   * @returns WriteAuthorization with v, r, s
   */
  async createECDSAAuth(params: {
    secretContract: string;
    kvBlock: number;
    memberAddress: string;
    expiresAt?: number;
    signer: Signer;
  }): Promise<WriteAuthorization> {
    const {
      secretContract,
      kvBlock,
      memberAddress,
      expiresAt = Math.floor(Date.now() / 1000) + EXPIRATION_999_YEARS,
      signer,
    } = params;

    // 1. Compute message hash
    const messageHash = this.computeAuthHash(secretContract, kvBlock, memberAddress, expiresAt);

    // 2. Sign with EIP-191 personal_sign prefix
    // This matches: ethers.utils.arrayify(hash) then signMessage
    const signature = await signer.signMessage(getBytes(messageHash));

    // 3. Split signature into v, r, s
    const sig = Signature.from(signature);

    return {
      v: sig.v,
      r: sig.r,
      s: sig.s,
      expiresAt,
      authorizedWriter: memberAddress,
      secretContract,
      keyVaultBlock: kvBlock,
      isIdentityMode: false,
    };
  }

  // ==========================================================================
  // IDENTITY MODE (PATH 3) - EIP-1271
  // ==========================================================================

  /**
   * Create write authorization for IDENTITY mode (contract owner)
   *
   * The rivet device signs a message that will be verified by the IdentityContract
   * using EIP-1271 (isValidSignature).
   *
   * Flow:
   * 1. Rivet signs the authorization hash
   * 2. Member calls submitRivetSignature(rawSignature) first
   * 3. Member calls writeData() with special EIP-1271 signature format:
   *    - v = 0 (marker for EIP-1271)
   *    - r = identityContract (as bytes32)
   *    - s = signatureHash from submitRivetSignature (as bytes32)
   *
   * @param params - Authorization parameters
   * @returns WriteAuthorization with raw signature and identity info
   */
  async createEIP1271Auth(params: {
    secretContract: string;
    kvBlock: number;
    memberAddress: string;
    identityContract: string;
    expiresAt?: number;
    signer: Signer;
  }): Promise<WriteAuthorization> {
    const {
      secretContract,
      kvBlock,
      memberAddress,
      identityContract,
      expiresAt = Math.floor(Date.now() / 1000) + EXPIRATION_999_YEARS,
      signer,
    } = params;

    // 1. Compute message hash
    const messageHash = this.computeAuthHash(secretContract, kvBlock, memberAddress, expiresAt);

    // 2. Sign with rivet device
    const rawSignature = await signer.signMessage(getBytes(messageHash));

    // 3. Split for convenience (member will use rawSignature for submitRivetSignature)
    const sig = Signature.from(rawSignature);

    return {
      v: sig.v,
      r: sig.r,
      s: sig.s,
      expiresAt,
      authorizedWriter: memberAddress,
      secretContract,
      keyVaultBlock: kvBlock,
      rawSignature, // Member needs this for submitRivetSignature()
      identityContract,
      isIdentityMode: true,
    };
  }

  // ==========================================================================
  // UTILITY METHODS
  // ==========================================================================

  /**
   * Verify an authorization signature (for testing)
   *
   * @param auth - WriteAuthorization to verify
   * @param expectedSigner - Expected signer address
   * @returns true if signature is valid
   */
  verifyAuth(auth: WriteAuthorization, expectedSigner: string): boolean {
    try {
      // Recompute hash
      const messageHash = this.computeAuthHash(
        auth.secretContract,
        auth.keyVaultBlock,
        auth.authorizedWriter,
        auth.expiresAt
      );

      // Use ethers v6 hashMessage for EIP-191 prefixing
      const digest = hashMessage(getBytes(messageHash));

      // Recover signer from signature using ethers v6 API
      const sig = Signature.from({ v: auth.v, r: auth.r, s: auth.s });
      const recoveredAddress = recoverAddress(digest, sig);

      return recoveredAddress.toLowerCase() === expectedSigner.toLowerCase();
    } catch {
      return false;
    }
  }

  /**
   * Check if authorization is expired
   *
   * @param auth - WriteAuthorization to check
   * @returns true if expired
   */
  isExpired(auth: WriteAuthorization): boolean {
    if (auth.expiresAt === 0) {
      return false; // Never expires (but contract rejects 0)
    }
    const now = Math.floor(Date.now() / 1000);
    return now >= auth.expiresAt;
  }

  /**
   * Format authorization for contract call
   *
   * For LOCAL mode: return v, r, s directly
   * For IDENTITY mode: return special EIP-1271 format
   *
   * @param auth - WriteAuthorization
   * @param signatureHash - For EIP-1271: hash from submitRivetSignature
   * @returns { v, r, s } for writeData call
   */
  formatForContract(
    auth: WriteAuthorization,
    signatureHash?: string
  ): { v: number; r: string; s: string } {
    if (auth.isIdentityMode && signatureHash && auth.identityContract) {
      // EIP-1271 format:
      // v = 0 (marker)
      // r = identityContract padded to bytes32
      // s = signatureHash
      const paddedIdentity = auth.identityContract.toLowerCase().padStart(64, '0');
      return {
        v: 0,
        r: '0x' + paddedIdentity.slice(-64),
        s: signatureHash,
      };
    }

    // Standard ECDSA format
    return {
      v: auth.v,
      r: auth.r,
      s: auth.s,
    };
  }
}
