/**
 * Rootz V6 Dashboard - Factory Contract Adapter
 *
 * Implements the FactoryContract interface for SecretOrchestrator.
 * Wraps ethers.js contract interactions with the Rootz Factory.
 *
 * Supports both V4 (mintSecret) and V5 (createKeyVault) contract versions.
 * Default is V5 with Identity Mode support.
 *
 * ## Production Error Handling
 *
 * Uses TransactionManager for:
 * - Gas estimation with graceful fallback
 * - Automatic retry with gas escalation
 * - User-friendly error classification
 * - Pre-transaction cost preview
 *
 * Uses V6 package constants and utilities for consistency across all implementations.
 */

import { Contract, type JsonRpcProvider, type Signer, toUtf8Bytes } from 'ethers';
import {
  // ABIs
  FACTORY_ABI,
  SECRET_ABI,
  SECRET_ABI_V4,
  SECRET_ABI_V5,
  // Gas Provider
  GasProvider,
  GAS_LIMITS,
  type GasTier,
  // Transaction Manager
  TransactionManager,
  classifyTransactionError,
  type TransactionPreview,
  type ClassifiedError,
  // Utilities
  extractContractAddressFromReceipt,
  extractVaultIdFromReceipt,
  // Types
  type FactoryContract,
  type SecretContract,
  type DeployResult,
  type MintResult,
  type KeyVaultResult,
  type KeyVaultSchema,
  type ContractVersion,
  type V5KeyVaultData,
  type V5KeyVaultSchema,
  type OrchestratorWriteAuth as WriteAuthorization,
} from '@rootz/integration';
import type { GasConfig } from './config';

/**
 * Gas settings for transactions - EIP-1559 format
 */
export interface GasSettings {
  maxFeePerGas: bigint;
  maxPriorityFeePerGas: bigint;
  gasLimit?: bigint;
}

/**
 * Factory Contract Adapter
 *
 * Connects the SecretOrchestrator to the real blockchain Factory contract.
 * Supports both V4 (mintSecret) and V5 (createKeyVault) contract versions.
 *
 * Uses TransactionManager for production-ready error handling:
 * - DYNAMIC gas estimation via GasProvider
 * - Automatic retry with gas escalation on failure
 * - User-friendly error classification
 */
export class FactoryContractAdapter implements FactoryContract {
  private factory: Contract;
  private provider: JsonRpcProvider;
  private signer: Signer;
  private gasProvider: GasProvider;
  private txManager: TransactionManager;
  private gasTier: GasTier;
  private contractVersion: ContractVersion;

  constructor(
    factoryAddress: string,
    provider: JsonRpcProvider,
    signer: Signer,
    gasConfig?: GasConfig,
    contractVersion: ContractVersion = 'v5'  // Default to V5 for new development
  ) {
    this.provider = provider;
    this.signer = signer;
    this.contractVersion = contractVersion;
    this.factory = new Contract(factoryAddress, FACTORY_ABI, signer);

    // Create GasProvider for dynamic gas estimation
    this.gasProvider = new GasProvider(provider);
    this.txManager = new TransactionManager(provider);
    this.gasTier = 'standard';

    console.log(`[Factory] Contract version: ${contractVersion}`);
    console.log('[Factory] Using TransactionManager for production error handling');
  }

  /**
   * Get dynamic gas settings from network
   */
  private async getDynamicGas(): Promise<GasSettings> {
    const gas = await this.gasProvider.getGasSettings(this.gasTier);
    console.log(`[Factory] Gas PRICE (dynamic): ${gas.maxFeePerGasGwei.toFixed(2)} Gwei (base: ${(Number(gas.networkBaseFee) / 1e9).toFixed(2)} Gwei)`);
    console.log(`[Factory] Gas LIMIT: ${GAS_LIMITS.createSecret.toLocaleString()} (fixed)`);
    return {
      maxFeePerGas: gas.maxFeePerGas,
      maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
      gasLimit: GAS_LIMITS.createSecret,
    };
  }

  /**
   * Get user's current nonce from factory
   */
  async getUserNonce(address: string): Promise<bigint> {
    const nonce = await this.factory.getUserNonce(address);
    return BigInt(nonce);
  }

  /**
   * Preview secret creation transaction.
   *
   * Call this BEFORE showing the "Create Secret" confirmation to the user.
   * Returns estimated costs, gas info, and any blockers/warnings.
   *
   * @param params - Transaction parameters (same as createSovereignWallet)
   * @param walletAddress - User's wallet address for balance check
   * @returns Transaction preview with costs and warnings
   */
  async previewSecretCreation(
    params: {
      userAuthorizer: string;
      newbornAddress: string;
      walletName: string;
      secretName: string;
      secretType: string;
      authSignature: string;
      nonce: bigint;
      value: bigint;
    },
    walletAddress: string
  ): Promise<TransactionPreview> {
    console.log('[Factory] === PREVIEW SECRET CREATION ===');

    return this.txManager.previewTransaction({
      operation: 'createSecret',
      walletAddress,
      value: params.value,
      tier: this.gasTier,
      estimator: async () => {
        // Try to estimate gas for this specific transaction
        const estimated = await this.factory.createSovereignWalletAsNewborn.estimateGas(
          params.userAuthorizer,
          params.newbornAddress,
          params.walletName,
          params.secretName,
          params.secretType,
          params.authSignature,
          params.nonce,
          { value: params.value }
        );
        return BigInt(estimated);
      },
    });
  }

  /**
   * Create sovereign wallet (secret contract) via factory
   */
  async createSovereignWallet(params: {
    userAuthorizer: string;
    newbornAddress: string;
    walletName: string;
    secretName: string;
    secretType: string;
    authSignature: string;
    nonce: bigint;
    value: bigint;
  }): Promise<DeployResult> {
    console.log('[Factory] === FACTORY CALL DIAGNOSTICS ===');
    console.log('[Factory] Factory address:', this.factory.target);
    console.log('[Factory] userAuthorizer:', params.userAuthorizer);
    console.log('[Factory] newbornAddress:', params.newbornAddress);
    console.log('[Factory] walletName:', params.walletName);
    console.log('[Factory] secretName:', params.secretName);
    console.log('[Factory] secretType:', params.secretType);
    console.log('[Factory] nonce:', params.nonce.toString());
    console.log('[Factory] authSignature:', params.authSignature.slice(0, 42) + '...');
    console.log('[Factory] authSignature length:', params.authSignature.length);
    console.log('[Factory] value (POL):', params.value.toString());
    console.log('[Factory] === END FACTORY DIAGNOSTICS ===');

    // Get DYNAMIC gas settings from network
    const dynamicGas = await this.getDynamicGas();

    // ESTIMATE gas before sending - use TransactionManager for better error handling
    let estimatedGasLimit = dynamicGas.gasLimit;
    try {
      const estimatedGas = await this.factory.createSovereignWalletAsNewborn.estimateGas(
        params.userAuthorizer,
        params.newbornAddress,
        params.walletName,
        params.secretName,
        params.secretType,
        params.authSignature,
        params.nonce,
        { value: params.value }
      );
      console.log(`[Factory] Estimated gas: ${estimatedGas.toLocaleString()}`);
      console.log(`[Factory] Gas limit we will use: ${dynamicGas.gasLimit?.toLocaleString()}`);

      // If estimated gas exceeds our limit, auto-escalate
      if (dynamicGas.gasLimit && estimatedGas > dynamicGas.gasLimit) {
        const escalatedLimit = (BigInt(estimatedGas) * 130n) / 100n; // 30% buffer
        console.warn(`[Factory] ⚠️ ESTIMATED GAS (${estimatedGas}) EXCEEDS LIMIT (${dynamicGas.gasLimit})`);
        console.log(`[Factory] Auto-escalating to: ${escalatedLimit.toLocaleString()}`);
        estimatedGasLimit = escalatedLimit;
      }
    } catch (estimateError: unknown) {
      // Use TransactionManager to classify the error
      const classified = classifyTransactionError(estimateError);
      console.error(`[Factory] ⚠️ Gas estimation FAILED: ${classified.category}`);
      console.error(`[Factory] User message: ${classified.userMessage}`);
      console.error(`[Factory] Technical: ${classified.technicalMessage}`);
      console.error(`[Factory] Suggested action: ${classified.suggestedAction}`);

      if (!classified.recoverable) {
        // Non-recoverable errors should not proceed
        throw new Error(classified.userMessage);
      }

      // For recoverable errors, log warning and proceed with higher limit
      console.warn('[Factory] Proceeding with 50% higher gas limit due to estimation failure');
      estimatedGasLimit = (dynamicGas.gasLimit ?? GAS_LIMITS.createSecret) * 150n / 100n;
    }

    // Call factory to create secret contract with dynamic gas settings
    const txOptions: Record<string, unknown> = {
      value: params.value,
      maxFeePerGas: dynamicGas.maxFeePerGas,
      maxPriorityFeePerGas: dynamicGas.maxPriorityFeePerGas,
    };
    if (estimatedGasLimit) {
      txOptions.gasLimit = estimatedGasLimit;
    }

    const tx = await this.factory.createSovereignWalletAsNewborn(
      params.userAuthorizer,
      params.newbornAddress,
      params.walletName,
      params.secretName,
      params.secretType,
      params.authSignature,
      params.nonce,
      txOptions
    );

    console.log('[Factory] Transaction sent:', tx.hash);
    console.log('[Factory] Transaction data field:', tx.data?.slice(0, 100));
    const receipt = await tx.wait();
    console.log('[Factory] Transaction confirmed, block:', receipt.blockNumber);
    console.log('[Factory] Receipt logs:', receipt.logs.length);

    // Debug: Log all logs with their topics
    console.log('[Factory] Logs detail:');
    for (const log of receipt.logs) {
      console.log('  - Address:', log.address);
      console.log('    Topics:', log.topics);
      console.log('    Data:', log.data?.substring(0, 100) + '...');
    }

    // Extract contract address from event logs using package utility
    const iface = this.factory.interface;
    const parseLog = (log: { topics: string[]; data: string }) => {
      try {
        const parsed = iface.parseLog(log);
        console.log('[Factory] Parsed log:', parsed?.name, parsed?.args);
        if (parsed) {
          return { name: parsed.name, args: parsed.args as Record<string, unknown> };
        }
      } catch (e) {
        // Not our event - log for debugging
        console.log('[Factory] Could not parse log:', (e as Error).message?.substring(0, 50));
      }
      return null;
    };

    // Use the package utility for extraction (handles all fallback methods)
    const contractAddress = extractContractAddressFromReceipt(
      {
        hash: receipt.hash,
        blockNumber: receipt.blockNumber,
        logs: receipt.logs.map(log => ({
          address: log.address,
          topics: log.topics as string[],
          data: log.data,
        })),
        contractAddress: receipt.contractAddress,
      },
      this.factory.target?.toString(),
      parseLog
    );

    console.log('[Factory] Extracted contract address:', contractAddress);

    if (!contractAddress) {
      console.error('[Factory] Could not find contract address. Logs:', JSON.stringify(receipt.logs, null, 2));
      throw new Error('Could not find WalletCreated event in transaction logs');
    }

    return {
      contractAddress,
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      gasUsed: BigInt(receipt.gasUsed),
    };
  }

  /**
   * Get a SecretContract instance for a deployed contract
   */
  getSecretContract(address: string): SecretContract {
    return new SecretContractAdapter(address, this.provider, this.signer, this.contractVersion);
  }
}

/**
 * Secret Contract Adapter
 *
 * Wraps interactions with a deployed Secret contract.
 * Supports both V4 (mintSecret) and V5 (createKeyVault) contract versions.
 *
 * Uses DYNAMIC gas estimation via GasProvider.
 */
class SecretContractAdapter implements SecretContract {
  private contract: Contract;
  private gasProvider: GasProvider;
  private gasTier: GasTier;
  readonly version: ContractVersion;

  constructor(
    address: string,
    provider: JsonRpcProvider,
    signer: Signer,
    version: ContractVersion = 'v5'
  ) {
    this.version = version;
    this.gasProvider = new GasProvider(provider);
    this.gasTier = 'standard';

    // Use version-appropriate ABI
    const abi = version === 'v4' ? SECRET_ABI_V4 : SECRET_ABI_V5;
    this.contract = new Contract(address, abi, signer);
    console.log(`[Secret] Using ${version.toUpperCase()} contract at ${address} with DYNAMIC gas`);
  }

  /**
   * Get DYNAMIC gas options for transactions
   */
  private async getGasOptions(gasLimit?: bigint): Promise<Record<string, unknown>> {
    const gas = await this.gasProvider.getGasSettings(this.gasTier);
    console.log(`[Secret] Current gas: ${gas.maxFeePerGasGwei.toFixed(2)} Gwei`);
    const options: Record<string, unknown> = {
      maxFeePerGas: gas.maxFeePerGas,
      maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
    };
    if (gasLimit) {
      options.gasLimit = gasLimit;
    }
    return options;
  }

  /**
   * V4: Mint secret data on-chain.
   *
   * IMPORTANT: Only available on V4 contracts.
   * V5 contracts use storeSecretDataV5 instead.
   *
   * Contract signature:
   *   mintSecret(string _ipfsHash, bytes _encryptedContent, bytes _encryptedPrivateKey)
   */
  async mintSecret(
    encryptedIPFSHash: string,
    encryptedContent: string,
    masterKeyPackage: string
  ): Promise<MintResult> {
    if (this.version !== 'v4') {
      throw new Error('mintSecret not available on V5 contracts - use storeSecretDataV5');
    }

    console.log('[Secret] V4: Minting secret...');
    console.log('[Secret] IPFS hash data length:', encryptedIPFSHash.length);
    console.log('[Secret] Master key package length:', masterKeyPackage.length);

    const contentBytes = toUtf8Bytes(encryptedContent || '');
    const masterKeyBytes = toUtf8Bytes(masterKeyPackage);

    const gasOptions = await this.getGasOptions();
    const tx = await this.contract.mintSecret(
      encryptedIPFSHash,
      contentBytes,
      masterKeyBytes,
      gasOptions
    );

    console.log('[Secret] Mint transaction sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[Secret] Mint confirmed, block:', receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      gasUsed: BigInt(receipt.gasUsed),
    };
  }

  /**
   * V5: Store secret data via createKeyVault.
   * This is the V5 replacement for mintSecret.
   *
   * Stores encrypted data in the KeyVaultCreated event logs:
   * - encryptedKeysData: Contains encrypted master key + IPFS hash
   * - schemaDefinition: KeyVault schema with metadata
   *
   * Contract signature:
   *   createKeyVault(bytes encryptedKeysData, bytes schemaDefinition) external
   */
  async storeSecretDataV5(
    encryptedKeysData: V5KeyVaultData,
    schema: V5KeyVaultSchema
  ): Promise<V5CreateKeyVaultResult> {
    console.log('[Secret] V5: Storing secret data via createKeyVault...');
    console.log('[Secret] Schema:', schema.name, schema.type);

    // Serialize to bytes
    const keysDataJson = JSON.stringify(encryptedKeysData);
    const schemaJson = JSON.stringify(schema);

    const keysDataBytes = toUtf8Bytes(keysDataJson);
    const schemaBytes = toUtf8Bytes(schemaJson);

    console.log('[Secret] Keys data bytes length:', keysDataBytes.length);
    console.log('[Secret] Schema bytes length:', schemaBytes.length);

    const gasOptions = await this.getGasOptions(GAS_LIMITS.createKeyVault);
    const tx = await this.contract.createKeyVault(
      keysDataBytes,
      schemaBytes,
      gasOptions
    );

    console.log('[Secret] KeyVault transaction sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[Secret] KeyVault confirmed, block:', receipt.blockNumber);

    return {
      keyVaultBlock: receipt.blockNumber,
      txHash: receipt.hash,
      gasUsed: BigInt(receipt.gasUsed),
      schema,
    };
  }

  /**
   * V4: Create KeyVault for team/notes support (legacy)
   *
   * V5 uses storeSecretDataV5 which combines minting and KeyVault creation.
   */
  async createKeyVault(schema: KeyVaultSchema): Promise<KeyVaultResult> {
    if (this.version !== 'v4') {
      throw new Error('createKeyVault(schema) not available on V5 - use storeSecretDataV5');
    }

    console.log('[Secret] V4: Creating KeyVault...');
    console.log('[Secret] Schema:', schema);

    const schemaJson = JSON.stringify(schema);
    const gasOptions = await this.getGasOptions();
    const tx = await this.contract.createKeyVault(schemaJson, gasOptions);

    console.log('[Secret] KeyVault transaction sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[Secret] KeyVault confirmed, block:', receipt.blockNumber);

    const iface = this.contract.interface;
    const parseLog = (log: { topics: string[]; data: string }) => {
      try {
        const parsed = iface.parseLog(log);
        if (parsed) {
          return { name: parsed.name, args: parsed.args as Record<string, unknown> };
        }
      } catch {
        // Not our event
      }
      return null;
    };

    const vaultId = extractVaultIdFromReceipt(
      {
        hash: receipt.hash,
        blockNumber: receipt.blockNumber,
        logs: receipt.logs.map(log => ({
          address: log.address,
          topics: log.topics as string[],
          data: log.data,
        })),
      },
      parseLog
    );

    return {
      blockNumber: vaultId ? Number(vaultId) : receipt.blockNumber,
      txHash: receipt.hash,
      schema,
    };
  }

  /**
   * V5: Write data to an existing KeyVault.
   * Used for notes, team keys, and other data after initial creation.
   */
  async writeData(
    keyVaultBlock: number,
    data: Uint8Array,
    authorization: WriteAuthorization
  ): Promise<{ txHash: string; blockNumber: number; gasUsed: bigint }> {
    if (this.version !== 'v5') {
      throw new Error('writeData only available on V5 contracts');
    }

    console.log('[Secret] V5: Writing data to KeyVault...');
    console.log('[Secret] KeyVault block:', keyVaultBlock);
    console.log('[Secret] Data length:', data.length);
    console.log('[Secret] Authorization path:', authorization.path);

    const gasOptions = await this.getGasOptions();
    const tx = await this.contract.writeData(
      keyVaultBlock,
      data,
      authorization.expiresAt,
      authorization.v,
      authorization.r,
      authorization.s,
      gasOptions
    );

    console.log('[Secret] WriteData transaction sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[Secret] WriteData confirmed, block:', receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
      gasUsed: BigInt(receipt.gasUsed),
    };
  }

  /**
   * V5: Add team member with encrypted access key.
   */
  async addTeamMember(
    member: string,
    role: number,
    encryptedAccessKey: string,
    publicKey: string
  ): Promise<{ txHash: string; blockNumber: number }> {
    if (this.version !== 'v5') {
      throw new Error('addTeamMember only available on V5 contracts');
    }

    console.log('[Secret] V5: Adding team member...');
    console.log('[Secret] Member:', member);
    console.log('[Secret] Role:', role);

    const gasOptions = await this.getGasOptions();
    const tx = await this.contract.addTeamMember(
      member,
      role,
      encryptedAccessKey,
      publicKey,
      gasOptions
    );

    console.log('[Secret] AddTeamMember transaction sent:', tx.hash);
    const receipt = await tx.wait();
    console.log('[Secret] AddTeamMember confirmed, block:', receipt.blockNumber);

    return {
      txHash: receipt.hash,
      blockNumber: receipt.blockNumber,
    };
  }
}

/**
 * Create a factory contract adapter
 *
 * @param factoryAddress - Factory contract address
 * @param provider - JSON-RPC provider
 * @param signer - Transaction signer
 * @param gasConfig - Optional gas configuration
 * @param contractVersion - Contract version ('v4' or 'v5', default: 'v5')
 */
export function createFactoryContract(
  factoryAddress: string,
  provider: JsonRpcProvider,
  signer: Signer,
  gasConfig?: GasConfig,
  contractVersion: ContractVersion = 'v5'
): FactoryContract {
  return new FactoryContractAdapter(factoryAddress, provider, signer, gasConfig, contractVersion);
}
