/**
 * @rootz/identity-provider - IdentityManager
 *
 * CRITICAL SAFETY COMPONENT
 *
 * This manager handles multi-device identity operations:
 * - Any authorized device (rivet) can act for the identity
 * - If a device is lost, another device can add a replacement
 * - Then the lost device can be removed
 * - Identity is NEVER lost as long as ONE device remains
 *
 * Based on the V5 IdentityContract.sol (Argent-inspired pattern)
 */

import { ethers } from 'ethers';
import {
  IdentityManagerConfig,
  IdentityInfo,
  RivetInfo,
  CreateIdentityResult,
  FactoryStatus,
  AddRivetResult,
  RemoveRivetResult,
  ExecuteTransactionResult,
  SignatureValidationResult,
  DeviceRecoveryPlan,
  DeviceRecoveryResult,
  IdentityError,
  IdentityErrorCode,
  IdentityStep,
  EIP1271_MAGIC_VALUE,
  IDENTITY_CONTRACT_ABI,
  IDENTITY_FACTORY_ABI,
  // Key sharing types
  DeviceWithPublicKey,
  RegisterPublicKeyResult,
  EncryptedKeyPackage,
} from './types.js';

/**
 * IdentityManager - Manages multi-device identities on-chain
 *
 * ## Core Concept: Device Plurality
 *
 * An IdentityContract can have multiple authorized devices (rivets).
 * Each rivet is a wallet that can:
 * - Execute transactions as the identity
 * - Add new rivets (other devices)
 * - Remove rivets (including itself, if not the last one)
 * - Sign messages on behalf of the identity (EIP-1271)
 *
 * ## Recovery Flow
 *
 * If you lose a device:
 * 1. Use another authorized device to add a new replacement device
 * 2. Remove the lost device to prevent unauthorized access
 * 3. Your identity and all its assets are safe
 *
 * ## Usage
 *
 * ```typescript
 * const manager = new IdentityManager({
 *   signer: deviceWallet,
 *   chainId: 80002,
 *   factoryAddress: '0x...', // Optional - for creating new identities
 * });
 *
 * // Get identity info
 * const info = await manager.getIdentityInfo('0x...');
 *
 * // Add a new device
 * await manager.addRivet({
 *   identityAddress: '0x...',
 *   rivetAddress: '0xNewDevice...',
 *   rivetName: 'My New Phone',
 * });
 *
 * // Execute a transaction as the identity
 * await manager.executeTransaction({
 *   identityAddress: '0x...',
 *   target: '0xContract...',
 *   value: 0n,
 *   data: '0x...',
 * });
 * ```
 */
export class IdentityManager {
  private config: IdentityManagerConfig;
  private provider: ethers.Provider;

  constructor(config: IdentityManagerConfig) {
    this.config = config;
    this.provider = config.signer.provider;
  }

  /**
   * Get signer address - prefers async getAddress() for RootzSigner compatibility.
   * Falls back to sync .address property for legacy signers.
   *
   * Use this helper instead of directly accessing this.config.signer.address
   * to ensure compatibility with @rootz/wallet RootzSigner.
   */
  private async getSignerAddress(): Promise<string> {
    // Prefer async getAddress() - standard for RootzSigner and ethers v6
    if (typeof this.config.signer.getAddress === 'function') {
      return this.config.signer.getAddress();
    }
    // Fall back to sync address property
    return this.config.signer.address;
  }

  // ==========================================================================
  // Identity Creation
  // ==========================================================================

  /**
   * Create a new IdentityContract.
   *
   * The calling device (signer) automatically becomes the first rivet.
   *
   * NOTE: Requires factory contract address in config.
   */
  async createIdentity(): Promise<CreateIdentityResult> {
    if (!this.config.factoryAddress) {
      throw new IdentityError(
        'Factory address not configured',
        'FACTORY_NOT_CONFIGURED'
      );
    }

    this.progress('creating-identity', 'Creating identity contract...');

    // Get signer address (use async getAddress for RootzSigner compatibility)
    const signerAddress = await this.getSignerAddress();

    const factory = new ethers.Contract(
      this.config.factoryAddress,
      IDENTITY_FACTORY_ABI,
      { provider: this.provider }
    );

    // Call createIdentity through signer
    const iface = new ethers.Interface(IDENTITY_FACTORY_ABI);
    const data = iface.encodeFunctionData('createIdentity', []);

    // Get gas settings from callback if provided
    const gasSettings = this.config.getGasSettings
      ? await this.config.getGasSettings()
      : undefined;

    // Estimate gas with buffer
    let gasLimit: bigint;
    try {
      const estimatedGas = await this.provider.estimateGas({
        to: this.config.factoryAddress,
        data,
        from: signerAddress,
      });
      gasLimit = estimatedGas * 130n / 100n; // 30% buffer
    } catch {
      gasLimit = 3_500_000n; // Fallback for createIdentity - V6 contracts need ~2.5M gas
    }

    const tx = await this.config.signer.sendTransaction({
      to: this.config.factoryAddress,
      data,
      gasLimit,
      ...gasSettings,
    });

    const receipt = await tx.wait();

    // Parse the IdentityCreated event to get the new identity address
    let identityAddress: string | undefined;

    if (receipt.logs) {
      for (const log of receipt.logs) {
        try {
          const parsed = factory.interface.parseLog({
            topics: [...log.topics],
            data: log.data,
          });
          if (parsed?.name === 'IdentityCreated') {
            identityAddress = parsed.args?.identity;
            break;
          }
        } catch {
          // Not the event we're looking for
        }
      }
    }

    if (!identityAddress) {
      throw new IdentityError(
        'IdentityCreated event not found in transaction',
        'EVENT_NOT_FOUND'
      );
    }

    this.progress('complete', 'Identity created successfully', tx.hash, receipt.blockNumber);

    return {
      success: true,
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
      identityAddress,
      firstRivetAddress: signerAddress,
    };
  }

  // ==========================================================================
  // Identity Discovery
  // ==========================================================================

  /**
   * Discover all identity contracts created by a user through the factory.
   *
   * This queries the factory's on-chain tracking to find all identities
   * associated with a wallet address.
   *
   * NOTE: This only finds identities the user CREATED. To find identities
   * where the user was ADDED as a rivet, use discoverIdentitiesAsRivet().
   *
   * @param userAddress - The wallet address to discover identities for
   *                      (defaults to current signer)
   * @returns Array of identity contract addresses
   */
  async discoverIdentities(userAddress?: string): Promise<string[]> {
    if (!this.config.factoryAddress) {
      throw new IdentityError(
        'Factory address not configured - cannot discover identities',
        'FACTORY_NOT_CONFIGURED'
      );
    }

    const targetAddress = userAddress || await this.getSignerAddress();

    const factory = new ethers.Contract(
      this.config.factoryAddress,
      IDENTITY_FACTORY_ABI,
      this.provider
    );

    const identities = await factory.getUserIdentities(targetAddress);
    return identities.map((addr: string) => addr.toLowerCase());
  }

  /**
   * Discover identity contracts where this wallet was added as a rivet
   * by scanning for RivetAdded events from the factory's created identities.
   *
   * This is more expensive than discoverIdentities() as it queries events.
   *
   * @param fromBlock - Block to start scanning from (default: last 50000 blocks)
   * @returns Array of identity contract addresses where this wallet is a rivet
   */
  async discoverIdentitiesAsRivet(fromBlock?: number): Promise<string[]> {
    if (!this.config.factoryAddress) {
      throw new IdentityError(
        'Factory address not configured - cannot discover identities',
        'FACTORY_NOT_CONFIGURED'
      );
    }

    const myAddress = (await this.getSignerAddress()).toLowerCase();
    const identities: string[] = [];

    // First, get all identity contracts created by factory
    // Query IdentityCreated events to find all identity contracts
    const factory = new ethers.Contract(
      this.config.factoryAddress,
      IDENTITY_FACTORY_ABI,
      this.provider
    );

    const currentBlock = await this.provider.getBlockNumber();
    const startBlock = fromBlock ?? Math.max(0, currentBlock - 50000);

    console.log(`[IdentityManager] Scanning for RivetAdded events from block ${startBlock}...`);

    // Get all IdentityCreated events to find identity contract addresses
    const createdFilter = factory.filters.IdentityCreated();
    const createdEvents = await factory.queryFilter(createdFilter, startBlock, currentBlock);

    console.log(`[IdentityManager] Found ${createdEvents.length} identity contracts to check`);

    // For each identity contract, check if this wallet is a rivet
    for (const event of createdEvents) {
      const identityAddress = (event as ethers.EventLog).args?.identity;
      if (!identityAddress) continue;

      try {
        const isRivet = await this.isRivet(identityAddress, myAddress);
        if (isRivet) {
          identities.push(identityAddress.toLowerCase());
          console.log(`[IdentityManager] Found: ${identityAddress} (is rivet)`);
        }
      } catch (e) {
        // Skip invalid contracts
      }
    }

    return identities;
  }

  /**
   * Discover ALL identities - both created and added as rivet.
   *
   * Combines discoverIdentities() and discoverIdentitiesAsRivet().
   *
   * @param fromBlock - Block to start scanning for RivetAdded events
   * @returns Array of all identity contract addresses
   */
  async discoverAllIdentities(fromBlock?: number): Promise<string[]> {
    const allIdentities = new Set<string>();

    // First, get identities this wallet created
    try {
      const created = await this.discoverIdentities();
      created.forEach(addr => allIdentities.add(addr));
      console.log(`[IdentityManager] Found ${created.length} created identities`);
    } catch (e) {
      console.warn('[IdentityManager] Could not query created identities:', e);
    }

    // Then, scan for identities where we were added as rivet
    try {
      const asRivet = await this.discoverIdentitiesAsRivet(fromBlock);
      asRivet.forEach(addr => allIdentities.add(addr));
      console.log(`[IdentityManager] Found ${asRivet.length} identities as rivet`);
    } catch (e) {
      console.warn('[IdentityManager] Could not scan for rivet memberships:', e);
    }

    return Array.from(allIdentities);
  }

  /**
   * Get factory status and costs.
   *
   * Useful for checking if identity creation is available and affordable.
   */
  async getFactoryStatus(): Promise<FactoryStatus> {
    if (!this.config.factoryAddress) {
      throw new IdentityError(
        'Factory address not configured',
        'FACTORY_NOT_CONFIGURED'
      );
    }

    const factory = new ethers.Contract(
      this.config.factoryAddress,
      IDENTITY_FACTORY_ABI,
      this.provider
    );

    const [isActive, creditCheckEnabled, canCreateResult] = await Promise.all([
      factory.isActive() as Promise<boolean>,
      factory.creditCheckEnabled() as Promise<boolean>,
      factory.canCreateIdentity(this.config.signer.address) as Promise<[boolean, bigint, bigint]>,
    ]);

    const [canCreate, cost, balance] = canCreateResult;

    return {
      isActive,
      creditCheckEnabled,
      identityCost: cost,
      userBalance: balance,
      canCreate,
    };
  }

  /**
   * Discover and load the user's primary identity (first one created).
   *
   * Convenience method that combines discovery + info loading.
   *
   * @returns Identity info if found, null if no identity exists
   */
  async discoverAndLoadIdentity(): Promise<IdentityInfo | null> {
    const identities = await this.discoverIdentities();

    if (identities.length === 0) {
      return null;
    }

    // Load the first (primary) identity
    return this.getIdentityInfo(identities[0]);
  }

  // ==========================================================================
  // Identity Information
  // ==========================================================================

  /**
   * Get complete information about an identity contract.
   */
  async getIdentityInfo(identityAddress: string): Promise<IdentityInfo> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    // Fetch all info in parallel
    const [creator, rivetCount, balance, rivetAddresses] = await Promise.all([
      contract.creator() as Promise<string>,
      contract.rivetCount() as Promise<bigint>,
      contract.getBalance() as Promise<bigint>,
      contract.getRivets() as Promise<string[]>,
    ]);

    // Fetch rivet details
    const rivets: RivetInfo[] = await Promise.all(
      rivetAddresses.map(async (addr: string) => {
        const [name, addedAt, addedBy, active] = await contract.getRivetInfo(addr);
        return {
          address: addr.toLowerCase(),
          name,
          addedAt: Number(addedAt),
          addedBy: addedBy.toLowerCase(),
          active,
        };
      })
    );

    return {
      address: identityAddress.toLowerCase(),
      creator: creator.toLowerCase(),
      rivetCount: Number(rivetCount),
      balance,
      rivets,
    };
  }

  /**
   * Check if an address is an authorized rivet for an identity.
   */
  async isRivet(identityAddress: string, rivetAddress: string): Promise<boolean> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    return contract.isRivet(rivetAddress);
  }

  /**
   * Get the current signer's rivet status for an identity.
   */
  async isCurrentDeviceAuthorized(identityAddress: string): Promise<boolean> {
    const signerAddress = await this.getSignerAddress();
    return this.isRivet(identityAddress, signerAddress);
  }

  // ==========================================================================
  // Rivet Management (Device Plurality)
  // ==========================================================================

  /**
   * Add a new rivet (device) to an identity.
   *
   * IMPORTANT: This is how you add backup devices or recover from device loss.
   *
   * @param params.identityAddress - The identity contract address
   * @param params.rivetAddress - New device's wallet address
   * @param params.rivetName - Human-readable name (e.g., "laptop", "phone")
   */
  async addRivet(params: {
    identityAddress: string;
    rivetAddress: string;
    rivetName: string;
  }): Promise<AddRivetResult> {
    // Verify caller is an authorized rivet
    const isAuthorized = await this.isCurrentDeviceAuthorized(params.identityAddress);
    if (!isAuthorized) {
      throw new IdentityError(
        'Current device is not authorized to modify this identity',
        IdentityErrorCode.NOT_A_RIVET,
        { signer: this.config.signer.address, identity: params.identityAddress }
      );
    }

    // Check if rivet already exists
    const alreadyRivet = await this.isRivet(params.identityAddress, params.rivetAddress);
    if (alreadyRivet) {
      throw new IdentityError(
        'Device is already a rivet for this identity',
        IdentityErrorCode.RIVET_ALREADY_EXISTS,
        { rivetAddress: params.rivetAddress }
      );
    }

    this.progress('adding-rivet', `Adding device "${params.rivetName}"...`);

    const iface = new ethers.Interface(IDENTITY_CONTRACT_ABI);
    const data = iface.encodeFunctionData('addRivet', [
      params.rivetAddress,
      params.rivetName,
    ]);

    // Get gas settings from callback if provided
    const gasSettings = this.config.getGasSettings
      ? await this.config.getGasSettings()
      : undefined;

    // Estimate gas with 30% buffer, or use fallback
    let gasLimit: bigint;
    try {
      const estimatedGas = await this.provider.estimateGas({
        to: params.identityAddress,
        data,
        from: this.config.signer.address,
      });
      gasLimit = estimatedGas * 130n / 100n; // 30% buffer
    } catch {
      gasLimit = 300_000n; // Fallback for addRivet
    }

    const tx = await this.config.signer.sendTransaction({
      to: params.identityAddress,
      data,
      gasLimit,
      ...gasSettings,
    });

    const receipt = await tx.wait();

    this.progress('complete', 'Device added successfully', tx.hash, receipt.blockNumber);

    return {
      success: true,
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
      rivetAddress: params.rivetAddress.toLowerCase(),
      rivetName: params.rivetName,
    };
  }

  /**
   * Remove a rivet (device) from an identity.
   *
   * SAFETY: Cannot remove the last rivet - this protects against accidental lockout.
   *
   * @param params.identityAddress - The identity contract address
   * @param params.rivetAddress - Device to remove
   */
  async removeRivet(params: {
    identityAddress: string;
    rivetAddress: string;
  }): Promise<RemoveRivetResult> {
    // Verify caller is an authorized rivet
    const isAuthorized = await this.isCurrentDeviceAuthorized(params.identityAddress);
    if (!isAuthorized) {
      throw new IdentityError(
        'Current device is not authorized to modify this identity',
        IdentityErrorCode.NOT_A_RIVET,
        { signer: this.config.signer.address, identity: params.identityAddress }
      );
    }

    // Check rivet count before removal
    const info = await this.getIdentityInfo(params.identityAddress);
    const activeRivets = info.rivets.filter((r) => r.active);

    if (activeRivets.length <= 1) {
      throw new IdentityError(
        'Cannot remove the last rivet - this would lock out the identity',
        IdentityErrorCode.CANNOT_REMOVE_LAST_RIVET,
        { activeRivetCount: activeRivets.length }
      );
    }

    // Verify the rivet to remove actually exists
    const isTarget = await this.isRivet(params.identityAddress, params.rivetAddress);
    if (!isTarget) {
      throw new IdentityError(
        'Target address is not a rivet for this identity',
        IdentityErrorCode.NOT_A_RIVET,
        { rivetAddress: params.rivetAddress }
      );
    }

    this.progress('removing-rivet', 'Removing device...');

    const iface = new ethers.Interface(IDENTITY_CONTRACT_ABI);
    const data = iface.encodeFunctionData('removeRivet', [params.rivetAddress]);

    // Get gas settings from callback if provided
    const gasSettings = this.config.getGasSettings
      ? await this.config.getGasSettings()
      : undefined;

    // Estimate gas with 20% buffer, or use fallback
    let gasLimit: bigint;
    try {
      const estimatedGas = await this.provider.estimateGas({
        to: params.identityAddress,
        data,
        from: this.config.signer.address,
      });
      gasLimit = estimatedGas * 120n / 100n; // 20% buffer
    } catch {
      gasLimit = 200_000n; // Fallback for removeRivet
    }

    const tx = await this.config.signer.sendTransaction({
      to: params.identityAddress,
      data,
      gasLimit,
      ...gasSettings,
    });

    const receipt = await tx.wait();

    this.progress('complete', 'Device removed successfully', tx.hash, receipt.blockNumber);

    return {
      success: true,
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
      removedAddress: params.rivetAddress.toLowerCase(),
    };
  }

  // ==========================================================================
  // Transaction Execution
  // ==========================================================================

  /**
   * Execute a transaction as the identity.
   *
   * This allows the identity contract to interact with other contracts.
   * The transaction is sent from the identity's address, not the device.
   */
  async executeTransaction(params: {
    identityAddress: string;
    target: string;
    value?: bigint;
    data: string;
  }): Promise<ExecuteTransactionResult> {
    // Verify caller is an authorized rivet
    const isAuthorized = await this.isCurrentDeviceAuthorized(params.identityAddress);
    if (!isAuthorized) {
      throw new IdentityError(
        'Current device is not authorized to execute for this identity',
        IdentityErrorCode.NOT_A_RIVET,
        { signer: this.config.signer.address, identity: params.identityAddress }
      );
    }

    // Get gas settings from callback if provided
    const gasSettings = this.config.getGasSettings
      ? await this.config.getGasSettings()
      : undefined;

    // Encode executeTransaction call
    // Since executeTransaction is payable, we can send ETH directly with the call
    // The Identity contract will forward both the call and the ETH to the target
    this.progress('executing-transaction', 'Executing transaction as identity...');

    const iface = new ethers.Interface(IDENTITY_CONTRACT_ABI);
    const data = iface.encodeFunctionData('executeTransaction', [
      params.target,
      params.value || 0n,
      params.data,
    ]);

    // Estimate gas with buffer, or use fallback
    // NOTE: Include value - wallet sends ETH to Identity, Identity forwards to target
    let gasLimit: bigint;
    try {
      const estimatedGas = await this.provider.estimateGas({
        to: params.identityAddress,
        data,
        value: params.value, // Wallet sends ETH to Identity (payable executeTransaction)
        from: this.config.signer.address,
      });
      gasLimit = estimatedGas * 130n / 100n; // 30% buffer
    } catch {
      gasLimit = 500_000n; // Fallback for executeTransaction
    }

    const txParams = {
      to: params.identityAddress,
      data,
      value: params.value, // Wallet sends ETH to Identity, Identity forwards to target
      gasLimit,
      ...gasSettings,
    };

    const tx = await this.config.signer.sendTransaction(txParams);

    const receipt = await tx.wait();

    // Parse return data from event or logs if needed
    // For now, just return success
    this.progress('complete', 'Transaction executed successfully', tx.hash, receipt.blockNumber);

    return {
      success: true,
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
      returnData: '0x', // Would need to parse from logs
    };
  }

  // ==========================================================================
  // EIP-1271 Signature Validation
  // ==========================================================================

  /**
   * Validate a signature using EIP-1271.
   *
   * Returns true if the signature was created by an authorized rivet.
   */
  async isValidSignature(
    identityAddress: string,
    hash: string,
    signature: string
  ): Promise<SignatureValidationResult> {
    this.progress('validating-signature', 'Validating signature...');

    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    try {
      const magicValue = await contract.isValidSignature(hash, signature);

      const isValid = magicValue === EIP1271_MAGIC_VALUE;

      // Try to recover signer from signature
      let signer: string | undefined;
      if (isValid) {
        try {
          signer = ethers.recoverAddress(hash, signature);
        } catch {
          // Signature might be in a format we can't recover from
        }
      }

      this.progress('complete', isValid ? 'Signature valid' : 'Signature invalid');

      return {
        isValid,
        signer: signer?.toLowerCase(),
        magicValue,
      };
    } catch (error) {
      return {
        isValid: false,
        magicValue: '0xffffffff',
      };
    }
  }

  /**
   * Sign a message hash on behalf of the identity.
   *
   * The signature can be verified using isValidSignature.
   */
  async signForIdentity(
    identityAddress: string,
    messageHash: string
  ): Promise<string> {
    // Verify caller is an authorized rivet
    const isAuthorized = await this.isCurrentDeviceAuthorized(identityAddress);
    if (!isAuthorized) {
      throw new IdentityError(
        'Current device is not authorized to sign for this identity',
        IdentityErrorCode.NOT_A_RIVET,
        { signer: this.config.signer.address, identity: identityAddress }
      );
    }

    // Convert hash to bytes
    const hashBytes = ethers.getBytes(messageHash);

    // Sign with the device wallet
    const signature = await this.config.signer.signMessage(hashBytes);

    return signature;
  }

  // ==========================================================================
  // Device Recovery
  // ==========================================================================

  /**
   * Execute device recovery flow.
   *
   * CRITICAL SAFETY FEATURE:
   * This is how you protect your identity if a device is lost or compromised.
   *
   * Steps:
   * 1. Add a new replacement device
   * 2. Remove the lost/compromised device
   *
   * Your identity and all its assets are preserved.
   *
   * @example
   * ```typescript
   * // Lost your phone? Use your laptop to recover:
   * const result = await manager.recoverFromLostDevice({
   *   identityAddress: '0x...',
   *   activeRivets: currentRivets,
   *   lostRivetAddress: '0xOldPhone...',
   *   newRivetAddress: '0xNewPhone...',
   *   newRivetName: 'New Phone',
   *   recoveringRivetAddress: laptopWallet.address,
   * });
   * ```
   */
  async recoverFromLostDevice(
    plan: DeviceRecoveryPlan
  ): Promise<DeviceRecoveryResult> {
    // Verify the recovering device is the current signer
    if (
      plan.recoveringRivetAddress.toLowerCase() !==
      this.config.signer.address.toLowerCase()
    ) {
      return {
        success: false,
        error: 'Recovery must be performed by the configured signer',
      };
    }

    // Verify recovering device is authorized
    const isAuthorized = await this.isCurrentDeviceAuthorized(plan.identityAddress);
    if (!isAuthorized) {
      return {
        success: false,
        error: 'Recovering device is not authorized for this identity',
      };
    }

    // Step 1: Add the new device
    let addResult: AddRivetResult | undefined;
    try {
      addResult = await this.addRivet({
        identityAddress: plan.identityAddress,
        rivetAddress: plan.newRivetAddress,
        rivetName: plan.newRivetName,
      });
    } catch (error) {
      return {
        success: false,
        error: `Failed to add new device: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }

    // Step 2: Remove the lost device
    let removeResult: RemoveRivetResult | undefined;
    try {
      removeResult = await this.removeRivet({
        identityAddress: plan.identityAddress,
        rivetAddress: plan.lostRivetAddress,
      });
    } catch (error) {
      // Important: The add succeeded, so the new device is already authorized
      // The remove failed, but recovery is partially complete
      return {
        success: false,
        addResult,
        error: `New device added but failed to remove lost device: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }

    return {
      success: true,
      addResult,
      removeResult,
    };
  }

  /**
   * Plan a device recovery.
   *
   * Use this to prepare recovery before executing.
   */
  async planRecovery(params: {
    identityAddress: string;
    lostRivetAddress: string;
    newRivetAddress: string;
    newRivetName: string;
  }): Promise<DeviceRecoveryPlan> {
    const info = await this.getIdentityInfo(params.identityAddress);
    const activeRivets = info.rivets.filter((r) => r.active);

    // Verify there's at least one other active rivet
    const otherRivets = activeRivets.filter(
      (r) => r.address.toLowerCase() !== params.lostRivetAddress.toLowerCase()
    );

    if (otherRivets.length === 0) {
      throw new IdentityError(
        'No other active devices available for recovery',
        'NO_RECOVERY_DEVICE'
      );
    }

    // Use current signer as recovering device
    const recoveringRivet = otherRivets.find(
      (r) => r.address.toLowerCase() === this.config.signer.address.toLowerCase()
    );

    if (!recoveringRivet) {
      throw new IdentityError(
        'Current signer is not an authorized recovery device',
        IdentityErrorCode.NOT_A_RIVET
      );
    }

    return {
      identityAddress: params.identityAddress,
      activeRivets,
      lostRivetAddress: params.lostRivetAddress,
      newRivetAddress: params.newRivetAddress,
      newRivetName: params.newRivetName,
      recoveringRivetAddress: recoveringRivet.address,
    };
  }

  // ==========================================================================
  // Public Key Management (for ECDH Key Sharing)
  // ==========================================================================

  /**
   * Register this device's public key on the identity contract.
   *
   * CRITICAL: This must be done before other devices can share keys with you.
   * The public key is used for ECDH key exchange.
   *
   * @param identityAddress - The identity contract address
   * @param publicKey - Uncompressed secp256k1 public key (0x04 + 128 hex chars)
   */
  async registerPublicKey(
    identityAddress: string,
    publicKey: string
  ): Promise<RegisterPublicKeyResult> {
    // Validate public key format
    if (!publicKey.startsWith('0x04') || publicKey.length !== 132) {
      throw new IdentityError(
        'Invalid public key format. Must be uncompressed secp256k1 (0x04 + 128 hex chars)',
        'INVALID_PUBLIC_KEY',
        { publicKey: publicKey.slice(0, 20) + '...' }
      );
    }

    // Verify caller is authorized
    const isAuthorized = await this.isCurrentDeviceAuthorized(identityAddress);
    if (!isAuthorized) {
      throw new IdentityError(
        'Current device is not authorized to register public key',
        IdentityErrorCode.NOT_A_RIVET
      );
    }

    this.progress('adding-rivet', 'Registering public key on identity contract...');

    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.config.signer as unknown as ethers.Signer
    );

    const tx = await contract.setPublicKey(publicKey);
    const receipt = await tx.wait();

    this.progress('complete', 'Public key registered');

    return {
      success: true,
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
      publicKey,
    };
  }

  /**
   * Get a device's registered public key from the identity contract.
   *
   * @param identityAddress - The identity contract address
   * @param deviceAddress - The device to get the public key for
   * @returns The public key or null if not registered
   */
  async getDevicePublicKey(
    identityAddress: string,
    deviceAddress: string
  ): Promise<string | null> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    try {
      const publicKey = await contract.getPublicKey(deviceAddress);
      return publicKey && publicKey.length > 0 ? publicKey : null;
    } catch {
      return null;
    }
  }

  /**
   * Get all devices with their public keys from the identity contract.
   *
   * This is the essential function for multi-device key sharing:
   * it returns all devices that can participate in ECDH key exchange.
   *
   * @param identityAddress - The identity contract address
   * @returns Array of devices with their public keys
   */
  async getDevicesWithPublicKeys(
    identityAddress: string
  ): Promise<DeviceWithPublicKey[]> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    const [addresses, names, publicKeys] = await contract.getRivetsWithPublicKeys();

    return addresses.map((address: string, i: number) => ({
      address: address.toLowerCase(),
      name: names[i],
      publicKey: publicKeys[i],
      hasPublicKey: publicKeys[i] && publicKeys[i].length > 0 && publicKeys[i] !== '0x',
    }));
  }

  /**
   * Encrypt a master key for a specific recipient using ECDH.
   *
   * ECDH Flow:
   * 1. Compute shared secret: senderPrivateKey * recipientPublicKey
   * 2. Derive AES key from shared secret (keccak256)
   * 3. Encrypt master key with AES-256-GCM
   *
   * @param masterKey - The master key to encrypt (32 bytes hex)
   * @param recipientPublicKey - Recipient's uncompressed public key
   * @param senderPrivateKey - Sender's private key
   * @param senderPublicKey - Sender's public key (for recipient to compute shared secret)
   */
  async encryptKeyForDevice(
    masterKey: string,
    recipientPublicKey: string,
    senderPrivateKey: string,
    senderPublicKey: string
  ): Promise<EncryptedKeyPackage> {
    // Compute ECDH shared secret
    const signingKey = new ethers.SigningKey(senderPrivateKey);
    const sharedSecret = signingKey.computeSharedSecret(recipientPublicKey);

    // Derive AES key using keccak256 (Ethereum standard)
    const aesKeyHex = ethers.keccak256(sharedSecret);
    const aesKeyBytes = ethers.getBytes(aesKeyHex);

    // Import AES key for Web Crypto
    // Note: ethers.getBytes returns Uint8Array with ArrayBuffer, cast for strict TypeScript
    const aesKey = await crypto.subtle.importKey(
      'raw',
      aesKeyBytes as Uint8Array<ArrayBuffer>,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt']
    );

    // Generate random IV
    const iv = crypto.getRandomValues(new Uint8Array(12));

    // Encrypt the master key
    const masterKeyBytes = ethers.getBytes(masterKey);
    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv, tagLength: 128 },
      aesKey,
      masterKeyBytes as Uint8Array<ArrayBuffer>
    );

    return {
      recipientAddress: '', // Caller should set this
      encryptedKey: ethers.hexlify(new Uint8Array(ciphertext)),
      iv: ethers.hexlify(iv),
      senderPublicKey,
    };
  }

  /**
   * Decrypt a master key that was encrypted for this device using ECDH.
   *
   * @param encryptedPackage - The encrypted key package
   * @param recipientPrivateKey - This device's private key
   */
  async decryptKeyFromDevice(
    encryptedPackage: EncryptedKeyPackage,
    recipientPrivateKey: string
  ): Promise<string> {
    // Compute ECDH shared secret (same as sender computed)
    const signingKey = new ethers.SigningKey(recipientPrivateKey);
    const sharedSecret = signingKey.computeSharedSecret(encryptedPackage.senderPublicKey);

    // Derive same AES key
    const aesKeyHex = ethers.keccak256(sharedSecret);
    const aesKeyBytes = ethers.getBytes(aesKeyHex);

    // Import AES key for Web Crypto
    // Note: ethers.getBytes returns Uint8Array with ArrayBuffer, cast for strict TypeScript
    const aesKey = await crypto.subtle.importKey(
      'raw',
      aesKeyBytes as Uint8Array<ArrayBuffer>,
      { name: 'AES-GCM', length: 256 },
      false,
      ['decrypt']
    );

    // Decrypt
    const ciphertext = ethers.getBytes(encryptedPackage.encryptedKey);
    const iv = ethers.getBytes(encryptedPackage.iv);

    const plaintext = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: iv as Uint8Array<ArrayBuffer>, tagLength: 128 },
      aesKey,
      ciphertext as Uint8Array<ArrayBuffer>
    );

    return ethers.hexlify(new Uint8Array(plaintext));
  }

  /**
   * Encrypt a master key for ALL devices on an identity.
   *
   * This is the core function for multi-device secret sharing:
   * it creates encrypted copies of a master key for each device.
   *
   * @param identityAddress - The identity contract address
   * @param masterKey - The master key to share (32 bytes hex)
   * @param senderPrivateKey - The sender's private key
   * @param senderPublicKey - The sender's public key
   * @returns Array of encrypted packages, one per device with a registered public key
   */
  async encryptKeyForAllDevices(
    identityAddress: string,
    masterKey: string,
    senderPrivateKey: string,
    senderPublicKey: string
  ): Promise<EncryptedKeyPackage[]> {
    const devices = await this.getDevicesWithPublicKeys(identityAddress);
    const packages: EncryptedKeyPackage[] = [];

    for (const device of devices) {
      if (!device.hasPublicKey) {
        console.warn(`Skipping device ${device.address} - no public key registered`);
        continue;
      }

      const pkg = await this.encryptKeyForDevice(
        masterKey,
        device.publicKey,
        senderPrivateKey,
        senderPublicKey
      );

      packages.push({
        ...pkg,
        recipientAddress: device.address,
      });
    }

    return packages;
  }

  // ==========================================================================
  // KeyVault Operations (Encrypted Storage on Identity)
  // ==========================================================================

  /**
   * Store data in the identity's KeyVault.
   *
   * KeyVault is on-chain encrypted storage attached to the identity contract.
   * Useful for storing encrypted master keys, configuration, etc.
   *
   * @param identityAddress - The identity contract address
   * @param key - The key name to store under
   * @param value - The value to store (bytes)
   * @param isPublic - Whether external parties can read this key
   */
  async setKeyVault(
    identityAddress: string,
    key: string,
    value: Uint8Array,
    isPublic: boolean = false
  ): Promise<{ txHash: string; blockNumber: number }> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.config.signer as unknown as ethers.Signer
    );

    const tx = await contract.setKeyVault(key, value, isPublic);
    const receipt = await tx.wait();

    return {
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
    };
  }

  /**
   * Get data from the identity's KeyVault.
   *
   * @param identityAddress - The identity contract address
   * @param key - The key name to retrieve
   */
  async getKeyVault(identityAddress: string, key: string): Promise<Uint8Array | null> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    try {
      const value = await contract.getKeyVault(key);
      return ethers.getBytes(value);
    } catch {
      return null;
    }
  }

  /**
   * Check if a key exists in the identity's KeyVault.
   */
  async hasKeyVault(identityAddress: string, key: string): Promise<boolean> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.provider
    );

    try {
      return await contract.hasKeyVault(key);
    } catch {
      return false;
    }
  }

  /**
   * Delete a key from the identity's KeyVault.
   */
  async deleteKeyVault(
    identityAddress: string,
    key: string
  ): Promise<{ txHash: string; blockNumber: number }> {
    const contract = new ethers.Contract(
      identityAddress,
      IDENTITY_CONTRACT_ABI,
      this.config.signer as unknown as ethers.Signer
    );

    const tx = await contract.deleteKeyVault(key);
    const receipt = await tx.wait();

    return {
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
    };
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  private progress(
    step: IdentityStep['step'],
    message: string,
    txHash?: string,
    blockNumber?: number
  ): void {
    if (this.config.onProgress) {
      this.config.onProgress({ step, message, txHash, blockNumber });
    }
  }
}
