/**
 * Wallet Factory
 *
 * Factory functions for creating, loading, and recovering wallets.
 * Provides a high-level API that integrates signers with storage.
 */

import type { Provider } from 'ethers';
import { EOASigner } from './eoa-signer.js';
import {
  WalletError,
  type RootzSigner,
  type StorageAdapter,
  type StoredWallet,
  type WalletState,
  type CreateWalletOptions,
  type RecoverWalletOptions,
  type LoadWalletOptions,
} from './types.js';

/**
 * Result of wallet creation or loading.
 */
export interface WalletResult {
  /** The signer to use for operations */
  signer: RootzSigner;

  /** Wallet state information */
  state: WalletState;

  /** Mnemonic (only for new wallets - must be backed up) */
  mnemonic?: string;
}

/**
 * Create a new wallet.
 *
 * Generates a new BIP39 mnemonic and derives an HD wallet.
 * IMPORTANT: The mnemonic in the result MUST be backed up by the user.
 *
 * @example
 * ```typescript
 * const { signer, state, mnemonic } = await createWallet({
 *   storage: new BrowserStorageAdapter(),
 *   provider: new JsonRpcProvider(rpcUrl),
 * });
 *
 * // Show mnemonic to user for backup
 * console.log('Backup this phrase:', mnemonic);
 * ```
 */
export async function createWallet(
  options: CreateWalletOptions
): Promise<WalletResult> {
  const { storage, provider, identityContract, deviceId } = options;

  // Check if wallet already exists
  if (await storage.exists()) {
    throw new WalletError('Wallet already exists. Use loadWallet() or delete first.', 'STORAGE_ERROR');
  }

  // Create new wallet
  const { signer: baseSigner, mnemonic, stored } = EOASigner.create();

  // Add identity info if provided
  const walletData: StoredWallet = {
    ...stored,
    identityContract,
    deviceId,
  };

  // Save to storage
  await storage.save(walletData);

  // Connect to provider if provided
  const signer = provider ? baseSigner.connect(provider) : baseSigner;

  // Build state
  const state: WalletState = {
    address: walletData.address,
    publicKey: walletData.publicKey,
    isNew: true,
    signerType: 'eoa',
    identityContract,
  };

  // Get provider info if connected
  if (provider) {
    state.providerInfo = await getProviderInfo(signer, provider);
  }

  return { signer, state, mnemonic };
}

/**
 * Recover a wallet from mnemonic.
 *
 * @example
 * ```typescript
 * const { signer, state } = await recoverWallet({
 *   mnemonic: 'word1 word2 ... word12',
 *   storage: new BrowserStorageAdapter(),
 *   provider: new JsonRpcProvider(rpcUrl),
 * });
 * ```
 */
export async function recoverWallet(
  options: RecoverWalletOptions
): Promise<WalletResult> {
  const { mnemonic, storage, provider, derivationPath } = options;

  // Validate mnemonic (basic check)
  const words = mnemonic.trim().split(/\s+/);
  if (words.length !== 12 && words.length !== 24) {
    throw new WalletError('Invalid mnemonic: must be 12 or 24 words', 'INVALID_MNEMONIC');
  }

  // Recover wallet
  const { signer: baseSigner, stored } = EOASigner.fromMnemonic(
    mnemonic,
    derivationPath
  );

  // Save to storage
  await storage.save(stored);

  // Connect to provider if provided
  const signer = provider ? baseSigner.connect(provider) : baseSigner;

  // Build state
  const state: WalletState = {
    address: stored.address,
    publicKey: stored.publicKey,
    isNew: false, // Recovered, not new
    signerType: 'eoa',
  };

  // Get provider info if connected
  if (provider) {
    state.providerInfo = await getProviderInfo(signer, provider);
  }

  return { signer, state };
}

/**
 * Load an existing wallet from storage.
 *
 * @example
 * ```typescript
 * const { signer, state } = await loadWallet({
 *   storage: new BrowserStorageAdapter(),
 *   provider: new JsonRpcProvider(rpcUrl),
 * });
 * ```
 */
export async function loadWallet(
  options: LoadWalletOptions
): Promise<WalletResult> {
  const { storage, provider } = options;

  // Load from storage
  const stored = await storage.load();
  if (!stored) {
    throw new WalletError('No wallet found in storage. Use createWallet() first.', 'WALLET_NOT_FOUND');
  }

  // Create signer from stored data
  const baseSigner = EOASigner.fromStored(stored);

  // Connect to provider if provided
  const signer = provider ? baseSigner.connect(provider) : baseSigner;

  // Build state
  const state: WalletState = {
    address: stored.address,
    publicKey: stored.publicKey,
    isNew: false,
    signerType: 'eoa',
    identityContract: stored.identityContract,
  };

  // Get provider info if connected
  if (provider) {
    state.providerInfo = await getProviderInfo(signer, provider);
  }

  return { signer, state };
}

/**
 * Load wallet or create if doesn't exist.
 * Convenience method for apps that always want a wallet.
 *
 * @example
 * ```typescript
 * const { signer, state, mnemonic } = await loadOrCreateWallet({
 *   storage: new BrowserStorageAdapter(),
 *   provider: new JsonRpcProvider(rpcUrl),
 * });
 *
 * if (mnemonic) {
 *   // New wallet - show backup prompt
 *   showMnemonicBackup(mnemonic);
 * }
 * ```
 */
export async function loadOrCreateWallet(
  options: LoadWalletOptions & Partial<CreateWalletOptions>
): Promise<WalletResult> {
  const { storage, provider, identityContract, deviceId } = options;

  // Try to load first
  if (await storage.exists()) {
    return loadWallet({ storage, provider });
  }

  // Create new wallet
  return createWallet({
    storage,
    provider,
    identityContract,
    deviceId,
  });
}

/**
 * Delete wallet from storage.
 * WARNING: This is irreversible if mnemonic wasn't backed up.
 */
export async function deleteWallet(storage: StorageAdapter): Promise<void> {
  await storage.delete();
}

/**
 * Check if wallet exists in storage.
 */
export async function walletExists(storage: StorageAdapter): Promise<boolean> {
  return storage.exists();
}

/**
 * Get the mnemonic from stored wallet (for backup).
 * Returns null if no wallet or no mnemonic stored.
 */
export async function getMnemonic(
  storage: StorageAdapter
): Promise<string | null> {
  const stored = await storage.load();
  return stored?.mnemonic || null;
}

// ============================================================================
// Helpers
// ============================================================================

async function getProviderInfo(
  signer: RootzSigner,
  provider: Provider
): Promise<WalletState['providerInfo']> {
  try {
    const [network, balance] = await Promise.all([
      provider.getNetwork(),
      provider.getBalance(await signer.getAddress()),
    ]);

    // Format balance (assuming 18 decimals like POL/MATIC)
    const balanceFormatted = formatBalance(balance, 18, 'POL');

    return {
      chainId: Number(network.chainId),
      networkName: network.name,
      balance,
      balanceFormatted,
    };
  } catch {
    return undefined;
  }
}

function formatBalance(
  balance: bigint,
  decimals: number,
  symbol: string
): string {
  const divisor = 10n ** BigInt(decimals);
  const whole = balance / divisor;
  const remainder = balance % divisor;
  const decimal = remainder.toString().padStart(decimals, '0').slice(0, 4);
  return `${whole}.${decimal} ${symbol}`;
}
