// ============================================================================
// Render Functions
// ============================================================================

const CATEGORY_LABELS: Record<string, string> = {
  'getting-started': 'Getting Started',
  'features': 'Features',
  'advanced': 'Advanced',
  'troubleshooting': 'Troubleshooting',
};

/**
 * Render the full Help tab HTML
 */
export function renderHelpTab(): string {
  const categories = ['getting-started', 'features', 'advanced', 'troubleshooting'] as const;

  const guideSections = categories.map(cat => {
    const guides = HELP_GUIDES.filter(g => g.category === cat);
    return `
      <div class="help-category">
        <h3>${CATEGORY_LABELS[cat]}</h3>
        <div class="help-guide-list">
          ${guides.map(g => `
            <button class="help-guide-btn" data-guide="${g.id}">
              <span class="help-guide-title">${g.title}</span>
            </button>
          `).join('')}
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="help-tab">
      <div class="help-layout">
        <!-- Guide Navigation -->
        <div class="help-nav">
          <h2>Help & Tutorial</h2>
          <p class="help-intro">Learn how to use Rootz Desktop. Click a topic to read more.</p>
          ${guideSections}
        </div>

        <!-- Guide Content -->
        <div class="help-content" id="help-content">
          <div class="help-welcome">
            <h3>Welcome to Rootz Desktop Help</h3>
            <p>Select a topic from the left to get started.</p>
            <p>You can also click the <strong>?</strong> button on any tab for contextual help specific to that page.</p>
            <div class="help-quick-links">
              <h4>Quick links</h4>
              <button class="help-guide-btn inline" data-guide="first-setup">First-Time Setup</button>
              <button class="help-guide-btn inline" data-guide="mcp-connection">Connecting AI Tools</button>
              <button class="help-guide-btn inline" data-guide="identity-recovery">Identity & Recovery</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  `;
}

/**
 * Setup Help tab event handlers
 */
export function setupHelpTab(initialGuideId?: string): void {
  const contentEl = document.getElementById('help-content');
  if (!contentEl) return;

  // Guide button click handler
  document.querySelectorAll('.help-guide-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const guideId = (btn as HTMLElement).dataset.guide;
      if (guideId) showGuide(guideId, contentEl);

      // Highlight active button
      document.querySelectorAll('.help-guide-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // Show initial guide if specified
  if (initialGuideId) {
    showGuide(initialGuideId, contentEl);
    const btn = document.querySelector(`.help-guide-btn[data-guide="${initialGuideId}"]`);
    if (btn) btn.classList.add('active');
  }
}

function showGuide(guideId: string, contentEl: Element): void {
  const guide = HELP_GUIDES.find(g => g.id === guideId);
  if (!guide) return;

  contentEl.innerHTML = `
    <div class="help-guide-content">
      <h3>${guide.title}</h3>
      ${guide.content}
    </div>
  `;
}

// ============================================================================
// Contextual Help Panel (? button overlay)
// ============================================================================

/**
 * Show contextual help for a specific tab as a slide-out panel.
 * Returns the HTML for the help panel overlay.
 */
export function showContextualHelp(tabId: string): void {
  const topic = TAB_HELP[tabId];
  if (!topic) return;

  // Remove existing panel if any
  const existing = document.getElementById('contextual-help-panel');
  if (existing) existing.remove();

  const panel = document.createElement('div');
  panel.id = 'contextual-help-panel';
  panel.className = 'contextual-help-panel';
  panel.innerHTML = `
    <div class="contextual-help-header">
      <h3>${topic.title}</h3>
      <button class="contextual-help-close" id="close-contextual-help">&times;</button>
    </div>
    <div class="contextual-help-body">
      ${topic.content}
    </div>
    <div class="contextual-help-footer">
      <button class="help-guide-btn inline" id="open-full-help" data-tab="help">Open full Help tab</button>
    </div>
  `;

  document.body.appendChild(panel);

  // Animate in
  requestAnimationFrame(() => panel.classList.add('open'));

  // Close button
  document.getElementById('close-contextual-help')?.addEventListener('click', () => {
    panel.classList.remove('open');
    setTimeout(() => panel.remove(), 300);
  });

  // Full help button
  document.getElementById('open-full-help')?.addEventListener('click', () => {
    panel.classList.remove('open');
    setTimeout(() => panel.remove(), 300);
    // Click the help tab button
    const helpBtn = document.querySelector('button[data-tab="help"]') as HTMLButtonElement;
    if (helpBtn) helpBtn.click();
  });

  // Close on escape
  const escHandler = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      panel.classList.remove('open');
      setTimeout(() => panel.remove(), 300);
      document.removeEventListener('keydown', escHandler);
    }
  };
  document.addEventListener('keydown', escHandler);
}

/**
 * Inject contextual ? help button into a tab's content area.
 * Call this after rendering any tab's HTML.
 */
export function injectHelpButton(tabId: string): void {
  const topic = TAB_HELP[tabId];
  if (!topic) return;

  // Find the content area's first h2 or h3 to place the ? button near
  const content = document.getElementById('content');
  if (!content) return;

  // Create floating ? button
  let helpBtn = document.getElementById('tab-help-btn');
  if (!helpBtn) {
    helpBtn = document.createElement('button');
    helpBtn.id = 'tab-help-btn';
    helpBtn.className = 'tab-help-btn';
    helpBtn.textContent = '?';
    helpBtn.title = `Help: ${topic.title}`;
    document.body.appendChild(helpBtn);
  } else {
    helpBtn.title = `Help: ${topic.title}`;
  }

  // Update click handler for current tab
  helpBtn.onclick = () => showContextualHelp(tabId);
  helpBtn.style.display = 'block';
}

/**
 * Hide the contextual help button (e.g., when switching tabs before re-injection)
 */
export function hideHelpButton(): void {
  const btn = document.getElementById('tab-help-btn');
  if (btn) btn.style.display = 'none';
}
