/**
 * Operating mode for the dashboard.
 * - LOCAL: Operating as a standalone wallet (direct ownership)
 * - IDENTITY: Operating as a rivet of an Identity contract
 */
type OperatingMode = 'LOCAL' | 'IDENTITY';

interface AppState {
  config: AppConfig;
  wallet: WalletState;
  crypto: RootzCrypto;
  chainReader: ChainReader;
  storage: StorageGateway;
  chainName: string;

  // Operating mode - determines how secrets are created/shared/written
  operatingMode: OperatingMode;
  operatingIdentity: string | null;  // Identity contract address when in IDENTITY mode
  availableIdentities: string[];     // All Identity contracts this wallet is a rivet of
}

let app: AppState | null = null;

// Store current KV key for encrypted file downloads
let currentKvKey: Uint8Array | null = null;

// ABIs are now imported from @rootz/integration (REGISTRY_ADMIN_ABI, MULTI_TOKEN_PURCHASE_ABI, REGISTRY_V7_ABI)

/**
 * Save a known Identity contract to localStorage for future monitoring.
 * When we receive an invite from an Identity, we need to monitor that Identity
 * for executeTransaction calls that might contain messages for us.
 */
function saveKnownIdentity(walletAddress: string, identityAddress: string): void {
  const key = `known_identities_${walletAddress.toLowerCase()}`;
  try {
    const existing = localStorage.getItem(key);
    const identities: string[] = existing ? JSON.parse(existing) : [];
    const normalized = identityAddress.toLowerCase();
    if (!identities.includes(normalized)) {
      identities.push(normalized);
      localStorage.setItem(key, JSON.stringify(identities));
      console.log(`[Storage] Saved known Identity: ${identityAddress.slice(0, 10)}...`);
    }
  } catch (e) {
    console.warn('[Storage] Failed to save known identity:', e);
  }
}

/**
 * Buy credits using CreditPurchaser (MultiToken or Registry fallback)
 * 0.1 POL = 1000 credits (with POL rate: 1000 credits per 1 POL)
 */
async function buyCredits(state: AppState): Promise<void> {
  const btn = document.getElementById('buy-credits-btn') as HTMLButtonElement;
  if (!btn) return;

  const originalText = btn.textContent;
  btn.textContent = 'Buying...';
  btn.disabled = true;

  try {
    // Create CreditPurchaser with available contracts
    const purchaser = createCreditPurchaser(state.wallet.signer as any, {
      multiTokenPurchase: state.config.contracts.multiTokenPurchase,
      registry: state.config.contracts.registry,
    });

    console.log('[Credits] Using', purchaser.getPurchaseMethod(), 'method');
    console.log('[Credits] Buying with 0.1 POL...');

    // Preview if available (MultiToken only)
    const preview = await purchaser.previewPurchase('0.1');
    if (preview) {
      console.log('[Credits] Preview - Total:', preview.totalCredits.toString(), 'Bonus%:', preview.bonusPercent.toString());
    }

    // Purchase credits
    btn.textContent = 'Confirming...';
    const result = await purchaser.purchaseWithPOL('0.1');

    if (result.success) {
      console.log('[Credits] ✅ Confirmed, block:', result.blockNumber);

      // Update balance and refresh header (including credits)
      const balanceWei = await state.wallet.provider.getBalance(state.wallet.address);
      state.wallet.balance = formatEther(balanceWei);
      await updateHeader(state);

      btn.textContent = 'Success!';
    } else {
      console.error('[Credits] Purchase failed:', result.error);
      btn.textContent = 'Failed';
    }

    setTimeout(() => {
      btn.textContent = originalText;
      btn.disabled = false;
    }, 2000);

  } catch (error) {
    console.error('[Credits] Error:', error);
    btn.textContent = 'Failed';
    setTimeout(() => {
      btn.textContent = originalText;
      btn.disabled = false;
    }, 2000);
  }
}

/**
 * Check Registry admin status and show setup button if needed
 */
async function checkRegistryStatus(state: AppState): Promise<void> {
  const registryAddress = state.config.contracts.registry;
  const rateTableAddress = state.config.contracts.rateTable;

  if (!registryAddress) {
    console.log('[Registry] No registry configured');
    return;
  }

  try {
    const registry = new Contract(
      getAddress(registryAddress),
      REGISTRY_ADMIN_ABI,
      state.wallet.provider
    );

    const owner = await registry.owner();
    const rootzKey = await registry.rootzKey();

    console.log('[Registry] Owner:', owner);
    console.log('[Registry] RootzKey:', rootzKey);
    console.log('[Registry] RateTable config:', rateTableAddress);

    const isOwner = owner.toLowerCase() === state.wallet.address.toLowerCase();
    const needsSetup = rootzKey === '0x0000000000000000000000000000000000000000';

    if (needsSetup) {
      console.log('[Registry] ⚠️ RootzKey NOT registered - credits system not active');

      if (isOwner) {
        console.log('[Registry] ✅ You are the owner - you can register rootzKey');

        // Add setup button to header
        const headerRight = document.querySelector('.header-right');
        if (headerRight && !document.getElementById('setup-registry-btn')) {
          const setupBtn = document.createElement('button');
          setupBtn.id = 'setup-registry-btn';
          setupBtn.className = 'warning';
          setupBtn.textContent = '⚠️ Setup Registry';
          setupBtn.style.marginRight = '10px';
          setupBtn.onclick = () => registerRootzKey(state);
          headerRight.insertBefore(setupBtn, headerRight.firstChild);
        }
      } else {
        console.log('[Registry] ❌ You are NOT the owner - contact admin to setup');
      }
    } else {
      console.log('[Registry] ✅ RootzKey registered:', rootzKey);
    }

  } catch (error) {
    console.error('[Registry] Error checking status:', error);
  }
}

/**
 * Register rootzKey and rateTable on Registry (owner only)
 */
async function registerRootzKey(state: AppState): Promise<void> {
  const btn = document.getElementById('setup-registry-btn') as HTMLButtonElement;
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Setting up...';
  }

  try {
    const registryAddress = state.config.contracts.registry;
    const rateTableAddress = state.config.contracts.rateTable;

    if (!registryAddress || !rateTableAddress) {
      throw new Error('Registry or RateTable not configured');
    }

    const registry = new Contract(
      getAddress(registryAddress),
      REGISTRY_ADMIN_ABI,
      state.wallet.signer as any
    );

    // Use the connected wallet as the rootzKey (receives POL from credit purchases)
    const rootzKeyAddress = state.wallet.address;

    console.log('[Registry] Registering rootzKey and rateTable...');
    console.log('[Registry] RootzKey (will receive POL):', rootzKeyAddress);
    console.log('[Registry] RateTable:', rateTableAddress);

    // Use DYNAMIC gas estimation via GasProvider
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gas = await gasProvider.getGasSettings('standard');
    console.log(`[Registry] Current gas: ${gas.maxFeePerGasGwei.toFixed(2)} Gwei`);

    const tx = await registry.registerRootzKeyAndRateTable(
      rootzKeyAddress,
      getAddress(rateTableAddress),
      {
        maxFeePerGas: gas.maxFeePerGas,
        maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
      }
    );

    console.log('[Registry] TX sent:', tx.hash);

    if (btn) btn.textContent = 'Confirming...';

    const receipt = await tx.wait();
    console.log('[Registry] ✅ Registered! Block:', receipt.blockNumber);

    // Remove setup button and refresh header
    if (btn) btn.remove();
    await updateHeader(state);

    alert('Registry setup complete! You can now buy credits.');

  } catch (error) {
    console.error('[Registry] Setup error:', error);
    if (btn) {
      btn.disabled = false;
      btn.textContent = '⚠️ Setup Registry';
    }
    alert(`Setup failed: ${(error as Error).message}`);
  }
}

/**
 * Update header with wallet and network info
 */
async function updateHeader(state: AppState) {
  const networkBadge = document.getElementById('network-badge');
  const walletAddress = document.getElementById('wallet-address');
  const walletBalance = document.getElementById('wallet-balance');
  const registryCredits = document.getElementById('registry-credits');

  if (networkBadge) {
    networkBadge.textContent = `${state.config.network.name} (${state.config.network.chainId})`;
  }

  if (walletAddress) {
    walletAddress.textContent = formatAddress(state.wallet.address);
    walletAddress.title = state.wallet.address;
    walletAddress.onclick = () => {
      navigator.clipboard.writeText(state.wallet.address);
      walletAddress.textContent = 'Copied!';
      setTimeout(() => {
        walletAddress.textContent = formatAddress(state.wallet.address);
      }, 1000);
    };
  }

  if (walletBalance) {
    const symbol = getCurrencySymbol(state.config.network.chainId);
    // Live-fetch balance from provider instead of using cached value
    try {
      const balanceWei = await state.wallet.provider.getBalance(state.wallet.address);
      state.wallet.balance = formatEther(balanceWei);
    } catch (e) {
      console.warn('[Header] Balance fetch failed, using cached:', e);
    }
    walletBalance.textContent = `${parseFloat(state.wallet.balance).toFixed(4)} ${symbol}`;
  }

  // Update Identity contract display
  const identityEl = document.getElementById('identity-address');
  if (identityEl) {
    if (state.operatingMode === 'IDENTITY' && state.operatingIdentity) {
      identityEl.textContent = `Identity: ${formatAddress(state.operatingIdentity)}`;
      identityEl.title = state.operatingIdentity;
      identityEl.className = 'identity-badge active';
      identityEl.onclick = () => {
        navigator.clipboard.writeText(state.operatingIdentity!);
        identityEl.textContent = 'Copied!';
        setTimeout(() => {
          identityEl.textContent = `Identity: ${formatAddress(state.operatingIdentity!)}`;
        }, 1000);
      };
    } else {
      identityEl.className = 'identity-badge';
    }
  }

  // Update wallet source badge
  const walletSourceBadge = document.getElementById('wallet-source-badge');
  if (walletSourceBadge) {
    const source = getWalletSource();
    if (source === 'hardware') {
      walletSourceBadge.textContent = 'Hardware';
      walletSourceBadge.className = 'wallet-source-badge hardware';
      walletSourceBadge.title = 'Hardware wallet: Keys protected by Trezor/Ledger';
    } else if (source === 'tpm') {
      walletSourceBadge.textContent = 'TPM';
      walletSourceBadge.className = 'wallet-source-badge tpm';
      walletSourceBadge.title = 'TPM-enhanced wallet: Two-factor hardware+software protection';
    } else {
      walletSourceBadge.textContent = 'Standard';
      walletSourceBadge.className = 'wallet-source-badge standard';
      walletSourceBadge.title = 'Standard wallet: Browser localStorage';
    }
  }

  // Fetch and display Registry credits
  if (registryCredits && state.config.contracts.registry) {
    try {
      // Use getAddress() to normalize addresses and avoid ENS resolution on non-ETH chains
      const registryAddr = getAddress(state.config.contracts.registry);
      const walletAddr = getAddress(state.wallet.address);
      const registry = new Contract(registryAddr, REGISTRY_ABI, state.wallet.provider);
      const credits = await registry.getUserCredits(walletAddr);
      const creditsNum = Number(credits);
      registryCredits.textContent = `Credits: ${creditsNum.toLocaleString()}`;
      registryCredits.className = creditsNum > 0 ? 'registry-credits has-credits' : 'registry-credits no-credits';
      console.log('[Header] Registry credits:', creditsNum);
    } catch (e) {
      console.error('[Header] Failed to fetch Registry credits:', e);
      registryCredits.textContent = 'Credits: --';
    }
  }

  // Setup Buy Credits button - opens modal
  const buyCreditsBtn = document.getElementById('buy-credits-btn');
  if (buyCreditsBtn) {
    buyCreditsBtn.onclick = () => openCreditModal(state);
  }

  // Render operating mode selector
  renderModeSelector(state);
}

/**
 * Render the operating mode selector in the header.
 * Allows user to switch between LOCAL and IDENTITY modes.
 */
function renderModeSelector(state: AppState): void {
  // Find or create the mode selector container
  let modeContainer = document.getElementById('operating-mode-container');
  if (!modeContainer) {
    // Create container and insert after wallet info
    const walletInfo = document.querySelector('.wallet-info');
    if (walletInfo) {
      modeContainer = document.createElement('div');
      modeContainer.id = 'operating-mode-container';
      modeContainer.className = 'operating-mode-container';
      walletInfo.parentNode?.insertBefore(modeContainer, walletInfo.nextSibling);
    } else {
      return; // No place to insert
    }
  }

  // Build options for the selector
  const options: string[] = [];

  // Always have LOCAL option
  options.push(`<option value="LOCAL" ${state.operatingMode === 'LOCAL' ? 'selected' : ''}>🔑 Local Wallet</option>`);

  // Add Identity options
  for (const identity of state.availableIdentities) {
    const selected = state.operatingMode === 'IDENTITY' && state.operatingIdentity === identity ? 'selected' : '';
    const shortAddr = `${identity.slice(0, 6)}...${identity.slice(-4)}`;
    options.push(`<option value="${identity}" ${selected}>🆔 Identity ${shortAddr}</option>`);
  }

  // Render the selector
  modeContainer.innerHTML = `
    <label class="mode-label">Operating as:</label>
    <select id="operating-mode-select" class="mode-select">
      ${options.join('')}
    </select>
  `;

  // Attach change handler
  const select = document.getElementById('operating-mode-select') as HTMLSelectElement;
  if (select) {
    select.onchange = () => {
      const value = select.value;
      if (value === 'LOCAL') {
        setOperatingMode(state, 'LOCAL', null);
      } else {
        setOperatingMode(state, 'IDENTITY', value);
      }
    };
  }
}

/**
 * Change the operating mode for the dashboard.
 * This affects how secrets are created, shared, and written.
 */
function setOperatingMode(state: AppState, mode: OperatingMode, identity: string | null): void {
  const oldMode = state.operatingMode;
  const oldIdentity = state.operatingIdentity;

  state.operatingMode = mode;
  state.operatingIdentity = identity;

  // Save to localStorage for persistence
  localStorage.setItem(`operating_mode_${state.wallet.address.toLowerCase()}`, mode);
  // Use storage module for identity persistence (handles multi-identity)
  setActiveIdentity(state.wallet.address, identity);

  // Log the change
  if (mode === 'LOCAL') {
    console.log('[Mode] Switched to LOCAL mode');
  } else {
    console.log(`[Mode] Switched to IDENTITY mode: ${identity?.slice(0, 12)}...`);
  }

  // Show notification if mode changed
  if (oldMode !== mode || oldIdentity !== identity) {
    const message = mode === 'LOCAL'
      ? 'Now operating as local wallet'
      : `Now operating as Identity ${identity?.slice(0, 10)}...`;
    showModeNotification(message);
  }
}

/**
 * Show a brief notification when mode changes.
 */
function showModeNotification(message: string): void {
  // Remove existing notification if any
  const existing = document.querySelector('.mode-notification');
  if (existing) existing.remove();

  const notification = document.createElement('div');
  notification.className = 'mode-notification';
  notification.textContent = message;
  document.body.appendChild(notification);

  // Fade out after 2 seconds
  setTimeout(() => {
    notification.classList.add('fade-out');
    setTimeout(() => notification.remove(), 300);
  }, 2000);
}

/**
 * Show entropy backup modal for TPM wallet
 * Returns a promise that resolves when user dismisses the modal
 */
function showEntropyBackupModal(address: string, entropy: string): Promise<void> {
  return new Promise((resolve) => {
    // Create modal overlay
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.display = 'flex';
    modal.innerHTML = `
      <div class="modal-backdrop"></div>
      <div class="modal-content" style="max-width: 500px;">
        <div class="modal-header">
          <h2>TPM Wallet Created</h2>
        </div>
        <div class="modal-body">
          <div class="success-message" style="background: #065f46; padding: 1rem; border-radius: 8px; margin-bottom: 1rem;">
            <strong>New Address:</strong>
            <div style="font-family: monospace; font-size: 0.85rem; word-break: break-all; margin-top: 0.5rem;">
              ${address}
            </div>
          </div>

          <div class="warning-message" style="background: #92400e; padding: 1rem; border-radius: 8px; margin-bottom: 1rem;">
            <strong>IMPORTANT: Back up your entropy!</strong>
            <p style="margin: 0.5rem 0; font-size: 0.9rem;">
              Your wallet requires BOTH this entropy AND this TPM to recover.
              Store this securely - losing it means losing access to this wallet.
            </p>
          </div>

          <div style="margin-bottom: 1rem;">
            <label style="display: block; margin-bottom: 0.5rem; font-weight: 600;">Entropy (click to copy):</label>
            <div id="entropy-display" style="
              font-family: monospace;
              font-size: 0.8rem;
              background: #1f2937;
              padding: 1rem;
              border-radius: 6px;
              word-break: break-all;
              cursor: pointer;
              border: 2px solid transparent;
              transition: border-color 0.2s;
            " title="Click to copy">${entropy}</div>
            <div id="copy-status" style="font-size: 0.8rem; color: #34d399; margin-top: 0.5rem; opacity: 0; transition: opacity 0.2s;"></div>
          </div>

          <button id="entropy-modal-close" class="primary full-width">I've Backed Up My Entropy</button>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    // Setup copy functionality
    const entropyDisplay = modal.querySelector('#entropy-display') as HTMLElement;
    const copyStatus = modal.querySelector('#copy-status') as HTMLElement;

    entropyDisplay.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(entropy);
        entropyDisplay.style.borderColor = '#34d399';
        copyStatus.textContent = 'Copied to clipboard!';
        copyStatus.style.opacity = '1';
        setTimeout(() => {
          entropyDisplay.style.borderColor = 'transparent';
          copyStatus.style.opacity = '0';
        }, 2000);
      } catch (err) {
        copyStatus.textContent = 'Copy failed - please select and copy manually';
        copyStatus.style.color = '#f87171';
        copyStatus.style.opacity = '1';
      }
    });

    // Setup close button
    const closeBtn = modal.querySelector('#entropy-modal-close') as HTMLButtonElement;
    closeBtn.addEventListener('click', () => {
      modal.remove();
      resolve();
    });

    // Close on backdrop click
    const backdrop = modal.querySelector('.modal-backdrop') as HTMLElement;
    backdrop.addEventListener('click', () => {
      modal.remove();
      resolve();
    });
  });
}

/**
 * Show an input modal (replacement for prompt() which doesn't work in Electron)
 * Returns null if cancelled, otherwise returns the input value
 */
function showInputModal(title: string, message: string, defaultValue: string = ''): Promise<string | null> {
  return new Promise((resolve) => {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.display = 'flex';
    modal.innerHTML = `
      <div class="modal-backdrop"></div>
      <div class="modal-content" style="max-width: 400px;">
        <div class="modal-header">
          <h2>${title}</h2>
        </div>
        <div class="modal-body">
          <p style="margin-bottom: 1rem; white-space: pre-wrap;">${message}</p>
          <input type="text" id="modal-input" value="${defaultValue}" style="
            width: 100%;
            padding: 0.75rem;
            font-size: 1rem;
            border: 1px solid #374151;
            border-radius: 6px;
            background: #1f2937;
            color: white;
            margin-bottom: 1rem;
          " />
          <div style="display: flex; gap: 0.5rem;">
            <button id="modal-cancel" class="secondary" style="flex: 1;">Cancel</button>
            <button id="modal-confirm" class="primary" style="flex: 1;">OK</button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const input = modal.querySelector('#modal-input') as HTMLInputElement;
    const cancelBtn = modal.querySelector('#modal-cancel') as HTMLButtonElement;
    const confirmBtn = modal.querySelector('#modal-confirm') as HTMLButtonElement;
    const backdrop = modal.querySelector('.modal-backdrop') as HTMLElement;

    // Focus input with delay for Electron compatibility
    setTimeout(() => {
      input.focus();
      input.select();
    }, 100);

    // Handle Enter key
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        modal.remove();
        resolve(input.value);
      } else if (e.key === 'Escape') {
        modal.remove();
        resolve(null);
      }
    });

    cancelBtn.addEventListener('click', () => {
      modal.remove();
      resolve(null);
    });

    confirmBtn.addEventListener('click', () => {
      modal.remove();
      resolve(input.value);
    });

    backdrop.addEventListener('click', () => {
      modal.remove();
      resolve(null);
    });
  });
}

// Store token configs globally for the modal
let creditTokenConfigs: Map<string, { creditsPerToken: bigint; bonusPercent: bigint; isActive: boolean }> = new Map();

/**
 * Open the credit purchase modal and load token options
 */
async function openCreditModal(state: AppState): Promise<void> {
  const modal = document.getElementById('credit-modal');
  const loading = document.getElementById('credit-modal-loading');
  const tokensDiv = document.getElementById('credit-modal-tokens');
  const tokenSelect = document.getElementById('credit-token-select') as HTMLSelectElement;

  if (!modal) return;

  // Show modal
  modal.style.display = 'flex';

  // Show loading, hide tokens
  if (loading) loading.style.display = 'block';
  if (tokensDiv) tokensDiv.style.display = 'none';

  try {
    const multiTokenAddress = state.config.contracts.multiTokenPurchase;

    if (!multiTokenAddress) {
      // Fallback to direct Registry deposit mode
      const nativeSymbol = getCurrencySymbol(state.config.network.chainId);
      if (loading) loading.textContent = `Using direct ${nativeSymbol} deposit to Registry.`;
      // Registry uses 1:1,000,000 rate (1 native token = 1M credits)
      creditTokenConfigs.clear();
      creditTokenConfigs.set(nativeSymbol, { creditsPerToken: 1000000n, bonusPercent: 0n, isActive: true });

      // Update dropdown with native token option
      if (tokenSelect) {
        tokenSelect.innerHTML = '';
        const option = document.createElement('option');
        option.value = nativeSymbol;
        option.textContent = `${nativeSymbol} (Native)`;
        tokenSelect.appendChild(option);
      }

      // Also update the amount symbol display
      const amountSymbol = document.getElementById('credit-amount-symbol');
      if (amountSymbol) amountSymbol.textContent = nativeSymbol;

      setupModalHandlers(state, [nativeSymbol]);
      return;
    }

    const multiToken = new Contract(
      getAddress(multiTokenAddress),
      MULTI_TOKEN_PURCHASE_ABI,
      state.wallet.provider
    );

    // Get supported tokens
    console.log('[Credits] Loading supported tokens...');
    let tokens: string[] = [];

    try {
      tokens = await multiToken.getSupportedTokens();
      console.log('[Credits] Supported tokens:', tokens);
    } catch (e) {
      // Fallback to POL only
      console.log('[Credits] getSupportedTokens failed, using POL only');
      tokens = ['POL'];
    }

    // Get config for each token
    creditTokenConfigs.clear();
    tokenSelect.innerHTML = '';

    for (const symbol of tokens) {
      try {
        const config = await multiToken.getTokenConfig(symbol);
        // config: [tokenAddress, creditsPerToken, bonusPercent, isActive, isStablecoin, purchases]
        if (config[3]) { // isActive
          creditTokenConfigs.set(symbol, {
            creditsPerToken: config[1],
            bonusPercent: config[2],
            isActive: config[3]
          });

          const bonusText = config[2] > 0n ? ` (+${config[2]}% bonus)` : '';
          const option = document.createElement('option');
          option.value = symbol;
          option.textContent = `${symbol}${bonusText}`;
          tokenSelect.appendChild(option);
        }
      } catch (e) {
        console.log(`[Credits] Failed to get config for ${symbol}:`, e);
      }
    }

    if (creditTokenConfigs.size === 0) {
      // No tokens available
      if (loading) loading.textContent = 'No payment tokens available.';
      return;
    }

    // Setup handlers and show tokens
    setupModalHandlers(state, Array.from(creditTokenConfigs.keys()));

  } catch (error) {
    console.error('[Credits] Error loading modal:', error);
    if (loading) loading.textContent = `Error: ${(error as Error).message}`;
  }
}

/**
 * Setup modal event handlers
 */
function setupModalHandlers(state: AppState, tokens: string[]): void {
  const loading = document.getElementById('credit-modal-loading');
  const tokensDiv = document.getElementById('credit-modal-tokens');
  const tokenSelect = document.getElementById('credit-token-select') as HTMLSelectElement;
  const amountInput = document.getElementById('credit-amount') as HTMLInputElement;
  const purchaseBtn = document.getElementById('credit-purchase-btn');

  // Hide loading, show tokens
  if (loading) loading.style.display = 'none';
  if (tokensDiv) tokensDiv.style.display = 'block';

  // Update preview when token or amount changes
  const updatePreview = () => updateCreditPreview(state);

  if (tokenSelect) {
    tokenSelect.onchange = updatePreview;
  }

  if (amountInput) {
    amountInput.oninput = updatePreview;
  }

  // Setup purchase button
  if (purchaseBtn) {
    purchaseBtn.onclick = () => executeCreditPurchase(state);
  }

  // Initial preview update
  updatePreview();
}

/**
 * Update credit preview based on selected token and amount
 */
function updateCreditPreview(state: AppState): void {
  const tokenSelect = document.getElementById('credit-token-select') as HTMLSelectElement;
  const amountInput = document.getElementById('credit-amount') as HTMLInputElement;
  const symbolSpan = document.getElementById('credit-amount-symbol');
  const rateSpan = document.getElementById('token-rate');
  const bonusSpan = document.getElementById('token-bonus');
  const baseSpan = document.getElementById('preview-base');
  const bonusCreditSpan = document.getElementById('preview-bonus');
  const totalSpan = document.getElementById('preview-total');

  if (!tokenSelect || !amountInput) return;

  const symbol = tokenSelect.value;
  const config = creditTokenConfigs.get(symbol);
  const amount = parseFloat(amountInput.value) || 0;

  // Update symbol display
  if (symbolSpan) symbolSpan.textContent = symbol;

  if (!config) {
    if (rateSpan) rateSpan.textContent = '--';
    if (bonusSpan) bonusSpan.textContent = '0%';
    if (baseSpan) baseSpan.textContent = '--';
    if (bonusCreditSpan) bonusCreditSpan.textContent = '--';
    if (totalSpan) totalSpan.textContent = '--';
    return;
  }

  // Calculate credits
  // creditsPerToken is credits per 1 token (in wei format, 18 decimals)
  // For POL: creditsPerToken might be 1000 (meaning 1000 credits per 1 POL)
  const creditsPerToken = Number(config.creditsPerToken);
  const bonusPercent = Number(config.bonusPercent);

  const baseCredits = Math.floor(amount * creditsPerToken);
  const bonusCredits = Math.floor(baseCredits * bonusPercent / 100);
  const totalCredits = baseCredits + bonusCredits;

  // Update display
  if (rateSpan) rateSpan.textContent = creditsPerToken.toLocaleString();
  if (bonusSpan) bonusSpan.textContent = `${bonusPercent}%`;
  if (baseSpan) baseSpan.textContent = baseCredits.toLocaleString();
  if (bonusCreditSpan) bonusCreditSpan.textContent = `+${bonusCredits.toLocaleString()}`;
  if (totalSpan) totalSpan.textContent = totalCredits.toLocaleString();
}

/**
 * Execute credit purchase with selected token
 */
async function executeCreditPurchase(state: AppState): Promise<void> {
  const tokenSelect = document.getElementById('credit-token-select') as HTMLSelectElement;
  const amountInput = document.getElementById('credit-amount') as HTMLInputElement;
  const purchaseBtn = document.getElementById('credit-purchase-btn') as HTMLButtonElement;
  const statusDiv = document.getElementById('credit-purchase-status');

  if (!tokenSelect || !amountInput) return;

  const symbol = tokenSelect.value;
  const amount = parseFloat(amountInput.value) || 0;

  if (amount <= 0) {
    if (statusDiv) {
      statusDiv.textContent = 'Please enter a valid amount';
      statusDiv.className = 'status-message error';
    }
    return;
  }

  // Disable button
  if (purchaseBtn) {
    purchaseBtn.disabled = true;
    purchaseBtn.textContent = 'Purchasing...';
  }

  if (statusDiv) {
    statusDiv.textContent = 'Sending transaction...';
    statusDiv.className = 'status-message pending';
  }

  try {
    const multiTokenAddress = state.config.contracts.multiTokenPurchase;
    const registryAddress = state.config.contracts.registry;
    const currencySymbol = getCurrencySymbol(state.config.network.chainId);

    // Use DYNAMIC gas estimation via GasProvider
    const gasProvider = new GasProvider(state.wallet.provider as any);
    const gas = await gasProvider.getGasSettings('standard');
    console.log(`[Credits] Current gas: ${gas.maxFeePerGasGwei.toFixed(2)} Gwei (base: ${(Number(gas.networkBaseFee) / 1e9).toFixed(2)} Gwei)`);

    const gasOptions = {
      gasLimit: 200000n,
      maxFeePerGas: gas.maxFeePerGas,
      maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
    };

    let tx;

    // Check if paying with native token (POL, JOC, ETH, etc.)
    const isNativeToken = symbol === currencySymbol || symbol === 'POL';

    // Check if we should use MultiToken or fallback to Registry.depositCredits
    if (multiTokenAddress && isNativeToken) {
      // Use MultiToken contract for native token purchases
      const multiToken = new Contract(
        getAddress(multiTokenAddress),
        MULTI_TOKEN_PURCHASE_ABI,
        state.wallet.signer as any
      );
      console.log(`[Credits] Purchasing with ${currencySymbol} via MultiToken:`, amount);
      tx = await multiToken.purchaseCreditsWithPOL(state.wallet.address, {
        ...gasOptions,
        value: parseEther(amount.toString()),
      });
    } else if (!multiTokenAddress && registryAddress && isNativeToken) {
      // Fallback: Use Registry.depositCredits directly
      console.log(`[Credits] Using Registry.depositCredits fallback (${currencySymbol}):`, amount);
      const registry = new Contract(
        getAddress(registryAddress),
        REGISTRY_ABI,
        state.wallet.signer as any
      );
      tx = await registry.depositCredits({
        ...gasOptions,
        value: parseEther(amount.toString()),
      });
    } else if (!isNativeToken && multiTokenAddress) {
      // ERC20 token purchase with approval flow
      console.log('[Credits] Purchasing with', symbol, ':', amount);

      const multiToken = new Contract(
        getAddress(multiTokenAddress),
        MULTI_TOKEN_PURCHASE_ABI,
        state.wallet.signer as any
      );

      // Get token config to find token address and decimals
      const [tokenAddress, creditsPerToken, bonusPercent, isActive] =
        await multiToken.getTokenConfig(symbol);

      if (!isActive) {
        throw new Error(`${symbol} is not currently active for purchases`);
      }

      console.log('[Credits] Token address:', tokenAddress);

      // Create ERC20 contract instance
      const tokenContract = new Contract(
        getAddress(tokenAddress),
        ERC20_ABI,
        state.wallet.signer as any
      );

      // Get token decimals (wRVT uses 18 decimals like most ERC20s)
      const decimals = await tokenContract.decimals();
      const tokenAmount = parseEther(amount.toString()); // Assuming 18 decimals

      console.log('[Credits] Token amount (wei):', tokenAmount.toString());

      // Check current allowance
      const currentAllowance = await tokenContract.allowance(
        state.wallet.address,
        multiTokenAddress
      );
      console.log('[Credits] Current allowance:', currentAllowance.toString());

      // If allowance is insufficient, approve first
      if (currentAllowance < tokenAmount) {
        if (statusDiv) {
          statusDiv.textContent = `Approving ${symbol}...`;
        }
        console.log('[Credits] Approving', symbol, 'for MultiToken contract');

        // Approve max uint256 for future transactions (common pattern)
        const maxApproval = 2n ** 256n - 1n;
        const approveTx = await tokenContract.approve(multiTokenAddress, maxApproval, {
          gasLimit: 100000n,
          maxFeePerGas: gas.maxFeePerGas,
          maxPriorityFeePerGas: gas.maxPriorityFeePerGas,
        });

        console.log('[Credits] Approval TX sent:', approveTx.hash);
        await approveTx.wait();
        console.log('[Credits] Approval confirmed');

        if (statusDiv) {
          statusDiv.textContent = `${symbol} approved. Purchasing credits...`;
        }
      }

      // Now purchase credits with the token
      tx = await multiToken.purchaseCreditsWithToken(
        symbol,
        tokenAmount,
        state.wallet.address,
        gasOptions
      );
    } else if (!isNativeToken) {
      throw new Error(`${symbol} purchases require MultiToken contract. Use ${currencySymbol} for now.`);
    } else {
      throw new Error('No credit purchase contract available');
    }

    console.log('[Credits] TX sent:', tx.hash);
    if (statusDiv) {
      statusDiv.textContent = `Transaction sent: ${tx.hash.slice(0, 10)}...`;
    }

    const receipt = await tx.wait();
    console.log('[Credits] ✅ Confirmed, block:', receipt.blockNumber);

    if (statusDiv) {
      statusDiv.textContent = `✅ Purchase complete! Block: ${receipt.blockNumber}`;
      statusDiv.className = 'status-message success';
    }

    // Update header credits
    const balanceWei = await state.wallet.provider.getBalance(state.wallet.address);
    state.wallet.balance = formatEther(balanceWei);
    await updateHeader(state);

    // Reset button
    if (purchaseBtn) {
      purchaseBtn.disabled = false;
      purchaseBtn.textContent = 'Purchase Credits';
    }

    // Close modal after delay
    setTimeout(() => {
      const modal = document.getElementById('credit-modal');
      if (modal) modal.style.display = 'none';
    }, 2000);

  } catch (error) {
    console.error('[Credits] Purchase error:', error);
    if (statusDiv) {
      statusDiv.textContent = `Error: ${(error as Error).message}`;
      statusDiv.className = 'status-message error';
    }
    if (purchaseBtn) {
      purchaseBtn.disabled = false;
      purchaseBtn.textContent = 'Purchase Credits';
    }
  }
}

