/**
 * Render secrets tab with split-pane layout
 */
async function renderSecrets(state: AppState): Promise<string> {
  const owned = await getOwnedSecrets();
  const shared = await getSharedSecrets();
  const total = owned.length + shared.length;

  console.log(`[Dashboard] renderSecrets: ${owned.length} owned, ${shared.length} shared`);

  // Collect unique types for filter dropdown
  const allSecrets = [...owned, ...shared];
  const typeSet = new Set<string>();
  for (const s of allSecrets) {
    const isArchive = s.name?.startsWith('Transcript Archive:');
    typeSet.add(isArchive ? 'TRANSCRIPT' : (s.type || 'SECRET').toUpperCase());
  }
  const types = Array.from(typeSet).sort();

  // Compact secret row renderer
  const renderSecretRow = (secret: StoredSecret & { isTeam?: boolean; sharedBy?: string }, isOwned: boolean) => {
    const isTeam = (secret as any).isTeam === true;
    const sharedBy = (secret as any).sharedBy;
    const isArchive = secret.name?.startsWith('Transcript Archive:');
    const isRecovered = secret.name?.startsWith('Recovered session');
    const icon = isArchive ? '📜' : (isOwned ? '🔐' : (isTeam ? '👥' : '🔗'));
    const teamBadge = isTeam ? '<span class="team-badge">Team</span>' : '';
    const archiveBadge = isArchive ? '<span class="archive-badge">Archive</span>' : '';
    const displayName = isArchive
      ? secret.name.replace('Transcript Archive: ', '').replace('claud-project--', '')
      : (secret.name || 'Unnamed');
    const secretType = isArchive ? 'TRANSCRIPT' : (secret.type || 'SECRET').toUpperCase();
    // Format date from mintBlockNumber or lastSyncedAt
    const ts = secret.lastSyncedAt || secret.lastAccessedAt || 0;
    const dateStr = ts > 0 ? new Date(ts).toLocaleDateString() : '';

    return `
      <div class="secret-row ${isTeam ? 'team-secret' : ''} ${isArchive ? 'archive-secret' : ''} ${isRecovered ? 'recovered-secret' : ''}"
           data-contract="${secret.contractAddress}"
           data-name="${(displayName || '').toLowerCase()}"
           data-type="${secretType}"
           data-date="${ts}"
           data-recovered="${isRecovered ? '1' : '0'}">
        <span class="secret-row-icon">${icon}</span>
        <div class="secret-row-info">
          <div class="secret-row-name">${displayName} ${teamBadge}${archiveBadge}</div>
          <div class="secret-row-meta">
            <span class="secret-row-type">${secretType}</span>
            ${dateStr ? `<span class="secret-row-date">${dateStr}</span>` : ''}
            ${isTeam && sharedBy ? `<span class="shared-by">from ${sharedBy.slice(0, 8)}...</span>` : ''}
            ${secret.ipfsHash ? '<span class="secret-row-ipfs">📦</span>' : ''}
          </div>
        </div>
      </div>
    `;
  };

  return `
    <div class="secrets-split-view">
      <!-- Left Panel: Secrets List -->
      <div class="secrets-list-panel">
        <div class="secrets-list-header">
          <h2>Secrets (${total})</h2>
          <button id="sync-secrets" class="secondary">⟳ Sync</button>
        </div>
        <div class="secrets-filter-bar">
          <input type="text" id="secrets-search" placeholder="Search by name..." class="secrets-search-input" />
          <select id="secrets-type-filter" class="secrets-filter-select">
            <option value="">All Types</option>
            ${types.map(t => `<option value="${t}">${t}</option>`).join('')}
          </select>
          <select id="secrets-sort" class="secrets-filter-select">
            <option value="date-desc">Newest First</option>
            <option value="date-asc">Oldest First</option>
            <option value="name-asc">Name A-Z</option>
            <option value="name-desc">Name Z-A</option>
          </select>
          <label class="secrets-checkbox-label">
            <input type="checkbox" id="secrets-hide-recovered" /> Hide Recovered
          </label>
        </div>
        <div class="secrets-list">
          ${total === 0 ? `
            <div class="empty-state" style="padding: 1.5rem;">
              <p>No secrets found.</p>
              <p style="color: #666; font-size: 0.8rem; margin-top: 0.5rem;">Click Sync to load from blockchain.</p>
            </div>
          ` : ''}

          ${owned.length > 0 ? `
            <div class="secrets-list-section" id="owned-section">
              <div class="secrets-list-section-header">Owned (<span id="owned-count">${owned.length}</span>)</div>
              ${owned.map(s => renderSecretRow(s, true)).join('')}
            </div>
          ` : ''}

          ${shared.length > 0 ? `
            <div class="secrets-list-section" id="shared-section">
              <div class="secrets-list-section-header">Shared (<span id="shared-count">${shared.length}</span>)</div>
              ${shared.map(s => renderSecretRow(s, false)).join('')}
            </div>
          ` : ''}
        </div>
      </div>

      <!-- Right Panel: Detail View -->
      <div class="secret-detail-panel" id="secret-detail-panel">
        <div class="detail-placeholder">
          <p>Select a secret from the list to view details</p>
        </div>
      </div>
    </div>
  `;
}

/**
 * Setup sync button handler
 */
function setupSyncButton(state: AppState) {
  const syncBtn = document.getElementById('sync-secrets');
  if (syncBtn) {
    syncBtn.addEventListener('click', async () => {
      syncBtn.textContent = 'Syncing...';
      syncBtn.setAttribute('disabled', 'true');
      try {
        // Invalidate cache when user explicitly clicks Sync
        teamScanCache = null;
        teamScanCacheTime = 0;

        const result = await syncFromChain(0);
        console.log('[Dashboard] Sync result:', result);

        // Fetch chain data for any shared secrets missing ipfsHash (for direct-keys)
        syncBtn.textContent = 'Fetching chain data...';
        const updated = await fetchMissingChainDataForSharedSecrets(state.chainReader);
        if (updated > 0) {
          console.log(`[Dashboard] Updated ${updated} shared secrets with chain data`);
        }

        // Auto-process fat key packages (decrypt master keys from fat package invites)
        syncBtn.textContent = 'Processing fat packages...';
        const fatPackagesProcessed = await autoProcessFatKeyPackages(state);
        if (fatPackagesProcessed > 0) {
          console.log(`[Dashboard] Decrypted ${fatPackagesProcessed} fat package keys`);
        }

        // Auto-process bootstrap sync packages (decrypt keys from rivet-to-rivet sync)
        syncBtn.textContent = 'Processing sync packages...';
        const syncPackagesProcessed = await autoProcessBootstrapSync(state);
        if (syncPackagesProcessed > 0) {
          console.log(`[Dashboard] Imported keys from ${syncPackagesProcessed} bootstrap sync packages`);
        }

        // Re-render secrets tab
        const content = document.getElementById('content');
        if (content) {
          content.innerHTML = await renderSecrets(state);
          setupSyncButton(state);
          setupSecretsFilterBar();
          setupSecretCardClickHandlers();
          // Enable compact mode for narrow displays (Word Add-in)
          if (LIGHT_MODE || isOfficeContext()) {
            const splitView = document.querySelector('.secrets-split-view');
            if (splitView) {
              splitView.classList.add('compact-mode');
            }
          }
        }
      } catch (error) {
        console.error('[Dashboard] Sync failed:', error);
        syncBtn.textContent = 'Sync Failed - Retry';
      } finally {
        syncBtn.removeAttribute('disabled');
      }
    });
  }
}

/**
 * Setup search, sort, and filter controls for the secrets list
 */
function setupSecretsFilterBar() {
  const searchInput = document.getElementById('secrets-search') as HTMLInputElement;
  const typeFilter = document.getElementById('secrets-type-filter') as HTMLSelectElement;
  const sortSelect = document.getElementById('secrets-sort') as HTMLSelectElement;
  const hideRecovered = document.getElementById('secrets-hide-recovered') as HTMLInputElement;

  if (!searchInput) return;

  const applyFilters = () => {
    const query = (searchInput.value || '').toLowerCase().trim();
    const typeVal = (typeFilter?.value || '').toUpperCase();
    const hideRec = hideRecovered?.checked || false;
    const sortVal = sortSelect?.value || 'date-desc';

    // Get all secret rows in each section
    const sections = document.querySelectorAll('.secrets-list-section');
    sections.forEach(section => {
      const rows = Array.from(section.querySelectorAll('.secret-row')) as HTMLElement[];
      let visibleCount = 0;

      // Filter
      rows.forEach(row => {
        const name = row.getAttribute('data-name') || '';
        const type = row.getAttribute('data-type') || '';
        const isRec = row.getAttribute('data-recovered') === '1';

        let show = true;
        if (query && !name.includes(query)) show = false;
        if (typeVal && type !== typeVal) show = false;
        if (hideRec && isRec) show = false;

        row.style.display = show ? '' : 'none';
        if (show) visibleCount++;
      });

      // Sort visible rows
      const visibleRows = rows.filter(r => r.style.display !== 'none');
      visibleRows.sort((a, b) => {
        if (sortVal === 'name-asc') {
          return (a.getAttribute('data-name') || '').localeCompare(b.getAttribute('data-name') || '');
        } else if (sortVal === 'name-desc') {
          return (b.getAttribute('data-name') || '').localeCompare(a.getAttribute('data-name') || '');
        } else if (sortVal === 'date-asc') {
          return Number(a.getAttribute('data-date') || 0) - Number(b.getAttribute('data-date') || 0);
        } else { // date-desc
          return Number(b.getAttribute('data-date') || 0) - Number(a.getAttribute('data-date') || 0);
        }
      });

      // Re-append in sorted order
      visibleRows.forEach(row => section.appendChild(row));

      // Update section count
      const countEl = section.querySelector('.secrets-list-section-header span');
      if (countEl) countEl.textContent = String(visibleCount);
    });
  };

  searchInput.addEventListener('input', applyFilters);
  typeFilter?.addEventListener('change', applyFilters);
  sortSelect?.addEventListener('change', applyFilters);
  hideRecovered?.addEventListener('change', applyFilters);
}

/**
 * Decrypt master key using ECDH (self-encryption pattern)
 *
 * When owner encrypts for themselves, they use their own public key.
 * To decrypt, compute shared secret with own private key and public key.
 *
 * @param encryptedPackage - { encrypted, iv, algorithm }
 * @param privateKey - Owner's private key (hex)
 * @param publicKey - Owner's public key (hex, uncompressed 0x04...)
 * @returns Decrypted master key (hex)
 */
async function decryptMasterKeyECDH(
  encryptedPackage: { encrypted: string; iv: string },
  privateKey: string,
  publicKey: string
): Promise<string> {
  console.log('[ECDH] Decrypting master key');
  console.log('[ECDH] Public key length:', publicKey.length);

  // Compute shared secret using ECDH
  const sharedSecret = ECDH.computeSharedSecret(privateKey, publicKey);
  console.log('[ECDH] Shared secret computed');

  // Derive AES key from shared secret
  const aesKey = await ECDH.deriveAESKey(sharedSecret);
  console.log('[ECDH] AES key derived');

  // Handle the "new format" where auth tag is included in encrypted data
  // Format: { encrypted, iv } - auth tag is last 16 bytes of encrypted
  const encrypted = encryptedPackage.encrypted.startsWith('0x')
    ? encryptedPackage.encrypted.slice(2)
    : encryptedPackage.encrypted;
  const iv = encryptedPackage.iv.startsWith('0x')
    ? encryptedPackage.iv.slice(2)
    : encryptedPackage.iv;

  // Convert hex to bytes
  const encryptedBytes = new Uint8Array(encrypted.length / 2);
  for (let i = 0; i < encrypted.length; i += 2) {
    encryptedBytes[i / 2] = parseInt(encrypted.substr(i, 2), 16);
  }
  const ivBytes = new Uint8Array(iv.length / 2);
  for (let i = 0; i < iv.length; i += 2) {
    ivBytes[i / 2] = parseInt(iv.substr(i, 2), 16);
  }

  // Decrypt using Web Crypto API
  // The encrypted data includes the auth tag (last 16 bytes)
  const plaintext = await crypto.subtle.decrypt(
    {
      name: 'AES-GCM',
      iv: ivBytes,
      tagLength: 128,
    },
    aesKey,
    encryptedBytes
  );

  // Convert decrypted bytes to hex string
  const plaintextBytes = new Uint8Array(plaintext);
  let hex = '0x';
  for (let i = 0; i < plaintextBytes.length; i++) {
    hex += plaintextBytes[i].toString(16).padStart(2, '0');
  }

  console.log('[ECDH] Master key decrypted successfully');
  return hex;
}

