  // Handler: Decrypt secret
  window.rootzMCP.onRequest('mcp:decryptSecret', async (params) => {
    const secretAddress = params.secretAddress as string;
    console.log('[MCP] Decrypt secret request:', secretAddress);

    if (!appState.wallet || !appState.config) {
      throw new Error('Wallet not connected');
    }

    if (!appState.storage) {
      throw new Error('Storage not initialized');
    }

    // Find secret in storage
    const secrets = await appState.storage.getAllSecrets();
    const secret = secrets.find(
      (s) => s.contractAddress?.toLowerCase() === secretAddress.toLowerCase()
    ) as (typeof secrets[0]) & { rawKeysData?: string; ipfsIV?: string };

    if (!secret) {
      throw new Error('Secret not found. Try syncing first.');
    }

    if (!secret.ipfsHash) {
      throw new Error('Secret missing IPFS hash');
    }

    // Decrypt master key from rawKeysData (same flow as dashboard decrypt button)
    let masterKey: string;
    const crypto = appState.crypto || new RootzCrypto();

    // Check localStorage for cached master key (from team sharing or prior decrypt)
    const cachedKeys = localStorage.getItem(`secret_keys_${secret.contractAddress}`) ||
                       localStorage.getItem(`secret_keys_${secret.contractAddress.toLowerCase()}`);
    if (cachedKeys) {
      try {
        const cached = JSON.parse(cachedKeys);
        if (cached.masterKey) {
          masterKey = cached.masterKey;
          console.log('[MCP] Using cached master key');
        }
      } catch {}
    }

    // If no cached key, decrypt from rawKeysData
    if (!masterKey!) {
      if (!secret.rawKeysData) {
        throw new Error('Secret missing encryption data (no rawKeysData). Try syncing secrets first.');
      }

      const keysData = JSON.parse(secret.rawKeysData);
      console.log('[MCP] Decrypting from rawKeysData, keys:', Object.keys(keysData));

      const privateKey = appState.wallet.privateKey;
      if (!privateKey) {
        throw new Error('Wallet private key not available for decryption');
      }
      const walletAddress = appState.wallet.address;

      // V5 KeyVault format with ECDH (primary path for V6-created secrets)
      if (keysData.encryptedMasterKey && (keysData.encryptedMasterKey.ephemeralPub || keysData.isMultiDevice)) {
        console.log('[MCP] Using V5 ECDH decryption');
        masterKey = await ECDH.decryptFromV5KeyVaultData(keysData, walletAddress, privateKey);
      } else if (keysData.encryptedMasterKey) {
        // Legacy signature-based or old ECDH
        const encryptedMasterKey = keysData.encryptedMasterKey;
        const hasKeyDerivation = encryptedMasterKey.keyDerivation === 'signature-storage-key';
        const hasEncryptedFor = !!encryptedMasterKey.encryptedFor;

        if (hasKeyDerivation || hasEncryptedFor) {
          console.log('[MCP] Using signature-based decryption (legacy)');
          const package_ = {
            version: '1.0.0' as const,
            algorithm: 'AES-256-GCM' as const,
            keyDerivation: 'signature-storage-key' as const,
            encryptedKey: encryptedMasterKey.encrypted,
            iv: encryptedMasterKey.iv,
            encryptedFor: encryptedMasterKey.encryptedFor || walletAddress,
            timestamp: keysData.metadata?.createdAt || Date.now(),
            extensions: keysData.metadata || {},
          };
          masterKey = await crypto.decryptMasterKeyForOwner(package_, appState.wallet.signer as any);
        } else {
          // Default: try signature-based
          console.log('[MCP] Using signature-based decryption (default)');
          masterKey = await crypto.decryptMasterKeyForOwner(encryptedMasterKey, appState.wallet.signer as any);
        }
      } else {
        throw new Error('No encryptedMasterKey found in rawKeysData');
      }

      // Cache for future use
      localStorage.setItem(`secret_keys_${secret.contractAddress.toLowerCase()}`, JSON.stringify({
        masterKey,
        decryptedAt: Date.now(),
      }));
    }

    // Decrypt IPFS hash
    const ipfsHashData = { encrypted: secret.ipfsHash, iv: secret.ipfsIV || '' };
    const ipfsHash = await crypto.decryptIPFSHash(ipfsHashData, masterKey);
    console.log('[MCP] Decrypted IPFS hash:', ipfsHash);

    // Fetch and decrypt content from IPFS
    const ipfsUrl = `https://gateway.pinata.cloud/ipfs/${ipfsHash}`;
    const response = await fetch(ipfsUrl);

    if (!response.ok) {
      throw new Error(`Failed to fetch from IPFS: ${response.status}`);
    }

    const ipfsData = await response.json();
    let decrypted: string;

    if (ipfsData.encryptedContent && ipfsData.contentIV) {
      // Standard V6 format
      const encrypted = { encrypted: ipfsData.encryptedContent, iv: ipfsData.contentIV };
      decrypted = await crypto.decryptContent(encrypted, masterKey);
    } else if (ipfsData.encrypted) {
      // Legacy format
      decrypted = await crypto.decryptContent(ipfsData.encrypted, masterKey);
    } else {
      // Not encrypted or unknown format
      decrypted = JSON.stringify(ipfsData, null, 2);
    }

    return {
      success: true,
      secretAddress,
      name: secret.name,
      content: decrypted,
      decryptedAt: new Date().toISOString(),
    };
  });

  // Handler: Generate share link (master key encoded in URL)
  // Works with or without the secret being synced to localStorage —
  // falls back to chain query + ECDH decryption using ChainReader and @rootz/crypto
  window.rootzMCP.onRequest('mcp:getShareLink', async (params) => {
    const secretAddress = params.secretAddress as string;
    console.log('[MCP] Share link request:', secretAddress);

    if (!appState.wallet || !appState.config) {
      throw new Error('Wallet not connected');
    }

    // Helper: encode master key hex → base64url for URL
    function masterKeyToBase64url(masterKey: string): string {
      const keyBytes = new Uint8Array(masterKey.replace(/^0x/, '').match(/.{1,2}/g)!.map((b: string) => parseInt(b, 16)));
      const base64 = btoa(String.fromCharCode(...keyBytes));
      return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }

    // --- Fast path: try localStorage first (instant if secret is synced) ---
    let secretName = 'Unknown';
    let masterKey: string | null = null;

    if (appState.storage) {
      const secrets = await appState.storage.getAllSecrets();
      const secret = secrets.find((s: any) =>
        s.contractAddress?.toLowerCase() === secretAddress.toLowerCase()
      );

      if (secret) {
        secretName = secret.name || secretName;

        // Check if public secret
        if (secret.rawKeysData) {
          try {
            const keysData = JSON.parse(secret.rawKeysData);
            if (keysData.isPublic) {
              return {
                success: true,
                secretAddress,
                name: secretName,
                url: `https://rootz.global/public/${secretAddress}`,
                isPublic: true,
                createdAt: new Date().toISOString(),
              };
            }
          } catch { /* not JSON, continue */ }
        }

        masterKey = await getMasterKeyForSecret(secret);
      }
    }

    // --- Chain fallback: query KeyVaultCreated event directly via ChainReader ---
    if (!masterKey) {
      console.log('[MCP] Secret not in storage or key unavailable, querying chain...');

      if (!appState.chainReader) {
        throw new Error('ChainReader not initialized. Cannot query chain for secret.');
      }

      const event = await appState.chainReader.getKeyVaultCreatedEvent(
        secretAddress,
        appState.chainName
      );

      if (!event) {
        throw new Error(`Secret not found on chain: ${secretAddress}. Verify the address is correct.`);
      }

      // Parse the on-chain V5KeyVaultData
      let keysData: any;
      try {
        keysData = JSON.parse(event.encryptedKeysData);
      } catch {
        throw new Error('Could not parse on-chain key vault data');
      }

      // Check if public
      if (keysData.isPublic) {
        secretName = keysData.metadata?.secretName || secretName;
        return {
          success: true,
          secretAddress,
          name: secretName,
          url: `https://rootz.global/public/${secretAddress}`,
          isPublic: true,
          createdAt: new Date().toISOString(),
        };
      }

      // ECDH decrypt master key using wallet's private key
      const privateKey = appState.wallet.privateKey;
      if (!privateKey) {
        throw new Error('Wallet private key not available for ECDH decryption');
      }
      const walletAddress = await appState.wallet.signer.getAddress();

      try {
        masterKey = await ECDH.decryptFromV5KeyVaultData(keysData, walletAddress, privateKey);
        console.log('[MCP] Master key decrypted from chain data');
      } catch (ecdhError) {
        throw new Error('Could not decrypt master key. Make sure you are an owner of this secret.');
      }

      secretName = keysData.metadata?.secretName || secretName;
    }

    if (!masterKey) {
      throw new Error('Could not decrypt master key.');
    }

    const base64url = masterKeyToBase64url(masterKey);
    const shareUrl = `https://rootz.global/s/${secretAddress}?k=${base64url}`;
    console.log('[MCP] Share link generated:', shareUrl.substring(0, 60) + '...');

    return {
      success: true,
      secretAddress,
      name: secretName,
      url: shareUrl,
      isPublic: false,
      createdAt: new Date().toISOString(),
    };
  });

