  // Handler: Create note on secret
  window.rootzMCP.onRequest('mcp:createNote', async (params) => {
    const secretAddress = params.secretAddress as string;
    const content = params.content as string;
    console.log('[MCP] Create note request for:', secretAddress, 'content length:', content?.length);

    // Validate inputs
    if (!secretAddress || !content) {
      return {
        success: false,
        message: 'secretAddress and content are required',
        secretAddress,
      };
    }

    if (!app || !appState.storage) {
      return {
        success: false,
        message: 'App not initialized or storage not available',
        secretAddress,
      };
    }

    try {
      // Get the secret from storage
      const secret = await getSecret(secretAddress);
      if (!secret) {
        return {
          success: false,
          message: `Secret not found: ${secretAddress}`,
          secretAddress,
        };
      }

      // Get KeyVault for this secret - first try local storage, then query chain
      let storedKv = await appState.storage.keyVaults.getPrimary(secretAddress);

      // If not found locally, try to query from chain
      if (!storedKv) {
        console.log('[MCP] KeyVault not in local storage, querying chain for:', secretAddress);
        try {
          // Create temporary NoteManager to query KeyVault
          const tempNoteManager = new NoteManager(app.wallet.signer as any, {
            chainId: app.config.network.chainId,
            chainName: app.chainName,
            rpcUrl: app.config.network.rpc,
            chainReader: app.chainReader,
          });

          // Query KeyVaultCreated event from chain
          // If keyVaultBlock is known, query by block; otherwise use chainReader to find all events
          let kvEvent = null;
          if (secret.keyVaultBlock) {
            kvEvent = await tempNoteManager.queryKeyVaultCreatedEvent(secretAddress, secret.keyVaultBlock);
          } else if (app.chainReader) {
            console.log('[MCP] No keyVaultBlock, using chainReader to find KeyVault events...');
            const kvEvents = await app.chainReader.getKeyVaultCreatedEvents(secretAddress, app.chainName);
            kvEvent = kvEvents[0] || null;
          }

          if (kvEvent) {
            console.log('[MCP] Found KeyVault on chain at block:', kvEvent.blockNumber);
            // Construct a storedKv object from chain data
            storedKv = {
              keyVaultId: `kv_${secretAddress.toLowerCase()}_primary`,
              chainId: app.config.network.chainId,
              secretContract: secretAddress.toLowerCase(),
              blockNumber: kvEvent.blockNumber,
              creator: kvEvent.creator,
              encryptedKvKey: kvEvent.encryptedKeysData,
              kvKeyIv: '',
              schema: kvEvent.schemaDefinition,
              isPrimary: true,
              createdAt: new Date().toISOString(),
            };

            // Save to local storage for future use
            try {
              await appState.storage.keyVaults.put(storedKv);
              console.log('[MCP] Saved KeyVault to local storage');
            } catch (saveErr) {
              console.warn('[MCP] Failed to save KeyVault to local storage:', saveErr);
              // Continue anyway - we have the data
            }

            // Also repair the secret record if it's missing rawKeysData
            if (!secret.rawKeysData && kvEvent.encryptedKeysData) {
              console.log('[MCP] Repairing secret record with missing rawKeysData');
              try {
                await appState.storage.putSecret({
                  ...secret,
                  rawKeysData: kvEvent.encryptedKeysData,
                  keyVaultBlock: kvEvent.blockNumber,
                } as any);
                // Update the local secret reference for this request
                secret.rawKeysData = kvEvent.encryptedKeysData;
                secret.keyVaultBlock = kvEvent.blockNumber;
                console.log('[MCP] Secret record repaired');
              } catch (repairErr) {
                console.warn('[MCP] Failed to repair secret record:', repairErr);
              }
            }
          }
        } catch (queryErr) {
          console.error('[MCP] Failed to query KeyVault from chain:', queryErr);
        }
      }

      if (!storedKv) {
        return {
          success: false,
          message: `KeyVault not found for secret: ${secretAddress}. Try refreshing secrets or checking chain connection.`,
          secretAddress,
        };
      }

      // Check if this is a public secret (no encryption needed)
      // encryptedKvKey may be UTF-8 JSON or hex-encoded bytes (0x...)
      let isPublicSecret = false;
      try {
        let keysDataStr = storedKv.encryptedKvKey;
        if (keysDataStr.startsWith('0x')) {
          const hexData = keysDataStr.slice(2);
          const bytes = new Uint8Array(hexData.match(/.{1,2}/g)!.map((byte: string) => parseInt(byte, 16)));
          keysDataStr = new TextDecoder().decode(bytes);
        }
        const keysData = JSON.parse(keysDataStr);
        isPublicSecret = keysData.isPublic === true;
        console.log('[MCP] Public secret check:', { isPublic: keysData.isPublic, hasKvKey: !!keysData.kvKey });
      } catch (parseErr) {
        console.log('[MCP] encryptedKvKey not JSON:', (parseErr as Error).message, 'first 80 chars:', storedKv.encryptedKvKey?.slice(0, 80));
        // Not JSON - not a public secret
      }

      if (isPublicSecret) {
        // PUBLIC NOTE PATH: Write plaintext note (no encryption)
        console.log('[MCP] Public secret detected, writing plaintext note');

        const author = await app.wallet.signer.getAddress();
        const notePayload = JSON.stringify({
          type: 'public-note',
          content,
          author,
          timestamp: Date.now(),
          createdAt: new Date().toISOString(),
        });

        // Auto-fund and write
        const registryAddress = app?.config.contracts.registry;
        const noteManager = createWriteNoteManager(app as any, registryAddress || '');

        const estimatedDataSize = notePayload.length + 100;
        const writeResult = await noteManager.ensureCanWrite(secretAddress, storedKv.blockNumber, estimatedDataSize);

        if (!writeResult.canWrite && !writeResult.fundingPerformed) {
          return {
            success: false,
            message: `Cannot write public note: ${writeResult.reason}`,
            secretAddress,
          };
        }

        // Write plaintext directly via contract writeData
        const { Contract: EthersContract, toUtf8Bytes, ZeroHash: ethersZeroHash } = await import('ethers');
        const secretContract = new EthersContract(secretAddress, [
          'function writeData(uint256 keyVaultBlock, bytes data, uint256 expiresAt, uint8 v, bytes32 r, bytes32 s) external',
        ], app.wallet.signer as any);

        const tx = await secretContract.writeData(
          storedKv.blockNumber,
          toUtf8Bytes(notePayload),
          0, // no expiry
          0, ethersZeroHash, ethersZeroHash, // PATH 1: direct owner
          { gasLimit: 500_000 }
        );
        const receipt = await tx.wait();

        // Update note count
        storedKv.noteCount = (storedKv.noteCount || 0) + 1;
        await appState.storage.keyVaults?.put(storedKv);

        return {
          success: true,
          message: 'Public note created successfully',
          secretAddress,
          txHash: receipt.hash,
          blockNumber: receipt.blockNumber,
          noteCount: storedKv.noteCount,
          isPublic: true,
        };
      }

      // Get master key
      const masterKey = await getMasterKeyForSecret(secret);
      if (!masterKey) {
        return {
          success: false,
          message: 'Could not decrypt master key. Make sure you are an owner of this secret.',
          secretAddress,
        };
      }

      // Decrypt KV key - handle both formats
      let kvKey: Uint8Array;
      try {
        const keysDataJson = JSON.parse(storedKv.encryptedKvKey);
        if (keysDataJson.kvKey) {
          // Notes system format
          kvKey = await NoteCrypto.decryptKvKey(keysDataJson.kvKey, hexToBytes(masterKey));
        } else {
          // Secret-created KeyVault: use master key as KV key
          kvKey = hexToBytes(masterKey);
        }
      } catch {
        // Legacy/secret format: use master key as KV key
        kvKey = hexToBytes(masterKey);
      }

      // IPFS upload for content (> 1KB)
      // Most archive data should go to IPFS, only small metadata on-chain
      const IPFS_SIZE_THRESHOLD = 1024; // 1KB
      let noteContent = content;
      let noteFiles: NoteFileInput[] | undefined;

      if (content.length > IPFS_SIZE_THRESHOLD) {
        console.log(`[MCP] Content is large (${content.length} bytes), uploading to IPFS...`);

        try {
          // Convert content to Uint8Array for encryption
          const contentBytes = new TextEncoder().encode(content);

          // Encrypt content with KV key
          console.log('[MCP] Encrypting content for IPFS...');
          const encrypted = await NoteCrypto.encryptFileContent(contentBytes, kvKey);

          // Create blob for upload
          const uploadBlob = new Blob([encrypted.encrypted], { type: 'application/octet-stream' });

          // Upload encrypted content to IPFS
          console.log('[MCP] Uploading encrypted content to IPFS...');
          const ipfsHash = await uploadFileToIPFS(uploadBlob, app.config, 'chunk.enc');
          console.log('[MCP] Content uploaded to IPFS:', ipfsHash);

          // Compute content hash for verification
          const hashBuffer = await crypto.subtle.digest('SHA-256', contentBytes);
          const hashArray = Array.from(new Uint8Array(hashBuffer));
          const contentHash = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

          // Create file reference (IPFS hash will be encrypted in note)
          noteFiles = [{
            ipfsHash,
            filename: 'chunk.enc',
            contentType: 'application/octet-stream',
            size: content.length,
            contentHash,
            encrypted: true,
            encryptionIv: encrypted.iv,
            description: 'Encrypted transcript archive chunk',
          }];

          // Replace note content with small metadata reference
          noteContent = JSON.stringify({
            type: 'ipfs-chunk',
            originalSize: content.length,
            description: 'Transcript archive chunk stored on IPFS for efficiency',
          });

          console.log(`[MCP] Content moved to IPFS, note size reduced from ${content.length} to ${noteContent.length} bytes`);
        } catch (ipfsErr) {
          console.error('[MCP] IPFS upload failed:', ipfsErr);
          // Don't fall back to on-chain - fail gracefully for retry
          return {
            success: false,
            message: `IPFS upload failed: ${ipfsErr instanceof Error ? ipfsErr.message : String(ipfsErr)}. Content too large for on-chain storage (${content.length} bytes). Will retry later.`,
            secretAddress,
            retryable: true,
            contentSize: content.length,
          };
        }
      }

      // Create NoteManager with auto-funding using factory
      const registryAddress = app?.config.contracts.registry;
      const noteManager = createWriteNoteManager(app as any, registryAddress || '');

      // Use ensureCanWrite() for comprehensive auto-funding (V7 vault + owner credits)
      const estimatedDataSize = noteContent.length + (noteFiles ? 300 : 100);
      const writeResult = await noteManager.ensureCanWrite(secretAddress, storedKv.blockNumber, estimatedDataSize);

      console.log('[MCP] ensureCanWrite result:', {
        canWrite: writeResult.canWrite,
        fundingPerformed: writeResult.fundingPerformed,
        vaultFunded: writeResult.vaultFunded,
        ownerFunded: writeResult.ownerFunded,
        needsPOLPurchase: writeResult.needsPOLPurchase,
      });

      // If still can't write and POL purchase is needed, try that (app-level concern)
      if (!writeResult.canWrite && writeResult.needsPOLPurchase && registryAddress) {
        console.log('[MCP] Attempting POL credit purchase...');
        try {
          const estimatedCost = writeResult.creditStatus?.ownerCredits
            ? BigInt(estimatedDataSize * 10) // Rough estimate
            : 25000n;
          const polNeeded = Number(estimatedCost) / 1_000_000 + 0.01;
          const walletBalance = await app?.wallet.provider.getBalance(await app?.wallet.signer.getAddress());
          const polBalance = walletBalance ? Number(walletBalance) / 1e18 : 0;

          if (polBalance >= polNeeded) {
            console.log(`[MCP] Auto-purchasing ${polNeeded.toFixed(4)} POL worth of credits...`);
            const registry = new Contract(registryAddress, REGISTRY_ABI, app?.wallet.signer as any);
            const tx = await registry.depositCredits({ value: parseEther(polNeeded.toFixed(6)) });
            await tx.wait();
            console.log('[MCP] POL purchase complete, re-checking...');

            // Re-run ensureCanWrite after POL purchase
            const retryResult = await noteManager.ensureCanWrite(secretAddress, storedKv.blockNumber, estimatedDataSize);
            if (!retryResult.canWrite) {
              return {
                success: false,
                message: `Cannot write after POL purchase: ${retryResult.reason}`,
                secretAddress,
              };
            }
          }
        } catch (polErr) {
          console.error('[MCP] POL purchase failed:', polErr);
        }
      }

      // Final check - if still can't write, fail
      if (!writeResult.canWrite && !writeResult.fundingPerformed) {
        console.error('[MCP] Cannot write note:', writeResult.reason);
        return {
          success: false,
          message: `Cannot write: ${writeResult.reason}. Auto-funding was attempted but insufficient credits available.`,
          secretAddress,
          creditInfo: writeResult.creditStatus ? {
            registryBalance: writeResult.creditStatus.registryBalance.toString(),
            ownerCredits: writeResult.creditStatus.ownerCredits.toString(),
            vaultBalance: writeResult.creditStatus.vaultBalance.toString(),
          } : undefined,
        };
      }

      console.log('[MCP] Writing note to KeyVault block:', storedKv.blockNumber);
      if (noteFiles) {
        console.log('[MCP] Including IPFS file reference, original size:', content.length);
      }

      // Write note (with IPFS file reference if content was large)
      const result = await noteManager.writeNote({
        secretAddress,
        kvBlock: storedKv.blockNumber,
        content: noteContent,
        kvKey,
        files: noteFiles,
      });

      console.log('[MCP] Note written successfully, tx:', result.txHash);

      // Update note count
      storedKv.noteCount = (storedKv.noteCount || 0) + 1;
      await appState.storage.keyVaults?.put(storedKv);

      return {
        success: true,
        message: noteFiles
          ? `Note created with IPFS attachment (${content.length} bytes → ${noteContent.length} on-chain)`
          : 'Note created successfully',
        secretAddress,
        txHash: result.txHash,
        blockNumber: result.blockNumber,
        noteCount: storedKv.noteCount,
        usedIpfs: !!noteFiles,
        originalSize: content.length,
        onChainSize: noteContent.length,
      };
    } catch (error) {
      console.error('[MCP] Error creating note:', error);
      return {
        success: false,
        message: `Error creating note: ${error instanceof Error ? error.message : String(error)}`,
        secretAddress,
      };
    }
  });

  // Handler: Fund credits to a secret (bulk purchase for archive push)
  window.rootzMCP.onRequest('mcp:fundCredits', async (params) => {
    const secretAddress = params.secretAddress as string;
    const requestedAmount = params.amount as number || 25000;
    const minAmount = params.minAmount as number || 25000;
    console.log('[MCP] Fund credits request for:', secretAddress, 'amount:', requestedAmount);

    if (!secretAddress) {
      return { success: false, message: 'secretAddress is required' };
    }

    if (!app || !appState.storage) {
      return { success: false, message: 'App not initialized' };
    }

    try {
      const registryAddress = app.config.contracts.registry;
      if (!registryAddress) {
        return { success: false, message: 'No registry configured' };
      }

      // Get secret and KeyVault
      const secret = await getSecret(secretAddress);
      if (!secret) {
        return { success: false, message: 'Secret not found' };
      }

      // Create NoteManager early - needed for chain queries
      // V7: Include registryAddress for auto-funding support
      const noteManager = new NoteManager(app.wallet.signer as any, {
        chainId: app.config.network.chainId,
        chainName: app.chainName,
        rpcUrl: app.config.network.rpc,
        chainReader: app.chainReader,
        registryAddress: registryAddress,
        autoFundEnabled: true,
        autoFundAmount: 25000, // 25K credits default
      });

      // Get KeyVault - try local storage first, then query chain
      let storedKv = await appState.storage.keyVaults.getPrimary(secretAddress);
      if (!storedKv) {
        console.log('[MCP] KeyVault not in local storage, querying chain for funding...');
        try {
          const kvEvent = await noteManager.queryKeyVaultCreatedEvent(secretAddress, secret.keyVaultBlock);
          if (kvEvent) {
            storedKv = {
              keyVaultId: `kv_${secretAddress.toLowerCase()}_primary`,
              chainId: app.config.network.chainId,
              secretContract: secretAddress.toLowerCase(),
              blockNumber: kvEvent.blockNumber,
              creator: kvEvent.creator,
              encryptedKvKey: kvEvent.encryptedKeysData,
              kvKeyIv: '',
              schema: kvEvent.schemaDefinition,
              isPrimary: true,
              createdAt: new Date().toISOString(),
            };
            await appState.storage.keyVaults.put(storedKv);
            console.log('[MCP] Found and cached KeyVault at block:', kvEvent.blockNumber);
          }
        } catch (kvErr) {
          console.error('[MCP] Failed to query KeyVault:', kvErr);
        }
      }

      if (!storedKv) {
        return { success: false, message: 'KeyVault not found (checked local storage and chain)' };
      }

      console.log('[MCP] Using KeyVault block:', storedKv.blockNumber, 'for secret:', secretAddress);
      const creditStatus = await noteManager.getCreditStatus(secretAddress, storedKv.blockNumber, registryAddress);
      console.log('[MCP] Current credit status:', {
        ownerCredits: creditStatus.ownerCredits.toString(),
        vaultBalance: creditStatus.vaultBalance.toString(),
        registryBalance: creditStatus.registryBalance.toString(),
        kvBlock: storedKv.blockNumber,
      });

      // Calculate how much to fund
      const currentCredits = creditStatus.ownerCredits;
      const amountToFund = BigInt(Math.max(requestedAmount, minAmount));

      // V7: Check vault balance FIRST - even if owner credits are sufficient, vault may need funding
      const vaultBalance = creditStatus.vaultBalance;
      const needVaultFunding = vaultBalance < 0n;
      const vaultFundingNeeded = needVaultFunding ? -vaultBalance + 1000n : 0n; // Bring to +1000 buffer

      if (needVaultFunding) {
        console.log('[MCP] Vault balance is negative:', vaultBalance.toString(), '- need to fund', vaultFundingNeeded.toString(), 'to vault');
      }

      const ownerCreditsOk = currentCredits >= amountToFund;
      const creditsNeeded = ownerCreditsOk ? 0n : amountToFund - currentCredits;

      // If owner credits are OK AND vault doesn't need funding, return early
      if (ownerCreditsOk && !needVaultFunding) {
        console.log('[MCP] Already have sufficient credits and vault balance is OK:', currentCredits.toString());
        return {
          success: true,
          message: 'Sufficient credits already available',
          currentCredits: Number(currentCredits),
          vaultBalance: Number(vaultBalance),
          funded: 0,
        };
      }

      console.log('[MCP] Funding needed - owner credits:', creditsNeeded.toString(), 'vault balance:', vaultFundingNeeded.toString());

      const totalCreditsNeeded = creditsNeeded + vaultFundingNeeded;

      // Try to fund from Registry first
      if (creditStatus.registryBalance >= totalCreditsNeeded) {
        console.log('[MCP] Funding from Registry... (owner:', creditsNeeded.toString(), ', vault:', vaultFundingNeeded.toString(), ')');
        try {
          // Fund owner credits only if needed
          if (creditsNeeded > 0n) {
            await noteManager.fundSecretCredits(registryAddress, secretAddress, Number(creditsNeeded));
            console.log('[MCP] Funded', creditsNeeded.toString(), 'owner credits from Registry');
          }

          // V7: Fund vault balance if needed (critical for writes to succeed!)
          if (needVaultFunding && vaultFundingNeeded > 0n) {
            console.log('[MCP] Funding vault balance with', vaultFundingNeeded.toString(), 'credits at kvBlock:', storedKv.blockNumber);
            const registryV7 = new Contract(registryAddress, REGISTRY_V7_ABI, app.wallet.signer as any);
            const tx = await registryV7.fundVaultBalance(secretAddress, storedKv.blockNumber, vaultFundingNeeded);
            console.log('[MCP] Vault funding tx submitted:', tx.hash);
            await tx.wait();
            console.log('[MCP] Funded vault balance successfully!');
          }

          return {
            success: true,
            message: `Funded ${creditsNeeded} owner credits${needVaultFunding ? ` + ${vaultFundingNeeded} vault balance` : ''} from Registry`,
            funded: Number(creditsNeeded),
            vaultFunded: Number(vaultFundingNeeded),
            source: 'registry',
          };
        } catch (fundErr) {
          console.error('[MCP] Registry/vault funding failed:', fundErr);
          return {
            success: false,
            message: `Funding failed: ${fundErr instanceof Error ? fundErr.message : String(fundErr)}`,
            error: String(fundErr),
          };
        }
      }

      // Try to buy with POL (include vault funding in total)
      const polNeeded = Number(totalCreditsNeeded) / 1_000_000 + 0.05; // 1M credits = 1 POL, add buffer
      const walletBalance = await app.wallet.provider.getBalance(await app.wallet.signer.getAddress());
      const polBalance = Number(walletBalance) / 1e18;

      console.log('[MCP] POL balance:', polBalance.toFixed(4), 'need:', polNeeded.toFixed(4));

      if (polBalance >= polNeeded) {
        console.log('[MCP] Purchasing credits with POL...');
        try {
          const registry = new Contract(registryAddress, REGISTRY_ABI, app.wallet.signer as any);
          const tx = await registry.depositCredits({ value: parseEther(polNeeded.toFixed(6)) });
          await tx.wait();
          console.log('[MCP] Purchased credits, now funding secret...');
          await noteManager.fundSecretCredits(registryAddress, secretAddress, Number(creditsNeeded));
          console.log('[MCP] Funded', creditsNeeded.toString(), 'owner credits via POL purchase');

          // V7: Also fund vault balance if needed
          if (needVaultFunding && vaultFundingNeeded > 0n) {
            console.log('[MCP] Funding vault balance with', vaultFundingNeeded.toString(), 'credits...');
            try {
              const registryV7 = new Contract(registryAddress, REGISTRY_V7_ABI, app.wallet.signer as any);
              const vaultTx = await registryV7.fundVaultBalance(secretAddress, storedKv.blockNumber, vaultFundingNeeded);
              await vaultTx.wait();
              console.log('[MCP] Funded vault balance successfully');
            } catch (vaultErr) {
              console.warn('[MCP] Vault balance funding failed (may not be V7 contract):', vaultErr);
              // Continue - owner credits were funded, might still work
            }
          }

          return {
            success: true,
            message: `Purchased and funded ${creditsNeeded} owner credits${needVaultFunding ? ` + ${vaultFundingNeeded} vault balance` : ''} (${polNeeded.toFixed(4)} POL)`,
            funded: Number(creditsNeeded),
            vaultFunded: Number(vaultFundingNeeded),
            polSpent: polNeeded,
            source: 'pol',
          };
        } catch (buyErr) {
          console.error('[MCP] POL purchase failed:', buyErr);
          return {
            success: false,
            message: `POL purchase failed: ${buyErr instanceof Error ? buyErr.message : String(buyErr)}`,
            polNeeded,
            polBalance,
          };
        }
      }

      return {
        success: false,
        message: `Insufficient funds. Need ${creditsNeeded} credits (${polNeeded.toFixed(4)} POL) but only have ${polBalance.toFixed(4)} POL`,
        creditsNeeded: Number(creditsNeeded),
        polNeeded,
        polBalance,
      };
    } catch (error) {
      console.error('[MCP] Error funding credits:', error);
      return {
        success: false,
        message: `Error: ${error instanceof Error ? error.message : String(error)}`,
      };
    }
  });

