/**
 * Rootz V6 Dashboard - Configuration
 *
 * Loads config from config.json (no localStorage).
 * Fresh config on every page load.
 * Supports multi-network configuration (V4, V5, JOC, etc.)
 *
 * In Electron: Uses IPC to get config from main process
 * In Browser: Uses fetch to load config.json
 */

// Type declarations for Electron preload APIs
declare global {
  interface Window {
    // V6 component APIs (via IPC)
    rootzV6?: {
      config: {
        get: () => Promise<AppConfig | null>;
        getNetworks: () => Promise<Array<{ key: string; name: string; chainId: number; contractSet: string }>>;
        switchNetwork: (networkKey: string) => Promise<{ success: boolean; network?: string; error?: string }>;
      };
    };

    // Desktop-specific APIs
    rootzDesktop?: {
      getVersion: () => string;
      getPlatform: () => string;
    };

    // MCP API bridge for Claude Code integration (desktop only)
    rootzMCP?: {
      onRequest: (
        channel: string,
        handler: (params: Record<string, unknown>) => Promise<unknown>
      ) => void;
      respond: (requestId: number, result: unknown, error?: string | null) => void;
    };

    // TPM Hardware Security APIs (desktop only)
    tpm?: {
      isAvailable: () => Promise<{ available: boolean; reason?: string }>;
      ensureKey: () => Promise<{ success: boolean; exists?: boolean; created?: boolean; error?: string }>;
      sign: (dataHex: string) => Promise<{ success: boolean; signature?: string; error?: string }>;
      deriveKey: (entropy: string, salt: string) => Promise<{
        success: boolean;
        entropy?: string;
        tpmSignature?: string;
        error?: string;
      }>;
      getPCR0: () => Promise<{ success: boolean; pcr0?: string; error?: string }>;
      getSecureBootStatus: () => Promise<{
        success: boolean;
        enabled?: boolean;
        error?: string;
      }>;
    };
  }
}

export interface ContractsConfig {
  factory: string | null;
  registry: string | null;
  rateTable: string | null;
  identityTemplate: string | null;
  identityFactory: string | null;
  multiTokenPurchase: string | null;
  rootzKey: string | null;
  subscriptionManager: string | null;
}

export interface NetworkConfig {
  chainId: number;
  name: string;
  rpc: string;
  explorer: string;
  contractSet: 'v4' | 'v5' | 'v6';
  contracts: ContractsConfig;
}

export interface BrandingConfig {
  bannerLine1: string;
  bannerLine2: string;
}

export interface IPFSConfig {
  gateway: string;
  apiKey: string;
  secretKey: string;
}

export interface GasConfig {
  maxFeePerGas: string;
  maxPriorityFeePerGas: string;
  gasLimit: string;
}

export interface RawConfig {
  version: string;
  contractVersion: string;
  etherscanApiKey: string;
  branding: BrandingConfig;
  networks: Record<string, NetworkConfig>;
  defaultNetwork: string;
  ipfs: IPFSConfig;
  gas: GasConfig;
}

export interface AppConfig {
  version: string;
  contractVersion: string;
  etherscanApiKey: string;
  branding: BrandingConfig;
  network: NetworkConfig;
  /** The config key for the selected network (e.g., 'joc', 'amoy') - used as chainName for sync */
  networkKey: string;
  contracts: ContractsConfig;
  networks: Record<string, NetworkConfig>;
  defaultNetwork: string;
  ipfs: IPFSConfig;
  gas: GasConfig;
}

/**
 * Load configuration from config.json (browser) or IPC (Electron)
 * Checks localStorage for saved network preference
 */
export async function loadConfig(networkKey?: string): Promise<AppConfig> {
  // Check if running in Electron with preload APIs
  if (window.rootzV6?.config) {
    console.log('[Config] Running in Electron - using IPC');
    const config = await window.rootzV6.config.get();
    if (!config) {
      throw new Error('Failed to get config from Electron main process');
    }
    console.log(`📋 Config loaded (Electron): ${config.network.name} (${config.network.chainId})`);
    return config;
  }

  // Browser mode - fetch config.json
  console.log('[Config] Running in browser - fetching config.json');
  const response = await fetch('./config.json?v=' + Date.now());

  if (!response.ok) {
    throw new Error(`Failed to load config.json: ${response.status}`);
  }

  const rawConfig = await response.json() as RawConfig;

  // Determine which network to use (priority: param > localStorage > config default)
  const storedNetwork = localStorage.getItem('rootz_selected_network');
  const selectedNetwork = networkKey || storedNetwork || rawConfig.defaultNetwork;
  const network = rawConfig.networks[selectedNetwork];

  if (!network) {
    throw new Error(`Network '${selectedNetwork}' not found in config`);
  }

  // Validate required fields
  if (!network.chainId) {
    throw new Error('Config missing network.chainId');
  }
  if (!network.contracts?.factory) {
    throw new Error('Config missing contracts.factory');
  }

  // Flatten for backward compatibility
  const config: AppConfig = {
    version: rawConfig.version,
    contractVersion: rawConfig.contractVersion,
    etherscanApiKey: rawConfig.etherscanApiKey,
    branding: rawConfig.branding,
    network: network,
    networkKey: selectedNetwork,  // The config key (e.g., 'joc', 'amoy') for chainName
    contracts: network.contracts,
    networks: rawConfig.networks,
    defaultNetwork: rawConfig.defaultNetwork,
    ipfs: rawConfig.ipfs,
    gas: rawConfig.gas,
  };

  console.log(`📋 Config loaded: ${network.name} (${network.chainId}) - ${network.contractSet} contracts`);

  return config;
}

/**
 * Get list of available networks
 */
export function getAvailableNetworks(config: AppConfig): Array<{ key: string; network: NetworkConfig }> {
  return Object.entries(config.networks).map(([key, network]) => ({
    key,
    network,
  }));
}
