/**
 * NoteManager Factory
 *
 * Provides a convenient factory function to create NoteManager instances
 * from application state, reducing boilerplate and ensuring consistent configuration.
 *
 * ## Usage
 * ```typescript
 * import { createNoteManager } from '@rootz/notes';
 *
 * // Basic (for read operations)
 * const noteManager = createNoteManager(app);
 *
 * // With auto-funding (for write operations)
 * const noteManager = createNoteManager(app, { autoFund: true });
 * ```
 */

import { NoteManager } from './note-manager.js';
import type { NoteManagerConfig } from './types.js';
import type { Signer } from 'ethers';

/**
 * Minimal app state interface required for creating a NoteManager.
 * This interface is designed to be compatible with the dashboard's AppState
 * without creating a dependency on it.
 */
export interface NoteManagerAppState {
  wallet: {
    signer: Signer;
  };
  config: {
    network: {
      chainId: number;
      rpc: string;
    };
    contracts?: {
      registry?: string;
    };
  };
  chainName: string;
  chainReader: any; // ChainReader instance
}

/**
 * Factory options for creating NoteManager instances.
 */
export interface CreateNoteManagerOptions {
  /**
   * Enable auto-funding for write operations.
   * When true, uses registryAddress from app.config.contracts.registry
   * and enables automatic credit funding when writing notes.
   * @default false
   */
  autoFund?: boolean;

  /**
   * Amount of credits to auto-fund when balance is low.
   * Only used when autoFund is true.
   * @default 25000
   */
  autoFundAmount?: number;

  /**
   * Override the registry address (otherwise uses app.config.contracts.registry).
   */
  registryAddress?: string;

  /**
   * Additional NoteManagerConfig options to merge.
   */
  extraConfig?: Partial<NoteManagerConfig>;
}

/**
 * Create a NoteManager instance from application state.
 *
 * This factory function reduces boilerplate when creating NoteManager instances
 * throughout the application. It extracts the necessary configuration from
 * the app state and applies sensible defaults.
 *
 * @param app - Application state containing wallet, config, and chainReader
 * @param options - Optional configuration for auto-funding and overrides
 * @returns A configured NoteManager instance
 *
 * @example
 * ```typescript
 * // Basic usage (for reading notes)
 * const noteManager = createNoteManager(app);
 * const notes = await noteManager.readNotes({ secretAddress, kvBlock });
 *
 * // With auto-funding (for writing notes)
 * const noteManager = createNoteManager(app, { autoFund: true });
 * await noteManager.writeNote({ secretAddress, kvBlock, note, kvKey });
 * ```
 */
export function createNoteManager(
  app: NoteManagerAppState,
  options: CreateNoteManagerOptions = {}
): NoteManager {
  const {
    autoFund = false,
    autoFundAmount = 25000,
    registryAddress,
    extraConfig = {},
  } = options;

  // Determine registry address
  const resolvedRegistryAddress = registryAddress ?? app.config.contracts?.registry;

  // Build base config
  const config: NoteManagerConfig = {
    chainId: app.config.network.chainId,
    chainName: app.chainName,
    rpcUrl: app.config.network.rpc,
    chainReader: app.chainReader,
    ...extraConfig,
  };

  // Add auto-funding config if enabled
  if (autoFund && resolvedRegistryAddress) {
    config.registryAddress = resolvedRegistryAddress;
    config.autoFundEnabled = true;
    config.autoFundAmount = autoFundAmount;
  }

  return new NoteManager(app.wallet.signer as any, config);
}

/**
 * Create a NoteManager configured for write operations with auto-funding.
 *
 * This is a convenience function equivalent to:
 * `createNoteManager(app, { autoFund: true })`
 *
 * @param app - Application state
 * @param registryAddress - Registry contract address (required for auto-funding)
 * @param autoFundAmount - Credits to fund when low (default: 25000)
 */
export function createWriteNoteManager(
  app: NoteManagerAppState,
  registryAddress: string,
  autoFundAmount: number = 25000
): NoteManager {
  return createNoteManager(app, {
    autoFund: true,
    registryAddress,
    autoFundAmount,
  });
}
