/**
 * Document Secret Viewer - View and Extract Document Secrets
 *
 * When a team member receives a document secret, this module provides:
 * 1. Document download - Extract and download the embedded DOCX
 * 2. Proof of Origin report - Display all metadata for validation
 * 3. Hash verification - Verify document integrity
 * 4. Add Revision - Capture current Word document and write as note
 *
 * @module document-viewer
 */

import { isOfficeContext } from './office-integration';

/**
 * Context needed for document revision operations
 */
export interface DocumentViewerContext {
  /** Secret contract address */
  secretAddress: string;
  /** KeyVault block number */
  kvBlock?: number;
  /** Whether user is the owner (can add revisions) */
  isOwner: boolean;
  /** Count of existing notes/revisions */
  noteCount?: number;
}

/**
 * Parsed document secret content
 */
export interface DocumentSecretContent {
  type: 'word-document';
  version: string;

  // Document identity
  filename: string;
  title: string;
  mimeType: string;
  sizeBytes: number;
  contentHash: string;

  // Authorship
  author?: string;
  lastModifiedBy?: string;
  company?: string;

  // Temporal proof
  createdDate?: string;
  lastModifiedDate?: string;
  capturedAt: string;
  capturedAtMs: number;

  // Source
  sourceType: 'sharepoint' | 'onedrive' | 'local';
  sourceUrl?: string;

  // Document metadata
  subject?: string;
  keywords?: string;
  comments?: string;
  category?: string;
  template?: string;
  revisionNumber?: string;

  // Statistics
  wordCount?: number;
  characterCount?: number;
  paragraphCount?: number;

  // Environment
  environment?: {
    officeVersion?: string;
    platform?: string;
    hostName?: string;
    contentLanguage?: string;
    displayLanguage?: string;
  };

  // The document binary (base64)
  data: string;
}

/**
 * Check if secret content is a document secret
 */
export function isDocumentSecret(content: unknown): content is DocumentSecretContent {
  if (!content || typeof content !== 'object') return false;
  const obj = content as Record<string, unknown>;
  return obj.type === 'word-document' && typeof obj.data === 'string';
}

/**
 * Parse document secret from JSON string
 */
export function parseDocumentSecret(jsonContent: string): DocumentSecretContent | null {
  try {
    const parsed = JSON.parse(jsonContent);
    if (isDocumentSecret(parsed)) {
      return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Convert base64 to Uint8Array
 */
function base64ToBytes(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Compute SHA-256 hash of bytes
 */
async function computeHash(bytes: Uint8Array): Promise<string> {
  const buffer = new ArrayBuffer(bytes.length);
  new Uint8Array(buffer).set(bytes);
  const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Download the document from a document secret
 */
export function downloadDocument(doc: DocumentSecretContent): void {
  const bytes = base64ToBytes(doc.data);
  // Create a copy of the buffer to avoid SharedArrayBuffer issues
  const buffer = new ArrayBuffer(bytes.length);
  new Uint8Array(buffer).set(bytes);
  const blob = new Blob([buffer], { type: doc.mimeType });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = doc.filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

/**
 * Verify document integrity by recomputing hash
 */
export async function verifyDocumentHash(doc: DocumentSecretContent): Promise<{
  valid: boolean;
  expectedHash: string;
  computedHash: string;
}> {
  const bytes = base64ToBytes(doc.data);
  const computedHash = await computeHash(bytes);

  // Extract hash from contentHash (format: "sha256:abc123...")
  const expectedHash = doc.contentHash.replace('sha256:', '');

  return {
    valid: computedHash === expectedHash,
    expectedHash,
    computedHash,
  };
}

/**
 * Format date for display
 */
function formatDate(isoDate?: string): string {
  if (!isoDate) return '—';
  try {
    const date = new Date(isoDate);
    return date.toLocaleString();
  } catch {
    return isoDate;
  }
}

/**
 * Format file size
 */
function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

