/**
 * Escape HTML to prevent XSS
 */
function escapeHtml(text: string): string {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Callbacks for document viewer actions
 */
export interface DocumentViewerCallbacks {
  /** Called when user wants to add a revision */
  onAddRevision?: () => Promise<void>;
  /** Called when user wants to view history */
  onViewHistory?: () => void;
}

/**
 * Setup event handlers for the document viewer
 */
export function setupDocumentViewer(
  doc: DocumentSecretContent,
  context?: DocumentViewerContext,
  callbacks?: DocumentViewerCallbacks
): void {
  const downloadBtn = document.getElementById('download-document-btn');
  const verifyBtn = document.getElementById('verify-hash-btn');
  const verifyResult = document.getElementById('verify-result');
  const addRevisionBtn = document.getElementById('add-revision-btn');
  const viewHistoryBtn = document.getElementById('view-history-btn');
  const revisionStatus = document.getElementById('revision-status');

  if (downloadBtn) {
    downloadBtn.addEventListener('click', () => {
      downloadDocument(doc);
    });
  }

  if (verifyBtn && verifyResult) {
    verifyBtn.addEventListener('click', async () => {
      verifyBtn.textContent = 'Verifying...';
      (verifyBtn as HTMLButtonElement).disabled = true;

      try {
        const result = await verifyDocumentHash(doc);

        verifyResult.classList.remove('hidden');
        if (result.valid) {
          verifyResult.className = 'verify-result valid';
          verifyResult.innerHTML = `
            <strong>✓ Integrity Verified</strong><br>
            The document hash matches. Content has not been modified.
          `;
        } else {
          verifyResult.className = 'verify-result invalid';
          verifyResult.innerHTML = `
            <strong>✗ Hash Mismatch</strong><br>
            Expected: ${result.expectedHash}<br>
            Computed: ${result.computedHash}<br>
            <em>The document may have been modified.</em>
          `;
        }
      } catch (err: any) {
        verifyResult.classList.remove('hidden');
        verifyResult.className = 'verify-result invalid';
        verifyResult.innerHTML = `
          <strong>Verification Failed</strong><br>
          ${err.message || 'Unknown error'}
        `;
      } finally {
        verifyBtn.textContent = 'Verify Integrity';
        (verifyBtn as HTMLButtonElement).disabled = false;
      }
    });
  }

  // Add Revision button handler
  if (addRevisionBtn && callbacks?.onAddRevision) {
    addRevisionBtn.addEventListener('click', async () => {
      addRevisionBtn.textContent = 'Capturing...';
      (addRevisionBtn as HTMLButtonElement).disabled = true;

      if (revisionStatus) {
        revisionStatus.classList.remove('hidden');
        revisionStatus.className = 'revision-status info';
        revisionStatus.innerHTML = 'Capturing document from Word...';
      }

      try {
        await callbacks.onAddRevision();

        if (revisionStatus) {
          revisionStatus.className = 'revision-status success';
          revisionStatus.innerHTML = `
            <strong>✓ Revision Added</strong><br>
            Document captured and saved as a new revision.
          `;
        }
      } catch (err: any) {
        console.error('[DocumentViewer] Add revision failed:', err);
        if (revisionStatus) {
          revisionStatus.className = 'revision-status error';
          revisionStatus.innerHTML = `
            <strong>Failed to add revision</strong><br>
            ${err.message || 'Unknown error'}
          `;
        }
      } finally {
        addRevisionBtn.textContent = 'Add Revision';
        (addRevisionBtn as HTMLButtonElement).disabled = false;
      }
    });
  }

  // View History button handler
  if (viewHistoryBtn && callbacks?.onViewHistory) {
    viewHistoryBtn.addEventListener('click', () => {
      callbacks.onViewHistory();
    });
  }
}

