/**
 * Contract ABIs for Rootz V6/V7 operations.
 *
 * This module centralizes all ABI definitions for contract interactions
 * across the Rootz system. Import from @rootz/notes or @rootz/integration.
 *
 * ## Usage
 * ```typescript
 * import { REGISTRY_V7_ABI, REGISTRY_ADMIN_ABI, MULTI_TOKEN_PURCHASE_ABI } from '@rootz/notes';
 * // or
 * import { REGISTRY_V7_ABI, REGISTRY_ADMIN_ABI, MULTI_TOKEN_PURCHASE_ABI } from '@rootz/integration';
 * ```
 */

/**
 * V7 Registry ABI for vault and credit operations.
 *
 * V7 introduced fundVaultBalance to allow funding specific vault balances,
 * fixing the V6 bug where vault balances could only decrease.
 */
export const REGISTRY_V7_ABI = [
  'function fundVaultBalance(address secretContract, uint256 keyVaultBlock, uint256 amount) external',
  'function fundSecretCredits(address secretContract, uint256 amount) external',
  'function getUserCredits(address user) view returns (uint256)',
];

/**
 * Registry Admin ABI for owner operations.
 *
 * Used for:
 * - Checking registry ownership
 * - Setting up rootzKey and rateTable
 * - Authorizing factories
 * - Depositing credits
 */
export const REGISTRY_ADMIN_ABI = [
  'function owner() view returns (address)',
  'function rootzKey() view returns (address)',
  'function rateTable() view returns (address)',
  'function registerRootzKeyAndRateTable(address _rootzKey, address _rateTable) external',
  'function authorizeFactory(address factory) external',
  'function depositCredits() external payable',
  'function getUserCredits(address user) view returns (uint256)',
];

/**
 * MultiTokenCreditPurchase ABI for credit purchases.
 *
 * Allows purchasing credits with:
 * - Native token (POL/MATIC)
 * - ERC20 tokens (USDC, etc.)
 *
 * Supports bonus credits based on token type and amount.
 */
export const MULTI_TOKEN_PURCHASE_ABI = [
  'function purchaseCreditsWithPOL(address recipient) external payable',
  'function purchaseCreditsWithToken(string tokenSymbol, uint256 tokenAmount, address recipient) external',
  'function previewPurchase(string tokenSymbol, uint256 tokenAmount) external view returns (uint256 baseCredits, uint256 bonusCredits, uint256 totalCredits, uint256 bonusPercent)',
  'function getSupportedTokens() external view returns (string[])',
  'function getTokenConfig(string tokenSymbol) external view returns (address tokenAddress, uint256 creditsPerToken, uint256 bonusPercent, bool isActive, bool isStablecoin, uint256 purchases)',
];

/**
 * ERC20 ABI for token approvals.
 *
 * Used for:
 * - Checking token balance
 * - Checking allowance for spender
 * - Approving spender to transfer tokens
 */
export const ERC20_ABI = [
  'function balanceOf(address account) view returns (uint256)',
  'function allowance(address owner, address spender) view returns (uint256)',
  'function approve(address spender, uint256 amount) returns (bool)',
  'function decimals() view returns (uint8)',
  'function symbol() view returns (string)',
];
